    try (BlockInputStream blockInputStreamWithRetry = new DummyBlockInputStreamWithRetry(blockID, blockSize, MockPipeline.createSingleNodePipeline(), null, null, chunks, chunkDataMap, isRefreshed, null, clientConfig)) {
