@ParameterizedTest
@MethodSource("exceptionsTriggersRefresh")
public void testRefreshOnReadFailureAfterUnbuffer(IOException ex) throws Exception {
    // GIVEN
    BlockID blockID = new BlockID(new ContainerBlockID(1, 1));
    Pipeline pipeline = MockPipeline.createSingleNodePipeline();
    Pipeline newPipeline = MockPipeline.createSingleNodePipeline();
    XceiverClientFactory clientFactory = mock(XceiverClientFactory.class);
    XceiverClientSpi client = mock(XceiverClientSpi.class);
    BlockLocationInfo blockLocationInfo = mock(BlockLocationInfo.class);
    when(clientFactory.acquireClientForReadData(pipeline)).thenReturn(client);
    final int len = 200;
    final ChunkInputStream stream = throwingChunkInputStream(ex, len, true);
    when(refreshFunction.apply(blockID)).thenReturn(blockLocationInfo);
    when(blockLocationInfo.getPipeline()).thenReturn(newPipeline);
    OzoneClientConfig clientConfig = conf.getObject(OzoneClientConfig.class);
    clientConfig.setChecksumVerify(false);
    BlockInputStream subject = new BlockInputStream(blockID, blockSize, pipeline, null, clientFactory, refreshFunction, clientConfig) {

        @Override
        protected List<ChunkInfo> getChunkInfoListUsingClient() {
            return chunks;
        }

        @Override
        protected ChunkInputStream createChunkInputStream(ChunkInfo chunkInfo) {
            return stream;
        }
    };
    try {
        subject.initialize();
        subject.unbuffer();
        // WHEN
        byte[] b = new byte[len];
        int bytesRead = subject.read(b, 0, len);
        // THEN
        assertEquals(len, bytesRead);
        verify(refreshFunction).apply(blockID);
        verify(clientFactory).acquireClientForReadData(pipeline);
        verify(clientFactory).releaseClientForReadData(client, false);
    } finally {
        subject.close();
    }
}

@ParameterizedTest
@ValueSource(ints = { 1, 1024, 1024 * 1024 })
void test(final int writeSize) throws IOException {
    assertEquals(0, DATA_SIZE % writeSize);
    final BufferPool bufferPool = new BufferPool(4 * 1024 * 1024, 32 / 4);
    for (int block = 0; block < 10; block++) {
        try (BlockOutputStream outputStream = createBlockOutputStream(bufferPool)) {
            for (int i = 0; i < DATA_SIZE / writeSize; i++) {
                if (writeSize > 1) {
                    outputStream.write(DATA, i * writeSize, writeSize);
                } else {
                    outputStream.write(DATA[i]);
                }
            }
        }
    }
}

/**
 * Tests an EC offline reconstruction scenario in which none of the ChunkInfo in an EC stripe have stripeChecksum.
 * Such ChunkInfo will exist for any EC data that was written in a version in which the ChunkInfo protobuf message did
 * not have the stripeChecksum field. Here, we assert that executePutBlock during reconstruction does not throw an
 * exception because of missing stripeChecksum. This essentially tests compatibility between an Ozone version that
 * did not have stripeChecksum and a version that has stripeChecksum.
 */
@Test
public void testMissingStripeChecksumDoesNotMakeExecutePutBlockFailDuringECReconstruction() throws IOException {
    // setup some parameters required for creating ECBlockOutputStream
    OzoneClientConfig config = new OzoneClientConfig();
    ECReplicationConfig replicationConfig = new ECReplicationConfig(3, 2);
    BlockID blockID = new BlockID(1, 1);
    DatanodeDetails datanodeDetails = MockDatanodeDetails.randomDatanodeDetails();
    Pipeline pipeline = Pipeline.newBuilder().setId(PipelineID.valueOf(datanodeDetails.getUuid())).setReplicationConfig(replicationConfig).setNodes(ImmutableList.of(datanodeDetails)).setState(Pipeline.PipelineState.CLOSED).// we'll executePutBlock for the parity index 5 because stripeChecksum is written to either the first or the
    // parity indexes
    setReplicaIndexes(ImmutableMap.of(datanodeDetails, 5)).build();
    BlockLocationInfo locationInfo = new BlockLocationInfo.Builder().setBlockID(blockID).setOffset(1).setLength(10).setPipeline(pipeline).build();
    /*
    The array of BlockData contains metadata about blocks and their chunks, and is read in executePutBlock. In
    this test, we deliberately don't write stripeChecksum to any chunk. The expectation is that executePutBlock
    should not throw an exception because of missing stripeChecksum.
     */
    BlockData[] blockData = createBlockDataWithoutStripeChecksum(blockID, replicationConfig);
    try (ECBlockOutputStream ecBlockOutputStream = createECBlockOutputStream(config, replicationConfig, blockID, pipeline)) {
        Assertions.assertDoesNotThrow(() -> ecBlockOutputStream.executePutBlock(true, true, locationInfo.getLength(), blockData));
    }
}

