}

@Test
public void connectsToNewPipeline() throws Exception {
    // GIVEN
    Pipeline pipeline = MockPipeline.createSingleNodePipeline();
    Pipeline newPipeline = MockPipeline.createSingleNodePipeline();
    Token<?> token = mock(Token.class);
    when(token.encodeToUrlString()).thenReturn("oldToken");
    Token<?> newToken = mock(Token.class);
    when(newToken.encodeToUrlString()).thenReturn("newToken");
    AtomicReference<Pipeline> pipelineRef = new AtomicReference<>(pipeline);
    AtomicReference<Token<?>> tokenRef = new AtomicReference<>(token);
    XceiverClientFactory clientFactory = mock(XceiverClientFactory.class);
    XceiverClientSpi client = mock(XceiverClientSpi.class);
    when(clientFactory.acquireClientForReadData(any())).thenReturn(client);
    ArgumentCaptor<ContainerCommandRequestProto> requestCaptor = ArgumentCaptor.forClass(ContainerCommandRequestProto.class);
    when(client.getPipeline()).thenAnswer(invocation -> pipelineRef.get());
    when(client.sendCommand(requestCaptor.capture(), any())).thenAnswer(invocation -> getReadChunkResponse(requestCaptor.getValue(), ChunkBuffer.wrap(ByteBuffer.wrap(chunkData)), ByteStringConversion::safeWrap));
    try (ChunkInputStream subject = new ChunkInputStream(chunkInfo, blockID, clientFactory, pipelineRef::get, false, tokenRef::get)) {
        // WHEN
        subject.unbuffer();
        pipelineRef.set(newPipeline);
        tokenRef.set(newToken);
        byte[] buffer = new byte[CHUNK_SIZE];
        int read = subject.read(buffer);
        // THEN
        assertEquals(CHUNK_SIZE, read);
        assertArrayEquals(chunkData, buffer);
        verify(clientFactory).acquireClientForReadData(newPipeline);
        verify(newToken).encodeToUrlString();
    }
}

@Test
public void testRecordChunkMetrics() {
    ContainerClientMetrics metrics = ContainerClientMetrics.acquire();
    PipelineID pipelineId1 = PipelineID.randomId();
    UUID leaderId1 = UUID.randomUUID();
    PipelineID pipelineId2 = PipelineID.randomId();
    UUID leaderId2 = UUID.randomUUID();
    PipelineID pipelineId3 = PipelineID.randomId();
    metrics.recordWriteChunk(createPipeline(pipelineId1, leaderId1), 10);
    metrics.recordWriteChunk(createPipeline(pipelineId2, leaderId2), 20);
    metrics.recordWriteChunk(createPipeline(pipelineId3, leaderId1), 30);
    assertEquals(3, metrics.getTotalWriteChunkCalls().value());
    assertEquals(60, metrics.getTotalWriteChunkBytes().value());
    assertEquals(3, metrics.getWriteChunkBytesByPipeline().size());
    assertEquals(10, metrics.getWriteChunkBytesByPipeline().get(pipelineId1).value());
    assertEquals(20, metrics.getWriteChunkBytesByPipeline().get(pipelineId2).value());
    assertEquals(30, metrics.getWriteChunkBytesByPipeline().get(pipelineId3).value());
    assertEquals(3, metrics.getWriteChunkCallsByPipeline().size());
    assertEquals(1, metrics.getWriteChunkCallsByPipeline().get(pipelineId1).value());
    assertEquals(1, metrics.getWriteChunkCallsByPipeline().get(pipelineId2).value());
    assertEquals(1, metrics.getWriteChunkCallsByPipeline().get(pipelineId3).value());
    assertEquals(2, metrics.getWriteChunksCallsByLeaders().size());
    assertEquals(2, metrics.getWriteChunksCallsByLeaders().get(leaderId1).value());
    assertEquals(1, metrics.getWriteChunksCallsByLeaders().get(leaderId2).value());
}

