@Test
public void testCanHandleErrorAndFailOverToReconstruction() throws IOException {
    int blockLength = 5 * ONEMB;
    generateData(blockLength);
    Map<DatanodeDetails, Integer> dnMap = ECStreamTestUtil.createIndexMap(1, 2, 3, 4, 5);
    BlockLocationInfo blockInfo = ECStreamTestUtil.createKeyInfo(repConfig, blockLength, dnMap);
    ByteBuffer readBuffer = ByteBuffer.allocate(100);
    DatanodeDetails badDN = blockInfo.getPipeline().getFirstNode();
    dataGenerator = new SplittableRandom(randomSeed);
