    final long writtenSize = 32 * KB;
    File file = new File(dir, "data");
    createFile(file, (int) writtenSize);
    SpaceUsageSource du = new DU(file);
    long duSize = du.getUsedSpace();
    assertFileSize(writtenSize, duSize);
}

