/**
 * Due to RocksDB internals, prefixed keys may be grouped all at the
 * beginning or end of the key iteration, depending on the serialization
 * used. Keys of the same prefix are grouped
 * together. This method runs the same set of tests on the iterator first
 * positively filtering one prefix, and then positively filtering
 * a second prefix. If the sets of keys with prefix one, prefix
 * two, and no prefixes are not empty, it follows that the filter will
 * encounter both of the following cases:
 *
 * 1. A failing key followed by a passing key.
 * 2. A passing key followed by a failing key.
 *
 * Note that with the current block data table implementation, there is
 * only ever one type of prefix. This test adds a dummy second prefix type
 * to ensure that the iterator will continue to work if more prefixes are
 * added in the future.
 *
 * @throws Exception
 */
@ParameterizedTest
@MethodSource("provideTestData")
public void testKeyValueBlockIteratorWithAdvancedFilter(ContainerTestVersionInfo versionInfo, String keySeparator) throws Exception {
    initTest(versionInfo, keySeparator);
    // Block data table currently only uses one prefix type.
    // Introduce a second prefix type to make sure the iterator functions
    // correctly if more prefixes were to be added in the future.
    final String secondPrefix = "#FOOBAR#";
    Map<String, Integer> prefixCounts = new HashMap<>();
    prefixCounts.put(OzoneConsts.DELETING_KEY_PREFIX, 3);
    prefixCounts.put("", 3);
    prefixCounts.put(secondPrefix, 3);
    Map<String, List<Long>> blockIDs = createContainerWithBlocks(CONTAINER_ID, prefixCounts);
    // Test deleting filter.
    testWithFilter(containerData.getDeletingBlockKeyFilter(), blockIDs.get(OzoneConsts.DELETING_KEY_PREFIX));
    // Test arbitrary filter.
    String schemaPrefix = containerData.containerPrefix();
    MetadataKeyFilters.KeyPrefixFilter secondFilter = new MetadataKeyFilters.KeyPrefixFilter().addFilter(schemaPrefix + secondPrefix);
    testWithFilter(secondFilter, blockIDs.get(secondPrefix));
}

@Test
public void testContainersShareColumnFamilyOptions() {
    ConfigurationSource conf = new OzoneConfiguration();
    // Make sure ColumnFamilyOptions are same for a particular db profile
    for (Supplier<DatanodeDBProfile> dbProfileSupplier : new Supplier[] { DatanodeDBProfile.Disk::new, DatanodeDBProfile.SSD::new }) {
        // ColumnFamilyOptions should be same across configurations
        ColumnFamilyOptions columnFamilyOptions1 = dbProfileSupplier.get().getColumnFamilyOptions(new OzoneConfiguration());
        ColumnFamilyOptions columnFamilyOptions2 = dbProfileSupplier.get().getColumnFamilyOptions(new OzoneConfiguration());
        assertEquals(columnFamilyOptions1, columnFamilyOptions2);
        // ColumnFamilyOptions should be same when queried multiple times
        // for a particulat configuration
        columnFamilyOptions1 = dbProfileSupplier.get().getColumnFamilyOptions(conf);
        columnFamilyOptions2 = dbProfileSupplier.get().getColumnFamilyOptions(conf);
        assertEquals(columnFamilyOptions1, columnFamilyOptions2);
    }
    // Make sure ColumnFamilyOptions are different for different db profile
    DatanodeDBProfile diskProfile = new DatanodeDBProfile.Disk();
    DatanodeDBProfile ssdProfile = new DatanodeDBProfile.SSD();
    assertNotEquals(diskProfile.getColumnFamilyOptions(new OzoneConfiguration()), ssdProfile.getColumnFamilyOptions(new OzoneConfiguration()));
    assertNotEquals(diskProfile.getColumnFamilyOptions(conf), ssdProfile.getColumnFamilyOptions(conf));
}

