@ParameterizedTest
@EnumSource
void testInputOutput(CopyContainerCompression compression) throws Exception {
    byte[] original = getRandomBytes(16);
    ByteArrayOutputStream out = new ByteArrayOutputStream();
    try (OutputStream compressed = compression.wrap(out)) {
        compressed.write(original);
    }
    byte[] written = out.toByteArray();
    if (compression == CopyContainerCompression.NO_COMPRESSION) {
        assertArrayEquals(original, written);
    } else {
        assertNotEquals(original, written);
    }
    ByteArrayInputStream input = new ByteArrayInputStream(written);
    try (InputStream uncompressed = compression.wrap(input)) {
        byte[] read = new byte[original.length];
        readFully(uncompressed, read);
        assertArrayEquals(original, read);
        assertEquals(0, uncompressed.available());
    }
}

@Test
void successfulReplication() throws Exception {
    // GIVEN
    GrpcReplicationClient client = mock(GrpcReplicationClient.class);
    ArgumentCaptor<StreamObserver<SendContainerResponse>> captor = ArgumentCaptor.forClass(StreamObserver.class);
    when(client.upload(captor.capture())).thenReturn(new NoopObserver() {

        @Override
        public void onNext(SendContainerRequest value) {
            captor.getValue().onNext(SendContainerResponse.getDefaultInstance());
        }
    });
    CompletableFuture<Void> callback = new CompletableFuture<>();
    GrpcContainerUploader subject = createSubject(client);
    // WHEN
    OutputStream out = startUpload(subject, callback);
    out.close();
    // THEN
    verify(client).close();
}

