void testReceiveDataForExistingContainer() throws Exception {
    long containerId = 1;
    // create containerImporter
    ContainerSet containerSet = new ContainerSet(0);
    MutableVolumeSet volumeSet = new MutableVolumeSet("test", conf, null, StorageVolume.VolumeType.DATA_VOLUME, null);
    ContainerImporter containerImporter = new ContainerImporter(conf, new ContainerSet(0), mock(ContainerController.class), volumeSet);
