    try (StreamingServer server = new StreamingServer(new DirectoryServerSource(sourceDir), 0, sslCtxServer)) {
        server.start();
        try (StreamingClient client = new StreamingClient("localhost", server.getPort(), new DirectoryServerDestination(destDir), sslCtxClient)) {
            client.stream(SUBDIR);
        }
    }
    //THEN: compare the files
