@Test
public void testStartupSlvLessThanMlv() throws Exception {
    // Add subdirectories under the temporary folder where the version file
    // will be placed.
    File datanodeSubdir = Files.createDirectory(tempFolder.resolve(DATANODE_LAYOUT_VERSION_DIR)).toFile();
    OzoneConfiguration conf = new OzoneConfiguration();
    conf.set(HddsConfigKeys.OZONE_METADATA_DIRS, tempFolder.toString());
    // Set metadata layout version larger then software layout version.
    int largestSlv = maxLayoutVersion();
    int mlv = largestSlv + 1;
    // Create version file with MLV > SLV, which should fail the
    // DataNodeStateMachine construction.
    UpgradeTestUtils.createVersionFile(datanodeSubdir, HddsProtos.NodeType.DATANODE, mlv);
    IOException ioException = assertThrows(IOException.class, () -> new DatanodeStateMachine(getNewDatanodeDetails(), conf));
    assertThat(ioException).hasMessageEndingWith(String.format("Metadata layout version (%s) > software layout version (%s)", mlv, largestSlv));
}

/**
 * Test RocksDB is created on data volume, not matter Schema V3 is
 * enabled or not.
 * If Schema V3 is enabled, RocksDB will be loaded.
 */
@ParameterizedTest(name = "schema V3 enabled :{0}")
@ValueSource(booleans = { true, false })
public void testDBOnHddsVolume(boolean schemaV3Enabled) throws Exception {
    initTests(schemaV3Enabled);
    // start DN and SCM
    startScmServer();
    addHddsVolume();
    startPreFinalizedDatanode();
    HddsVolume dataVolume = (HddsVolume) dsm.getContainer().getVolumeSet().getVolumesList().get(0);
    assertNull(dataVolume.getDbVolume());
    assertFalse(dataVolume.isDbLoaded());
    dsm.finalizeUpgrade();
    // RocksDB is created during upgrade
    File dbFile = new File(dataVolume.getStorageDir().getAbsolutePath() + "/" + dataVolume.getClusterID() + "/" + dataVolume.getStorageID());
    assertTrue(dbFile.exists());
    // RocksDB loaded when SchemaV3 is enabled
    if (VersionedDatanodeFeatures.SchemaV3.isFinalizedAndEnabled(conf)) {
        assertTrue(dataVolume.getDbParentDir().getAbsolutePath().startsWith(dataVolume.getStorageDir().toString()));
    } else {
        // RocksDB is not loaded when SchemaV3 is disabled.
        assertFalse(dataVolume.isDbLoaded());
    }
}

