/**
 * Test RocksDB in created in Finalize action for an existing hddsVolume.
 * This mimics the real cluster upgrade situation.
 */
@ParameterizedTest(name = "schema V3 enabled :{0}")
@ValueSource(booleans = { false, true })
public void testDBCreatedInFinalize(boolean schemaV3Enabled) throws Exception {
    initTests(schemaV3Enabled);
    // start DN and SCM
    startScmServer();
    // add one HddsVolume
    addHddsVolume();
    // Set layout version.
    DatanodeLayoutStorage layoutStorage = new DatanodeLayoutStorage(conf, UUID.randomUUID().toString(), HDDSLayoutFeature.ERASURE_CODED_STORAGE_SUPPORT.layoutVersion());
    layoutStorage.initialize();
    dsm = new DatanodeStateMachine(ContainerTestUtils.createDatanodeDetails(), conf);
    HddsVolume dataVolume = (HddsVolume) dsm.getContainer().getVolumeSet().getVolumesList().get(0);
    // Format HddsVolume to mimic the real cluster upgrade situation
    dataVolume.format(CLUSTER_ID);
    File idDir = new File(dataVolume.getStorageDir(), CLUSTER_ID);
    if (!idDir.mkdir()) {
        fail("Failed to create id directory");
    }
    assertNull(dataVolume.getDbParentDir());
    // Restart DN and finalize upgrade
    restartDatanode(HDDSLayoutFeature.ERASURE_CODED_STORAGE_SUPPORT.layoutVersion(), true);
    dsm.finalizeUpgrade();
    // RocksDB is created by upgrade action
    dataVolume = ((HddsVolume) dsm.getContainer().getVolumeSet().getVolumesList().get(0));
    assertNotNull(dataVolume.getDbParentDir());
    if (VersionedDatanodeFeatures.SchemaV3.isFinalizedAndEnabled(conf)) {
        assertTrue(dataVolume.isDbLoaded());
    } else {
        assertFalse(dataVolume.isDbLoaded());
    }
}

