@Test
public void protobufConversion() {
    final ByteString missingContainerIndexes = Proto2Utils.unsafeByteString(new byte[] { 1, 2 });
    List<Long> srcNodesIndexes = new ArrayList<>();
    for (int i = 0; i < srcNodesIndexes.size(); i++) {
        srcNodesIndexes.add(i + 1L);
    }
    ECReplicationConfig ecReplicationConfig = new ECReplicationConfig(3, 2);
    final List<DatanodeDetails> dnDetails = getDNDetails(5);
    List<ReconstructECContainersCommand.DatanodeDetailsAndReplicaIndex> sources = dnDetails.stream().map(a -> new ReconstructECContainersCommand.DatanodeDetailsAndReplicaIndex(a, dnDetails.indexOf(a))).collect(Collectors.toList());
    List<DatanodeDetails> targets = getDNDetails(2);
    ReconstructECContainersCommand reconstructECContainersCommand = new ReconstructECContainersCommand(1L, sources, targets, missingContainerIndexes, ecReplicationConfig);
    StorageContainerDatanodeProtocolProtos.ReconstructECContainersCommandProto proto = reconstructECContainersCommand.getProto();
    List<ReconstructECContainersCommand.DatanodeDetailsAndReplicaIndex> srcDnsFromProto = proto.getSourcesList().stream().map(a -> ReconstructECContainersCommand.DatanodeDetailsAndReplicaIndex.fromProto(a)).collect(Collectors.toList());
    List<DatanodeDetails> targetDnsFromProto = proto.getTargetsList().stream().map(a -> DatanodeDetails.getFromProtoBuf(a)).collect(Collectors.toList());
    assertEquals(1L, proto.getContainerID());
    assertEquals(sources, srcDnsFromProto);
    assertEquals(targets, targetDnsFromProto);
    assertEquals(missingContainerIndexes, proto.getMissingContainerIndexes());
    assertEquals(ecReplicationConfig, new ECReplicationConfig(proto.getEcReplicationConfig()));
    ReconstructECContainersCommand fromProtobuf = ReconstructECContainersCommand.getFromProtobuf(proto);
    assertEquals(reconstructECContainersCommand.getContainerID(), fromProtobuf.getContainerID());
    assertEquals(reconstructECContainersCommand.getSources(), fromProtobuf.getSources());
    assertEquals(reconstructECContainersCommand.getTargetDatanodes(), fromProtobuf.getTargetDatanodes());
    assertEquals(reconstructECContainersCommand.getMissingContainerIndexes(), fromProtobuf.getMissingContainerIndexes());
    assertEquals(reconstructECContainersCommand.getEcReplicationConfig(), fromProtobuf.getEcReplicationConfig());
}

@ParameterizedTest
@ValueSource(strings = { OzoneConsts.SCHEMA_V1, OzoneConsts.SCHEMA_V2, OzoneConsts.SCHEMA_V3 })
public void testDeletedContainersClearedOnShutdown(String schemaVersion) throws IOException {
    ContainerTestVersionInfo.setTestSchemaVersion(schemaVersion, conf);
    LOG.info("SchemaV3_enabled: " + conf.get(DatanodeConfiguration.CONTAINER_SCHEMA_V3_ENABLED));
    service.start(conf);
    assertNotNull(service.getDatanodeDetails());
    assertNotNull(service.getDatanodeDetails().getHostName());
    assertFalse(service.getDatanodeStateMachine().isDaemonStopped());
    // Get volumeSet and store volumes in temp folders
    // in order to access them after service.stop()
    MutableVolumeSet volumeSet = service.getDatanodeStateMachine().getContainer().getVolumeSet();
    // VolumeSet for this test, contains only 1 volume
    assertEquals(1, volumeSet.getVolumesList().size());
    StorageVolume volume = volumeSet.getVolumesList().get(0);
    // Check instanceof and typecast
    assertInstanceOf(HddsVolume.class, volume);
    HddsVolume hddsVolume = (HddsVolume) volume;
    StorageVolumeUtil.checkVolume(hddsVolume, clusterId, clusterId, conf, LOG, null);
    // Create a container and move it under the tmp delete dir.
    KeyValueContainer container = ContainerTestUtils.addContainerToDeletedDir(hddsVolume, clusterId, conf, schemaVersion);
    Path containerTmpPath = KeyValueContainerUtil.getTmpDirectoryPath(container.getContainerData(), hddsVolume);
    assertTrue(containerTmpPath.toFile().exists());
    File[] deletedContainersAfterShutdown = hddsVolume.getDeletedContainerDir().listFiles();
    assertNotNull(deletedContainersAfterShutdown);
    assertEquals(1, deletedContainersAfterShutdown.length);
    service.stop();
    service.join();
    service.close();
    deletedContainersAfterShutdown = hddsVolume.getDeletedContainerDir().listFiles();
    assertNotNull(deletedContainersAfterShutdown);
    assertEquals(0, deletedContainersAfterShutdown.length);
}

