    assertThat(writtenMetrics).withFailMessage("The expected metric line is present in prometheus metrics output").contains("same_name_counter{port=\"1234\"");
    assertThat(writtenMetrics).withFailMessage("The expected metric line is present in prometheus metrics output").contains("same_name_counter{port=\"2345\"");
