/**
 * Make sure Prometheus metrics start fresh after each flush.
 * Publish the metrics and flush them,
 * then unregister one of them and register another.
 * Publish and flush the metrics again
 * and then check that the unregistered metric is not present.
 */
@Test
public void testRemovingStaleMetricsOnFlush() throws InterruptedException, TimeoutException {
    // GIVEN
    metrics.register("StaleMetric", "staleMetric", (MetricsSource) (collector, all) -> collector.addRecord("StaleMetric").add(new MetricsTag(PORT_INFO, "1234")).addGauge(COUNTER_INFO, COUNTER_1).endRecord());
    waitForMetricsToPublish("stale_metric_counter");
    // unregister the metric
    metrics.unregisterSource("StaleMetric");
    metrics.register("SomeMetric", "someMetric", (MetricsSource) (collector, all) -> collector.addRecord("SomeMetric").add(new MetricsTag(PORT_INFO, "4321")).addGauge(COUNTER_INFO, COUNTER_2).endRecord());
    String writtenMetrics = waitForMetricsToPublish("some_metric_counter");
    // THEN
    // The first metric shouldn't be present
    assertThat(writtenMetrics).withFailMessage("The expected metric line is present in prometheus metrics output").doesNotContain("stale_metric_counter{port=\"1234\"");
    assertThat(writtenMetrics).withFailMessage("The expected metric line is present in prometheus metrics output").contains("some_metric_counter{port=\"4321\"");
    metrics.unregisterSource("SomeMetric");
}

