@ParameterizedTest
@EnumSource(TableCache.CacheType.class)
public void testTableCacheWithRenameKey(TableCache.CacheType cacheType) {
    createTableCache(cacheType);
    // putting cache with same epoch and different keyNames
    for (int i = 0; i < 3; i++) {
        tableCache.put(new CacheKey<>(Integer.toString(i).concat("A")), CacheValue.get(i));
        tableCache.put(new CacheKey<>(Integer.toString(i).concat("B")), CacheValue.get(i, Integer.toString(i)));
    }
    // Epoch entries should be like (long, (key1, key2, ...))
    // (0, (0A, 0B))  (1, (1A, 1B))  (2, (2A, 1B))
    assertEquals(3, tableCache.getEpochEntries().size());
    assertEquals(2, tableCache.getEpochEntries().get(0L).size());
    // Cache should be like (key, (cacheValue, long))
    // (0A, (null, 0))   (0B, (0, 0))
    // (1A, (null, 1))   (1B, (0, 1))
    // (2A, (null, 2))   (2B, (0, 2))
    for (int i = 0; i < 3; i++) {
        assertNull(tableCache.get(new CacheKey<>(Integer.toString(i).concat("A"))).getCacheValue());
        assertEquals(Integer.toString(i), tableCache.get(new CacheKey<>(Integer.toString(i).concat("B"))).getCacheValue());
    }
    ArrayList<Long> epochs = new ArrayList<>();
    epochs.add(0L);
    epochs.add(1L);
    epochs.add(2L);
    epochs.add(3L);
    epochs.add(4L);
    tableCache.evictCache(epochs);
    assertEquals(0, tableCache.getEpochEntries().size());
    if (cacheType == TableCache.CacheType.PARTIAL_CACHE) {
        assertEquals(0, tableCache.size());
    } else {
        assertEquals(3, tableCache.size());
    }
    verifyStats(tableCache, 6, 0, 0);
}

@ParameterizedTest
@EnumSource(TableCache.CacheType.class)
public void testPartialTableCacheWithNotContinuousEntries(TableCache.CacheType cacheType) {
    createTableCache(cacheType);
    int totalCount = 0;
    int insertedCount = 3000;
    int cleanupCount = 0;
    ArrayList<Long> epochs = new ArrayList<>();
    for (long i = 0; i < insertedCount; i += 2) {
        if (cleanupCount++ < 1000) {
            epochs.add(i);
        }
        tableCache.put(new CacheKey<>(Long.toString(i)), CacheValue.get(i, Long.toString(i)));
        totalCount++;
    }
    assertEquals(totalCount, tableCache.size());
    tableCache.evictCache(epochs);
    final int count = totalCount;
    // If cleanup policy is manual entries should have been removed.
    if (cacheType == TableCache.CacheType.PARTIAL_CACHE) {
        assertEquals(count - epochs.size(), tableCache.size());
        // Check remaining entries exist or not and deleted entries does not
        // exist.
        for (long i = 0; i < insertedCount; i += 2) {
            if (!epochs.contains(i)) {
                assertEquals(Long.toString(i), tableCache.get(new CacheKey<>(Long.toString(i))).getCacheValue());
            } else {
                assertNull(tableCache.get(new CacheKey<>(Long.toString(i))));
            }
        }
    } else {
        for (long i = 0; i < insertedCount; i += 2) {
            assertEquals(Long.toString(i), tableCache.get(new CacheKey<>(Long.toString(i))).getCacheValue());
        }
    }
}

@ParameterizedTest
@EnumSource(TableCache.CacheType.class)
public void testPartialTableCacheWithOverrideEntries(TableCache.CacheType cacheType) {
    createTableCache(cacheType);
    tableCache.put(new CacheKey<>(Long.toString(0)), CacheValue.get(0, Long.toString(0)));
    tableCache.put(new CacheKey<>(Long.toString(1)), CacheValue.get(1, Long.toString(1)));
    tableCache.put(new CacheKey<>(Long.toString(2)), CacheValue.get(2, Long.toString(2)));
    //Override first 2 entries
    // This is to simulate a case like create mpu key, commit part1, commit
    // part2. They override the same key.
    tableCache.put(new CacheKey<>(Long.toString(0)), CacheValue.get(3, Long.toString(0)));
    tableCache.put(new CacheKey<>(Long.toString(1)), CacheValue.get(4, Long.toString(1)));
    assertEquals(3, tableCache.size());
    // It will have 2 additional entries because we have 2 override entries.
    assertEquals(3 + 2, tableCache.getEpochEntries().size());
    // Now remove
    List<Long> epochs = new ArrayList<>();
    epochs.add(0L);
    epochs.add(1L);
    epochs.add(2L);
    epochs.add(3L);
    epochs.add(4L);
    if (cacheType == TableCache.CacheType.PARTIAL_CACHE) {
        tableCache.evictCache(epochs);
        assertEquals(0, tableCache.size());
        assertEquals(0, tableCache.getEpochEntries().size());
    }
    // Add a new entry.
    tableCache.put(new CacheKey<>(Long.toString(5)), CacheValue.get(5, Long.toString(5)));
    epochs = new ArrayList<>();
    epochs.add(5L);
    if (cacheType == TableCache.CacheType.PARTIAL_CACHE) {
        tableCache.evictCache(epochs);
        assertEquals(0, tableCache.size());
        // Overridden entries would have been deleted.
        assertEquals(0, tableCache.getEpochEntries().size());
    }
    verifyStats(tableCache, 0, 0, 0);
}

@ParameterizedTest
@EnumSource(TableCache.CacheType.class)
public void testPartialTableCacheWithOverrideAndDelete(TableCache.CacheType cacheType) {
    createTableCache(cacheType);
    tableCache.put(new CacheKey<>(Long.toString(0)), CacheValue.get(0, Long.toString(0)));
    tableCache.put(new CacheKey<>(Long.toString(1)), CacheValue.get(1, Long.toString(1)));
    tableCache.put(new CacheKey<>(Long.toString(2)), CacheValue.get(2, Long.toString(2)));
    // Override entries
    tableCache.put(new CacheKey<>(Long.toString(0)), CacheValue.get(3, Long.toString(0)));
    tableCache.put(new CacheKey<>(Long.toString(1)), CacheValue.get(4, Long.toString(1)));
    // Finally, mark them for deleted
    tableCache.put(new CacheKey<>(Long.toString(0)), CacheValue.get(5));
    tableCache.put(new CacheKey<>(Long.toString(1)), CacheValue.get(6));
    // So now our cache epoch entries looks like
    // 0-0, 1-1, 2-2, 0-3, 1-4, 0-5, 1-6
    // Cache looks like
    // 0-5, 1-6, 2-2
    assertEquals(3, tableCache.size());
    // It will have 4 additional entries because we have 4 override entries.
    assertEquals(3 + 4, tableCache.getEpochEntries().size());
    // Now remove
    List<Long> epochs = new ArrayList<>();
    epochs.add(0L);
    epochs.add(1L);
    epochs.add(2L);
    epochs.add(3L);
    epochs.add(4L);
    epochs.add(5L);
    epochs.add(6L);
    if (cacheType == TableCache.CacheType.PARTIAL_CACHE) {
        tableCache.evictCache(epochs);
        assertEquals(0, tableCache.size());
        assertEquals(0, tableCache.getEpochEntries().size());
    } else {
        tableCache.evictCache(epochs);
        assertEquals(1, tableCache.size());
        // Epoch entries which are overridden also will be cleaned up.
        assertEquals(0, tableCache.getEpochEntries().size());
    }
    // Add a new entry, now old override entries will be cleaned up.
    tableCache.put(new CacheKey<>(Long.toString(3)), CacheValue.get(7, Long.toString(3)));
    epochs = new ArrayList<>();
    epochs.add(7L);
    if (cacheType == TableCache.CacheType.PARTIAL_CACHE) {
        tableCache.evictCache(epochs);
        assertEquals(0, tableCache.size());
        // Epoch entries which are overridden now would have been deleted.
        assertEquals(0, tableCache.getEpochEntries().size());
    } else {
        tableCache.evictCache(epochs);
        // 2 entries will be in cache, as 2 are not deleted.
        assertEquals(2, tableCache.size());
        // Epoch entries which are not marked for delete will also be cleaned up.
        // As they are override entries in full cache.
        assertEquals(0, tableCache.getEpochEntries().size());
    }
    verifyStats(tableCache, 0, 0, 0);
}

@ParameterizedTest
@EnumSource(TableCache.CacheType.class)
public void testPartialTableCacheParallel(TableCache.CacheType cacheType) throws Exception {
    createTableCache(cacheType);
    int totalCount = 0;
    CompletableFuture<Integer> future = CompletableFuture.supplyAsync(() -> {
        try {
            return writeToCache(10, 1, 0);
        } catch (InterruptedException ex) {
            fail("writeToCache got interrupt exception");
        }
        return 0;
    });
    int value = future.get();
    assertEquals(10, value);
    totalCount += value;
    future = CompletableFuture.supplyAsync(() -> {
        try {
            return writeToCache(10, 11, 100);
        } catch (InterruptedException ex) {
            fail("writeToCache got interrupt exception");
        }
        return 0;
    });
    // Check we have first 10 entries in cache.
    for (int i = 1; i <= 10; i++) {
        assertEquals(Integer.toString(i), tableCache.get(new CacheKey<>(Integer.toString(i))).getCacheValue());
    }
    value = future.get();
    assertEquals(10, value);
    totalCount += value;
    if (cacheType == TableCache.CacheType.PARTIAL_CACHE) {
        int deleted = 5;
        // cleanup first 5 entries
        ArrayList<Long> epochs = new ArrayList<>();
        epochs.add(1L);
        epochs.add(2L);
        epochs.add(3L);
        epochs.add(4L);
        epochs.add(5L);
        tableCache.evictCache(epochs);
        // We should totalCount - deleted entries in cache.
        assertEquals(totalCount - deleted, tableCache.size());
        // Check if we have remaining entries.
        for (int i = 6; i <= totalCount; i++) {
            assertEquals(Integer.toString(i), tableCache.get(new CacheKey<>(Integer.toString(i))).getCacheValue());
        }
        epochs = new ArrayList<>();
        for (long i = 6; i <= totalCount; i++) {
            epochs.add(i);
        }
        tableCache.evictCache(epochs);
        // Cleaned up all entries, so cache size should be zero.
        assertEquals(0, tableCache.size());
    } else {
        ArrayList<Long> epochs = new ArrayList<>();
        for (long i = 0; i <= totalCount; i++) {
            epochs.add(i);
        }
        tableCache.evictCache(epochs);
        assertEquals(totalCount, tableCache.size());
    }
}

