@Test
public void builderWithColumnFamilyOptions(@TempDir Path tempDir) throws Exception {
    OzoneConfiguration conf = new OzoneConfiguration();
    conf.set(HddsConfigKeys.OZONE_METADATA_DIRS, tempDir.toString());
    File newFolder = new File(tempDir.toString() + "/newFolder");
    if (!newFolder.exists()) {
        assertTrue(newFolder.mkdirs());
    }
    String sampleTableName = "sampleTable";
    final DBColumnFamilyDefinition<String, Long> sampleTable = new DBColumnFamilyDefinition<>(sampleTableName, String.class, StringCodec.get(), Long.class, LongCodec.get());
    final DBDefinition sampleDB = new DBDefinition.WithMap(DBColumnFamilyDefinition.newUnmodifiableMap(sampleTable)) {

        {
            ManagedColumnFamilyOptions cfOptions = new ManagedColumnFamilyOptions();
            // reverse the default option for check
            cfOptions.setForceConsistencyChecks(!cfOptions.forceConsistencyChecks());
            sampleTable.setCfOptions(cfOptions);
        }

        @Override
        public String getName() {
            return "sampleDB";
        }

        @Override
        public String getLocationConfigKey() {
            return null;
        }

        @Override
        public File getDBLocation(ConfigurationSource conf) {
            return null;
        }
    };
    try (DBStore dbStore = DBStoreBuilder.newBuilder(conf, sampleDB).setName("SampleStore").setPath(newFolder.toPath()).build()) {
        assertInstanceOf(RDBStore.class, dbStore);
        RDBStore rdbStore = (RDBStore) dbStore;
        Collection<RocksDatabase.ColumnFamily> cfFamilies = rdbStore.getColumnFamilies();
        // we also have the default column family, so there are 2
        assertEquals(2, cfFamilies.size());
        boolean checked = false;
        for (RocksDatabase.ColumnFamily cfFamily : cfFamilies) {
            if (Arrays.equals(cfFamily.getHandle().getName(), sampleTableName.getBytes(StandardCharsets.UTF_8))) {
                // get the default value
                boolean defaultValue = new ManagedColumnFamilyOptions().forceConsistencyChecks();
                // the value should be different from the default value
                assertNotEquals(cfFamily.getHandle().getDescriptor().getOptions().forceConsistencyChecks(), defaultValue);
                checked = true;
            }
        }
        assertTrue(checked);
    }
}

