        final TypedTable<String, String> typedTable = new TypedTable<>(testTable, CodecRegistry.newBuilder().build(), String.class, String.class);
        for (int i = 0; i < 20; i++) {
            final int valueSize = TypedTable.BUFFER_SIZE_DEFAULT * i / 4;
