@Test
public void testTypedTableWithCacheWithFewDeletedOperationType() throws Exception {
    int iterCount = 10;
    try (Table<String, String> testTable = createTypedTable("Seven")) {
        for (int x = 0; x < iterCount; x++) {
            String key = Integer.toString(x);
            String value = Integer.toString(x);
            if (x % 2 == 0) {
                testTable.addCacheEntry(new CacheKey<>(key), CacheValue.get(x, value));
            } else {
                testTable.addCacheEntry(new CacheKey<>(key), CacheValue.get(x));
            }
        }
        // As we have added to cache, so get should return value even if it
        // does not exist in DB.
        for (int x = 0; x < iterCount; x++) {
            if (x % 2 == 0) {
                assertEquals(Integer.toString(x), testTable.get(Integer.toString(x)));
            } else {
                assertNull(testTable.get(Integer.toString(x)));
            }
        }
        ArrayList<Long> epochs = new ArrayList<>();
        for (long i = 0; i <= 5L; i++) {
            epochs.add(i);
        }
        testTable.cleanupCache(epochs);
        GenericTestUtils.waitFor(() -> ((TypedTable<String, String>) testTable).getCache().size() == 4, 100, 5000);
        //Check remaining values
        for (int x = 6; x < iterCount; x++) {
            if (x % 2 == 0) {
                assertEquals(Integer.toString(x), testTable.get(Integer.toString(x)));
            } else {
                assertNull(testTable.get(Integer.toString(x)));
            }
        }
    }
}

