@Test
public void testDownloadDBSnapshotFromLeader() throws Exception {
    File candidateDir = rdbSnapshotProvider.getCandidateDir();
    assertTrue(candidateDir.exists());
    DBCheckpoint checkpoint;
    int before = HAUtils.getExistingSstFiles(rdbSnapshotProvider.getCandidateDir()).size();
    assertEquals(0, before);
    // Get first snapshot
    checkpoint = rdbSnapshotProvider.downloadDBSnapshotFromLeader(LEADER_ID);
    File checkpointDir = checkpoint.getCheckpointLocation().toFile();
    assertEquals(candidateDir, checkpointDir);
    int first = HAUtils.getExistingSstFiles(rdbSnapshotProvider.getCandidateDir()).size();
    // Get second snapshot
    checkpoint = rdbSnapshotProvider.downloadDBSnapshotFromLeader(LEADER_ID);
    int second = HAUtils.getExistingSstFiles(rdbSnapshotProvider.getCandidateDir()).size();
    assertThat(second).withFailMessage("The second snapshot should have more SST files").isGreaterThan(first);
    DBCheckpoint latestCheckpoint = latestCK.get();
    compareDB(latestCheckpoint.getCheckpointLocation().toFile(), checkpoint.getCheckpointLocation().toFile(), NUM_USED_CF);
    // Get third snapshot
    checkpoint = rdbSnapshotProvider.downloadDBSnapshotFromLeader(LEADER_ID);
    int third = HAUtils.getExistingSstFiles(rdbSnapshotProvider.getCandidateDir()).size();
    assertThat(third).withFailMessage("The third snapshot should have more SST files").isGreaterThan(second);
    compareDB(latestCK.get().getCheckpointLocation().toFile(), checkpoint.getCheckpointLocation().toFile(), NUM_USED_CF);
    // Test cleanup candidateDB
    rdbSnapshotProvider.init();
    assertEquals(0, HAUtils.getExistingSstFiles(rdbSnapshotProvider.getCandidateDir()).size());
}

@Test
public void testCheckLeaderConsistency() throws IOException {
    // Leader initialized to null at startup.
    assertEquals(1, rdbSnapshotProvider.getInitCount());
    File dummyFile = new File(rdbSnapshotProvider.getCandidateDir(), "file1.sst");
    Files.write(dummyFile.toPath(), "dummyData".getBytes(StandardCharsets.UTF_8));
    assertTrue(dummyFile.exists());
    // Set the leader.
    rdbSnapshotProvider.checkLeaderConsistency("node1");
    assertEquals(2, rdbSnapshotProvider.getInitCount());
    assertFalse(dummyFile.exists());
    // Confirm setting the same leader doesn't reinitialize.
    rdbSnapshotProvider.checkLeaderConsistency("node1");
    assertEquals(2, rdbSnapshotProvider.getInitCount());
    // Confirm setting different leader does reinitialize.
    rdbSnapshotProvider.checkLeaderConsistency("node2");
    assertEquals(3, rdbSnapshotProvider.getInitCount());
}

