@ParameterizedTest(name = "{0}")
@MethodSource("casesGetSSTDiffListWithoutDB")
@SuppressWarnings("parameternumber")
public void testGetSSTDiffListWithoutDB(String description, String compactionLog, List<CompactionLogEntry> compactionLogEntries, DifferSnapshotInfo srcSnapshot, DifferSnapshotInfo destSnapshot, Set<String> srcSnapshotSstFiles, Set<String> destSnapshotSstFiles, Set<String> expectedSameSstFiles, Set<String> expectedDiffSstFiles, boolean expectingException) {
    boolean exceptionThrown = false;
    if (compactionLog != null) {
        // Construct DAG from compaction log input
        Arrays.stream(compactionLog.split("\n")).forEach(rocksDBCheckpointDiffer::processCompactionLogLine);
    } else if (compactionLogEntries != null) {
        compactionLogEntries.forEach(entry -> rocksDBCheckpointDiffer.addToCompactionLogTable(entry));
    } else {
        throw new IllegalArgumentException("One of compactionLog and " + "compactionLogEntries should be non-null.");
    }
    rocksDBCheckpointDiffer.loadAllCompactionLogs();
    Set<String> actualSameSstFiles = new HashSet<>();
    Set<String> actualDiffSstFiles = new HashSet<>();
    try {
        rocksDBCheckpointDiffer.internalGetSSTDiffList(srcSnapshot, destSnapshot, srcSnapshotSstFiles, destSnapshotSstFiles, actualSameSstFiles, actualDiffSstFiles);
    } catch (RuntimeException rtEx) {
        if (!expectingException) {
            fail("Unexpected exception thrown in test.");
        } else {
            exceptionThrown = true;
        }
    }
    // Check same and different SST files result
    assertEquals(expectedSameSstFiles, actualSameSstFiles);
    assertEquals(expectedDiffSstFiles, actualDiffSstFiles);
