@Test
public void containerMoveSelectionShouldFollowPlacementPolicy() throws IllegalContainerBalancerStateException, IOException, InvalidContainerBalancerConfigurationException, TimeoutException {
    balancerConfiguration.setThreshold(10);
    balancerConfiguration.setMaxSizeToMovePerIteration(50 * STORAGE_UNIT);
    balancerConfiguration.setMaxDatanodesPercentageToInvolvePerIteration(100);
    balancerConfiguration.setIterations(1);
    startBalancer(balancerConfiguration);
    stopBalancer();
    Map<ContainerID, DatanodeDetails> containerFromSourceMap = containerBalancerTask.getContainerToSourceMap();
    Map<ContainerID, DatanodeDetails> containerToTargetMap = containerBalancerTask.getContainerToTargetMap();
    // for each move selection, check if {replicas - source + target}
    // satisfies placement policy
    for (Map.Entry<ContainerID, DatanodeDetails> entry : containerFromSourceMap.entrySet()) {
        ContainerID container = entry.getKey();
        DatanodeDetails source = entry.getValue();
        List<DatanodeDetails> replicas = cidToReplicasMap.get(container).stream().map(ContainerReplica::getDatanodeDetails).collect(Collectors.toList());
        // remove source and add target
        replicas.remove(source);
        replicas.add(containerToTargetMap.get(container));
        ContainerInfo containerInfo = cidToInfoMap.get(container);
        ContainerPlacementStatus placementStatus;
        if (containerInfo.getReplicationType() == HddsProtos.ReplicationType.RATIS) {
            placementStatus = placementPolicy.validateContainerPlacement(replicas, containerInfo.getReplicationConfig().getRequiredNodes());
        } else {
            placementStatus = ecPlacementPolicy.validateContainerPlacement(replicas, containerInfo.getReplicationConfig().getRequiredNodes());
        }
        assertTrue(placementStatus.isPolicySatisfied());
    }
}

