    assertEquals(ContainerBalancerTask.IterationResult.ITERATION_COMPLETED, containerBalancerTask.getIterationResult());
    assertEquals(1, containerBalancerTask.getMetrics().getNumContainerMovesCompletedInLatestIteration());
    assertThat(containerBalancerTask.getMetrics().getNumContainerMovesTimeoutInLatestIteration()).isGreaterThan(1);
    stopBalancer();
}

