@ParameterizedTest
@ValueSource(ints = { 12, 13, 14 })
public void testFallback(int datanodeCount) throws SCMException {
    // 5 replicas. there are only 3 racks. policy with fallback should
    // allocate the 5th datanode though it will break the rack rule(first
    // 2 replicas on same rack, others on different racks).
    assumeTrue(datanodeCount > NODE_PER_RACK * 2 && (datanodeCount % NODE_PER_RACK > 1));
    setup(datanodeCount);
    int nodeNum = 5;
    List<DatanodeDetails> datanodeDetails = policy.chooseDatanodes(null, null, nodeNum, 0, 15);
    assertEquals(nodeNum, datanodeDetails.size());
    assertTrue(cluster.isSameParent(datanodeDetails.get(0), datanodeDetails.get(1)));
    assertFalse(cluster.isSameParent(datanodeDetails.get(0), datanodeDetails.get(2)));
    assertFalse(cluster.isSameParent(datanodeDetails.get(1), datanodeDetails.get(2)));
    assertFalse(cluster.isSameParent(datanodeDetails.get(0), datanodeDetails.get(3)));
    assertFalse(cluster.isSameParent(datanodeDetails.get(2), datanodeDetails.get(3)));
    // get metrics
    long totalRequest = metrics.getDatanodeRequestCount();
    long successCount = metrics.getDatanodeChooseSuccessCount();
    long tryCount = metrics.getDatanodeChooseAttemptCount();
    long compromiseCount = metrics.getDatanodeChooseFallbackCount();
    // verify metrics
    assertEquals(totalRequest, nodeNum);
    assertEquals(successCount, nodeNum);
    assertThat(tryCount).isGreaterThan(nodeNum);
    assertThat(compromiseCount).isGreaterThanOrEqualTo(1);
}

@ParameterizedTest
@ValueSource(ints = { 11, 12, 13, 14, 15 })
public void testNoFallback(int datanodeCount) {
    assumeTrue(datanodeCount > (NODE_PER_RACK * 2) && (datanodeCount <= NODE_PER_RACK * 3));
    setup(datanodeCount);
    // 5 replicas. there are only 3 racks. policy prohibit fallback should fail.
    int nodeNum = 5;
    Exception e = assertThrows(Exception.class, () -> policyNoFallback.chooseDatanodes(null, null, nodeNum, 0, 15), "Fallback prohibited, this call should fail");
    assertEquals("SCMException", e.getClass().getSimpleName());
    // get metrics
    long totalRequest = metrics.getDatanodeRequestCount();
    long successCount = metrics.getDatanodeChooseSuccessCount();
    long tryCount = metrics.getDatanodeChooseAttemptCount();
    long compromiseCount = metrics.getDatanodeChooseFallbackCount();
    assertEquals(nodeNum, totalRequest);
    assertThat(successCount).withFailMessage("Not enough success count").isGreaterThanOrEqualTo(1);
    assertThat(tryCount).withFailMessage("Not enough try count").isGreaterThanOrEqualTo(1);
    assertEquals(0, compromiseCount);
}

