    containerReplicas.add(openReplica);
    ContainerCheckRequest request = new ContainerCheckRequest.Builder().setPendingOps(Collections.emptyList()).setReport(new ReplicationManagerReport()).setContainerInfo(containerInfo).setContainerReplicas(containerReplicas).build();
    ContainerCheckRequest readRequest = new ContainerCheckRequest.Builder().setPendingOps(Collections.emptyList()).setReport(new ReplicationManagerReport()).setContainerInfo(containerInfo).setContainerReplicas(containerReplicas).setReadOnly(true).build();
    assertFalse(quasiClosedContainerHandler.handle(request));
    assertFalse(quasiClosedContainerHandler.handle(readRequest));
    verify(replicationManager, times(2)).sendCloseContainerReplicaCommand(any(), any(), anyBoolean());
}

