/**
 * If it's possible to force close replicas then only replicas with the
 * highest Sequence ID (also known as BCSID) should be closed.
 */
@Test
public void testReplicasWithHighestBCSIDAreClosed() {
    final ContainerInfo containerInfo = getContainer(HddsProtos.LifeCycleState.QUASI_CLOSED);
    containerInfo.setUsedBytes(99);
    final ContainerID id = containerInfo.containerID();
    // create replicas with unique origin DNs
    DatanodeDetails dnOne = randomDatanodeDetails();
    DatanodeDetails dnTwo = randomDatanodeDetails();
    DatanodeDetails dnThree = randomDatanodeDetails();
    // 1001 is the highest sequence id
    final ContainerReplica replicaOne = getReplicas(id, State.QUASI_CLOSED, 1000L, dnOne.getUuid(), dnOne);
    final ContainerReplica replicaTwo = getReplicas(id, State.QUASI_CLOSED, 1001L, dnTwo.getUuid(), dnTwo);
    final ContainerReplica replicaThree = getReplicas(id, State.QUASI_CLOSED, 1001L, dnThree.getUuid(), dnThree);
    Set<ContainerReplica> containerReplicas = new HashSet<>();
    containerReplicas.add(replicaOne);
    containerReplicas.add(replicaTwo);
    containerReplicas.add(replicaThree);
    ContainerCheckRequest request = new ContainerCheckRequest.Builder().setPendingOps(Collections.emptyList()).setReport(new ReplicationManagerReport()).setContainerInfo(containerInfo).setContainerReplicas(containerReplicas).build();
    ContainerCheckRequest readRequest = new ContainerCheckRequest.Builder().setPendingOps(Collections.emptyList()).setReport(new ReplicationManagerReport()).setContainerInfo(containerInfo).setContainerReplicas(containerReplicas).setReadOnly(true).build();
    assertFalse(quasiClosedContainerHandler.handle(request));
    assertFalse(quasiClosedContainerHandler.handle(readRequest));
    // verify close command was sent for replicas with sequence ID 1001, that
    // is dnTwo and dnThree
    verify(replicationManager, times(1)).sendCloseContainerReplicaCommand(eq(containerInfo), eq(dnTwo), anyBoolean());
    verify(replicationManager, times(1)).sendCloseContainerReplicaCommand(eq(containerInfo), eq(dnThree), anyBoolean());
}

