@Test
public void testSufficientlyReplicatedForOffline() {
    Set<ContainerReplica> replica = ReplicationTestUtil.createReplicas(Pair.of(IN_SERVICE, 2));
    ContainerReplica inServiceReplica = ReplicationTestUtil.createContainerReplica(container.containerID(), 1, IN_SERVICE, CLOSED);
    replica.add(inServiceReplica);
    ContainerReplica offlineReplica = ReplicationTestUtil.createContainerReplica(container.containerID(), 1, DECOMMISSIONING, CLOSED);
    replica.add(offlineReplica);
    ContainerReplica offlineNotReplicated = ReplicationTestUtil.createContainerReplica(container.containerID(), 3, DECOMMISSIONING, CLOSED);
    replica.add(offlineNotReplicated);
    ECContainerReplicaCount rcnt = new ECContainerReplicaCount(container, replica, Collections.emptyList(), 1);
    assertFalse(rcnt.isSufficientlyReplicated(false));
    assertTrue(rcnt.isSufficientlyReplicatedForOffline(offlineReplica.getDatanodeDetails(), null));
    assertFalse(rcnt.isSufficientlyReplicatedForOffline(offlineNotReplicated.getDatanodeDetails(), null));
    // A random DN not hosting a replica for this container should return false.
    assertFalse(rcnt.isSufficientlyReplicatedForOffline(MockDatanodeDetails.randomDatanodeDetails(), null));
    // Passing the IN_SERVICE node should return false even though the
    // replica is on a healthy node
    assertFalse(rcnt.isSufficientlyReplicatedForOffline(inServiceReplica.getDatanodeDetails(), null));
}

