@Test
public void testUnderReplicationWithDecomIndexAndMaintOnSameIndex() throws IOException {
    Set<ContainerReplica> availableReplicas = new LinkedHashSet<>();
    ContainerReplica deadMaintenance = createContainerReplica(container.containerID(), 1, IN_MAINTENANCE, CLOSED);
    availableReplicas.add(deadMaintenance);
    nodeManager = new MockNodeManager(true, 10) {

        @Override
        public NodeStatus getNodeStatus(DatanodeDetails dd) {
            if (dd.equals(deadMaintenance.getDatanodeDetails())) {
                return new NodeStatus(dd.getPersistedOpState(), HddsProtos.NodeState.DEAD);
            }
            return new NodeStatus(dd.getPersistedOpState(), HddsProtos.NodeState.HEALTHY, 0);
        }
    };
    availableReplicas.addAll(ReplicationTestUtil.createReplicas(Pair.of(DECOMMISSIONING, 1), Pair.of(IN_MAINTENANCE, 2), Pair.of(IN_SERVICE, 3), Pair.of(IN_SERVICE, 4), Pair.of(IN_SERVICE, 5)));
    // Note that maintenanceIndexes is set to zero as we do not expect any
    // maintenance commands to be created, as they are solved by the earlier
    // decommission command.
    Set<Pair<DatanodeDetails, SCMCommand<?>>> cmds = testUnderReplicationWithMissingIndexes(Lists.emptyList(), availableReplicas, 1, 0, policy);
    assertEquals(1, cmds.size());
    // Check the replicate command has index 1 set
    for (Pair<DatanodeDetails, SCMCommand<?>> c : cmds) {
        // Ensure neither of the commands are for the dead maintenance node
        assertNotEquals(deadMaintenance.getDatanodeDetails(), c.getKey());
    }
}

