@Test
public void testUnderRepSentToOverRepHandlerIfNoNewNodes() throws IOException {
    PlacementPolicy noNodesPolicy = ReplicationTestUtil.getNoNodesTestPlacementPolicy(nodeManager, conf);
    ContainerReplica overRepReplica = createContainerReplica(container.containerID(), 4, IN_SERVICE, CLOSED);
    ContainerReplica decomReplica = createContainerReplica(container.containerID(), 5, DECOMMISSIONING, CLOSED);
    ContainerReplica maintReplica = createContainerReplica(container.containerID(), 5, ENTERING_MAINTENANCE, CLOSED);
    List<ContainerReplica> replicasToAdd = new ArrayList<>();
    replicasToAdd.add(null);
    replicasToAdd.add(decomReplica);
    replicasToAdd.add(maintReplica);
    ECUnderReplicationHandler ecURH = new ECUnderReplicationHandler(noNodesPolicy, conf, replicationManager);
    UnderReplicatedHealthResult underRep = new UnderReplicatedHealthResult(container, 1, false, false, false);
    // The underRepHandler processes in stages. First missing indexes, then
    // decommission and then maintenance. If a stage cannot find new nodes and
    // there are no commands created yet, then we should either throw, or pass
    // control to the over rep handler if the container is also over replicated.
    // In this loop we first have the container under replicated with a missing
    // index, then with an under-rep index, and finally with a maintenance
    // index. In all cases, initially have it not over replicated, so it should
    // throw an exception, and then make it also over replicated, returning the
    // commands to fix the over replication instead.
    for (ContainerReplica toAdd : replicasToAdd) {
        clearInvocations(replicationManager);
        Set<ContainerReplica> availableReplicas = createReplicas(4);
        if (toAdd != null) {
            availableReplicas.add(toAdd);
        }
        assertThrows(SCMException.class, () -> ecURH.processAndSendCommands(availableReplicas, emptyList(), underRep, 2));
        // Now adjust replicas so it is also over replicated. This time before
        // throwing it should call the OverRepHandler and return whatever it
        // returns, which in this case is a delete command for replica index 4.
        availableReplicas.add(overRepReplica);
        assertThrows(SCMException.class, () -> ecURH.processAndSendCommands(availableReplicas, emptyList(), underRep, 2));
        verify(replicationManager, times(1)).processOverReplicatedContainer(underRep);
    }
}

/**
 * Tests that under replication handling tries to delete an UNHEALTHY
 * replica if no target datanodes are found. It should delete only
 * one UNHEALTHY replica so that the replica's host DN becomes available as a
 * target for reconstruction/replication of a healthy replica.
 */
@Test
public void testUnhealthyNodeDeletedIfNoTargetsFound() throws IOException {
    PlacementPolicy noNodesPolicy = ReplicationTestUtil.getNoNodesTestPlacementPolicy(nodeManager, conf);
    ContainerReplica decomReplica = createContainerReplica(container.containerID(), 5, DECOMMISSIONING, CLOSED);
    ContainerReplica maintReplica = createContainerReplica(container.containerID(), 5, ENTERING_MAINTENANCE, CLOSED);
    List<ContainerReplica> replicasToAdd = new ArrayList<>();
    replicasToAdd.add(null);
    replicasToAdd.add(decomReplica);
    replicasToAdd.add(maintReplica);
    ECUnderReplicationHandler ecURH = new ECUnderReplicationHandler(noNodesPolicy, conf, replicationManager);
    UnderReplicatedHealthResult underRep = new UnderReplicatedHealthResult(container, 1, false, false, false);
    ContainerReplica unhealthyReplica = createContainerReplica(container.containerID(), 4, IN_SERVICE, UNHEALTHY);
    /*
     The underRepHandler processes in stages. First missing indexes, then
     decommission and then maintenance. If a stage cannot find new nodes and
     there are no commands created yet, then we should either throw, or pass
     control to the over rep handler if the container is also over
     replicated, or try to delete an UNHEALTHY replica if one is present.
     In this loop we first have the container under replicated with a missing
     index, then with a decommissioning index, and finally with a maintenance
     index. In all cases, initially there are no UNHEALTHY replicas, so it
     should throw an exception. Then we add 2 UNHEALTHY replicas, so
     it should return the command to delete one.
     */
    for (ContainerReplica toAdd : replicasToAdd) {
        clearInvocations(replicationManager);
        Set<ContainerReplica> existingReplicas = ReplicationTestUtil.createReplicas(Pair.of(IN_SERVICE, 5), Pair.of(IN_SERVICE, 2), Pair.of(IN_SERVICE, 3), Pair.of(IN_SERVICE, 4));
        if (toAdd != null) {
            existingReplicas.add(toAdd);
        }
        // should throw an SCMException indicating no targets were found
        assertThrows(SCMException.class, () -> ecURH.processAndSendCommands(existingReplicas, emptyList(), underRep, 2));
        verify(replicationManager, times(0)).sendThrottledDeleteCommand(eq(container), anyInt(), any(DatanodeDetails.class), anyBoolean());
        /*
      Now, for the same container, also add an UNHEALTHY replica. The handler
      should catch the SCMException that says no targets were found and try
      to handle it by deleting the UNHEALTHY replica.
      */
        existingReplicas.add(unhealthyReplica);
        existingReplicas.add(createContainerReplica(container.containerID(), 1, IN_SERVICE, UNHEALTHY));
        /*
      Mock such that when replication manager is called to send a delete
      command, we add the command to commandsSet and later use it for
      assertions.
      */
        commandsSent.clear();
        doAnswer(invocation -> {
            commandsSent.add(Pair.of(invocation.getArgument(2), createDeleteContainerCommand(invocation.getArgument(0), invocation.getArgument(1))));
            return null;
        }).when(replicationManager).sendThrottledDeleteCommand(any(ContainerInfo.class), anyInt(), any(DatanodeDetails.class), eq(true));
        assertThrows(SCMException.class, () -> ecURH.processAndSendCommands(existingReplicas, emptyList(), underRep, 2));
        verify(replicationManager, times(1)).sendThrottledDeleteCommand(container, unhealthyReplica.getReplicaIndex(), unhealthyReplica.getDatanodeDetails(), true);
        assertEquals(1, commandsSent.size());
        Pair<DatanodeDetails, SCMCommand<?>> command = commandsSent.iterator().next();
        assertEquals(SCMCommandProto.Type.deleteContainerCommand, command.getValue().getType());
        DeleteContainerCommand deleteCommand = (DeleteContainerCommand) command.getValue();
        assertEquals(unhealthyReplica.getDatanodeDetails(), command.getKey());
        assertEquals(container.containerID(), ContainerID.valueOf(deleteCommand.getContainerID()));
        assertEquals(unhealthyReplica.getReplicaIndex(), deleteCommand.getReplicaIndex());
    }
}

