    UnderReplicatedHealthResult underRep = new UnderReplicatedHealthResult(container, 1, false, false, false);
    // The underRepHandler processes in stages. First missing indexes, then
    // decommission and then maintenance. If a stage fails due to no new nodes
    // available and there are some commands created by an earlier stage, we
    // should just return those created commands even if the container is over
    // replicated.
    for (ContainerReplica toAdd : replicasToAdd) {
        // The replicas are always over replicated with 2 index 4's.
        // Index 1 is missing, then we add in either a decommissioning or
        // entering_maintenance replica 5.
        Set<ContainerReplica> availableReplicas = ReplicationTestUtil.createReplicas(Pair.of(IN_SERVICE, 2), Pair.of(IN_SERVICE, 3), Pair.of(IN_SERVICE, 4), Pair.of(IN_SERVICE, 4));
        if (toAdd != null) {
            availableReplicas.add(toAdd);
        }
        assertThrows(SCMException.class, () -> ecURH.processAndSendCommands(availableReplicas, emptyList(), underRep, 2));
        verify(replicationManager, times(1)).processOverReplicatedContainer(underRep);
        assertEquals(1, commandsSent.size());
        Pair<DatanodeDetails, SCMCommand<?>> pair = commandsSent.iterator().next();
        assertEquals(newNode, pair.getKey());
        assertEquals(SCMCommandProto.Type.reconstructECContainersCommand, pair.getValue().getType());
        clearInvocations(replicationManager);
        commandsSent.clear();
    }
}

@Test
public void testUnderRepDueToDecomAndOverRep() throws IOException {
    PlacementPolicy sameNodePolicy = ReplicationTestUtil.getNoNodesTestPlacementPolicy(nodeManager, conf);
    // First it is under-replicated, due to decom index 5, but no mode will be
    // found. This will cause an exception to be thrown out, as the container is
    // not also over replicated.
    Set<ContainerReplica> availableReplicas = ReplicationTestUtil.createReplicas(Pair.of(IN_SERVICE, 1), Pair.of(IN_SERVICE, 2), Pair.of(IN_SERVICE, 3), Pair.of(IN_SERVICE, 4), Pair.of(DECOMMISSIONING, 5));
