    });
    assertThrows(SCMException.class, () -> ecURH.processAndSendCommands(availableReplicas, emptyList(), underRep, 1));
    verify(replicationManager, times(1)).processOverReplicatedContainer(underRep);
    assertEquals(expectedDelete, commandsSent);
}

