    assertEquals(1, report.getStat(ReplicationManagerReport.HealthState.QUASI_CLOSED_STUCK));
}

/**
 * 2 quasi-closed replicas.
 * 1 unhealthy replica.
 * All replicas have same origin node ID.
 * Expectation:
 *    Round 1: Quasi closed replica is replicated.
 *    Round 2: Unhealthy replica is deleted.
 *
 * When a container is QUASI_CLOSED and we don't have quorum to force close
 * the container, the container should have all the replicas in QUASI_CLOSED
 * state, else ReplicationManager will take action.
 *
 * In this test case we make one of the replica unhealthy, replication
 * manager will send delete container command to the datanode which has the
 * unhealthy replica.
 */
@Test
public void testQuasiClosedContainerWithUnhealthyReplica() throws IOException, TimeoutException {
    final ContainerInfo container = getContainer(LifeCycleState.QUASI_CLOSED);
    container.setUsedBytes(100);
    final ContainerID id = container.containerID();
    final UUID originNodeId = UUID.randomUUID();
    final ContainerReplica replicaOne = getReplicas(id, QUASI_CLOSED, 1000L, originNodeId, randomDatanodeDetails());
    final ContainerReplica replicaTwo = getReplicas(id, QUASI_CLOSED, 1000L, originNodeId, randomDatanodeDetails());
    final ContainerReplica replicaThree = getReplicas(id, QUASI_CLOSED, 1000L, originNodeId, randomDatanodeDetails());
    containerStateManager.addContainer(container.getProtobuf());
    containerStateManager.updateContainerReplica(id, replicaOne);
    containerStateManager.updateContainerReplica(id, replicaTwo);
    containerStateManager.updateContainerReplica(id, replicaThree);
    int currentReplicateCommandCount = datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.replicateContainerCommand);
    // All the QUASI_CLOSED replicas have same originNodeId, so the
    // container will not be closed. ReplicationManager should take no action.
    replicationManager.processAll();
    eventQueue.processAll(1000);
    assertEquals(0, datanodeCommandHandler.getInvocation());
    // Make the first replica unhealthy
    final ContainerReplica unhealthyReplica = getReplicas(id, UNHEALTHY, 1000L, originNodeId, replicaOne.getDatanodeDetails());
    containerStateManager.updateContainerReplica(id, unhealthyReplica);
    long currentBytesToReplicate = replicationManager.getMetrics().getReplicationBytesTotal();
    replicationManager.processAll();
    eventQueue.processAll(1000);
    // Under replication handler should first re-replicate one of the quasi
    // closed containers.
    // The unhealthy container should not have been deleted in the first pass.
    assertDeleteScheduled(0);
    currentReplicateCommandCount += 1;
    currentBytesToReplicate += 100L;
    assertEquals(currentReplicateCommandCount, datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.replicateContainerCommand));
    assertEquals(currentReplicateCommandCount, replicationManager.getMetrics().getReplicationCmdsSentTotal());
    assertEquals(currentBytesToReplicate, replicationManager.getMetrics().getReplicationBytesTotal());
    assertEquals(1, getInflightCount(InflightType.REPLICATION));
    assertEquals(1, replicationManager.getMetrics().getInflightReplication());
    // The quasi closed container cannot be closed, but it should have been
    // restored to full replication on the previous run.
    // The unhealthy replica should remain until the next iteration.
    ReplicationManagerReport report = replicationManager.getContainerReport();
    assertEquals(1, report.getStat(LifeCycleState.QUASI_CLOSED));
    assertEquals(1, report.getStat(ReplicationManagerReport.HealthState.QUASI_CLOSED_STUCK));
    assertEquals(0, report.getStat(ReplicationManagerReport.HealthState.UNDER_REPLICATED));
    assertEquals(1, report.getStat(ReplicationManagerReport.HealthState.UNHEALTHY));
    // Create the replica so replication manager sees it on the next run.
    List<CommandForDatanode> replicateCommands = datanodeCommandHandler.getReceivedCommands().stream().filter(c -> c.getCommand().getType().equals(SCMCommandProto.Type.replicateContainerCommand)).collect(Collectors.toList());
    for (CommandForDatanode replicateCommand : replicateCommands) {
        DatanodeDetails newNode = createDatanodeDetails(replicateCommand.getDatanodeId());
        ContainerReplica newReplica = getReplicas(id, QUASI_CLOSED, 1000L, originNodeId, newNode);
        containerStateManager.updateContainerReplica(id, newReplica);
    }
    // On the next run, the unhealthy container should be scheduled for
    // deletion, since the quasi closed container is now sufficiently
    // replicated.
    // This method runs an iteration of replication manager.
    assertDeleteScheduled(1);
    assertExactDeleteTargets(unhealthyReplica.getDatanodeDetails());
    // Replication should have finished on the previous iteration, leaving
    // these numbers unchanged.
    assertEquals(currentReplicateCommandCount, datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.replicateContainerCommand));
    assertEquals(currentReplicateCommandCount, replicationManager.getMetrics().getReplicationCmdsSentTotal());
    assertEquals(currentBytesToReplicate, replicationManager.getMetrics().getReplicationBytesTotal());
    assertEquals(0, getInflightCount(InflightType.REPLICATION));
    assertEquals(0, replicationManager.getMetrics().getInflightReplication());
    // Now we will delete the unhealthy replica.
    containerStateManager.removeContainerReplica(id, unhealthyReplica);
    // There should be no work left on the following runs.
    replicationManager.processAll();
    eventQueue.processAll(1000);
    // The two commands shown are the previous delete and replicate commands.
    assertEquals(2, datanodeCommandHandler.getInvocation());
}

/**
 * Container is quasi closed.
 * 3 quasi-closed replicas with the same origin node ID.
 * 1 unhealthy replica with unique origin node ID.
 *
 * Expectation:
 * No action taken. 3 healthy replicas are present. The unhealthy replica
 * should not be deleted since it has a unique origin node ID. The
 * container cannot be closed because there are not enough healthy unique
 * origin node IDs.
 */
@Test
public void testQuasiClosedContainerWithUniqueUnhealthyReplica() throws IOException, TimeoutException {
    final ContainerInfo container = getContainer(LifeCycleState.QUASI_CLOSED);
    container.setUsedBytes(100);
    final ContainerID id = container.containerID();
    final UUID originNodeId = UUID.randomUUID();
    final ContainerReplica replicaOne = getReplicas(id, QUASI_CLOSED, 1000L, originNodeId, randomDatanodeDetails());
    final ContainerReplica replicaTwo = getReplicas(id, QUASI_CLOSED, 1000L, originNodeId, randomDatanodeDetails());
    final ContainerReplica replicaThree = getReplicas(id, QUASI_CLOSED, 1000L, originNodeId, randomDatanodeDetails());
    final ContainerReplica replica4 = getReplicas(id, UNHEALTHY, 1000L, randomDatanodeDetails().getUuid(), randomDatanodeDetails());
    containerStateManager.addContainer(container.getProtobuf());
    containerStateManager.updateContainerReplica(id, replicaOne);
    containerStateManager.updateContainerReplica(id, replicaTwo);
    containerStateManager.updateContainerReplica(id, replicaThree);
    containerStateManager.updateContainerReplica(id, replica4);
    replicationManager.processAll();
    eventQueue.processAll(1000);
    assertEquals(0, datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.replicateContainerCommand));
    assertEquals(0, datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.deleteContainerCommand));
    // now, add a copy of the UNHEALTHY replica on a decommissioning node,
    // and another on a dead node. The expectation is still that no replica
    // should be deleted as both these nodes are likely going away soon.
    final ContainerReplica replica5 = getReplicas(id, UNHEALTHY, 1000L, replica4.getOriginDatanodeId(), randomDatanodeDetails());
    nodeManager.register(replica5.getDatanodeDetails(), new NodeStatus(DECOMMISSIONING, HEALTHY));
    DatanodeDetails deadNode = randomDatanodeDetails();
    nodeManager.register(deadNode, NodeStatus.inServiceDead());
    final ContainerReplica replica6 = getReplicas(id, UNHEALTHY, 1000L, replica4.getOriginDatanodeId(), deadNode);
    containerStateManager.updateContainerReplica(container.containerID(), replica5);
    containerStateManager.updateContainerReplica(container.containerID(), replica6);
    replicationManager.processAll();
    eventQueue.processAll(1000);
    assertEquals(0, datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.replicateContainerCommand));
    assertEquals(0, datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.deleteContainerCommand));
    ReplicationManagerReport report = replicationManager.getContainerReport();
    assertEquals(1, report.getStat(LifeCycleState.QUASI_CLOSED));
    assertEquals(1, report.getStat(ReplicationManagerReport.HealthState.QUASI_CLOSED_STUCK));
    assertEquals(0, report.getStat(ReplicationManagerReport.HealthState.UNDER_REPLICATED));
    // Even though we have extra replicas, we are deliberately keeping them
    // since they are unique. This does not count as over-replication.
    assertEquals(0, report.getStat(ReplicationManagerReport.HealthState.OVER_REPLICATED));
    assertEquals(1, report.getStat(ReplicationManagerReport.HealthState.UNHEALTHY));
}

/**
 * Situation: QUASI_CLOSED container with 3 QUASI_CLOSED replicas
 * whose Sequence ID is smaller than the container's. There are 2
 * UNHEALTHY replicas with Sequence ID same as the container's. One of
 * them is on a decommissioning node.
 *
 * Expectation: Replication command should be sent for the UNHEALTHY
 * replica on the decommissioning node.
 */
@Test
public void testQuasiClosedHavingUnhealthyReplicaWithGreatestBCSID() throws IOException {
    final ContainerInfo container = getContainer(LifeCycleState.QUASI_CLOSED);
    container.setUsedBytes(100);
    final ContainerID id = container.containerID();
    final UUID originNodeId = UUID.randomUUID();
    long sequenceID = container.getSequenceId();
    final ContainerReplica replica1 = getReplicas(id, QUASI_CLOSED, sequenceID - 1, originNodeId, randomDatanodeDetails());
    final ContainerReplica replica2 = getReplicas(id, QUASI_CLOSED, sequenceID - 1, originNodeId, randomDatanodeDetails());
    final ContainerReplica replica3 = getReplicas(id, QUASI_CLOSED, sequenceID - 1, originNodeId, randomDatanodeDetails());
    DatanodeDetails decommissioning = MockDatanodeDetails.randomDatanodeDetails();
    decommissioning.setPersistedOpState(DECOMMISSIONING);
    nodeManager.register(decommissioning, new NodeStatus(DECOMMISSIONING, HEALTHY));
    final ContainerReplica replica4 = getReplicas(id, UNHEALTHY, sequenceID, decommissioning.getUuid(), decommissioning);
    final ContainerReplica replica5 = getReplicas(id, UNHEALTHY, sequenceID, randomDatanodeDetails().getUuid(), randomDatanodeDetails());
    containerStateManager.addContainer(container.getProtobuf());
    containerStateManager.updateContainerReplica(id, replica1);
    containerStateManager.updateContainerReplica(id, replica2);
    containerStateManager.updateContainerReplica(id, replica3);
    containerStateManager.updateContainerReplica(id, replica4);
    containerStateManager.updateContainerReplica(id, replica5);
    replicationManager.processAll();
    eventQueue.processAll(1000);
    // 1 replicate command should have been sent
    assertEquals(1, datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.replicateContainerCommand));
    assertEquals(1, replicationManager.getContainerReport().getStat(ReplicationManagerReport.HealthState.UNDER_REPLICATED));
    // the following code asserts that replicate was sent for the UNHEALTHY
    // replica on the decommissioning node
    CommandForDatanode command = datanodeCommandHandler.getReceivedCommands().iterator().next();
    assertEquals(SCMCommandProto.Type.replicateContainerCommand, command.getCommand().getType());
    ReplicateContainerCommand replicateCommand = (ReplicateContainerCommand) command.getCommand();
    assertEquals(1, replicateCommand.getSourceDatanodes().size());
    assertEquals(replica4.getDatanodeDetails(), replicateCommand.getSourceDatanodes().iterator().next());
    assertEquals(0, datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.deleteContainerCommand));
    // If we don't complete the pending add by the next iteration, it's
    // expected that another replicate command is not sent.
    replicationManager.processAll();
    eventQueue.processAll(100);
    // that 1 command is the one RM sent in the last iteration
    assertEquals(1, datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.replicateContainerCommand));
    assertEquals(0, datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.deleteContainerCommand));
    // Now, we will complete the add. Expectation is that no new commands
    // should be sent in the next iteration.
    ContainerReplica newReplica = getReplicas(container.containerID(), UNHEALTHY, container.getSequenceId(), replica4.getOriginDatanodeId(), MockDatanodeDetails.createDatanodeDetails(command.getDatanodeId()));
    containerStateManager.updateContainerReplica(container.containerID(), newReplica);
    replicationManager.processAll();
    eventQueue.processAll(100);
    // that 1 command is the one RM sent in the last iteration
    assertEquals(1, datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.replicateContainerCommand));
    assertEquals(0, datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.deleteContainerCommand));
}

/**
 * Situation: QUASI_CLOSED container with 2 QUASI_CLOSED replicas
 * whose Sequence ID is smaller than the container's. There's 1
 * UNHEALTHY replica with Sequence ID same as the container's and on a
