/**
 * Test for when a quasi_closed container's under replication cannot be
 * solved because there are UNHEALTHY replicas occupying datanodes.
 */
@Test
public void testUnderRepQuasiClosedContainerBlockedByUnhealthyReplicas() throws IOException, TimeoutException {
    when(ratisContainerPlacementPolicy.chooseDatanodes(anyList(), any(), anyInt(), anyLong(), anyLong())).thenAnswer(invocation -> {
        List<DatanodeDetails> excluded = invocation.getArgument(0);
        if (excluded.size() == 3) {
            throw new SCMException(SCMException.ResultCodes.FAILED_TO_FIND_SUITABLE_NODE);
        } else {
            int nodesRequired = invocation.getArgument(2);
            List<DatanodeDetails> nodes = new ArrayList<>(nodesRequired);
            while (nodesRequired != 0) {
                DatanodeDetails dn = MockDatanodeDetails.randomDatanodeDetails();
                nodeManager.register(dn, NodeStatus.inServiceHealthy());
                nodes.add(dn);
                nodesRequired--;
            }
            return nodes;
        }
    });
    final ContainerInfo container = createContainer(LifeCycleState.QUASI_CLOSED);
    ContainerReplica quasi1 = addReplicaToDn(container, randomDatanodeDetails(), QUASI_CLOSED, container.getSequenceId());
    DatanodeDetails nodeForQuasi2 = MockDatanodeDetails.randomDatanodeDetails();
    nodeManager.register(nodeForQuasi2, NodeStatus.inServiceHealthy());
    ContainerReplica quasi2 = getReplicaBuilder(container.containerID(), QUASI_CLOSED, container.getUsedBytes(), container.getNumberOfKeys(), container.getSequenceId(), quasi1.getOriginDatanodeId(), nodeForQuasi2).build();
    containerStateManager.updateContainerReplica(container.containerID(), quasi2);
    ContainerReplica unhealthy = addReplicaToDn(container, randomDatanodeDetails(), UNHEALTHY, container.getSequenceId());
    // First RM iteration.
    // this container is under replicated by 1 replica.
    // delete command should be sent for unhealthy to unblock under rep
    // handling.
    assertDeleteScheduled(1);
    assertTrue(datanodeCommandHandler.received(SCMCommandProto.Type.deleteContainerCommand, unhealthy.getDatanodeDetails()));
    List<CommandForDatanode> commands = datanodeCommandHandler.getReceivedCommands();
    assertEquals(1, commands.size());
    DeleteContainerCommand deleteContainerCommand = (DeleteContainerCommand) commands.get(0).getCommand();
    assertTrue(deleteContainerCommand.isForce());
    assertUnderReplicatedCount(1);
    // Update RM with the result of delete command
    containerStateManager.removeContainerReplica(container.containerID(), unhealthy);
    // Second RM iteration
    // Now that we have a free DN, a quasi_closed replica should be replicated
    assertReplicaScheduled(1);
    assertUnderReplicatedCount(1);
    // Process the replicate command and report the replica back to SCM.
    List<CommandForDatanode> replicateCommands = datanodeCommandHandler.getReceivedCommands().stream().filter(command -> command.getCommand().getType().equals(SCMCommandProto.Type.replicateContainerCommand)).collect(Collectors.toList());
    assertEquals(1, replicateCommands.size());
    ReplicateContainerCommand command = (ReplicateContainerCommand) replicateCommands.iterator().next().getCommand();
    List<DatanodeDetails> sources = command.getSourceDatanodes();
    assertThat(sources).contains(quasi1.getDatanodeDetails(), quasi2.getDatanodeDetails());
    ContainerReplica replica3 = getReplicas(container.containerID(), QUASI_CLOSED, container.getSequenceId(), quasi1.getOriginDatanodeId(), MockDatanodeDetails.randomDatanodeDetails());
    containerStateManager.updateContainerReplica(container.containerID(), replica3);
    // Third RM iteration
    assertReplicaScheduled(0);
    assertUnderReplicatedCount(0);
    assertOverReplicatedCount(0);
}

