    containerStateManager.removeContainerReplica(container.containerID(), unhealthy);
    // Do a second run.
    assertReplicaScheduled(0);
    assertUnderReplicatedCount(0);
    for (CommandForDatanode<?> command : datanodeCommandHandler.getReceivedCommands()) {
        if (command.getCommand().getType() == SCMCommandProto.Type.deleteContainerCommand) {
            if (command.getDatanodeId() == unhealthy.getDatanodeDetails().getUuid()) {
                unhealthyDeleted = true;
            } else {
                closedDeleted = true;
            }
        }
    }
    assertTrue(unhealthyDeleted);
    assertTrue(closedDeleted);
}

