/**
 * 4 quasi-closed replicas.
 * All have same origin node ID.
 * Expectation: One of the replicas is deleted.
 */
@Test
public void testOverReplicatedQuasiClosedContainer() throws IOException, TimeoutException {
    final ContainerInfo container = getContainer(LifeCycleState.QUASI_CLOSED);
    container.setUsedBytes(101);
    final ContainerID id = container.containerID();
    final UUID originNodeId = UUID.randomUUID();
    final ContainerReplica replicaOne = getReplicas(id, QUASI_CLOSED, 1000L, originNodeId, randomDatanodeDetails());
    final ContainerReplica replicaTwo = getReplicas(id, QUASI_CLOSED, 1000L, originNodeId, randomDatanodeDetails());
    final ContainerReplica replicaThree = getReplicas(id, QUASI_CLOSED, 1000L, originNodeId, randomDatanodeDetails());
    final ContainerReplica replicaFour = getReplicas(id, QUASI_CLOSED, 1000L, originNodeId, randomDatanodeDetails());
    containerStateManager.addContainer(container.getProtobuf());
    containerStateManager.updateContainerReplica(id, replicaOne);
    containerStateManager.updateContainerReplica(id, replicaTwo);
    containerStateManager.updateContainerReplica(id, replicaThree);
    containerStateManager.updateContainerReplica(id, replicaFour);
    final int currentDeleteCommandCount = datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.deleteContainerCommand);
    replicationManager.processAll();
    eventQueue.processAll(1000);
    assertEquals(currentDeleteCommandCount + 1, datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.deleteContainerCommand));
    assertEquals(currentDeleteCommandCount + 1, replicationManager.getMetrics().getDeletionCmdsSentTotal());
    assertEquals(1, getInflightCount(InflightType.DELETION));
    assertEquals(1, replicationManager.getMetrics().getInflightDeletion());
    ReplicationManagerReport report = replicationManager.getContainerReport();
    assertEquals(1, report.getStat(LifeCycleState.QUASI_CLOSED));
    assertEquals(1, report.getStat(ReplicationManagerReport.HealthState.QUASI_CLOSED_STUCK));
    assertEquals(1, report.getStat(ReplicationManagerReport.HealthState.OVER_REPLICATED));
    // Now we remove the replica according to inflight
    DatanodeDetails targetDn = replicationManager.getLegacyReplicationManager().getFirstDatanode(InflightType.DELETION, id);
    if (targetDn.equals(replicaOne.getDatanodeDetails())) {
        containerStateManager.removeContainerReplica(id, replicaOne);
    } else if (targetDn.equals(replicaTwo.getDatanodeDetails())) {
        containerStateManager.removeContainerReplica(id, replicaTwo);
    } else if (targetDn.equals(replicaThree.getDatanodeDetails())) {
        containerStateManager.removeContainerReplica(id, replicaThree);
    } else if (targetDn.equals(replicaFour.getDatanodeDetails())) {
        containerStateManager.removeContainerReplica(id, replicaFour);
    }
    final long currentDeleteCommandCompleted = replicationManager.getMetrics().getReplicasDeletedTotal();
    final long deleteBytesCompleted = replicationManager.getMetrics().getDeletionBytesCompletedTotal();
    replicationManager.processAll();
    eventQueue.processAll(1000);
    assertEquals(0, getInflightCount(InflightType.DELETION));
    assertEquals(0, replicationManager.getMetrics().getInflightDeletion());
    assertEquals(currentDeleteCommandCompleted + 1, replicationManager.getMetrics().getReplicasDeletedTotal());
    assertEquals(deleteBytesCompleted + 101, replicationManager.getMetrics().getDeletionBytesCompletedTotal());
    report = replicationManager.getContainerReport();
    assertEquals(1, report.getStat(LifeCycleState.QUASI_CLOSED));
    assertEquals(1, report.getStat(ReplicationManagerReport.HealthState.QUASI_CLOSED_STUCK));
    assertEquals(0, report.getStat(ReplicationManagerReport.HealthState.OVER_REPLICATED));
}

