      One of the quasi closed replicas should be replicated and no close
      commands should be sent.
       */
    replicationManager.processAll();
    eventQueue.processAll(1000);
    assertEquals(currentCloseCommandCount, datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.closeContainerCommand));
    // One replication command should be sent
    assertEquals(currentReplicateCommandCount + 1, datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.replicateContainerCommand));
    assertEquals(currentReplicateCommandCount + 1, replicationManager.getMetrics().getReplicationCmdsSentTotal());
    assertEquals(currentBytesToReplicate + container.getUsedBytes(), replicationManager.getMetrics().getReplicationBytesTotal());
    assertEquals(1, getInflightCount(InflightType.REPLICATION));
    assertEquals(1, replicationManager.getMetrics().getInflightReplication());
    ReplicationManagerReport report = replicationManager.getContainerReport();
    assertEquals(1, report.getStat(LifeCycleState.QUASI_CLOSED));
    assertEquals(1, report.getStat(ReplicationManagerReport.HealthState.QUASI_CLOSED_STUCK));
    assertEquals(1, report.getStat(ReplicationManagerReport.HealthState.UNDER_REPLICATED));
}

