/**
 * 2 quasi-closed replicas.
 * 2 unique origin IDs with different BCSIDs.
 * Expectation: Container is closed, then replicated on the next iteration.
 */
@Test
public void testCloseableIsClosedBeforeReplication() throws IOException {
    final ContainerInfo container = getContainer(LifeCycleState.QUASI_CLOSED);
    final ContainerID id = container.containerID();
    final ContainerReplica replicaOne = getReplicas(id, QUASI_CLOSED, 1000L, UUID.randomUUID(), randomDatanodeDetails());
    final ContainerReplica replicaTwo = getReplicas(id, QUASI_CLOSED, 900L, UUID.randomUUID(), randomDatanodeDetails());
    containerStateManager.addContainer(container.getProtobuf());
    containerStateManager.updateContainerReplica(id, replicaOne);
    containerStateManager.updateContainerReplica(id, replicaTwo);
    // Since we have 2/3 replicas, the container should be closed on this
    // iteration. The replica with the higher BCSID can be closed.
    int currentCloseCommandCount = datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.closeContainerCommand);
    replicationManager.processAll();
    eventQueue.processAll(1000);
    assertEquals(currentCloseCommandCount + 1, datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.closeContainerCommand));
    // The highest BCSID replica should have been closed.
    Optional<CommandForDatanode> cmd = datanodeCommandHandler.getReceivedCommands().stream().findFirst();
    assertTrue(cmd.isPresent());
    assertEquals(replicaOne.getDatanodeDetails().getUuid(), cmd.get().getDatanodeId());
    ReplicationManagerReport report = replicationManager.getContainerReport();
    // Container will register as closed after the closed replica is
    // reported in the next iteration.
    assertEquals(0, report.getStat(LifeCycleState.CLOSED));
    // Legacy replication manager does not count over/under replicated
    // status until the container is eligible to be replicated.
    assertEquals(0, report.getStat(ReplicationManagerReport.HealthState.UNDER_REPLICATED));
    assertEquals(1, report.getStat(LifeCycleState.QUASI_CLOSED));
    assertEquals(0, report.getStat(ReplicationManagerReport.HealthState.QUASI_CLOSED_STUCK));
    // Move the higher BCSID replica to closed state.
    final ContainerReplica closedReplicaOne = getReplicas(id, CLOSED, 1000L, replicaOne.getOriginDatanodeId(), replicaOne.getDatanodeDetails());
    containerStateManager.updateContainerReplica(id, closedReplicaOne);
    // On the next iteration, the container should be replicated.
    currentCloseCommandCount = datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.closeContainerCommand);
    int currentReplicateCommandCount = datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.replicateContainerCommand);
    replicationManager.processAll();
    eventQueue.processAll(1000);
    // No more close commands should be sent.
    assertEquals(currentCloseCommandCount, datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.closeContainerCommand));
    // Two replicate commands should be triggered for the now closed
    // container.
    assertEquals(currentReplicateCommandCount + 2, datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.replicateContainerCommand));
    assertEquals(currentReplicateCommandCount + 2, replicationManager.getMetrics().getReplicationCmdsSentTotal());
    assertEquals(1, getInflightCount(InflightType.REPLICATION));
    assertEquals(1, replicationManager.getMetrics().getInflightReplication());
    // Once the replicas are closed, moving the container to CLOSED state
    // in SCM is done on the container report, not in the replication manager.
}

