/**
 * if crash happened and restarted, move option should work as expected.
 */
@Test
public void testMoveCrashAndRestart() throws IOException, NodeNotFoundException, InterruptedException, TimeoutException {
    final ContainerInfo container = createContainer(LifeCycleState.CLOSED);
    ContainerID id = container.containerID();
    ContainerReplica dn1 = addReplica(container, new NodeStatus(IN_SERVICE, HEALTHY), CLOSED);
    addReplica(container, new NodeStatus(IN_SERVICE, HEALTHY), CLOSED);
    addReplica(container, new NodeStatus(IN_SERVICE, HEALTHY), CLOSED);
    DatanodeDetails dn3 = addNode(new NodeStatus(IN_SERVICE, HEALTHY));
    replicationManager.move(id, dn1.getDatanodeDetails(), dn3);
    assertThat(scmLogs.getOutput()).contains("receive a move request about container");
    Thread.sleep(100L);
    assertTrue(datanodeCommandHandler.received(SCMCommandProto.Type.replicateContainerCommand, dn3));
    assertEquals(1, datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.replicateContainerCommand));
    //crash happens, restart scm.
    //clear current inflight actions and reload inflightMove from DBStore.
    resetReplicationManager();
    replicationManager.getMoveScheduler().reinitialize(SCMDBDefinition.MOVE.getTable(dbStore));
    assertTrue(replicationManager.getMoveScheduler().getInflightMove().containsKey(id));
    MoveDataNodePair kv = replicationManager.getMoveScheduler().getInflightMove().get(id);
    assertEquals(kv.getSrc(), dn1.getDatanodeDetails());
    assertEquals(kv.getTgt(), dn3);
    serviceManager.notifyStatusChanged();
    Thread.sleep(100L);
    // now, the container is not over-replicated,
    // so no deleteContainerCommand will be sent
    assertFalse(datanodeCommandHandler.received(SCMCommandProto.Type.deleteContainerCommand, dn1.getDatanodeDetails()));
    //replica does not exist in target datanode, so a
    // replicateContainerCommand will be sent again at
    // notifyStatusChanged#onLeaderReadyAndOutOfSafeMode
    assertEquals(2, datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.replicateContainerCommand));
    //replicate container to dn3, now, over-replicated
    addReplicaToDn(container, dn3, CLOSED);
    replicationManager.processAll();
    eventQueue.processAll(1000);
    //deleteContainerCommand is sent, but the src replica is not deleted now
    assertEquals(1, datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.deleteContainerCommand));
    //crash happens, restart scm.
    //clear current inflight actions and reload inflightMove from DBStore.
    resetReplicationManager();
    replicationManager.getMoveScheduler().reinitialize(SCMDBDefinition.MOVE.getTable(dbStore));
    assertTrue(replicationManager.getMoveScheduler().getInflightMove().containsKey(id));
    kv = replicationManager.getMoveScheduler().getInflightMove().get(id);
    assertEquals(kv.getSrc(), dn1.getDatanodeDetails());
    assertEquals(kv.getTgt(), dn3);
    serviceManager.notifyStatusChanged();
    //after restart and the container is over-replicated now,
    //deleteContainerCommand will be sent again
    assertEquals(2, datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.deleteContainerCommand));
    containerStateManager.removeContainerReplica(id, dn1);
    //replica in src datanode is deleted now
    containerStateManager.removeContainerReplica(id, dn1);
    replicationManager.processAll();
    eventQueue.processAll(1000);
    //since the move is complete,so after scm crash and restart
    //inflightMove should not contain the container again
    resetReplicationManager();
    replicationManager.getMoveScheduler().reinitialize(SCMDBDefinition.MOVE.getTable(dbStore));
    assertThat(replicationManager.getMoveScheduler().getInflightMove()).doesNotContainKey(id);
    //completeableFuture is not stored in DB, so after scm crash and
    //restart ,completeableFuture is missing
}

