/**
 * before Replication Manager generates a completablefuture for a move
 * option, some Prerequisites should be satisfied.
 */
@Test
public void testMovePrerequisites() throws IOException, NodeNotFoundException, InterruptedException, ExecutionException, InvalidStateTransitionException, TimeoutException {
    //all conditions is met
    final ContainerInfo container = createContainer(LifeCycleState.OPEN);
    ContainerID id = container.containerID();
    ContainerReplica dn1 = addReplica(container, new NodeStatus(IN_SERVICE, HEALTHY), CLOSED);
    ContainerReplica dn2 = addReplica(container, new NodeStatus(IN_SERVICE, HEALTHY), CLOSED);
    DatanodeDetails dn3 = addNode(new NodeStatus(IN_SERVICE, HEALTHY));
    ContainerReplica dn4 = addReplica(container, new NodeStatus(IN_SERVICE, HEALTHY), CLOSED);
    CompletableFuture<MoveManager.MoveResult> cf;
    //the above move is executed successfully, so there may be some item in
    //inflightReplication or inflightDeletion. here we stop replication
    // manager to clear these states, which may impact the tests below.
    //we don't need a running replicationManamger now
    replicationManager.stop();
    Thread.sleep(100L);
    cf = replicationManager.move(id, dn1.getDatanodeDetails(), dn3);
    assertTrue(cf.isDone() && cf.get() == MoveManager.MoveResult.FAIL_UNEXPECTED_ERROR);
    replicationManager.start();
    Thread.sleep(100L);
    //container in not in OPEN state
    cf = replicationManager.move(id, dn1.getDatanodeDetails(), dn3);
    assertTrue(cf.isDone() && cf.get() == MoveManager.MoveResult.REPLICATION_FAIL_CONTAINER_NOT_CLOSED);
    //open -> closing
    containerStateManager.updateContainerState(id.getProtobuf(), LifeCycleEvent.FINALIZE);
    cf = replicationManager.move(id, dn1.getDatanodeDetails(), dn3);
    assertTrue(cf.isDone() && cf.get() == MoveManager.MoveResult.REPLICATION_FAIL_CONTAINER_NOT_CLOSED);
    //closing -> quasi_closed
    containerStateManager.updateContainerState(id.getProtobuf(), LifeCycleEvent.QUASI_CLOSE);
    cf = replicationManager.move(id, dn1.getDatanodeDetails(), dn3);
    assertTrue(cf.isDone() && cf.get() == MoveManager.MoveResult.REPLICATION_FAIL_CONTAINER_NOT_CLOSED);
    //quasi_closed -> closed
    containerStateManager.updateContainerState(id.getProtobuf(), LifeCycleEvent.FORCE_CLOSE);
    assertSame(LifeCycleState.CLOSED, containerStateManager.getContainer(id).getState());
    //Node is not in healthy state
    for (HddsProtos.NodeState state : HddsProtos.NodeState.values()) {
        if (state != HEALTHY) {
            nodeManager.setNodeStatus(dn3, new NodeStatus(IN_SERVICE, state));
            cf = replicationManager.move(id, dn1.getDatanodeDetails(), dn3);
            assertTrue(cf.isDone() && cf.get() == MoveManager.MoveResult.REPLICATION_FAIL_NODE_UNHEALTHY);
            cf = replicationManager.move(id, dn3, dn1.getDatanodeDetails());
            assertTrue(cf.isDone() && cf.get() == MoveManager.MoveResult.REPLICATION_FAIL_NODE_UNHEALTHY);
        }
    }
    nodeManager.setNodeStatus(dn3, new NodeStatus(IN_SERVICE, HEALTHY));
    //Node is not in IN_SERVICE state
    for (HddsProtos.NodeOperationalState state : HddsProtos.NodeOperationalState.values()) {
        if (state != IN_SERVICE) {
            nodeManager.setNodeStatus(dn3, new NodeStatus(state, HEALTHY));
            cf = replicationManager.move(id, dn1.getDatanodeDetails(), dn3);
            assertTrue(cf.isDone() && cf.get() == MoveManager.MoveResult.REPLICATION_FAIL_NODE_NOT_IN_SERVICE);
            cf = replicationManager.move(id, dn3, dn1.getDatanodeDetails());
            assertTrue(cf.isDone() && cf.get() == MoveManager.MoveResult.REPLICATION_FAIL_NODE_NOT_IN_SERVICE);
        }
    }
    nodeManager.setNodeStatus(dn3, new NodeStatus(IN_SERVICE, HEALTHY));
    //container exists in target datanode
    cf = replicationManager.move(id, dn1.getDatanodeDetails(), dn2.getDatanodeDetails());
    assertTrue(cf.isDone() && cf.get() == MoveManager.MoveResult.REPLICATION_FAIL_EXIST_IN_TARGET);
    //container does not exist in source datanode
    cf = replicationManager.move(id, dn3, dn3);
    assertTrue(cf.isDone() && cf.get() == MoveManager.MoveResult.REPLICATION_FAIL_NOT_EXIST_IN_SOURCE);
    //make container over relplicated to test the
    // case that container is in inflightDeletion
    ContainerReplica dn5 = addReplica(container, new NodeStatus(IN_SERVICE, HEALTHY), State.CLOSED);
    replicationManager.processAll();
    //waiting for inflightDeletion generation
    eventQueue.processAll(1000);
    cf = replicationManager.move(id, dn1.getDatanodeDetails(), dn3);
    assertTrue(cf.isDone() && cf.get() == MoveManager.MoveResult.REPLICATION_FAIL_INFLIGHT_DELETION);
    resetReplicationManager();
    //make the replica num be 2 to test the case
    //that container is in inflightReplication
    containerStateManager.removeContainerReplica(id, dn5);
    containerStateManager.removeContainerReplica(id, dn4);
    //replication manager should generate inflightReplication
    replicationManager.processAll();
    //waiting for inflightReplication generation
    eventQueue.processAll(1000);
    cf = replicationManager.move(id, dn1.getDatanodeDetails(), dn3);
    assertTrue(cf.isDone() && cf.get() == MoveManager.MoveResult.REPLICATION_FAIL_INFLIGHT_REPLICATION);
}

@Test
public void additionalReplicaScheduledWhenMisReplicated() throws IOException, TimeoutException {
    final ContainerInfo container = getContainer(LifeCycleState.CLOSED);
    container.setUsedBytes(100);
    final ContainerID id = container.containerID();
    final UUID originNodeId = UUID.randomUUID();
    final ContainerReplica replicaOne = getReplicas(id, State.CLOSED, 1000L, originNodeId, randomDatanodeDetails());
    final ContainerReplica replicaTwo = getReplicas(id, State.CLOSED, 1000L, originNodeId, randomDatanodeDetails());
    final ContainerReplica replicaThree = getReplicas(id, State.CLOSED, 1000L, originNodeId, randomDatanodeDetails());
    containerStateManager.addContainer(container.getProtobuf());
    containerStateManager.updateContainerReplica(id, replicaOne);
    containerStateManager.updateContainerReplica(id, replicaTwo);
    containerStateManager.updateContainerReplica(id, replicaThree);
    // Ensure a mis-replicated status is returned for any containers in this
    // test where there are 3 replicas. When there are 2 or 4 replicas
    // the status returned will be healthy.
    when(ratisContainerPlacementPolicy.validateContainerPlacement(argThat(list -> list.size() == 3), anyInt())).thenAnswer(invocation -> {
        return new ContainerPlacementStatusDefault(1, 2, 3);
    });
    int currentReplicateCommandCount = datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.replicateContainerCommand);
    final long currentBytesToReplicate = replicationManager.getMetrics().getReplicationBytesTotal();
    replicationManager.processAll();
    eventQueue.processAll(1000);
    // At this stage, due to the mocked calls to validateContainerPlacement
    // the policy will not be satisfied, and replication will be triggered.
    assertEquals(currentReplicateCommandCount + 1, datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.replicateContainerCommand));
    assertEquals(currentReplicateCommandCount + 1, replicationManager.getMetrics().getReplicationCmdsSentTotal());
    assertEquals(currentBytesToReplicate + 100, replicationManager.getMetrics().getReplicationBytesTotal());
    assertEquals(1, getInflightCount(InflightType.REPLICATION));
    assertEquals(1, replicationManager.getMetrics().getInflightReplication());
    ReplicationManagerReport report = replicationManager.getContainerReport();
    assertEquals(1, report.getStat(LifeCycleState.CLOSED));
    assertEquals(1, report.getStat(ReplicationManagerReport.HealthState.MIS_REPLICATED));
    // Now make it so that all containers seem mis-replicated no matter how
    // many replicas. This will test replicas are not scheduled if the new
    // replica does not fix the mis-replication.
    when(ratisContainerPlacementPolicy.validateContainerPlacement(anyList(), anyInt())).thenAnswer(invocation -> {
        return new ContainerPlacementStatusDefault(1, 2, 3);
    });
    currentReplicateCommandCount = datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.replicateContainerCommand);
    replicationManager.processAll();
    eventQueue.processAll(1000);
    // At this stage, due to the mocked calls to validateContainerPlacement
    // the mis-replicated racks will not have improved, so expect to see
    // nothing scheduled.
    assertEquals(currentReplicateCommandCount, datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.replicateContainerCommand));
    assertEquals(currentReplicateCommandCount, replicationManager.getMetrics().getReplicationCmdsSentTotal());
    assertEquals(1, getInflightCount(InflightType.REPLICATION));
    assertEquals(1, replicationManager.getMetrics().getInflightReplication());
}

@Test
public void overReplicatedButRemovingMakesMisReplicated() throws IOException, TimeoutException {
    // In this test, the excess replica should not be removed.
    final ContainerInfo container = getContainer(LifeCycleState.CLOSED);
    final ContainerID id = container.containerID();
    final UUID originNodeId = UUID.randomUUID();
    final ContainerReplica replicaOne = getReplicas(id, State.CLOSED, 1000L, originNodeId, randomDatanodeDetails());
    final ContainerReplica replicaTwo = getReplicas(id, State.CLOSED, 1000L, originNodeId, randomDatanodeDetails());
    final ContainerReplica replicaThree = getReplicas(id, State.CLOSED, 1000L, originNodeId, randomDatanodeDetails());
    final ContainerReplica replicaFour = getReplicas(id, State.CLOSED, 1000L, originNodeId, randomDatanodeDetails());
    containerStateManager.addContainer(container.getProtobuf());
    containerStateManager.updateContainerReplica(id, replicaOne);
    containerStateManager.updateContainerReplica(id, replicaTwo);
    containerStateManager.updateContainerReplica(id, replicaThree);
    containerStateManager.updateContainerReplica(id, replicaFour);
    // Ensure a mis-replicated status is returned for any containers in this
    // test where there are exactly 3 replicas checked.
    when(ratisContainerPlacementPolicy.validateContainerPlacement(argThat(list -> list.size() == 3), anyInt())).thenAnswer(invocation -> new ContainerPlacementStatusDefault(1, 2, 3));
    int currentDeleteCommandCount = datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.deleteContainerCommand);
    replicationManager.processAll();
    eventQueue.processAll(1000);
    // TODO the new (non-legacy) RM needs a separate handler for
    //  topology status to make progress in this case by:
    //  1. Deleting the closed replica to restore proper replica count.
    //  2. Deleting the unhealthy replica since there are adequate healthy
    //  replicas.
    //  3. Fixing topology issues left by the previous cleanup tasks.
    // Current legacy RM implementation will take no action in this case
    // because deletion would compromise topology.
    assertEquals(currentDeleteCommandCount, datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.deleteContainerCommand));
    assertEquals(currentDeleteCommandCount, replicationManager.getMetrics().getDeletionCmdsSentTotal());
    assertEquals(0, getInflightCount(InflightType.DELETION));
    assertEquals(0, replicationManager.getMetrics().getInflightDeletion());
    assertOverReplicatedCount(1);
}

