@Test
void testQuasiClosedReplicaWithInCorrectSequenceID() {
    final long sequenceID = 101;
    final ContainerInfo container = createContainerInfo(RatisReplicationConfig.getInstance(THREE), 1L, HddsProtos.LifeCycleState.CLOSED, sequenceID);
    final ContainerID containerID = container.containerID();
    final ContainerReplica replicaOne = createContainerReplica(containerID, 0, IN_SERVICE, State.CLOSED, sequenceID);
    final ContainerReplica replicaTwo = createContainerReplica(containerID, 0, IN_SERVICE, State.CLOSED, sequenceID);
    final ContainerReplica quasiCloseReplica = createContainerReplica(containerID, 0, IN_SERVICE, State.QUASI_CLOSED, sequenceID - 5);
    final Set<ContainerReplica> replicas = new HashSet<>();
    replicas.add(replicaOne);
    replicas.add(replicaTwo);
    replicas.add(quasiCloseReplica);
    final RatisContainerReplicaCount crc = new RatisContainerReplicaCount(container, replicas, Collections.emptyList(), 2, false);
    validate(crc, false, 1, false, false);
    assertFalse(crc.isSufficientlyReplicated(true));
    assertEquals(1, crc.getUnhealthyReplicaCount());
    // With additional unhealthy replica
    final Set<ContainerReplica> unhealthyReplica = createReplicas(container.containerID(), UNHEALTHY, 0);
    replicas.addAll(unhealthyReplica);
    final RatisContainerReplicaCount crcWithUnhealthy = new RatisContainerReplicaCount(container, replicas, Collections.emptyList(), 2, false);
    validate(crcWithUnhealthy, false, 1, false, false);
    assertFalse(crcWithUnhealthy.isSufficientlyReplicated(true));
    assertEquals(2, crcWithUnhealthy.getUnhealthyReplicaCount());
}

