@Test
public void testDeleteThrottlingMisMatchedReplica() throws IOException {
    Set<ContainerReplica> closedReplicas = createReplicas(container.containerID(), ContainerReplicaProto.State.CLOSED, 0, 0, 0, 0);
    ContainerReplica quasiClosedReplica = createContainerReplica(container.containerID(), 0, HddsProtos.NodeOperationalState.IN_SERVICE, ContainerReplicaProto.State.QUASI_CLOSED);
    // When processing the quasi closed replica, simulate an overloaded
    // exception so that it does not get deleted. Then we can ensure that only
    // one of the CLOSED replicas is removed.
    doThrow(CommandTargetOverloadedException.class).when(replicationManager).sendThrottledDeleteCommand(any(ContainerInfo.class), anyInt(), eq(quasiClosedReplica.getDatanodeDetails()), anyBoolean());
    Set<ContainerReplica> replicas = new HashSet<>();
    replicas.add(quasiClosedReplica);
    replicas.addAll(closedReplicas);
    RatisOverReplicationHandler handler = new RatisOverReplicationHandler(policy, replicationManager);
    assertThrows(CommandTargetOverloadedException.class, () -> handler.processAndSendCommands(replicas, Collections.emptyList(), getOverReplicatedHealthResult(), 2));
    assertEquals(1, commandsSent.size());
    Pair<DatanodeDetails, SCMCommand<?>> cmd = commandsSent.iterator().next();
    assertNotEquals(quasiClosedReplica.getDatanodeDetails(), cmd.getKey());
}

@Test
public void testDeleteThrottling() throws IOException {
    Set<ContainerReplica> closedReplicas = createReplicas(container.containerID(), ContainerReplicaProto.State.CLOSED, 0, 0, 0, 0, 0);
    final AtomicBoolean shouldThrow = new AtomicBoolean(true);
    // On the first call we throw, on subsequent calls we succeed.
    doAnswer((Answer<Void>) invocationOnMock -> {
        if (shouldThrow.get()) {
            shouldThrow.set(false);
            throw new CommandTargetOverloadedException("Test exception");
        }
        ContainerInfo containerInfo = invocationOnMock.getArgument(0);
        int replicaIndex = invocationOnMock.getArgument(1);
        DatanodeDetails target = invocationOnMock.getArgument(2);
        boolean forceDelete = invocationOnMock.getArgument(3);
        DeleteContainerCommand deleteCommand = new DeleteContainerCommand(containerInfo.getContainerID(), forceDelete);
        deleteCommand.setReplicaIndex(replicaIndex);
        commandsSent.add(Pair.of(target, deleteCommand));
        return null;
    }).when(replicationManager).sendThrottledDeleteCommand(any(), anyInt(), any(), anyBoolean());
    RatisOverReplicationHandler handler = new RatisOverReplicationHandler(policy, replicationManager);
    handler.processAndSendCommands(closedReplicas, Collections.emptyList(), getOverReplicatedHealthResult(), 2);
    assertEquals(2, commandsSent.size());
}

