@Test
void testGetContainers() throws Exception {
    assertEquals(emptyList(), containerManager.getContainers());
    List<ContainerID> ids = new ArrayList<>();
    for (int i = 0; i < 10; i++) {
        ContainerInfo container = containerManager.allocateContainer(RatisReplicationConfig.getInstance(ReplicationFactor.THREE), "admin");
        ids.add(container.containerID());
    }
    assertIds(ids, containerManager.getContainers(ContainerID.MIN, 10));
    assertIds(ids.subList(0, 5), containerManager.getContainers(ContainerID.MIN, 5));
    assertIds(ids, containerManager.getContainers(ids.get(0), 10));
    assertIds(ids, containerManager.getContainers(ids.get(0), 100));
    assertIds(ids.subList(5, ids.size()), containerManager.getContainers(ids.get(5), 100));
    assertIds(emptyList(), containerManager.getContainers(ids.get(5), 100, LifeCycleState.CLOSED));
    containerManager.updateContainerState(ids.get(0), HddsProtos.LifeCycleEvent.FINALIZE);
    assertIds(ids.subList(0, 1), containerManager.getContainers(LifeCycleState.CLOSING));
    assertIds(ids.subList(1, ids.size()), containerManager.getContainers(LifeCycleState.OPEN));
    containerManager.updateContainerState(ids.get(1), HddsProtos.LifeCycleEvent.FINALIZE);
    assertIds(ids.subList(0, 2), containerManager.getContainers(LifeCycleState.CLOSING));
    assertIds(ids.subList(2, ids.size()), containerManager.getContainers(LifeCycleState.OPEN));
    containerManager.updateContainerState(ids.get(1), HddsProtos.LifeCycleEvent.QUASI_CLOSE);
    containerManager.updateContainerState(ids.get(2), HddsProtos.LifeCycleEvent.FINALIZE);
    containerManager.updateContainerState(ids.get(2), HddsProtos.LifeCycleEvent.CLOSE);
    assertEquals(7, containerManager.getContainerStateCount(LifeCycleState.OPEN));
    assertEquals(1, containerManager.getContainerStateCount(LifeCycleState.CLOSING));
    assertEquals(1, containerManager.getContainerStateCount(LifeCycleState.QUASI_CLOSED));
    assertEquals(1, containerManager.getContainerStateCount(LifeCycleState.CLOSED));
}

