        for (NodeState health : NodeState.values()) {
            addRandomNodeWithState(op, health);
            nodeCount++;
        }
    }
    NodeStatus requestedState = NodeStatus.inServiceStale();
    List<DatanodeInfo> nodes = map.getDatanodeInfos(requestedState);
    assertEquals(1, nodes.size());
    assertEquals(1, map.getNodeCount(requestedState));
    assertEquals(nodeCount, map.getTotalNodeCount());
    assertEquals(nodeCount, map.getAllNodes().size());
    assertEquals(nodeCount, map.getAllDatanodeInfos().size());
    // Checks for the getNodeCount(opstate, health) method
    assertEquals(nodeCount, map.getNodeCount(null, null));
    assertEquals(1, map.getNodeCount(NodeOperationalState.DECOMMISSIONING, NodeState.STALE));
    assertEquals(5, map.getNodeCount(null, NodeState.HEALTHY));
    assertEquals(4, map.getNodeCount(NodeOperationalState.DECOMMISSIONING, null));
}

/**
 * Test if container list is iterable even if it's modified from other thread.
 */
@Test
public void testConcurrency() throws Exception {
    final DatanodeDetails datanodeDetails = MockDatanodeDetails.randomDatanodeDetails();
    map.addNode(datanodeDetails, NodeStatus.inServiceHealthy(), null);
    UUID dnUuid = datanodeDetails.getUuid();
    map.addContainer(dnUuid, ContainerID.valueOf(1L));
    map.addContainer(dnUuid, ContainerID.valueOf(2L));
    map.addContainer(dnUuid, ContainerID.valueOf(3L));
    CountDownLatch elementRemoved = new CountDownLatch(1);
    CountDownLatch loopStarted = new CountDownLatch(1);
    new Thread(() -> {
        try {
            loopStarted.await();
            map.removeContainer(dnUuid, ContainerID.valueOf(1L));
            elementRemoved.countDown();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }).start();
    boolean first = true;
    for (ContainerID key : map.getContainers(dnUuid)) {
        if (first) {
            loopStarted.countDown();
            elementRemoved.await();
        }
        first = false;
        System.out.println(key);
    }
}

@Test
public void testSummaryUpdated() {
    CommandQueue commandQueue = new CommandQueue();
    long containerID = 1;
    SCMCommand<?> closeContainerCommand = new CloseContainerCommand(containerID, PipelineID.randomId());
    SCMCommand<?> createPipelineCommand = new CreatePipelineCommand(PipelineID.randomId(), HddsProtos.ReplicationType.RATIS, HddsProtos.ReplicationFactor.THREE, Collections.emptyList());
    SCMCommand<?> replicationCommand = ReplicateContainerCommand.toTarget(containerID, MockDatanodeDetails.randomDatanodeDetails());
    ReplicateContainerCommand lowReplicationCommand = ReplicateContainerCommand.toTarget(containerID, MockDatanodeDetails.randomDatanodeDetails());
    lowReplicationCommand.setPriority(StorageContainerDatanodeProtocolProtos.ReplicationCommandPriority.LOW);
    UUID datanode1UUID = UUID.randomUUID();
    UUID datanode2UUID = UUID.randomUUID();
    commandQueue.addCommand(datanode1UUID, closeContainerCommand);
    commandQueue.addCommand(datanode1UUID, closeContainerCommand);
    commandQueue.addCommand(datanode1UUID, createPipelineCommand);
    commandQueue.addCommand(datanode1UUID, replicationCommand);
    commandQueue.addCommand(datanode1UUID, lowReplicationCommand);
    commandQueue.addCommand(datanode2UUID, closeContainerCommand);
    commandQueue.addCommand(datanode2UUID, createPipelineCommand);
    commandQueue.addCommand(datanode2UUID, createPipelineCommand);
    // Check zero returned for unknown DN
    assertEquals(0, commandQueue.getDatanodeCommandCount(UUID.randomUUID(), SCMCommandProto.Type.closeContainerCommand));
    assertEquals(2, commandQueue.getDatanodeCommandCount(datanode1UUID, SCMCommandProto.Type.closeContainerCommand));
    assertEquals(1, commandQueue.getDatanodeCommandCount(datanode1UUID, SCMCommandProto.Type.createPipelineCommand));
    assertEquals(0, commandQueue.getDatanodeCommandCount(datanode1UUID, SCMCommandProto.Type.closePipelineCommand));
    assertEquals(1, commandQueue.getDatanodeCommandCount(datanode1UUID, SCMCommandProto.Type.replicateContainerCommand));
    Map<SCMCommandProto.Type, Integer> commandSummary = commandQueue.getDatanodeCommandSummary(datanode1UUID);
    assertEquals(3, commandSummary.size());
    assertEquals(Integer.valueOf(2), commandSummary.get(SCMCommandProto.Type.closeContainerCommand));
    assertEquals(Integer.valueOf(1), commandSummary.get(SCMCommandProto.Type.createPipelineCommand));
    assertEquals(Integer.valueOf(1), commandSummary.get(SCMCommandProto.Type.replicateContainerCommand));
    assertEquals(1, commandQueue.getDatanodeCommandCount(datanode2UUID, SCMCommandProto.Type.closeContainerCommand));
    assertEquals(2, commandQueue.getDatanodeCommandCount(datanode2UUID, SCMCommandProto.Type.createPipelineCommand));
    // Ensure the counts are cleared when the commands are retrieved
    List<SCMCommand> cmds = commandQueue.getCommand(datanode1UUID);
    assertEquals(5, cmds.size());
    assertEquals(0, commandQueue.getDatanodeCommandCount(datanode1UUID, SCMCommandProto.Type.closeContainerCommand));
    assertEquals(0, commandQueue.getDatanodeCommandCount(datanode1UUID, SCMCommandProto.Type.createPipelineCommand));
    assertEquals(0, commandQueue.getDatanodeCommandCount(datanode1UUID, SCMCommandProto.Type.closePipelineCommand));
    assertEquals(0, commandQueue.getDatanodeCommandCount(datanode1UUID, SCMCommandProto.Type.replicateContainerCommand));
    assertEquals(1, commandQueue.getDatanodeCommandCount(datanode2UUID, SCMCommandProto.Type.closeContainerCommand));
    assertEquals(2, commandQueue.getDatanodeCommandCount(datanode2UUID, SCMCommandProto.Type.createPipelineCommand));
    // Ensure the commands are zeroed when the queue is cleared
    commandQueue.clear();
    assertEquals(0, commandQueue.getDatanodeCommandCount(datanode2UUID, SCMCommandProto.Type.closeContainerCommand));
    assertEquals(0, commandQueue.getDatanodeCommandCount(datanode2UUID, SCMCommandProto.Type.createPipelineCommand));
}

/**
 * Test capacity based container placement policy with node reports.
 *
 * @throws IOException
 * @throws InterruptedException
 */
@Test
public void testContainerPlacementCapacity() throws IOException, InterruptedException {
    final int nodeCount = 4;
    final long capacity = 10L * OzoneConsts.GB;
    final long used = 2L * OzoneConsts.GB;
    final long remaining = capacity - used;
    testDir = PathUtils.getTestDir(TestContainerPlacement.class);
    conf.set(HddsConfigKeys.OZONE_METADATA_DIRS, testDir.getAbsolutePath());
    conf.setClass(ScmConfigKeys.OZONE_SCM_CONTAINER_PLACEMENT_IMPL_KEY, SCMContainerPlacementCapacity.class, PlacementPolicy.class);
    conf.setBoolean(ScmConfigKeys.HDDS_CONTAINER_RATIS_ENABLED_KEY, true);
    SCMNodeManager scmNodeManager = createNodeManager(conf);
    containerManager = createContainerManager();
    List<DatanodeDetails> datanodes = HddsTestUtils.getListOfRegisteredDatanodeDetails(scmNodeManager, nodeCount);
    XceiverClientManager xceiverClientManager = null;
    try {
        for (DatanodeDetails datanodeDetails : datanodes) {
            UUID dnId = datanodeDetails.getUuid();
            DatanodeInfo datanodeInfo = scmNodeManager.getNodeStateManager().getNode(dnId);
            StorageContainerDatanodeProtocolProtos.StorageReportProto report = HddsTestUtils.createStorageReport(dnId, testDir.getAbsolutePath() + "/" + dnId, capacity, used, remaining, null);
            StorageContainerDatanodeProtocolProtos.NodeReportProto nodeReportProto = HddsTestUtils.createNodeReport(Arrays.asList(report), emptyList());
            datanodeInfo.updateStorageReports(nodeReportProto.getStorageReportList());
            scmNodeManager.processHeartbeat(datanodeDetails);
        }
        //TODO: wait for heartbeat to be processed
        Thread.sleep(4 * 1000);
        assertEquals(nodeCount, scmNodeManager.getNodeCount(null, HEALTHY));
        assertEquals(capacity * nodeCount, (long) scmNodeManager.getStats().getCapacity().get());
        assertEquals(used * nodeCount, (long) scmNodeManager.getStats().getScmUsed().get());
        assertEquals(remaining * nodeCount, (long) scmNodeManager.getStats().getRemaining().get());
        xceiverClientManager = new XceiverClientManager(conf);
        ContainerInfo container = containerManager.allocateContainer(ReplicationConfig.fromProtoTypeAndFactor(SCMTestUtils.getReplicationType(conf), SCMTestUtils.getReplicationFactor(conf)), OzoneConsts.OZONE);
        int replicaCount = 0;
        for (DatanodeDetails datanodeDetails : datanodes) {
            if (replicaCount == SCMTestUtils.getReplicationFactor(conf).getNumber()) {
                break;
            }
            UUID dnId = datanodeDetails.getUuid();
            DatanodeInfo datanodeInfo = scmNodeManager.getNodeStateManager().getNode(dnId);
            addReplica(container, datanodeInfo);
            replicaCount++;
        }
        assertEquals(SCMTestUtils.getReplicationFactor(conf).getNumber(), containerManager.getContainerReplicas(container.containerID()).size());
    } catch (NodeNotFoundException e) {
        throw new RuntimeException(e);
    } finally {
        IOUtils.closeQuietly(containerManager);
        IOUtils.closeQuietly(scmNodeManager);
        if (xceiverClientManager != null) {
            xceiverClientManager.close();
        }
    }
}

