/**
 * For leader SCM, ensure that a change to the operationalState of a node
 * fires a SCMCommand of type SetNodeOperationalStateCommand.
 *
 * For follower SCM, no SetNodeOperationalStateCommand should be fired, yet
 * operationalState of the node will be updated according to the heartbeat.
 */
@Test
public void testSetNodeOpStateAndCommandFired() throws IOException, NodeNotFoundException, AuthenticationException {
    final int interval = 100;
    OzoneConfiguration conf = getConf();
    conf.setTimeDuration(OZONE_SCM_HEARTBEAT_PROCESS_INTERVAL, interval, MILLISECONDS);
    // If factor 1 pipelines are auto created, registering the new node will
    // trigger a pipeline creation command which may interfere with command
    // checking in this test.
    conf.setBoolean(OZONE_SCM_PIPELINE_AUTO_CREATE_FACTOR_ONE, false);
    try (SCMNodeManager nodeManager = createNodeManager(conf)) {
        DatanodeDetails dn = HddsTestUtils.createRandomDatanodeAndRegister(nodeManager);
        long expiry = System.currentTimeMillis() / 1000 + 1000;
        nodeManager.setNodeOperationalState(dn, HddsProtos.NodeOperationalState.ENTERING_MAINTENANCE, expiry);
        // If found mismatch, leader SCM fires a SetNodeOperationalStateCommand
        // to update the opState persisted in Datanode.
        scm.getScmContext().updateLeaderAndTerm(true, 1);
        List<SCMCommand> commands = nodeManager.processHeartbeat(dn);
        assertEquals(SetNodeOperationalStateCommand.class, commands.get(0).getClass());
        assertEquals(1, commands.size());
        // If found mismatch, follower SCM update its own opState according
        // to the heartbeat, and no SCMCommand will be fired.
        scm.getScmContext().updateLeaderAndTerm(false, 2);
        commands = nodeManager.processHeartbeat(dn);
        assertEquals(0, commands.size());
        NodeStatus scmStatus = nodeManager.getNodeStatus(dn);
        assertTrue(scmStatus.getOperationalState() == dn.getPersistedOpState() && scmStatus.getOpStateExpiryEpochSeconds() == dn.getPersistedOpStateExpiryEpochSec());
    }
}

/**
 * Asserts that a single node moves from Healthy to stale node, then from
 * stale node to dead node if it misses enough heartbeats.
 *
 * @throws IOException
 * @throws InterruptedException
 * @throws TimeoutException
 */
@Test
public void testScmDetectStaleAndDeadNode() throws IOException, InterruptedException, AuthenticationException {
    final int interval = 100;
    final int nodeCount = 10;
    OzoneConfiguration conf = getConf();
    conf.setTimeDuration(OZONE_SCM_HEARTBEAT_PROCESS_INTERVAL, interval, MILLISECONDS);
    conf.setTimeDuration(HDDS_HEARTBEAT_INTERVAL, 1, SECONDS);
    conf.setTimeDuration(OZONE_SCM_STALENODE_INTERVAL, 3, SECONDS);
    conf.setTimeDuration(OZONE_SCM_DEADNODE_INTERVAL, 6, SECONDS);
    try (SCMNodeManager nodeManager = createNodeManager(conf)) {
        List<DatanodeDetails> nodeList = createNodeSet(nodeManager, nodeCount);
        DatanodeDetails staleNode = HddsTestUtils.createRandomDatanodeAndRegister(nodeManager);
        // Heartbeat once
        nodeManager.processHeartbeat(staleNode);
        // Heartbeat all other nodes.
        for (DatanodeDetails dn : nodeList) {
            nodeManager.processHeartbeat(dn);
        }
        // Wait for 2 seconds .. and heartbeat good nodes again.
        Thread.sleep(2 * 1000);
        for (DatanodeDetails dn : nodeList) {
            nodeManager.processHeartbeat(dn);
        }
        // Wait for 2 seconds, wait a total of 4 seconds to make sure that the
        // node moves into stale state.
        Thread.sleep(2 * 1000);
        List<DatanodeDetails> staleNodeList = nodeManager.getNodes(NodeStatus.inServiceStale());
        assertEquals(1, nodeManager.getNodeCount(NodeStatus.inServiceStale()), "Expected to find 1 stale node");
        assertEquals(1, staleNodeList.size(), "Expected to find 1 stale node");
        assertEquals(staleNode.getUuid(), staleNodeList.get(0).getUuid(), "Stale node is not the expected ID");
        Map<String, Map<String, Integer>> nodeCounts = nodeManager.getNodeCount();
        assertEquals(1, nodeCounts.get(HddsProtos.NodeOperationalState.IN_SERVICE.name()).get(HddsProtos.NodeState.STALE.name()).intValue());
        Thread.sleep(1000);
        // heartbeat good nodes again.
        for (DatanodeDetails dn : nodeList) {
            nodeManager.processHeartbeat(dn);
        }
        //  6 seconds is the dead window for this test , so we wait a total of
        // 7 seconds to make sure that the node moves into dead state.
        Thread.sleep(2 * 1000);
        // the stale node has been removed
        staleNodeList = nodeManager.getNodes(NodeStatus.inServiceStale());
        nodeCounts = nodeManager.getNodeCount();
        assertEquals(0, nodeManager.getNodeCount(NodeStatus.inServiceStale()), "Expected to find 1 stale node");
        assertEquals(0, staleNodeList.size(), "Expected to find 1 stale node");
        assertEquals(0, nodeCounts.get(HddsProtos.NodeOperationalState.IN_SERVICE.name()).get(HddsProtos.NodeState.STALE.name()).intValue());
        // Check for the dead node now.
        List<DatanodeDetails> deadNodeList = nodeManager.getNodes(NodeStatus.inServiceDead());
        assertEquals(1, nodeManager.getNodeCount(NodeStatus.inServiceDead()), "Expected to find 1 dead node");
        assertEquals(1, deadNodeList.size(), "Expected to find 1 dead node");
        assertEquals(1, nodeCounts.get(HddsProtos.NodeOperationalState.IN_SERVICE.name()).get(HddsProtos.NodeState.DEAD.name()).intValue());
        assertEquals(staleNode.getUuid(), deadNodeList.get(0).getUuid(), "Dead node is not the expected ID");
    }
}

/**
 * Simulate a JVM Pause by pausing the health check process
 * Ensure that none of the nodes with heartbeats become Dead or Stale.
 * @throws IOException
 * @throws InterruptedException
 * @throws AuthenticationException
 */
@Test
void testScmHandleJvmPause() throws Exception {
    // milliseconds
    final int healthCheckInterval = 200;
    // seconds
    final int heartbeatInterval = 1;
    // seconds
    final int staleNodeInterval = 3;
    // seconds
    final int deadNodeInterval = 6;
    ScheduledFuture schedFuture;
    OzoneConfiguration conf = getConf();
    conf.setTimeDuration(OZONE_SCM_HEARTBEAT_PROCESS_INTERVAL, healthCheckInterval, MILLISECONDS);
    conf.setTimeDuration(HDDS_HEARTBEAT_INTERVAL, heartbeatInterval, SECONDS);
    conf.setTimeDuration(OZONE_SCM_STALENODE_INTERVAL, staleNodeInterval, SECONDS);
    conf.setTimeDuration(OZONE_SCM_DEADNODE_INTERVAL, deadNodeInterval, SECONDS);
    try (SCMNodeManager nodeManager = createNodeManager(conf)) {
        DatanodeDetails node1 = HddsTestUtils.createRandomDatanodeAndRegister(nodeManager);
        DatanodeDetails node2 = HddsTestUtils.createRandomDatanodeAndRegister(nodeManager);
        nodeManager.processHeartbeat(node1);
        nodeManager.processHeartbeat(node2);
        // Sleep so that heartbeat processing thread gets to run.
        Thread.sleep(1000);
        //Assert all nodes are healthy.
        assertEquals(2, nodeManager.getAllNodes().size());
        assertEquals(2, nodeManager.getNodeCount(NodeStatus.inServiceHealthy()));
        /**
         * Simulate a JVM Pause and subsequent handling in following steps:
         * Step 1 : stop heartbeat check process for stale node interval
         * Step 2 : resume heartbeat check
         * Step 3 : wait for 1 iteration of heartbeat check thread
         * Step 4 : retrieve the state of all nodes - assert all are HEALTHY
         * Step 5 : heartbeat for node1
         * [TODO : what if there is scheduling delay of test thread in Step 5?]
         * Step 6 : wait for some time to allow iterations of check process
         * Step 7 : retrieve the state of all nodes -  assert node2 is STALE
         * and node1 is HEALTHY
         */
        // Step 1 : stop health check process (simulate JVM pause)
        nodeManager.pauseHealthCheck();
        Thread.sleep(MILLISECONDS.convert(staleNodeInterval, SECONDS));
        // Step 2 : resume health check
        assertEquals(0, nodeManager.getSkippedHealthChecks(), "Unexpected, already skipped heartbeat checks");
        schedFuture = nodeManager.unpauseHealthCheck();
        // Step 3 : wait for 1 iteration of health check
        schedFuture.get();
        assertThat(nodeManager.getSkippedHealthChecks()).withFailMessage("We did not skip any heartbeat checks").isGreaterThan(0);
        // Step 4 : all nodes should still be HEALTHY
        assertEquals(2, nodeManager.getAllNodes().size());
        assertEquals(2, nodeManager.getNodeCount(NodeStatus.inServiceHealthy()));
        // Step 5 : heartbeat for node1
        nodeManager.processHeartbeat(node1);
        // Step 6 : wait for health check process to run
        Thread.sleep(1000);
        // Step 7 : node2 should transition to STALE
        assertEquals(1, nodeManager.getNodeCount(NodeStatus.inServiceHealthy()));
        assertEquals(1, nodeManager.getNodeCount(NodeStatus.inServiceStale()));
    }
}

@Test
public void testProcessLayoutVersion() throws IOException {
    // TODO: Refactor this class to use org.junit.jupiter so test
    //  parameterization can be used.
    for (FinalizationCheckpoint checkpoint : FinalizationCheckpoint.values()) {
        LOG.info("Testing with SCM finalization checkpoint {}", checkpoint);
        testProcessLayoutVersionLowerMlv(checkpoint);
        testProcessLayoutVersionReportHigherMlv(checkpoint);
    }
}

@Test
public void testProcessCommandQueueReport() throws IOException, NodeNotFoundException, AuthenticationException {
    OzoneConfiguration conf = new OzoneConfiguration();
    SCMStorageConfig scmStorageConfig = mock(SCMStorageConfig.class);
    when(scmStorageConfig.getClusterID()).thenReturn("xyz111");
    EventPublisher eventPublisher = mock(EventPublisher.class);
    HDDSLayoutVersionManager lvm = new HDDSLayoutVersionManager(scmStorageConfig.getLayoutVersion());
    createNodeManager(getConf());
    SCMNodeManager nodeManager = new SCMNodeManager(conf, scmStorageConfig, eventPublisher, new NetworkTopologyImpl(conf), scmContext, lvm);
    DatanodeDetails node1 = HddsTestUtils.createRandomDatanodeAndRegister(nodeManager);
    verify(eventPublisher, times(1)).fireEvent(NEW_NODE, node1);
    for (int i = 0; i < 3; i++) {
        nodeManager.addDatanodeCommand(node1.getUuid(), ReplicateContainerCommand.toTarget(1, MockDatanodeDetails.randomDatanodeDetails()));
    }
    for (int i = 0; i < 5; i++) {
        nodeManager.addDatanodeCommand(node1.getUuid(), new DeleteBlocksCommand(emptyList()));
    }
    assertEquals(3, nodeManager.getTotalDatanodeCommandCount(node1, SCMCommandProto.Type.replicateContainerCommand));
    assertEquals(5, nodeManager.getTotalDatanodeCommandCount(node1, SCMCommandProto.Type.deleteBlocksCommand));
    nodeManager.processHeartbeat(node1, CommandQueueReportProto.newBuilder().addCommand(SCMCommandProto.Type.replicateContainerCommand).addCount(123).addCommand(SCMCommandProto.Type.closeContainerCommand).addCount(11).build());
    assertEquals(-1, nodeManager.getNodeQueuedCommandCount(node1, SCMCommandProto.Type.closePipelineCommand));
    assertEquals(126, nodeManager.getNodeQueuedCommandCount(node1, SCMCommandProto.Type.replicateContainerCommand));
    assertEquals(11, nodeManager.getNodeQueuedCommandCount(node1, SCMCommandProto.Type.closeContainerCommand));
    assertEquals(5, nodeManager.getNodeQueuedCommandCount(node1, SCMCommandProto.Type.deleteBlocksCommand));
    assertEquals(126, nodeManager.getTotalDatanodeCommandCount(node1, SCMCommandProto.Type.replicateContainerCommand));
    assertEquals(5, nodeManager.getTotalDatanodeCommandCount(node1, SCMCommandProto.Type.deleteBlocksCommand));
    ArgumentCaptor<DatanodeDetails> captor = ArgumentCaptor.forClass(DatanodeDetails.class);
    verify(eventPublisher, times(1)).fireEvent(eq(DATANODE_COMMAND_COUNT_UPDATED), captor.capture());
    assertEquals(node1, captor.getValue());
    // Send another report missing an earlier entry, and ensure it is not
    // still reported as a stale value.
    nodeManager.processHeartbeat(node1, CommandQueueReportProto.newBuilder().addCommand(SCMCommandProto.Type.closeContainerCommand).addCount(11).build());
    assertEquals(-1, nodeManager.getNodeQueuedCommandCount(node1, SCMCommandProto.Type.replicateContainerCommand));
    assertEquals(11, nodeManager.getNodeQueuedCommandCount(node1, SCMCommandProto.Type.closeContainerCommand));
    verify(eventPublisher, times(2)).fireEvent(eq(DATANODE_COMMAND_COUNT_UPDATED), captor.capture());
    assertEquals(node1, captor.getValue());
    // Add a a few more commands to the queue and check the counts are the sum.
    for (int i = 0; i < 5; i++) {
        nodeManager.addDatanodeCommand(node1.getUuid(), new CloseContainerCommand(1, PipelineID.randomId()));
    }
    assertEquals(0, nodeManager.getTotalDatanodeCommandCount(node1, SCMCommandProto.Type.replicateContainerCommand));
    assertEquals(16, nodeManager.getTotalDatanodeCommandCount(node1, SCMCommandProto.Type.closeContainerCommand));
    Map<SCMCommandProto.Type, Integer> counts = nodeManager.getTotalDatanodeCommandCounts(node1, SCMCommandProto.Type.replicateContainerCommand, SCMCommandProto.Type.closeContainerCommand);
    assertEquals(0, counts.get(SCMCommandProto.Type.replicateContainerCommand));
    assertEquals(16, counts.get(SCMCommandProto.Type.closeContainerCommand));
}

