@Test
public void testUpdatePipelineStates() throws Exception {
    SCMHADBTransactionBuffer buffer = new SCMHADBTransactionBufferStub(dbStore);
    PipelineManagerImpl pipelineManager = createPipelineManager(true, buffer);
    Table<PipelineID, Pipeline> pipelineStore = SCMDBDefinition.PIPELINES.getTable(dbStore);
    Pipeline pipeline = assertAllocate(pipelineManager);
    buffer.flush();
    assertEquals(ALLOCATED, pipelineStore.get(pipeline.getId()).getPipelineState());
    PipelineID pipelineID = pipeline.getId();
    pipelineManager.openPipeline(pipelineID);
    pipelineManager.addContainerToPipeline(pipelineID, ContainerID.valueOf(1));
    assertTrue(pipelineManager.getPipelines(RatisReplicationConfig.getInstance(ReplicationFactor.THREE), Pipeline.PipelineState.OPEN).contains(pipeline));
    buffer.flush();
    assertTrue(pipelineStore.get(pipeline.getId()).isOpen());
    pipelineManager.deactivatePipeline(pipeline.getId());
    assertEquals(Pipeline.PipelineState.DORMANT, pipelineManager.getPipeline(pipelineID).getPipelineState());
    buffer.flush();
    assertEquals(Pipeline.PipelineState.DORMANT, pipelineStore.get(pipeline.getId()).getPipelineState());
    assertThat(pipelineManager.getPipelines(RatisReplicationConfig.getInstance(ReplicationFactor.THREE), Pipeline.PipelineState.OPEN)).doesNotContain(pipeline);
    assertEquals(1, pipelineManager.getPipelineCount(RatisReplicationConfig.getInstance(ReplicationFactor.THREE), Pipeline.PipelineState.DORMANT));
    pipelineManager.activatePipeline(pipeline.getId());
    assertTrue(pipelineManager.getPipelines(RatisReplicationConfig.getInstance(ReplicationFactor.THREE), Pipeline.PipelineState.OPEN).contains(pipeline));
    assertEquals(1, pipelineManager.getPipelineCount(RatisReplicationConfig.getInstance(ReplicationFactor.THREE), Pipeline.PipelineState.OPEN));
    buffer.flush();
    assertTrue(pipelineStore.get(pipeline.getId()).isOpen());
    pipelineManager.close();
}

