@Test
public void testScrubPipelines() throws Exception {
    // Allocated pipelines should not be scrubbed for 50 seconds.
    conf.setTimeDuration(OZONE_SCM_PIPELINE_ALLOCATED_TIMEOUT, 50, TimeUnit.SECONDS);
    conf.setTimeDuration(OZONE_SCM_PIPELINE_DESTROY_TIMEOUT, 50, TimeUnit.SECONDS);
    PipelineManagerImpl pipelineManager = createPipelineManager(true);
    Pipeline allocatedPipeline = pipelineManager.createPipeline(RatisReplicationConfig.getInstance(ReplicationFactor.THREE));
    // At this point, pipeline is not at OPEN stage.
    assertEquals(Pipeline.PipelineState.ALLOCATED, allocatedPipeline.getPipelineState());
    // pipeline should be seen in pipelineManager as ALLOCATED.
    assertTrue(pipelineManager.getPipelines(RatisReplicationConfig.getInstance(ReplicationFactor.THREE), Pipeline.PipelineState.ALLOCATED).contains(allocatedPipeline));
    Pipeline closedPipeline = pipelineManager.createPipeline(RatisReplicationConfig.getInstance(ReplicationFactor.THREE));
    pipelineManager.openPipeline(closedPipeline.getId());
    pipelineManager.closePipeline(closedPipeline, true);
    // pipeline should be seen in pipelineManager as CLOSED.
    assertTrue(pipelineManager.getPipelines(RatisReplicationConfig.getInstance(ReplicationFactor.THREE), Pipeline.PipelineState.CLOSED).contains(closedPipeline));
    // Set the clock to "now". All pipelines were created before this.
    testClock.set(Instant.now());
    pipelineManager.scrubPipelines();
    // The allocatedPipeline should not be scrubbed as the interval has not
    // yet passed.
    assertTrue(pipelineManager.getPipelines(RatisReplicationConfig.getInstance(ReplicationFactor.THREE), Pipeline.PipelineState.ALLOCATED).contains(allocatedPipeline));
    // The closedPipeline should not be scrubbed as the interval has not
    // yet passed.
    assertTrue(pipelineManager.getPipelines(RatisReplicationConfig.getInstance(ReplicationFactor.THREE), Pipeline.PipelineState.CLOSED).contains(closedPipeline));
    testClock.fastForward((60000));
    pipelineManager.scrubPipelines();
    // The allocatedPipeline should now be scrubbed as the interval has passed
    assertThat(pipelineManager.getPipelines(RatisReplicationConfig.getInstance(ReplicationFactor.THREE), Pipeline.PipelineState.ALLOCATED)).doesNotContain(allocatedPipeline);
    // The closedPipeline should now be scrubbed as the interval has passed
    assertThat(pipelineManager.getPipelines(RatisReplicationConfig.getInstance(ReplicationFactor.THREE), Pipeline.PipelineState.CLOSED)).doesNotContain(closedPipeline);
    pipelineManager.close();
}

