    assertNotSame(datanodeDetails.get(0).getUuid(), excludeNodes.get(1).getUuid());
    assertNotSame(datanodeDetails.get(1).getUuid(), excludeNodes.get(0).getUuid());
    assertNotSame(datanodeDetails.get(1).getUuid(), excludeNodes.get(1).getUuid());
    // One of the node should be in same rack as Node0
    assertTrue(cluster.isSameParent(usedNodes.get(0), datanodeDetails.get(0)) || cluster.isSameParent(usedNodes.get(0), datanodeDetails.get(1)));
    // 2 Used node
    usedNodes.clear();
    usedNodes.add(datanodes.get(0));
    usedNodes.add(datanodes.get(4));
    excludeNodes.add(datanodes.get(1));
    excludeNodes.add(datanodes.get(2));
    nodeNum = 1;
    datanodeDetails = policy.chooseDatanodes(usedNodes, excludeNodes, null, nodeNum, 15, 15);
    assertEquals(nodeNum, datanodeDetails.size());
    // policy should not return any of excluded node
    assertNotSame(datanodeDetails.get(0).getUuid(), excludeNodes.get(0).getUuid());
    assertNotSame(datanodeDetails.get(0).getUuid(), excludeNodes.get(1).getUuid());
    // Since rack0 has not enough node (node0 is used and node1 is excluded),
    // Anchor will change to node4(rack2) and will return another node
    // from rack2
    assertTrue(cluster.isSameParent(usedNodes.get(1), datanodeDetails.get(0)));
}

