@Test
public void testRemoveContainer() throws IOException, TimeoutException {
    long containerID = 1;
    Pipeline pipeline = createDummyPipeline(1);
    HddsProtos.Pipeline pipelineProto = pipeline.getProtobufMessage(ClientVersion.CURRENT_VERSION);
    // create an open pipeline in stateMap
    stateManager.addPipeline(pipelineProto);
    openPipeline(pipelineProto);
    stateManager.addContainerToPipeline(pipeline.getId(), ContainerID.valueOf(containerID));
    assertEquals(1, stateManager.getContainers(pipeline.getId()).size());
    stateManager.removeContainerFromPipeline(pipeline.getId(), ContainerID.valueOf(containerID));
    assertEquals(0, stateManager.getContainers(pipeline.getId()).size());
    // add two containers in the pipeline
    stateManager.addContainerToPipeline(pipeline.getId(), ContainerID.valueOf(++containerID));
    stateManager.addContainerToPipeline(pipeline.getId(), ContainerID.valueOf(++containerID));
    assertEquals(2, stateManager.getContainers(pipeline.getId()).size());
    // move pipeline to closing state
    finalizePipeline(pipelineProto);
    stateManager.removeContainerFromPipeline(pipeline.getId(), ContainerID.valueOf(containerID));
    stateManager.removeContainerFromPipeline(pipeline.getId(), ContainerID.valueOf(--containerID));
    assertEquals(0, stateManager.getContainers(pipeline.getId()).size());
    // clean up
    removePipeline(pipelineProto);
}

