@Test
public void testComputeMd5Crc() throws IOException {
    final int lenOfBytes = 32;
    byte[] randomChunkChecksum = RandomUtils.nextBytes(lenOfBytes);
    MD5Hash emptyBlockMD5 = MD5Hash.digest(randomChunkChecksum);
    byte[] emptyBlockMD5Hash = emptyBlockMD5.getDigest();
    AbstractBlockChecksumComputer computer = buildBlockChecksumComputer(randomChunkChecksum, lenOfBytes, ContainerProtos.ChecksumType.CRC32);
    computer.compute(MD5MD5CRC);
    ByteBuffer output = computer.getOutByteBuffer();
    assertArrayEquals(emptyBlockMD5Hash, output.array());
}

@Test
public void testComputeCompositeCrc() throws IOException {
    final int lenOfBytes = 32;
    byte[] randomChunkChecksum = RandomUtils.nextBytes(lenOfBytes);
    CrcComposer crcComposer = CrcComposer.newCrcComposer(DataChecksum.Type.CRC32C, 4);
    int chunkCrc = CrcUtil.readInt(randomChunkChecksum, 0);
    crcComposer.update(chunkCrc, 4);
    byte[] blockCompositeCRC = crcComposer.digest();
    AbstractBlockChecksumComputer computer = buildBlockChecksumComputer(randomChunkChecksum, lenOfBytes, ContainerProtos.ChecksumType.CRC32C);
    computer.compute(COMPOSITE_CRC);
    ByteBuffer output = computer.getOutByteBuffer();
    assertArrayEquals(blockCompositeCRC, output.array());
}

@Test
public void testEmptyBlock() throws IOException {
    // test the file checksum of a file with an empty block.
    RpcClient mockRpcClient = mock(RpcClient.class);
    OzoneManagerProtocol om = mock(OzoneManagerProtocol.class);
    when(mockRpcClient.getOzoneManagerClient()).thenReturn(om);
    OmKeyInfo omKeyInfo = new OmKeyInfo.Builder().setVolumeName(null).setBucketName(null).setKeyName(null).setOmKeyLocationInfos(Collections.singletonList(new OmKeyLocationInfoGroup(0, new ArrayList<>()))).setCreationTime(Time.now()).setModificationTime(Time.now()).setDataSize(0).setReplicationConfig(RatisReplicationConfig.getInstance(HddsProtos.ReplicationFactor.ONE)).setFileEncryptionInfo(null).setAcls(null).build();
    when(om.lookupKey(any())).thenReturn(omKeyInfo);
    OzoneVolume mockVolume = mock(OzoneVolume.class);
    when(mockVolume.getName()).thenReturn("vol1");
    OzoneBucket bucket = mock(OzoneBucket.class);
    when(bucket.getName()).thenReturn("bucket1");
    OzoneClientConfig.ChecksumCombineMode combineMode = OzoneClientConfig.ChecksumCombineMode.MD5MD5CRC;
    ReplicatedFileChecksumHelper helper = new ReplicatedFileChecksumHelper(mockVolume, bucket, "dummy", 10, combineMode, mockRpcClient);
    helper.compute();
    FileChecksum fileChecksum = helper.getFileChecksum();
    assertInstanceOf(MD5MD5CRC32GzipFileChecksum.class, fileChecksum);
    assertEquals(DataChecksum.Type.CRC32, ((MD5MD5CRC32GzipFileChecksum) fileChecksum).getCrcType());
    // test negative length
    helper = new ReplicatedFileChecksumHelper(mockVolume, bucket, "dummy", -1, combineMode, mockRpcClient);
    helper.compute();
    assertNull(helper.getKeyLocationInfoList());
}

