@Test
public void testSmallerThanChunkSize() throws IOException {
    byte[] firstSmallChunk = new byte[chunkSize - 1];
    Arrays.fill(firstSmallChunk, 0, firstSmallChunk.length - 1, Byte.parseByte("1"));
    writeIntoECKey(firstSmallChunk, keyName, new DefaultReplicationConfig(new ECReplicationConfig(dataBlocks, parityBlocks, ECReplicationConfig.EcCodec.RS, chunkSize)));
    OzoneManagerProtocolProtos.KeyLocationList blockList = transportStub.getKeys().get(volumeName).get(bucketName).get(keyName).getKeyLocationListList().get(0);
    Map<DatanodeDetails, MockDatanodeStorage> storages = factoryStub.getStorages();
    OzoneManagerProtocolProtos.KeyLocation keyLocations = blockList.getKeyLocations(0);
    List<MockDatanodeStorage> dns = new ArrayList<>();
    for (int i = 0; i < dataBlocks + parityBlocks; i++) {
        HddsProtos.DatanodeDetailsProto member = blockList.getKeyLocations(0).getPipeline().getMembers(i);
        MockDatanodeStorage mockDatanodeStorage = storages.get(getMatchingStorage(storages, member.getUuid()));
        dns.add(mockDatanodeStorage);
    }
    String firstBlockData = dns.get(0).getFullBlockData(new BlockID(keyLocations.getBlockID().getContainerBlockID().getContainerID(), keyLocations.getBlockID().getContainerBlockID().getLocalID()));
    assertArrayEquals(firstSmallChunk, firstBlockData.getBytes(UTF_8));
    final ByteBuffer[] dataBuffers = new ByteBuffer[dataBlocks];
    dataBuffers[0] = ByteBuffer.wrap(firstSmallChunk);
    //Let's pad the remaining length equal to firstSmall chunk len
    for (int i = 1; i < dataBlocks; i++) {
        dataBuffers[i] = ByteBuffer.allocate(firstSmallChunk.length);
        Arrays.fill(dataBuffers[i].array(), 0, firstSmallChunk.length, (byte) 0);
    }
    final ByteBuffer[] parityBuffers = new ByteBuffer[parityBlocks];
    for (int i = 0; i < parityBlocks; i++) {
        parityBuffers[i] = ByteBuffer.allocate(firstSmallChunk.length);
    }
    encoder.encode(dataBuffers, parityBuffers);
    //Lets assert the parity data.
    for (int i = dataBlocks; i < dataBlocks + parityBlocks; i++) {
        String parityBlockData = dns.get(i).getFullBlockData(new BlockID(keyLocations.getBlockID().getContainerBlockID().getContainerID(), keyLocations.getBlockID().getContainerBlockID().getLocalID()));
        String expected = new String(parityBuffers[i - dataBlocks].array(), UTF_8);
        assertEquals(expected, parityBlockData);
        assertEquals(expected.length(), parityBlockData.length());
    }
}

