@Test
public void testCanonicalTokenServiceName() throws IOException {
    OzoneConfiguration ozoneConf = new OzoneConfiguration();
    ArrayList<String> nodeAddrs = new ArrayList<>(Arrays.asList("4.3.2.1:9862", "2.1.0.5:9862", "3.2.1.0:9862"));
    assertEquals(numNodes, nodeAddrs.size());
    StringJoiner allNodeIds = new StringJoiner(",");
    for (int i = 1; i <= numNodes; i++) {
        String nodeId = NODE_ID_BASE_STR + i;
        ozoneConf.set(ConfUtils.addKeySuffixes(OZONE_OM_ADDRESS_KEY, OM_SERVICE_ID, nodeId), nodeAddrs.get(i - 1));
        allNodeIds.add(nodeId);
    }
    ozoneConf.set(ConfUtils.addKeySuffixes(OZONE_OM_NODES_KEY, OM_SERVICE_ID), allNodeIds.toString());
    HadoopRpcOMFailoverProxyProvider prov = new HadoopRpcOMFailoverProxyProvider(ozoneConf, UserGroupInformation.getCurrentUser(), OM_SERVICE_ID, OzoneManagerProtocolPB.class);
    Text dtService = prov.getCurrentProxyDelegationToken();
    Collections.sort(nodeAddrs);
    String expectedDtService = String.join(",", nodeAddrs);
    assertEquals(expectedDtService, dtService.toString());
