            int res = ToolRunner.run(shell, new String[] { "-rm", "-skipTrash", linkPathStr });
            assertEquals(0, res);
            try {
                objectStore.getVolume(destVolume).getBucket(srcBucket);
                fail("Bucket should not exist, should throw OMException");
            } catch (OMException ex) {
                assertEquals(BUCKET_NOT_FOUND, ex.getResult());
            }
            assertEquals(srcBucket, objectStore.getVolume(srcVolume).getBucket(srcBucket).getName());
            assertEquals(key, objectStore.getVolume(srcVolume).getBucket(srcBucket).getKey(key).getName());
            // re-create symlink
            createLinkBucket(destVolume, srcBucket, srcVolume, srcBucket);
            assertTrue(fs.exists(new Path(OZONE_URI_DELIMITER + destVolume + OZONE_URI_DELIMITER + srcBucket)));
            // test symlink -rm -R -f destVol/destBucket/ -> srcVol/srcBucket
            // should delete only link contents (src bucket contents),
            // link and srcBucket unaltered
            // run toolrunner ozone fs shell commands
            linkPathStr = rootPath + destVolume + OZONE_URI_DELIMITER + srcBucket;
            res = ToolRunner.run(shell, new String[] { "-rm", "-skipTrash", "-f", "-R", linkPathStr + OZONE_URI_DELIMITER });
            assertEquals(0, res);
            assertEquals(srcBucket, objectStore.getVolume(destVolume).getBucket(srcBucket).getName());
            assertTrue(objectStore.getVolume(destVolume).getBucket(srcBucket).isLink());
            assertEquals(srcBucket, objectStore.getVolume(srcVolume).getBucket(srcBucket).getName());
            try {
                objectStore.getVolume(srcVolume).getBucket(srcBucket).getKey(key);
                fail("Key should be deleted under srcBucket, " + "OMException expected");
            } catch (OMException ex) {
                assertEquals(KEY_NOT_FOUND, ex.getResult());
            }
            // test symlink -rm -R -f destVol/destBucket -> srcVol/srcBucket
            // should delete only link
            // run toolrunner ozone fs shell commands
            linkPathStr = rootPath + destVolume + OZONE_URI_DELIMITER + srcBucket;
            res = ToolRunner.run(shell, new String[] { "-rm", "-skipTrash", "-f", "-R", linkPathStr });
            assertEquals(0, res);
            assertEquals(srcBucket, objectStore.getVolume(srcVolume).getBucket(srcBucket).getName());
            // test link existence
            try {
                objectStore.getVolume(destVolume).getBucket(srcBucket);
                fail("link should not exist, " + "OMException expected");
            } catch (OMException ex) {
                assertEquals(BUCKET_NOT_FOUND, ex.getResult());
            }
            // test src bucket existence
            assertEquals(objectStore.getVolume(srcVolume).getBucket(srcBucket).getName(), srcBucket);
        } finally {
            shell.close();
        }
    } finally {
        // cleanup; note must delete link before link src bucket
        // due to bug - HDDS-7884
        fs.delete(new Path(OZONE_URI_DELIMITER + destVolume + OZONE_URI_DELIMITER + srcBucket));
        fs.delete(new Path(OZONE_URI_DELIMITER + srcVolume + OZONE_URI_DELIMITER + srcBucket));
        fs.delete(new Path(OZONE_URI_DELIMITER + srcVolume), false);
        fs.delete(new Path(OZONE_URI_DELIMITER + destVolume), false);
    }
}

