/**
 *  Test EC checksum with Replicated checksum.
 */
@ParameterizedTest
@MethodSource("missingIndexes")
void testEcFileChecksum(List<Integer> missingIndexes) throws IOException {
    String volumeName = UUID.randomUUID().toString();
    String legacyBucket = UUID.randomUUID().toString();
    String ecBucketName = UUID.randomUUID().toString();
    client.getObjectStore().createVolume(volumeName);
    BucketArgs.Builder bucketArgs = BucketArgs.newBuilder().setStorageType(StorageType.DISK).setBucketLayout(BucketLayout.LEGACY);
    createBucket(client, volumeName, bucketArgs.build(), legacyBucket);
    bucketArgs.setDefaultReplicationConfig(new DefaultReplicationConfig(new ECReplicationConfig("RS-3-2-1024k")));
    final OzoneBucket ecBucket = createBucket(client, volumeName, bucketArgs.build(), ecBucketName);
    assertEquals(ReplicationType.EC.name(), ecBucket.getReplicationConfig().getReplicationType().name());
    Map<Integer, String> replicatedChecksums = new HashMap<>();
    for (int dataLen : DATA_SIZES) {
        byte[] data = randomAlphabetic(dataLen).getBytes(UTF_8);
        try (OutputStream file = adapter.createFile(volumeName + "/" + legacyBucket + "/test" + dataLen, (short) 3, true, false)) {
            file.write(data);
        }
        Path parent1 = new Path("/" + volumeName + "/" + legacyBucket + "/");
        Path replicatedKey = new Path(parent1, "test" + dataLen);
        FileChecksum replicatedChecksum = fs.getFileChecksum(replicatedKey);
        String replicatedChecksumString = StringUtils.byteToHexString(replicatedChecksum.getBytes(), 0, replicatedChecksum.getLength());
        replicatedChecksums.put(dataLen, replicatedChecksumString);
        try (OutputStream file = adapter.createFile(volumeName + "/" + ecBucketName + "/test" + dataLen, (short) 3, true, false)) {
            file.write(data);
        }
    }
    // Fail DataNodes
    for (int index : missingIndexes) {
        cluster.shutdownHddsDatanode(index);
    }
    for (boolean topologyAware : TOPOLOGY_AWARENESS) {
        OzoneConfiguration clientConf = new OzoneConfiguration(conf);
        clientConf.setBoolean(OZONE_NETWORK_TOPOLOGY_AWARE_READ_KEY, topologyAware);
        try (FileSystem fsForRead = FileSystem.get(clientConf)) {
            for (int dataLen : DATA_SIZES) {
                // Compute checksum after failed DNs
                Path parent = new Path("/" + volumeName + "/" + ecBucketName + "/");
                Path ecKey = new Path(parent, "test" + dataLen);
                FileChecksum ecChecksum = fsForRead.getFileChecksum(ecKey);
                String ecChecksumString = StringUtils.byteToHexString(ecChecksum.getBytes(), 0, ecChecksum.getLength());
                assertEquals(replicatedChecksums.get(dataLen), ecChecksumString, () -> "Checksum mismatch for data size: " + dataLen + ", topologyAware: " + topologyAware + ", failed nodes: " + missingIndexes);
            }
        }
    }
}

