@Test
void testScmSafeMode() throws Exception {
    int datanodeCount = 6;
    setup(datanodeCount);
    waitForRatis3NodePipelines(datanodeCount / 3);
    waitForRatis1NodePipelines(datanodeCount);
    int totalPipelineCount = datanodeCount + (datanodeCount / 3);
    //Cluster is started successfully
    cluster.stop();
    cluster.restartOzoneManager();
    cluster.restartStorageContainerManager(false);
    pipelineManager = cluster.getStorageContainerManager().getPipelineManager();
    List<Pipeline> pipelineList = pipelineManager.getPipelines(RatisReplicationConfig.getInstance(ReplicationFactor.THREE));
    pipelineList.get(0).getNodes().forEach(datanodeDetails -> {
        try {
            cluster.restartHddsDatanode(datanodeDetails, false);
        } catch (Exception ex) {
            fail("Datanode restart failed");
        }
    });
    SCMSafeModeManager scmSafeModeManager = cluster.getStorageContainerManager().getScmSafeModeManager();
    // Ceil(0.1 * 2) is 1, as one pipeline is healthy pipeline rule is
    // satisfied
    GenericTestUtils.waitFor(() -> scmSafeModeManager.getHealthyPipelineSafeModeRule().validate(), 1000, 60000);
    // As Ceil(0.9 * 2) is 2, and from second pipeline no datanodes's are
    // reported this rule is not met yet.
    GenericTestUtils.waitFor(() -> !scmSafeModeManager.getOneReplicaPipelineSafeModeRule().validate(), 1000, 60000);
    assertTrue(cluster.getStorageContainerManager().isInSafeMode());
    DatanodeDetails restartedDatanode = pipelineList.get(1).getFirstNode();
    // Now restart one datanode from the 2nd pipeline
    cluster.restartHddsDatanode(restartedDatanode, false);
    GenericTestUtils.waitFor(() -> scmSafeModeManager.getOneReplicaPipelineSafeModeRule().validate(), 1000, 60000);
    // All safeMode preChecks are now satisfied, SCM should be out of safe mode.
    GenericTestUtils.waitFor(() -> !scmSafeModeManager.getInSafeMode(), 1000, 60000);
    // As after safeMode wait time is not completed, we should have total
    // pipeline's as original count 6(1 node pipelines) + 2 (3 node pipeline)
    assertEquals(totalPipelineCount, pipelineManager.getPipelines().size());
    // The below check calls pipelineManager.getPipelines()
    // which is a call to the SCM to get the list of pipeline infos.
    // This is independent of DN reports or whether any number of DataNodes are
    // alive as the pipeline info is persisted to SCM upon creation and loaded
    // back upon restart.
    waitForRatis1NodePipelines(datanodeCount);
    waitForRatis3NodePipelines(datanodeCount / 3);
    ReplicationManager replicationManager = cluster.getStorageContainerManager().getReplicationManager();
    GenericTestUtils.waitFor(() -> replicationManager.isRunning(), 1000, 60000);
}

@Test
public void testReleaseBuffers() throws Exception {
    int capacity = 2;
    BufferPool bufferPool = new BufferPool(chunkSize, capacity);
    try (XceiverClientManager mgr = new XceiverClientManager(conf)) {
        ContainerWithPipeline container = storageContainerLocationClient.allocateContainer(HddsProtos.ReplicationType.RATIS, HddsProtos.ReplicationFactor.THREE, OzoneConsts.OZONE);
        Pipeline pipeline = container.getPipeline();
        long containerId = container.getContainerInfo().getContainerID();
        try (XceiverClientSpi xceiverClient = mgr.acquireClient(pipeline)) {
            assertEquals(1, xceiverClient.getRefcount());
            XceiverClientRatis ratisClient = assertInstanceOf(XceiverClientRatis.class, xceiverClient);
            CommitWatcher watcher = new CommitWatcher(bufferPool, ratisClient);
            BlockID blockID = ContainerTestHelper.getTestBlockID(containerId);
            List<XceiverClientReply> replies = new ArrayList<>();
            long length = 0;
            List<CompletableFuture<ContainerCommandResponseProto>> futures = new ArrayList<>();
            for (int i = 0; i < capacity; i++) {
                ContainerCommandRequestProto writeChunkRequest = ContainerTestHelper.getWriteChunkRequest(pipeline, blockID, chunkSize);
                // add the data to the buffer pool
                final ChunkBuffer byteBuffer = bufferPool.allocateBuffer(0);
                byteBuffer.put(writeChunkRequest.getWriteChunk().getData());
                ratisClient.sendCommandAsync(writeChunkRequest);
                ContainerCommandRequestProto putBlockRequest = ContainerTestHelper.getPutBlockRequest(pipeline, writeChunkRequest.getWriteChunk());
                XceiverClientReply reply = ratisClient.sendCommandAsync(putBlockRequest);
                final List<ChunkBuffer> bufferList = singletonList(byteBuffer);
                length += byteBuffer.position();
                CompletableFuture<ContainerCommandResponseProto> future = reply.getResponse().thenApply(v -> {
                    watcher.updateCommitInfoMap(reply.getLogIndex(), bufferList);
                    return v;
                });
                futures.add(future);
                watcher.putFlushFuture(length, future);
                replies.add(reply);
            }
            assertEquals(2, replies.size());
            // wait on the 1st putBlock to complete
            CompletableFuture<ContainerCommandResponseProto> future1 = futures.get(0);
            CompletableFuture<ContainerCommandResponseProto> future2 = futures.get(1);
            future1.get();
            assertEquals(future1, watcher.getFutureMap().get((long) chunkSize));
            // wait on 2nd putBlock to complete
            future2.get();
            assertEquals(future2, watcher.getFutureMap().get((long) 2 * chunkSize));
            assertEquals(2, watcher.getCommitIndexMap().size());
            watcher.watchOnFirstIndex();
            assertThat(watcher.getCommitIndexMap()).doesNotContainKey(replies.get(0).getLogIndex());
            assertThat(watcher.getFutureMap()).doesNotContainKey((long) chunkSize);
            assertThat(watcher.getTotalAckDataLength()).isGreaterThanOrEqualTo(chunkSize);
            watcher.watchOnLastIndex();
            assertThat(watcher.getCommitIndexMap()).doesNotContainKey(replies.get(1).getLogIndex());
            assertThat(watcher.getFutureMap()).doesNotContainKey((long) 2 * chunkSize);
            assertEquals(2 * chunkSize, watcher.getTotalAckDataLength());
            assertThat(watcher.getFutureMap()).isEmpty();
            assertThat(watcher.getCommitIndexMap()).isEmpty();
        }
    } finally {
        bufferPool.clearBufferPool();
    }
}

