                CompletableFuture<ContainerCommandResponseProto> future = reply.getResponse().thenApply(v -> {
                    watcher.updateCommitInfoMap(reply.getLogIndex(), bufferList);
                    return v;
                });
                futures.add(future);
                watcher.putFlushFuture(length, future);
                replies.add(reply);
            }
            assertEquals(2, replies.size());
            // wait on the 1st putBlock to complete
            CompletableFuture<ContainerCommandResponseProto> future1 = futures.get(0);
            CompletableFuture<ContainerCommandResponseProto> future2 = futures.get(1);
            future1.get();
            assertEquals(future1, watcher.getFutureMap().get((long) chunkSize));
            // wait on 2nd putBlock to complete
            future2.get();
            assertEquals(future2, watcher.getFutureMap().get((long) 2 * chunkSize));
            assertEquals(2, watcher.getCommitIndexMap().size());
            watcher.watchOnFirstIndex();
            assertThat(watcher.getCommitIndexMap()).doesNotContainKey(replies.get(0).getLogIndex());
            assertThat(watcher.getFutureMap()).doesNotContainKey((long) chunkSize);
            assertThat(watcher.getTotalAckDataLength()).isGreaterThanOrEqualTo(chunkSize);
            cluster.shutdownHddsDatanode(pipeline.getNodes().get(0));
            cluster.shutdownHddsDatanode(pipeline.getNodes().get(1));
            // just watch for a higher index so as to ensure, it does an actual
            // call to Ratis. Otherwise, it may just return in case the
            // commitInfoMap is updated to the latest index in putBlock response.
            IOException ioe = assertThrows(IOException.class, () -> watcher.watchForCommit(replies.get(1).getLogIndex() + 100));
            Throwable t = HddsClientUtils.checkForException(ioe);
            // with retry count set to noRetry and a lower watch request
            // timeout, watch request will eventually
            // fail with TimeoutIOException from ratis client or the client
            // can itself get AlreadyClosedException from the Ratis Server
            // and the write may fail with RaftRetryFailureException
            assertTrue(t instanceof RaftRetryFailureException || t instanceof TimeoutIOException || t instanceof AlreadyClosedException || t instanceof NotReplicatedException, "Unexpected exception: " + t.getClass());
            if (ratisClient.getReplicatedMinCommitIndex() < replies.get(1).getLogIndex()) {
                assertEquals(chunkSize, watcher.getTotalAckDataLength());
                assertEquals(1, watcher.getCommitIndexMap().size());
                assertEquals(1, watcher.getFutureMap().size());
            } else {
                assertEquals(2 * chunkSize, watcher.getTotalAckDataLength());
                assertThat(watcher.getFutureMap()).isEmpty();
                assertThat(watcher.getCommitIndexMap()).isEmpty();
            }
        }
    } finally {
        bufferPool.clearBufferPool();
    }
}

@Test
public void testOrphanBlock() throws Exception {
    // Close all pipelines so we are guaranteed to get a new one
    closeAllPipelines(repConfig);
    // First write a full stripe, which is chunksize * dataNum
    int keyLen = EC_CHUNK_SIZE * EC_DATA;
    String keyName = UUID.randomUUID().toString();
    try (OutputStream out = classBucket.createKey(keyName, keyLen, repConfig, new HashMap<>())) {
        out.write(RandomUtils.nextBytes(keyLen));
    }
    long orphanContainerID = classBucket.getKey(keyName).getOzoneKeyLocations().get(0).getContainerID();
    PipelineID orphanPipelineID = scm.getContainerManager().getContainer(ContainerID.valueOf(orphanContainerID)).getPipelineID();
    Pipeline orphanPipeline = scm.getPipelineManager().getPipeline(orphanPipelineID);
    Token<ContainerTokenIdentifier> orphanContainerToken = containerTokenGenerator.generateToken(ANY_USER, new ContainerID(orphanContainerID));
    // Close the container by closing the pipeline
    scm.getPipelineManager().closePipeline(orphanPipeline, false);
    // Find the datanode hosting Replica index = 2
    HddsDatanodeService dn2Service = null;
    List<DatanodeDetails> pipelineNodes = orphanPipeline.getNodes();
    DatanodeDetails dn2 = findDatanodeWithIndex(orphanPipeline, pipelineNodes, 2);
    // Find the Cluster node corresponding to the datanode hosting index = 2
    for (HddsDatanodeService dn : cluster.getHddsDatanodes()) {
        if (dn.getDatanodeDetails().equals(dn2)) {
            dn2Service = dn;
            break;
        }
    }
    if (dn2 == null || dn2Service == null) {
        throw new RuntimeException("Could not find datanode hosting index 2");
    }
    // Wait for all replicas in the pipeline to report as closed.
    GenericTestUtils.waitFor(() -> {
        try {
            return scm.getContainerManager().getContainerReplicas(ContainerID.valueOf(orphanContainerID)).stream().allMatch(cr -> cr.getState() == StorageContainerDatanodeProtocolProtos.ContainerReplicaProto.State.CLOSED);
        } catch (ContainerNotFoundException e) {
            throw new RuntimeException(e);
        }
    }, 500, 10000);
    // Get the block ID of the key we have just written. This will be used to
    // delete the block from one of the datanode to make the stripe look like
    // a orphan block.
    long localID = classBucket.getKey(keyName).getOzoneKeyLocations().get(0).getLocalID();
    // Create a delete command for the block and sent it.
    DeleteBlocksCommand deleteBlocksCommand = new DeleteBlocksCommand(ImmutableList.of(StorageContainerDatanodeProtocolProtos.DeletedBlocksTransaction.newBuilder().setContainerID(orphanContainerID).addLocalID(localID).setTxID(1L).setCount(10).build()));
    dn2Service.getDatanodeStateMachine().getContext().addCommand(deleteBlocksCommand);
    try (XceiverClientGrpc client = new XceiverClientGrpc(createSingleNodePipeline(orphanPipeline, dn2, 1), cluster.getConf())) {
        // Wait for the block to be actually deleted
        GenericTestUtils.waitFor(() -> {
            try {
                ListBlockResponseProto response = ContainerProtocolCalls.listBlock(client, orphanContainerID, null, Integer.MAX_VALUE, orphanContainerToken);
                for (BlockData bd : response.getBlockDataList()) {
                    if (bd.getBlockID().getLocalID() == localID) {
                        return false;
                    }
                }
                return true;
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }, 500, 30000);
    }
    // Create a reconstruction command to create a new copy of indexes 4 and 5
    // which means 1 to 3 must be available. However we know the block
    // information is missing for index 2. As all containers in the stripe must
    // have the block information, this makes the stripe look like a orphan
    // block, where the write went to some nodes but not all.
    SortedMap<Integer, DatanodeDetails> sourceNodeMap = new TreeMap<>();
    for (DatanodeDetails node : orphanPipeline.getNodes()) {
        if (orphanPipeline.getReplicaIndex(node) <= EC_DATA) {
            sourceNodeMap.put(orphanPipeline.getReplicaIndex(node), node);
        }
    }
    // Here we find some spare nodes - ie nodes in the cluster that are not in
    // the original pipeline.
    List<DatanodeDetails> targets = cluster.getHddsDatanodes().stream().map(HddsDatanodeService::getDatanodeDetails).filter(d -> !orphanPipeline.getNodes().contains(d)).limit(2).collect(Collectors.toList());
    SortedMap<Integer, DatanodeDetails> targetNodeMap = new TreeMap<>();
    for (int j = 0; j < targets.size(); j++) {
        targetNodeMap.put(EC_DATA + j + 1, targets.get(j));
    }
    try (ECReconstructionCoordinator coordinator = new ECReconstructionCoordinator(config, certClient, secretKeyClient, null, ECReconstructionMetrics.create(), "")) {
        // Attempt to reconstruct the container.
        coordinator.reconstructECContainerGroup(orphanContainerID, (ECReplicationConfig) repConfig, sourceNodeMap, targetNodeMap);
    }
    // Check the block listing for the recovered containers 4 or 5 and they
    // should be present but with no blocks as the only block in the container
    // was an orphan block.
    try (XceiverClientGrpc reconClient = new XceiverClientGrpc(createSingleNodePipeline(orphanPipeline, targetNodeMap.get(4), 4), cluster.getConf())) {
        ListBlockResponseProto response = ContainerProtocolCalls.listBlock(reconClient, orphanContainerID, null, Integer.MAX_VALUE, orphanContainerToken);
        long count = response.getBlockDataList().stream().filter(bd -> bd.getBlockID().getLocalID() == localID).count();
        assertEquals(0L, count);
        assertEquals(0, response.getBlockDataList().size());
    }
}

@Test
public void testListBlock() throws Exception {
    for (int i = 0; i < datanodeDetails.size(); i++) {
        final int minKeySize = i < EC_DATA ? i * EC_CHUNK_SIZE : 0;
        final int minNumExpectedBlocks = (int) Arrays.stream(values).mapToInt(v -> v.length).filter(s -> s > minKeySize).count();
        Function<Integer, Integer> expectedChunksFunc = chunksInReplicaFunc(i);
        final int minNumExpectedChunks = Arrays.stream(values).mapToInt(v -> v.length).map(expectedChunksFunc::apply).sum();
        if (minNumExpectedBlocks == 0) {
            final int j = i;
            Throwable t = assertThrows(StorageContainerException.class, () -> ContainerProtocolCalls.listBlock(clients.get(j), containerID, null, minNumExpectedBlocks + 1, containerToken));
            assertEquals("ContainerID " + containerID + " does not exist", t.getMessage());
            continue;
        }
        ListBlockResponseProto response = ContainerProtocolCalls.listBlock(clients.get(i), containerID, null, Integer.MAX_VALUE, containerToken);
        assertThat(minNumExpectedBlocks).withFailMessage("blocks count should be same or more than min expected" + " blocks count on DN " + i).isLessThanOrEqualTo(response.getBlockDataList().stream().filter(k -> k.getChunksCount() > 0 && k.getChunks(0).getLen() > 0).collect(Collectors.toList()).size());
        assertThat(minNumExpectedChunks).withFailMessage("chunks count should be same or more than min expected" + " chunks count on DN " + i).isLessThanOrEqualTo(response.getBlockDataList().stream().mapToInt(BlockData::getChunksCount).sum());
    }
}

@Test
public void testCreateRecoveryContainer() throws Exception {
    try (XceiverClientManager xceiverClientManager = new XceiverClientManager(config)) {
        ECReplicationConfig replicationConfig = new ECReplicationConfig(3, 2);
        Pipeline newPipeline = scm.getPipelineManager().createPipeline(replicationConfig);
        scm.getPipelineManager().activatePipeline(newPipeline.getId());
        final ContainerInfo container = scm.getContainerManager().allocateContainer(replicationConfig, "test");
        Token<ContainerTokenIdentifier> cToken = containerTokenGenerator.generateToken(ANY_USER, container.containerID());
        scm.getContainerManager().getContainerStateManager().addContainer(container.getProtobuf());
        int replicaIndex = 4;
        XceiverClientSpi dnClient = xceiverClientManager.acquireClient(createSingleNodePipeline(newPipeline, newPipeline.getNodes().get(0), replicaIndex));
        try {
            // To create the actual situation, container would have been in closed
            // state at SCM.
            scm.getContainerManager().getContainerStateManager().updateContainerState(container.containerID().getProtobuf(), HddsProtos.LifeCycleEvent.FINALIZE);
            scm.getContainerManager().getContainerStateManager().updateContainerState(container.containerID().getProtobuf(), HddsProtos.LifeCycleEvent.CLOSE);
            //Create the recovering container in DN.
            String encodedToken = cToken.encodeToUrlString();
            ContainerProtocolCalls.createRecoveringContainer(dnClient, container.containerID().getProtobuf().getId(), encodedToken, replicaIndex);
            BlockID blockID = ContainerTestHelper.getTestBlockID(container.containerID().getProtobuf().getId());
            Token<? extends TokenIdentifier> blockToken = blockTokenGenerator.generateToken(ANY_USER, blockID, EnumSet.of(READ, WRITE), Long.MAX_VALUE);
            byte[] data = "TestData".getBytes(UTF_8);
            ContainerProtos.ContainerCommandRequestProto writeChunkRequest = newWriteChunkRequestBuilder(newPipeline, blockID, ChunkBuffer.wrap(ByteBuffer.wrap(data)), 0).setEncodedToken(blockToken.encodeToUrlString()).build();
            dnClient.sendCommand(writeChunkRequest);
            // Now, explicitly make a putKey request for the block.
            ContainerProtos.ContainerCommandRequestProto putKeyRequest = ContainerTestHelper.getPutBlockRequest(newPipeline, writeChunkRequest.getWriteChunk());
            dnClient.sendCommand(putKeyRequest);
            ContainerProtos.ReadContainerResponseProto readContainerResponseProto = ContainerProtocolCalls.readContainer(dnClient, container.containerID().getProtobuf().getId(), encodedToken);
            assertEquals(ContainerProtos.ContainerDataProto.State.RECOVERING, readContainerResponseProto.getContainerData().getState());
            // Container at SCM should be still in closed state.
            assertEquals(HddsProtos.LifeCycleState.CLOSED, scm.getContainerManager().getContainerStateManager().getContainer(container.containerID()).getState());
            // close container call
            ContainerProtocolCalls.closeContainer(dnClient, container.containerID().getProtobuf().getId(), encodedToken);
            // Make sure we have the container and readable.
            readContainerResponseProto = ContainerProtocolCalls.readContainer(dnClient, container.containerID().getProtobuf().getId(), encodedToken);
            assertEquals(ContainerProtos.ContainerDataProto.State.CLOSED, readContainerResponseProto.getContainerData().getState());
            ContainerProtos.ReadChunkResponseProto readChunkResponseProto = ContainerProtocolCalls.readChunk(dnClient, writeChunkRequest.getWriteChunk().getChunkData(), blockID.getDatanodeBlockIDProtobufBuilder().setReplicaIndex(replicaIndex).build(), null, blockToken);
            ByteBuffer[] readOnlyByteBuffersArray = BufferUtils.getReadOnlyByteBuffersArray(readChunkResponseProto.getDataBuffers().getBuffersList());
            assertEquals(readOnlyByteBuffersArray[0].limit(), data.length);
            byte[] readBuff = new byte[readOnlyByteBuffersArray[0].limit()];
            readOnlyByteBuffersArray[0].get(readBuff, 0, readBuff.length);
            assertArrayEquals(data, readBuff);
        } finally {
            xceiverClientManager.releaseClient(dnClient, false);
        }
    }
}

@Test
public void testCreateRecoveryContainerAfterDNRestart() throws Exception {
    try (XceiverClientManager xceiverClientManager = new XceiverClientManager(config)) {
        ECReplicationConfig replicationConfig = new ECReplicationConfig(3, 2);
        Pipeline newPipeline = scm.getPipelineManager().createPipeline(replicationConfig);
        scm.getPipelineManager().activatePipeline(newPipeline.getId());
        final ContainerInfo container = scm.getContainerManager().allocateContainer(replicationConfig, "test");
        Token<ContainerTokenIdentifier> cToken = containerTokenGenerator.generateToken(ANY_USER, container.containerID());
        scm.getContainerManager().getContainerStateManager().addContainer(container.getProtobuf());
        DatanodeDetails targetDN = newPipeline.getNodes().get(0);
        XceiverClientSpi dnClient = xceiverClientManager.acquireClient(createSingleNodePipeline(newPipeline, targetDN, 2));
        try {
            // To create the actual situation, container would have been in closed
            // state at SCM.
            scm.getContainerManager().getContainerStateManager().updateContainerState(container.containerID().getProtobuf(), HddsProtos.LifeCycleEvent.FINALIZE);
            scm.getContainerManager().getContainerStateManager().updateContainerState(container.containerID().getProtobuf(), HddsProtos.LifeCycleEvent.CLOSE);
            //Create the recovering container in target DN.
            String encodedToken = cToken.encodeToUrlString();
            ContainerProtocolCalls.createRecoveringContainer(dnClient, container.containerID().getProtobuf().getId(), encodedToken, 4);
            // Restart the DN.
            cluster.restartHddsDatanode(targetDN, true);
            // Recovering container state after DN restart should be UNHEALTHY.
            assertEquals(ContainerProtos.ContainerDataProto.State.UNHEALTHY, cluster.getHddsDatanode(targetDN).getDatanodeStateMachine().getContainer().getContainerSet().getContainer(container.getContainerID()).getContainerState());
            // Writes to recovering container after DN restart should fail
            // because the container is marked UNHEALTHY
            // and hence does not accept any writes.
            BlockID blockID = ContainerTestHelper.getTestBlockID(container.containerID().getProtobuf().getId());
            Token<? extends TokenIdentifier> blockToken = blockTokenGenerator.generateToken(ANY_USER, blockID, EnumSet.of(READ, WRITE), Long.MAX_VALUE);
            byte[] data = "TestData".getBytes(UTF_8);
            ContainerProtos.ContainerCommandRequestProto writeChunkRequest = newWriteChunkRequestBuilder(newPipeline, blockID, ChunkBuffer.wrap(ByteBuffer.wrap(data)), 0).setEncodedToken(blockToken.encodeToUrlString()).build();
            scm.getPipelineManager().activatePipeline(newPipeline.getId());
            try {
                dnClient.sendCommand(writeChunkRequest);
            } catch (StorageContainerException e) {
                assertEquals(CONTAINER_UNHEALTHY, e.getResult());
            }
        } finally {
            xceiverClientManager.releaseClient(dnClient, false);
        }
    }
}

