@Test
public void testECReconstructionCoordinatorShouldCleanupContainersOnFailure() throws Exception {
    List<Integer> missingIndexes = ImmutableList.of(1, 3);
    ObjectStore objectStore = rpcClient.getObjectStore();
    String keyString = UUID.randomUUID().toString();
    String volumeName = UUID.randomUUID().toString();
    String bucketName = volumeName;
    objectStore.createVolume(volumeName);
    objectStore.getVolume(volumeName).createBucket(bucketName);
    OzoneVolume volume = objectStore.getVolume(volumeName);
    OzoneBucket bucket = volume.getBucket(bucketName);
    createKeyAndWriteData(keyString, bucket, 3);
    OzoneKeyDetails key = bucket.getKey(keyString);
    long conID = key.getOzoneKeyLocations().get(0).getContainerID();
    Token<ContainerTokenIdentifier> cToken = containerTokenGenerator.generateToken(ANY_USER, new ContainerID(conID));
    closeContainer(conID);
    Pipeline containerPipeline = scm.getPipelineManager().getPipeline(scm.getContainerManager().getContainer(ContainerID.valueOf(conID)).getPipelineID());
    List<DatanodeDetails> nodeSet = containerPipeline.getNodes();
    SortedMap<Integer, DatanodeDetails> sourceNodeMap = new TreeMap<>();
    nodeSet.stream().filter(k -> {
        int replIndex = containerPipeline.getReplicaIndex(k);
        return !missingIndexes.contains(replIndex);
    }).forEach(dn -> {
        sourceNodeMap.put(containerPipeline.getReplicaIndex(dn), dn);
    });
    //Find a good node outside of pipeline
    List<DatanodeDetails> clusterDnsList = cluster.getHddsDatanodes().stream().map(k -> k.getDatanodeDetails()).collect(Collectors.toList());
    DatanodeDetails goodTargetNode = null;
    for (DatanodeDetails clusterDN : clusterDnsList) {
        if (!nodeSet.contains(clusterDN)) {
            goodTargetNode = clusterDN;
            break;
        }
    }
    //Give the new target to reconstruct the container
    SortedMap<Integer, DatanodeDetails> targetNodeMap = new TreeMap<>();
    targetNodeMap.put(1, goodTargetNode);
    // Replace one of the target node with wrong to simulate failure at target.
    DatanodeDetails invalidTargetNode = MockDatanodeDetails.randomDatanodeDetails();
    targetNodeMap.put(3, invalidTargetNode);
    assertThrows(IOException.class, () -> {
        try (ECReconstructionCoordinator coordinator = new ECReconstructionCoordinator(config, certClient, secretKeyClient, null, ECReconstructionMetrics.create(), "")) {
            coordinator.reconstructECContainerGroup(conID, (ECReplicationConfig) containerPipeline.getReplicationConfig(), sourceNodeMap, targetNodeMap);
        }
    });
    final DatanodeDetails targetDNToCheckContainerCLeaned = goodTargetNode;
    StorageContainerException ex = assertThrows(StorageContainerException.class, () -> {
        try (ECContainerOperationClient client = new ECContainerOperationClient(config, certClient)) {
            client.listBlock(conID, targetDNToCheckContainerCLeaned, new ECReplicationConfig(3, 2), cToken);
        }
    });
    assertEquals("ContainerID 1 does not exist", ex.getMessage());
}

