@Test
public void testMoveFailover() throws Exception {
    SCMClientConfig scmClientConfig = conf.getObject(SCMClientConfig.class);
    scmClientConfig.setRetryCount(1);
    scmClientConfig.setRetryInterval(100);
    scmClientConfig.setMaxRetryTimeout(1500);
    assertEquals(15, scmClientConfig.getRetryCount());
    conf.setFromObject(scmClientConfig);
    StorageContainerManager scm = getLeader(cluster);
    assertNotNull(scm);
    final ContainerID id = getContainer(HddsProtos.LifeCycleState.CLOSED).containerID();
    DatanodeDetails dn1 = randomDatanodeDetails();
    DatanodeDetails dn2 = randomDatanodeDetails();
    //here we just want to test whether the new leader will get the same
    //inflight move after failover, so no need to create container and datanode,
    //just mock them bypassing all the pre checks.
    scm.getReplicationManager().getMoveScheduler().startMove(id.getProtobuf(), (new MoveDataNodePair(dn1, dn2)).getProtobufMessage(ClientVersion.CURRENT_VERSION));
    SCMBlockLocationFailoverProxyProvider failoverProxyProvider = new SCMBlockLocationFailoverProxyProvider(conf);
    failoverProxyProvider.changeCurrentProxy(scm.getSCMNodeId());
    ScmBlockLocationProtocolClientSideTranslatorPB scmBlockLocationClient = new ScmBlockLocationProtocolClientSideTranslatorPB(failoverProxyProvider);
    GenericTestUtils.setLogLevel(SCMBlockLocationFailoverProxyProvider.LOG, Level.DEBUG);
    GenericTestUtils.LogCapturer logCapture = GenericTestUtils.LogCapturer.captureLogs(SCMBlockLocationFailoverProxyProvider.LOG);
    ScmBlockLocationProtocol scmBlockLocationProtocol = TracingUtil.createProxy(scmBlockLocationClient, ScmBlockLocationProtocol.class, conf);
    scmBlockLocationProtocol.getScmInfo();
    assertThat(logCapture.getOutput()).contains("Performing failover to suggested leader");
    scm = getLeader(cluster);
    assertNotNull(scm);
    //switch to the new leader successfully, new leader should
    //get the same inflightMove
    Map<ContainerID, MoveDataNodePair> inflightMove = scm.getReplicationManager().getMoveScheduler().getInflightMove();
    assertThat(inflightMove).containsKey(id);
    MoveDataNodePair mp = inflightMove.get(id);
    assertEquals(dn2, mp.getTgt());
    assertEquals(dn1, mp.getSrc());
    //complete move in the new leader
    scm.getReplicationManager().getMoveScheduler().completeMove(id.getProtobuf());
    SCMContainerLocationFailoverProxyProvider proxyProvider = new SCMContainerLocationFailoverProxyProvider(conf, null);
    GenericTestUtils.setLogLevel(SCMContainerLocationFailoverProxyProvider.LOG, Level.DEBUG);
    logCapture = GenericTestUtils.LogCapturer.captureLogs(SCMContainerLocationFailoverProxyProvider.LOG);
    proxyProvider.changeCurrentProxy(scm.getSCMNodeId());
    StorageContainerLocationProtocol scmContainerClient = TracingUtil.createProxy(new StorageContainerLocationProtocolClientSideTranslatorPB(proxyProvider), StorageContainerLocationProtocol.class, conf);
    scmContainerClient.allocateContainer(HddsProtos.ReplicationType.RATIS, HddsProtos.ReplicationFactor.ONE, "ozone");
    assertThat(logCapture.getOutput()).contains("Performing failover to suggested leader");
    //switch to the new leader successfully, new leader should
    //get the same inflightMove , which should not contains
    //that container.
    scm = getLeader(cluster);
    assertNotNull(scm);
    inflightMove = scm.getReplicationManager().getMoveScheduler().getInflightMove();
    assertThat(inflightMove).doesNotContainKey(id);
}

/**
 * Starts ContainerBalancer when the cluster is already balanced.
 * ContainerBalancer will identify that no unbalanced nodes are present and
 * exit and stop in the first iteration. We test that ContainerBalancer
 * persists ContainerBalancerConfigurationProto#shouldRun as false in all
 * the 3 SCMs when it stops.
 * @throws IOException
 * @throws IllegalContainerBalancerStateException
 * @throws InvalidContainerBalancerConfigurationException
 * @throws InterruptedException
 * @throws TimeoutException
 */
@Test
public void testContainerBalancerPersistsConfigurationInAllSCMs() throws IOException, IllegalContainerBalancerStateException, InvalidContainerBalancerConfigurationException, InterruptedException, TimeoutException {
    SCMClientConfig scmClientConfig = conf.getObject(SCMClientConfig.class);
    scmClientConfig.setRetryInterval(100);
    scmClientConfig.setMaxRetryTimeout(1500);
    assertEquals(15, scmClientConfig.getRetryCount());
    conf.setFromObject(scmClientConfig);
    StorageContainerManager leader = getLeader(cluster);
    assertNotNull(leader);
    ScmClient scmClient = new ContainerOperationClient(conf);
    // assert that container balancer is not running right now
    assertFalse(scmClient.getContainerBalancerStatus());
    ContainerBalancerConfiguration balancerConf = conf.getObject(ContainerBalancerConfiguration.class);
    ContainerBalancer containerBalancer = leader.getContainerBalancer();
    /*
    Start container balancer. Since this cluster is already balanced,
    container balancer should exit early, stop, and persist configuration to DB.
     */
    containerBalancer.startBalancer(balancerConf);
    // assert that balancer has stopped since the cluster is already balanced
    GenericTestUtils.waitFor(() -> !containerBalancer.isBalancerRunning(), 10, 500);
    assertFalse(containerBalancer.isBalancerRunning());
    ByteString byteString = leader.getScmMetadataStore().getStatefulServiceConfigTable().get(containerBalancer.getServiceName());
    ContainerBalancerConfigurationProto proto = ContainerBalancerConfigurationProto.parseFrom(byteString);
    GenericTestUtils.waitFor(() -> !proto.getShouldRun(), 5, 50);
    long leaderTermIndex = leader.getScmHAManager().getRatisServer().getSCMStateMachine().getLastAppliedTermIndex().getIndex();
    /*
    Fetch persisted configuration to verify that `shouldRun` is set to false.
     */
    for (StorageContainerManager scm : cluster.getStorageContainerManagers()) {
        if (!scm.checkLeader()) {
            // Wait and retry for follower to update transactions to leader
            // snapshot index.
            // Timeout error if follower does not load update within 3s
            GenericTestUtils.waitFor(() -> scm.getScmHAManager().getRatisServer().getSCMStateMachine().getLastAppliedTermIndex().getIndex() >= leaderTermIndex, 100, 3000);
            ContainerBalancer followerBalancer = scm.getContainerBalancer();
            GenericTestUtils.waitFor(() -> !followerBalancer.isBalancerRunning(), 50, 5000);
            GenericTestUtils.waitFor(() -> !followerBalancer.shouldRun(), 100, 5000);
        }
        scm.getStatefulServiceStateManager().readConfiguration(containerBalancer.getServiceName());
        byteString = scm.getScmMetadataStore().getStatefulServiceConfigTable().get(containerBalancer.getServiceName());
        ContainerBalancerConfigurationProto protobuf = ContainerBalancerConfigurationProto.parseFrom(byteString);
        assertFalse(protobuf.getShouldRun());
    }
}

@Test
public void tesGetCommittedBlockLength() throws Exception {
    final AtomicReference<ContainerProtos.GetCommittedBlockLengthResponseProto> response = new AtomicReference<>();
    ContainerWithPipeline container = storageContainerLocationClient.allocateContainer(SCMTestUtils.getReplicationType(ozoneConfig), HddsProtos.ReplicationFactor.ONE, OzoneConsts.OZONE);
    long containerID = container.getContainerInfo().getContainerID();
    Pipeline pipeline = container.getPipeline();
    XceiverClientSpi client = xceiverClientManager.acquireClient(pipeline);
    //create the container
    ContainerProtocolCalls.createContainer(client, containerID, null);
    BlockID blockID = ContainerTestHelper.getTestBlockID(containerID);
    byte[] data = RandomStringUtils.random(RandomUtils.nextInt(1, 1024)).getBytes(UTF_8);
    ContainerProtos.ContainerCommandRequestProto writeChunkRequest = ContainerTestHelper.getWriteChunkRequest(container.getPipeline(), blockID, data.length);
    client.sendCommand(writeChunkRequest);
    // Now, explicitly make a putKey request for the block.
    ContainerProtos.ContainerCommandRequestProto putKeyRequest = ContainerTestHelper.getPutBlockRequest(pipeline, writeChunkRequest.getWriteChunk());
    client.sendCommand(putKeyRequest);
    GenericTestUtils.waitFor(() -> {
