@Test
public void testBlockDeletionTransactions() throws Exception {
    int numKeys = 5;
    OzoneConfiguration conf = new OzoneConfiguration();
    conf.setTimeDuration(OZONE_BLOCK_DELETING_SERVICE_INTERVAL, 100, TimeUnit.MILLISECONDS);
    DatanodeConfiguration datanodeConfiguration = conf.getObject(DatanodeConfiguration.class);
    datanodeConfiguration.setBlockDeletionInterval(Duration.ofMillis(100));
    conf.setFromObject(datanodeConfiguration);
    ScmConfig scmConfig = conf.getObject(ScmConfig.class);
    scmConfig.setBlockDeletionInterval(Duration.ofMillis(100));
    conf.setFromObject(scmConfig);
    conf.setTimeDuration(RatisHelper.HDDS_DATANODE_RATIS_PREFIX_KEY + ".client.request.write.timeout", 30, TimeUnit.SECONDS);
    conf.setTimeDuration(RatisHelper.HDDS_DATANODE_RATIS_PREFIX_KEY + ".client.request.watch.timeout", 30, TimeUnit.SECONDS);
    conf.setInt("hdds.datanode.block.delete.threads.max", 5);
    conf.setInt("hdds.datanode.block.delete.queue.limit", 32);
    conf.setTimeDuration(HDDS_HEARTBEAT_INTERVAL, 50, TimeUnit.MILLISECONDS);
    conf.setTimeDuration(HDDS_CONTAINER_REPORT_INTERVAL, 200, TimeUnit.MILLISECONDS);
    conf.setTimeDuration(HDDS_COMMAND_STATUS_REPORT_INTERVAL, 200, TimeUnit.MILLISECONDS);
    conf.setInt(ScmConfigKeys.OZONE_SCM_BLOCK_DELETION_MAX_RETRY, 5);
    // Reset container provision size, otherwise only one container
    // is created by default.
    conf.setInt(ScmConfigKeys.OZONE_SCM_PIPELINE_OWNER_CONTAINER_COUNT, numKeys);
    try (MiniOzoneCluster cluster = MiniOzoneCluster.newBuilder(conf).build()) {
        cluster.waitForClusterToBeReady();
        DeletedBlockLog delLog = cluster.getStorageContainerManager().getScmBlockManager().getDeletedBlockLog();
        assertEquals(0, delLog.getNumOfValidTransactions());
        Map<String, OmKeyInfo> keyLocations = TestDataUtil.createKeys(cluster, numKeys);
        // Wait for container report
        Thread.sleep(1000);
        for (OmKeyInfo keyInfo : keyLocations.values()) {
            OzoneTestUtils.closeContainers(keyInfo.getKeyLocationVersions(), cluster.getStorageContainerManager());
        }
        Map<Long, List<Long>> containerBlocks = createDeleteTXLog(cluster.getStorageContainerManager(), delLog, keyLocations, cluster, conf);
        // Verify a few TX gets created in the TX log.
        assertThat(delLog.getNumOfValidTransactions()).isGreaterThan(0);
        // Once TXs are written into the log, SCM starts to fetch TX
        // entries from the log and schedule block deletions in HB interval,
        // after sometime, all the TX should be proceed and by then
        // the number of containerBlocks of all known containers will be
        // empty again.
        GenericTestUtils.waitFor(() -> {
            try {
                if (SCMHAUtils.isSCMHAEnabled(cluster.getConf())) {
                    cluster.getStorageContainerManager().getScmHAManager().asSCMHADBTransactionBuffer().flush();
                }
                return delLog.getNumOfValidTransactions() == 0;
            } catch (IOException e) {
                return false;
            }
        }, 1000, 22000);
        assertTrue(verifyBlocksWithTxnTable(cluster, conf, containerBlocks));
        // Continue the work, add some TXs that with known container names,
        // but unknown block IDs.
        for (Long containerID : containerBlocks.keySet()) {
            // Add 2 TXs per container.
            Map<Long, List<Long>> deletedBlocks = new HashMap<>();
            List<Long> blocks = new ArrayList<>();
            blocks.add(RandomUtils.nextLong());
            blocks.add(RandomUtils.nextLong());
            deletedBlocks.put(containerID, blocks);
            addTransactions(cluster.getStorageContainerManager(), delLog, deletedBlocks);
        }
        // Verify a few TX gets created in the TX log.
        assertThat(delLog.getNumOfValidTransactions()).isGreaterThan(0);
        // These blocks cannot be found in the container, skip deleting them
        // eventually these TX will success.
        GenericTestUtils.waitFor(() -> {
            try {
                if (SCMHAUtils.isSCMHAEnabled(cluster.getConf())) {
                    cluster.getStorageContainerManager().getScmHAManager().asSCMHADBTransactionBuffer().flush();
                }
                return delLog.getFailedTransactions(-1, 0).size() == 0;
            } catch (IOException e) {
                return false;
            }
        }, 1000, 20000);
    }
}

@Test
public void testOldDNRegistersToReInitialisedSCM() throws Exception {
    OzoneConfiguration conf = new OzoneConfiguration();
    conf.setTimeDuration(HDDS_HEARTBEAT_INTERVAL, 1000, TimeUnit.MILLISECONDS);
    conf.setTimeDuration(ScmConfigKeys.OZONE_SCM_HEARTBEAT_PROCESS_INTERVAL, 3000, TimeUnit.MILLISECONDS);
    try (MiniOzoneCluster cluster = MiniOzoneCluster.newBuilder(conf).setNumDatanodes(1).build()) {
        cluster.waitForClusterToBeReady();
        HddsDatanodeService datanode = cluster.getHddsDatanodes().get(0);
        StorageContainerManager scm = cluster.getStorageContainerManager();
        scm.stop();
        // re-initialise SCM with new clusterID
        GenericTestUtils.deleteDirectory(new File(scm.getScmStorageConfig().getStorageDir()));
        String newClusterId = UUID.randomUUID().toString();
        StorageContainerManager.scmInit(scm.getConfiguration(), newClusterId);
        scm = HddsTestUtils.getScmSimple(scm.getConfiguration());
        DatanodeStateMachine dsm = datanode.getDatanodeStateMachine();
        assertEquals(DatanodeStateMachine.DatanodeStates.RUNNING, dsm.getContext().getState());
        // DN Endpoint State has already gone through GetVersion and Register,
        // so it will be in HEARTBEAT state.
        for (EndpointStateMachine endpoint : dsm.getConnectionManager().getValues()) {
            assertEquals(EndpointStateMachine.EndPointStates.HEARTBEAT, endpoint.getState());
        }
        GenericTestUtils.LogCapturer scmDnHBDispatcherLog = GenericTestUtils.LogCapturer.captureLogs(SCMDatanodeHeartbeatDispatcher.LOG);
        LogManager.getLogger(HeartbeatEndpointTask.class).setLevel(Level.DEBUG);
        GenericTestUtils.LogCapturer heartbeatEndpointTaskLog = GenericTestUtils.LogCapturer.captureLogs(HeartbeatEndpointTask.LOG);
        GenericTestUtils.LogCapturer versionEndPointTaskLog = GenericTestUtils.LogCapturer.captureLogs(VersionEndpointTask.LOG);
        // Initially empty
        assertThat(scmDnHBDispatcherLog.getOutput()).isEmpty();
        assertThat(versionEndPointTaskLog.getOutput()).isEmpty();
        // start the new SCM
        scm.start();
        // Initially DatanodeStateMachine will be in Running state
        assertEquals(DatanodeStateMachine.DatanodeStates.RUNNING, dsm.getContext().getState());
        // DN heartbeats to new SCM, SCM doesn't recognize the node, sends the
        // command to DN to re-register. Wait for SCM to send re-register command
        String expectedLog = String.format("SCM received heartbeat from an unregistered datanode %s. " + "Asking datanode to re-register.", datanode.getDatanodeDetails());
        GenericTestUtils.waitFor(() -> scmDnHBDispatcherLog.getOutput().contains(expectedLog), 100, 5000);
        ExitUtil.disableSystemExit();
        // As part of processing response for re-register, DN EndpointStateMachine
        // goes to GET-VERSION state which checks if there is already existing
        // version file on the DN & if the clusterID matches with that of the SCM
        // In this case, it won't match and gets InconsistentStorageStateException
        // and DN shuts down.
        String expectedLog2 = "Received SCM notification to register." + " Interrupt HEARTBEAT and transit to GETVERSION state.";
        GenericTestUtils.waitFor(() -> heartbeatEndpointTaskLog.getOutput().contains(expectedLog2), 100, 5000);
        GenericTestUtils.waitFor(() -> dsm.getContext().getShutdownOnError(), 100, 5000);
        assertEquals(DatanodeStateMachine.DatanodeStates.SHUTDOWN, dsm.getContext().getState());
        assertThat(versionEndPointTaskLog.getOutput()).contains("org.apache.hadoop.ozone.common" + ".InconsistentStorageStateException: Mismatched ClusterIDs");
    }
}

@Test
public void testBlockDeletingThrottling() throws Exception {
    int numKeys = 15;
    OzoneConfiguration conf = new OzoneConfiguration();
    conf.setTimeDuration(HDDS_CONTAINER_REPORT_INTERVAL, 1, TimeUnit.SECONDS);
    conf.setInt(ScmConfigKeys.OZONE_SCM_BLOCK_DELETION_MAX_RETRY, 5);
