/**
 * Test datanode heartbeat well processed with a 4-layer network topology.
 */
@Test
public void testScmProcessDatanodeHeartbeat() throws Exception {
    String rackName = "/rack1";
    OzoneConfiguration conf = new OzoneConfiguration();
    conf.setClass(NET_TOPOLOGY_NODE_SWITCH_MAPPING_IMPL_KEY, StaticMapping.class, DNSToSwitchMapping.class);
    StaticMapping.addNodeToRack(NetUtils.normalizeHostName(HddsUtils.getHostName(conf)), rackName);
    // In case of JDK17, the IP address is resolved to localhost mapped to 127.0.0.1 which is not in sync with JDK8
    // and hence need to make following entry under HDDS-10132
    StaticMapping.addNodeToRack(LOCALHOST_IP, rackName);
    final int datanodeNum = 3;
    try (MiniOzoneCluster cluster = MiniOzoneCluster.newBuilder(conf).setNumDatanodes(datanodeNum).build()) {
        cluster.waitForClusterToBeReady();
        StorageContainerManager scm = cluster.getStorageContainerManager();
        // first sleep 10s
        Thread.sleep(10000);
        // verify datanode heartbeats are well processed
        long heartbeatCheckerIntervalMs = cluster.getConf().getTimeDuration(HDDS_HEARTBEAT_INTERVAL, 1000, TimeUnit.MILLISECONDS);
        long start = Time.monotonicNow();
        Thread.sleep(heartbeatCheckerIntervalMs * 2);
        List<DatanodeDetails> allNodes = scm.getScmNodeManager().getAllNodes();
        assertEquals(datanodeNum, allNodes.size());
        for (DatanodeDetails node : allNodes) {
            DatanodeInfo datanodeInfo = (DatanodeInfo) scm.getScmNodeManager().getNodeByUuid(node.getUuidString());
            assertThat(datanodeInfo.getLastHeartbeatTime()).isGreaterThan(start);
            assertEquals(datanodeInfo.getUuidString(), datanodeInfo.getNetworkName());
            assertEquals("/rack1", datanodeInfo.getNetworkLocation());
        }
    }
}

@Test
@SuppressWarnings("unchecked")
public void testCloseContainerCommandOnRestart() throws Exception {
    int numKeys = 15;
    OzoneConfiguration conf = new OzoneConfiguration();
    conf.setTimeDuration(HDDS_CONTAINER_REPORT_INTERVAL, 1, TimeUnit.SECONDS);
    conf.setInt(ScmConfigKeys.OZONE_SCM_BLOCK_DELETION_MAX_RETRY, 5);
    conf.setTimeDuration(OZONE_BLOCK_DELETING_SERVICE_INTERVAL, 100, TimeUnit.MILLISECONDS);
    conf.setInt(ScmConfigKeys.OZONE_SCM_PIPELINE_OWNER_CONTAINER_COUNT, numKeys);
    conf.setBoolean(HDDS_SCM_SAFEMODE_PIPELINE_CREATION, false);
    conf.setTimeDuration(HDDS_HEARTBEAT_INTERVAL, 1000, TimeUnit.MILLISECONDS);
    conf.setTimeDuration(ScmConfigKeys.OZONE_SCM_HEARTBEAT_PROCESS_INTERVAL, 3000, TimeUnit.MILLISECONDS);
    try (MiniOzoneCluster cluster = MiniOzoneCluster.newBuilder(conf).setNumDatanodes(1).build()) {
        cluster.waitForClusterToBeReady();
        cluster.waitForPipelineTobeReady(HddsProtos.ReplicationFactor.ONE, 30000);
        TestDataUtil.createKeys(cluster, 10);
        GenericTestUtils.waitFor(() -> cluster.getStorageContainerManager().getContainerManager().getContainers() != null, 1000, 10000);
        StorageContainerManager scm = cluster.getStorageContainerManager();
        List<ContainerInfo> containers = cluster.getStorageContainerManager().getContainerManager().getContainers();
        assertNotNull(containers);
        ContainerInfo selectedContainer = containers.iterator().next();
        // Stop processing HB
        scm.getDatanodeProtocolServer().stop();
        LOG.info("Current Container State is {}", selectedContainer.getState());
        try {
            scm.getContainerManager().updateContainerState(selectedContainer.containerID(), HddsProtos.LifeCycleEvent.FINALIZE);
        } catch (SCMException ex) {
            if (selectedContainer.getState() != HddsProtos.LifeCycleState.CLOSING) {
                ex.printStackTrace();
                throw (ex);
            }
        }
        cluster.restartStorageContainerManager(false);
        scm = cluster.getStorageContainerManager();
        ReplicationManager rm = scm.getReplicationManager();
        NodeManager nodeManager = mock(NodeManager.class);
        setInternalState(rm, "nodeManager", nodeManager);
        EventPublisher publisher = mock(EventPublisher.class);
        setInternalState(rm.getLegacyReplicationManager(), "eventPublisher", publisher);
        UUID dnUuid = cluster.getHddsDatanodes().iterator().next().getDatanodeDetails().getUuid();
        CloseContainerCommand closeContainerCommand = new CloseContainerCommand(selectedContainer.getContainerID(), selectedContainer.getPipelineID(), false);
        GenericTestUtils.waitFor(() -> {
            SCMContext scmContext = cluster.getStorageContainerManager().getScmContext();
            return !scmContext.isInSafeMode() && scmContext.isLeader();
        }, 1000, 25000);
        // After safe mode is off, ReplicationManager starts to run with a delay.
        Thread.sleep(5000);
        // Give ReplicationManager some time to process the containers.
        cluster.getStorageContainerManager().getReplicationManager().processAll();
        Thread.sleep(5000);
        if (rm.getConfig().isLegacyEnabled()) {
            CommandForDatanode commandForDatanode = new CommandForDatanode(dnUuid, closeContainerCommand);
            verify(publisher).fireEvent(eq(SCMEvents.DATANODE_COMMAND), argThat(new CloseContainerCommandMatcher(dnUuid, commandForDatanode)));
        } else {
            verify(nodeManager).addDatanodeCommand(dnUuid, closeContainerCommand);
        }
    }
}

@Test
public void testContainerReportQueueWithDrop() throws Exception {
    EventQueue eventQueue = new EventQueue();
    List<BlockingQueue<SCMDatanodeHeartbeatDispatcher.ContainerReport>> queues = new ArrayList<>();
    for (int i = 0; i < 1; ++i) {
        queues.add(new ContainerReportQueue());
    }
    ContainerReportsProto report = ContainerReportsProto.getDefaultInstance();
    DatanodeDetails dn = DatanodeDetails.newBuilder().setUuid(UUID.randomUUID()).build();
    ContainerReportFromDatanode dndata = new ContainerReportFromDatanode(dn, report);
    ContainerReportHandler containerReportHandler = mock(ContainerReportHandler.class);
    doAnswer((inv) -> {
        Thread.sleep(500);
        return null;
    }).when(containerReportHandler).onMessage(dndata, eventQueue);
    List<ThreadPoolExecutor> executors = FixedThreadPoolWithAffinityExecutor.initializeExecutorPool(queues);
    Map<String, FixedThreadPoolWithAffinityExecutor> reportExecutorMap = new ConcurrentHashMap<>();
    EventExecutor<ContainerReportFromDatanode> containerReportExecutors = new FixedThreadPoolWithAffinityExecutor<>(EventQueue.getExecutorName(SCMEvents.CONTAINER_REPORT, containerReportHandler), containerReportHandler, queues, eventQueue, ContainerReportFromDatanode.class, executors, reportExecutorMap);
    eventQueue.addHandler(SCMEvents.CONTAINER_REPORT, containerReportExecutors, containerReportHandler);
    eventQueue.fireEvent(SCMEvents.CONTAINER_REPORT, dndata);
    eventQueue.fireEvent(SCMEvents.CONTAINER_REPORT, dndata);
    eventQueue.fireEvent(SCMEvents.CONTAINER_REPORT, dndata);
    eventQueue.fireEvent(SCMEvents.CONTAINER_REPORT, dndata);
    assertThat(containerReportExecutors.droppedEvents()).isGreaterThan(1);
    Thread.sleep(1000);
    assertEquals(containerReportExecutors.droppedEvents() + containerReportExecutors.scheduledEvents(), containerReportExecutors.queuedEvents());
    containerReportExecutors.close();
}

