void testAllSCMAreRunning() throws Exception {
    int count = 0;
    List<StorageContainerManager> scms = cluster.getStorageContainerManagers();
    assertEquals(numOfSCMs, scms.size());
    int peerSize = cluster.getStorageContainerManager().getScmHAManager().getRatisServer().getDivision().getGroup().getPeers().size();
    StorageContainerManager leaderScm = null;
    for (StorageContainerManager scm : scms) {
        if (scm.checkLeader()) {
            count++;
            leaderScm = scm;
        }
        assertEquals(peerSize, numOfSCMs);
    }
    assertEquals(1, count);
    assertNotNull(leaderScm);
    assertRatisRoles();
    String leaderSCMId = leaderScm.getScmId();
    checkSCMHAMetricsForAllSCMs(scms, leaderSCMId);
    count = 0;
    List<OzoneManager> oms = cluster.getOzoneManagersList();
    assertEquals(numOfOMs, oms.size());
    for (OzoneManager om : oms) {
        if (om.isLeaderReady()) {
            count++;
        }
    }
    assertEquals(1, count);
    // verify timer based transaction buffer flush is working
    SnapshotInfo latestSnapshot = leaderScm.getScmHAManager().asSCMHADBTransactionBuffer().getLatestSnapshot();
    doPutKey();
    final StorageContainerManager leaderScmTmp = leaderScm;
    GenericTestUtils.waitFor(() -> {
        if (leaderScmTmp.getScmHAManager().asSCMHADBTransactionBuffer().getLatestSnapshot() != null) {
            if (leaderScmTmp.getScmHAManager().asSCMHADBTransactionBuffer().getLatestSnapshot().getIndex() > latestSnapshot.getIndex()) {
                return true;
            }
        }
        return false;
    }, 2000, 30000);
}

