    init(conf, new DefaultUpgradeFinalizationExecutor<>(), numInactiveSCMs);
    GenericTestUtils.LogCapturer logCapture = GenericTestUtils.LogCapturer.captureLogs(FinalizationStateManagerImpl.LOG);
    StorageContainerManager inactiveScm = cluster.getInactiveSCM().next();
    LOG.info("Inactive SCM node ID: {}", inactiveScm.getSCMNodeId());
    List<StorageContainerManager> scms = cluster.getStorageContainerManagersList();
    List<StorageContainerManager> activeScms = new ArrayList<>();
    for (StorageContainerManager scm : scms) {
        if (!scm.getSCMNodeId().equals(inactiveScm.getSCMNodeId())) {
            activeScms.add(scm);
        }
    }
    // Wait for finalization from the client perspective.
    finalizationFuture.get();
    TestHddsUpgradeUtils.waitForFinalizationFromClient(scmClient, CLIENT_ID);
    // Wait for two running SCMs to finish finalization.
    waitForScmsToFinalize(activeScms);
    TestHddsUpgradeUtils.testPostUpgradeConditionsSCM(activeScms, 0, NUM_DATANODES);
    TestHddsUpgradeUtils.testPostUpgradeConditionsDataNodes(cluster.getHddsDatanodes(), 0, CLOSED);
    // Move SCM log index farther ahead to make sure a snapshot install
    // happens on the restarted SCM.
    for (int i = 0; i < 10; i++) {
        ContainerWithPipeline container = scmClient.allocateContainer(HddsProtos.ReplicationType.RATIS, HddsProtos.ReplicationFactor.ONE, "owner");
        scmClient.closeContainer(container.getContainerInfo().getContainerID());
    }
    cluster.startInactiveSCM(inactiveScm.getSCMNodeId());
    waitForScmToFinalize(inactiveScm);
    TestHddsUpgradeUtils.testPostUpgradeConditionsSCM(inactiveScm, 0, NUM_DATANODES);
    // Use log to verify a snapshot was installed.
    assertThat(logCapture.getOutput()).contains("New SCM snapshot " + "received with metadata layout version");
}

