@Test
public void testDeleteLinkedBucket() throws Exception {
    String volumeName = UUID.randomUUID().toString();
    String bucketName = UUID.randomUUID().toString();
    String linkedBucketName = UUID.randomUUID().toString();
    store.createVolume(volumeName);
    OzoneVolume volume = store.getVolume(volumeName);
    volume.createBucket(bucketName);
    OzoneBucket bucket = volume.getBucket(bucketName);
    assertNotNull(bucket);
    volume.createBucket(linkedBucketName, BucketArgs.newBuilder().setSourceBucket(bucketName).setSourceVolume(volumeName).build());
    OzoneBucket linkedBucket = volume.getBucket(linkedBucketName);
    assertNotNull(linkedBucket);
    volume.deleteBucket(bucketName);
    OzoneTestUtils.expectOmException(ResultCodes.BUCKET_NOT_FOUND, () -> volume.getBucket(bucketName));
    //now linkedBucketName has become a dangling one
    //should still be possible to get its info
    OzoneBucket danglingLinkedBucket = volume.getBucket(linkedBucketName);
    assertNotNull(danglingLinkedBucket);
    //now delete the dangling linked bucket
    volume.deleteBucket(linkedBucketName);
    OzoneTestUtils.expectOmException(ResultCodes.BUCKET_NOT_FOUND, () -> volume.getBucket(linkedBucketName));
    store.deleteVolume(volumeName);
}

@ParameterizedTest
@CsvSource({ "rs-3-3-1024k,false", "xor-3-5-2048k,false", "rs-3-2-1024k,true", "rs-6-3-1024k,true", "rs-10-4-1024k,true" })
public void testPutKeyWithReplicationConfig(String replicationValue, boolean isValidReplicationConfig) throws IOException {
    String volumeName = UUID.randomUUID().toString();
    String bucketName = UUID.randomUUID().toString();
    store.createVolume(volumeName);
    OzoneVolume volume = store.getVolume(volumeName);
    volume.createBucket(bucketName);
    OzoneBucket bucket = volume.getBucket(bucketName);
    String keyName = UUID.randomUUID().toString();
    String value = UUID.randomUUID().toString();
    ReplicationConfig replicationConfig = new ECReplicationConfig(replicationValue);
    if (isValidReplicationConfig) {
        OzoneOutputStream out = bucket.createKey(keyName, value.getBytes(UTF_8).length, replicationConfig, new HashMap<>());
        out.write(value.getBytes(UTF_8));
        out.close();
        OzoneKey key = bucket.getKey(keyName);
        assertEquals(keyName, key.getName());
        try (OzoneInputStream is = bucket.readKey(keyName)) {
            byte[] fileContent = new byte[value.getBytes(UTF_8).length];
            is.read(fileContent);
            assertEquals(value, new String(fileContent, UTF_8));
        }
    } else {
        assertThrows(IllegalArgumentException.class, () -> bucket.createKey(keyName, "dummy".getBytes(UTF_8).length, replicationConfig, new HashMap<>()));
    }
}

@Test
public void testPutKey() throws IOException {
    String volumeName = UUID.randomUUID().toString();
    String bucketName = UUID.randomUUID().toString();
    Instant testStartTime = getTestStartTime();
    String value = "sample value";
    store.createVolume(volumeName);
    OzoneVolume volume = store.getVolume(volumeName);
    volume.createBucket(bucketName);
    OzoneBucket bucket = volume.getBucket(bucketName);
    for (int i = 0; i < 10; i++) {
        String keyName = UUID.randomUUID().toString();
        OzoneOutputStream out = bucket.createKey(keyName, value.getBytes(UTF_8).length, RATIS, ONE, new HashMap<>());
        out.write(value.getBytes(UTF_8));
        out.close();
        OzoneKey key = bucket.getKey(keyName);
        assertEquals(keyName, key.getName());
        try (OzoneInputStream is = bucket.readKey(keyName)) {
            byte[] fileContent = new byte[value.getBytes(UTF_8).length];
            is.read(fileContent);
            verifyReplication(volumeName, bucketName, keyName, RatisReplicationConfig.getInstance(HddsProtos.ReplicationFactor.ONE));
            assertEquals(value, new String(fileContent, UTF_8));
            assertFalse(key.getCreationTime().isBefore(testStartTime));
            assertFalse(key.getModificationTime().isBefore(testStartTime));
        }
    }
}

