@Test
public void testMultipartUploadWithACL() throws Exception {
    String volumeName = UUID.randomUUID().toString();
    String bucketName = UUID.randomUUID().toString();
    String keyName = UUID.randomUUID().toString();
    store.createVolume(volumeName);
    OzoneVolume volume = store.getVolume(volumeName);
    // TODO: HDDS-3402. Files/dirs in FSO buckets currently do not inherit
    //  parent ACLs.
    volume.createBucket(bucketName, BucketArgs.newBuilder().setBucketLayout(BucketLayout.OBJECT_STORE).build());
    OzoneBucket bucket = volume.getBucket(bucketName);
    // Add ACL on Bucket
    OzoneAcl acl1 = new OzoneAcl(USER, "Monday", DEFAULT, ACLType.ALL);
    OzoneAcl acl2 = new OzoneAcl(USER, "Friday", DEFAULT, ACLType.ALL);
    OzoneAcl acl3 = new OzoneAcl(USER, "Jan", ACCESS, ACLType.ALL);
    OzoneAcl acl4 = new OzoneAcl(USER, "Feb", ACCESS, ACLType.ALL);
    bucket.addAcl(acl1);
    bucket.addAcl(acl2);
    bucket.addAcl(acl3);
    bucket.addAcl(acl4);
    ReplicationConfig replication = RatisReplicationConfig.getInstance(HddsProtos.ReplicationFactor.ONE);
    doMultipartUpload(bucket, keyName, (byte) 98, replication);
    OzoneObj keyObj = OzoneObjInfo.Builder.newBuilder().setBucketName(bucketName).setVolumeName(volumeName).setKeyName(keyName).setResType(OzoneObj.ResourceType.KEY).setStoreType(OzoneObj.StoreType.OZONE).build();
    List<OzoneAcl> aclList = store.getAcl(keyObj);
    // key should inherit bucket's DEFAULT type acl
    assertTrue(aclList.stream().anyMatch(acl -> acl.getName().equals(acl1.getName())));
    assertTrue(aclList.stream().anyMatch(acl -> acl.getName().equals(acl2.getName())));
    // kye should not inherit bucket's ACCESS type acl
    assertFalse(aclList.stream().anyMatch(acl -> acl.getName().equals(acl3.getName())));
    assertFalse(aclList.stream().anyMatch(acl -> acl.getName().equals(acl4.getName())));
    // User without permission should fail to upload the object
    String userName = "test-user";
    UserGroupInformation remoteUser = UserGroupInformation.createRemoteUser(userName);
    try (OzoneClient client = remoteUser.doAs((PrivilegedExceptionAction<OzoneClient>) () -> OzoneClientFactory.getRpcClient(cluster.getConf()))) {
        OzoneAcl acl5 = new OzoneAcl(USER, userName, DEFAULT, ACLType.READ);
        OzoneAcl acl6 = new OzoneAcl(USER, userName, ACCESS, ACLType.READ);
        OzoneObj volumeObj = OzoneObjInfo.Builder.newBuilder().setVolumeName(volumeName).setStoreType(OzoneObj.StoreType.OZONE).setResType(OzoneObj.ResourceType.VOLUME).build();
        OzoneObj bucketObj = OzoneObjInfo.Builder.newBuilder().setVolumeName(volumeName).setBucketName(bucketName).setStoreType(OzoneObj.StoreType.OZONE).setResType(OzoneObj.ResourceType.BUCKET).build();
        store.addAcl(volumeObj, acl5);
        store.addAcl(volumeObj, acl6);
        store.addAcl(bucketObj, acl5);
        store.addAcl(bucketObj, acl6);
        // User without permission cannot start multi-upload
        String keyName2 = UUID.randomUUID().toString();
        OzoneBucket bucket2 = client.getObjectStore().getVolume(volumeName).getBucket(bucketName);
        OMException ome = assertThrows(OMException.class, () -> initiateMultipartUpload(bucket2, keyName2, anyReplication()), "User without permission should fail");
        assertEquals(ResultCodes.PERMISSION_DENIED, ome.getResult());
        // Add create permission for user, and try multi-upload init again
        OzoneAcl acl7 = new OzoneAcl(USER, userName, DEFAULT, ACLType.CREATE);
        OzoneAcl acl8 = new OzoneAcl(USER, userName, ACCESS, ACLType.CREATE);
        OzoneAcl acl9 = new OzoneAcl(USER, userName, DEFAULT, WRITE);
        OzoneAcl acl10 = new OzoneAcl(USER, userName, ACCESS, WRITE);
        store.addAcl(volumeObj, acl7);
        store.addAcl(volumeObj, acl8);
        store.addAcl(volumeObj, acl9);
        store.addAcl(volumeObj, acl10);
        store.addAcl(bucketObj, acl7);
        store.addAcl(bucketObj, acl8);
        store.addAcl(bucketObj, acl9);
        store.addAcl(bucketObj, acl10);
        String uploadId = initiateMultipartUpload(bucket2, keyName2, anyReplication());
        // Upload part
        byte[] data = generateData(OzoneConsts.OM_MULTIPART_MIN_SIZE, (byte) 1);
        Pair<String, String> partNameAndETag = uploadPart(bucket, keyName2, uploadId, 1, data);
        Map<Integer, String> eTagsMaps = new TreeMap<>();
        eTagsMaps.put(1, partNameAndETag.getValue());
        // Complete multipart upload request
        completeMultipartUpload(bucket2, keyName2, uploadId, eTagsMaps);
        // User without permission cannot read multi-uploaded object
        OMException ex = assertThrows(OMException.class, () -> {
            try (OzoneInputStream ignored = bucket2.readKey(keyName)) {
                LOG.error("User without permission should fail");
            }
        }, "User without permission should fail");
        assertEquals(ResultCodes.PERMISSION_DENIED, ex.getResult());
    }
}

