        store.createVolume(volumeName);
        store.getVolume(volumeName).createBucket(bucketName);
        OzoneObj volumeObj = OzoneObjInfo.Builder.newBuilder().setVolumeName(volumeName).setStoreType(OzoneObj.StoreType.OZONE).setResType(OzoneObj.ResourceType.VOLUME).build();
        OzoneObj bucketObj = OzoneObjInfo.Builder.newBuilder().setVolumeName(volumeName).setBucketName(bucketName).setStoreType(OzoneObj.StoreType.OZONE).setResType(OzoneObj.ResourceType.BUCKET).build();
        store.addAcl(volumeObj, new OzoneAcl(USER, "user1", ACCESS, ACLType.ALL));
        store.addAcl(volumeObj, new OzoneAcl(USER, "awsUser1", ACCESS, ACLType.ALL));
        store.addAcl(bucketObj, new OzoneAcl(USER, "user1", ACCESS, ACLType.ALL));
        store.addAcl(bucketObj, new OzoneAcl(USER, "awsUser1", ACCESS, ACLType.ALL));
        // user1 MultipartUpload a key
        UserGroupInformation.setLoginUser(user1);
        setOzClient(OzoneClientFactory.getRpcClient(cluster.getConf()));
        setStore(ozClient.getObjectStore());
        OzoneBucket bucket = store.getVolume(volumeName).getBucket(bucketName);
        doMultipartUpload(bucket, keyName1, (byte) 96, replication);
        assertEquals(user1.getShortUserName(), bucket.getKey(keyName1).getOwner());
        // After HDDS-5881 the user will not be different,
        // as S3G uses single RpcClient.
        // * performing the operation. the real user is an AWS user
        // form AWS client.
        String strToSign = "AWS4-HMAC-SHA256\n" + "20150830T123600Z\n" + "20150830/us-east-1/iam/aws4_request\n" + "f536975d06c0309214f805bb90ccff089219ecd68b2" + "577efef23edd43b7e1a59";
        String signature = "5d672d79c15b13162d9279b0855cfba" + "6789a8edb4c82c400e06b5924a6f2b5d7";
        String secret = "wJalrXUtnFEMI/K7MDENG+bPxRfiCYEXAMPLEKEY";
        S3Auth s3Auth = new S3Auth(strToSign, signature, awsUser1.getShortUserName(), awsUser1.getShortUserName());
        // Add secret to S3Secret table.
        S3SecretManager s3SecretManager = cluster.getOzoneManager().getS3SecretManager();
        s3SecretManager.storeSecret(awsUser1.getShortUserName(), S3SecretValue.of(awsUser1.getShortUserName(), secret));
        setOzClient(OzoneClientFactory.getRpcClient(cluster.getConf()));
        setStore(ozClient.getObjectStore());
        // set AWS user for RPCClient and OzoneManager
        store.getClientProxy().setThreadLocalS3Auth(s3Auth);
        OzoneManager.setS3Auth(OzoneManagerProtocolProtos.S3Authentication.newBuilder().setAccessId(awsUser1.getUserName()).build());
        // awsUser1 create a key
        bucket = store.getVolume(volumeName).getBucket(bucketName);
        doMultipartUpload(bucket, keyName2, (byte) 96, replication);
        assertEquals(awsUser1.getShortUserName(), bucket.getKey(keyName2).getOwner());
    } finally {
        OzoneManager.setS3Auth(null);
        UserGroupInformation.setLoginUser(oldUser);
        setOzClient(OzoneClientFactory.getRpcClient(cluster.getConf()));
        setStore(ozClient.getObjectStore());
    }
}

