@Test
public void testUploadWithStreamAndMemoryMappedBuffer() throws IOException {
    // create a local dir
    final String dir = GenericTestUtils.getTempPath(getClass().getSimpleName());
    GenericTestUtils.assertDirCreation(new File(dir));
    // create a local file
    final int chunkSize = 1024;
    final byte[] data = new byte[8 * chunkSize];
    ThreadLocalRandom.current().nextBytes(data);
    final File file = new File(dir, "data");
    try (FileOutputStream out = new FileOutputStream(file)) {
        out.write(data);
    }
    // create a volume
    final String volumeName = "vol-" + UUID.randomUUID();
    getStore().createVolume(volumeName);
    final OzoneVolume volume = getStore().getVolume(volumeName);
    // create a bucket
    final String bucketName = "buck-" + UUID.randomUUID();
    final BucketArgs bucketArgs = BucketArgs.newBuilder().setDefaultReplicationConfig(new DefaultReplicationConfig(ReplicationConfig.fromTypeAndFactor(ReplicationType.RATIS, THREE))).build();
    volume.createBucket(bucketName, bucketArgs);
    final OzoneBucket bucket = volume.getBucket(bucketName);
    // upload a key from the local file using memory-mapped buffers
    final String keyName = "key-" + UUID.randomUUID();
    try (RandomAccessFile raf = new RandomAccessFile(file, "r");
        OzoneDataStreamOutput out = bucket.createStreamKey(keyName, data.length)) {
        final FileChannel channel = raf.getChannel();
        long off = 0;
        for (long len = raf.length(); len > 0; ) {
            final long writeLen = Math.min(len, chunkSize);
            final ByteBuffer mapped = channel.map(FileChannel.MapMode.READ_ONLY, off, writeLen);
            out.write(mapped);
            off += writeLen;
            len -= writeLen;
        }
    }
    // verify the key details
    final OzoneKeyDetails keyDetails = bucket.getKey(keyName);
    assertEquals(keyName, keyDetails.getName());
    assertEquals(data.length, keyDetails.getDataSize());
    // verify the key content
    final byte[] buffer = new byte[data.length];
    try (OzoneInputStream in = keyDetails.getContent()) {
        for (int off = 0; off < data.length; ) {
            final int n = in.read(buffer, off, data.length - off);
            if (n < 0) {
                break;
            }
            off += n;
        }
    }
    assertArrayEquals(data, buffer);
}

@Test
public void testParallelDeleteBucketAndCreateKey() throws IOException, InterruptedException, TimeoutException {
    assumeThat(getCluster().getOzoneManager().isRatisEnabled()).isTrue();
    String volumeName = UUID.randomUUID().toString();
    String bucketName = UUID.randomUUID().toString();
    String value = "sample value";
    getStore().createVolume(volumeName);
    OzoneVolume volume = getStore().getVolume(volumeName);
    volume.createBucket(bucketName);
    String keyName = UUID.randomUUID().toString();
    GenericTestUtils.LogCapturer omSMLog = GenericTestUtils.LogCapturer.captureLogs(OzoneManagerStateMachine.LOG);
    OzoneManagerStateMachine omSM = getCluster().getOzoneManager().getOmRatisServer().getOmStateMachine();
    Thread thread1 = new Thread(() -> {
        try {
            volume.deleteBucket(bucketName);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    });
    Thread thread2 = new Thread(() -> {
        try {
            getClient().getProxy().createKey(volumeName, bucketName, keyName, 0, ReplicationType.RATIS, ONE, new HashMap<>());
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    });
    OMRequestHandlerPauseInjector injector = new OMRequestHandlerPauseInjector();
    omSM.getHandler().setInjector(injector);
    thread1.start();
    thread2.start();
    // Wait long enough for createKey's preExecute to finish executing
    GenericTestUtils.waitFor(() -> {
        return getCluster().getOzoneManager().getOmServerProtocol().getLastRequestToSubmit().getCmdType().equals(OzoneManagerProtocolProtos.Type.CreateKey);
    }, 100, 10000);
    injector.resume();
    try {
        thread1.join();
        thread2.join();
    } catch (InterruptedException ex) {
        throw new RuntimeException(ex);
    }
    omSM.getHandler().setInjector(null);
    // Generate more write requests to OM
    String newBucketName = UUID.randomUUID().toString();
    volume.createBucket(newBucketName);
    OzoneBucket bucket = volume.getBucket(newBucketName);
    for (int i = 0; i < 10; i++) {
        bucket.createKey("key-" + i, value.getBytes(UTF_8).length, ReplicationType.RATIS, ONE, new HashMap<>());
    }
    assertThat(omSMLog.getOutput()).contains("Failed to write, Exception occurred");
}

