/**
 * The test simulates an inadequate DN scenario by first writing key thereby
 * creating a container on 3 dns of the cluster. Then, a dn is shutdown and a
 * close container cmd gets issued so that in the leader and the alive
 * follower, container gets closed. And then, key is deleted and the node is
 * started up again so that it rejoins the ring and starts applying the
 * transaction from where it left by fetching the entries from the leader.
 * Until and unless this follower catches up and its replica gets closed, the
 * data is not deleted from any of the nodes which have the closed replica.
 */
@Test
void testDeleteKeyWithInAdequateDN() throws Exception {
    String keyName = "ratis";
    OzoneOutputStream key = objectStore.getVolume(volumeName).getBucket(bucketName).createKey(keyName, 0, ReplicationConfig.fromTypeAndFactor(ReplicationType.RATIS, ReplicationFactor.THREE), new HashMap<>());
    byte[] testData = "ratis".getBytes(UTF_8);
    // First write and flush creates a container in the datanode
    key.write(testData);
    key.flush();
    KeyOutputStream groupOutputStream = (KeyOutputStream) key.getOutputStream();
    List<OmKeyLocationInfo> locationInfoList = groupOutputStream.getLocationInfoList();
    Assumptions.assumeTrue(1 == locationInfoList.size(), "Expected exactly a single location, but got: " + locationInfoList.size());
    OmKeyLocationInfo omKeyLocationInfo = locationInfoList.get(0);
    long containerID = omKeyLocationInfo.getContainerID();
    // A container is created on the datanode. Now figure out a follower node to
    // kill.
    HddsDatanodeService follower = null;
    HddsDatanodeService leader = null;
    List<Pipeline> pipelineList = cluster.getStorageContainerManager().getPipelineManager().getPipelines(RatisReplicationConfig.getInstance(THREE));
    Assumptions.assumeTrue(pipelineList.size() >= FACTOR_THREE_PIPELINE_COUNT);
    Pipeline pipeline = pipelineList.get(0);
    for (HddsDatanodeService dn : cluster.getHddsDatanodes()) {
        if (RatisTestHelper.isRatisFollower(dn, pipeline)) {
            follower = dn;
        } else if (RatisTestHelper.isRatisLeader(dn, pipeline)) {
            leader = dn;
        }
    }
    assertNotNull(follower);
    assertNotNull(leader);
    //ensure that the chosen follower is still a follower
    Assumptions.assumeTrue(RatisTestHelper.isRatisFollower(follower, pipeline));
    // shutdown the  follower node
    cluster.shutdownHddsDatanode(follower.getDatanodeDetails());
    key.write(testData);
    key.close();
    // now move the container to the closed on the datanode.
    ContainerProtos.ContainerCommandRequestProto.Builder request = ContainerProtos.ContainerCommandRequestProto.newBuilder();
    request.setDatanodeUuid(pipeline.getFirstNode().getUuidString());
    request.setCmdType(ContainerProtos.Type.CloseContainer);
    request.setContainerID(containerID);
    request.setCloseContainer(ContainerProtos.CloseContainerRequestProto.getDefaultInstance());
    XceiverClientSpi xceiverClient = xceiverClientManager.acquireClient(pipeline);
    try {
        xceiverClient.sendCommand(request.build());
    } finally {
        xceiverClientManager.releaseClient(xceiverClient, false);
    }
    ContainerStateMachine stateMachine = (ContainerStateMachine) RatisTestHelper.getStateMachine(leader, pipeline);
    OmKeyArgs keyArgs = new OmKeyArgs.Builder().setVolumeName(volumeName).setBucketName(bucketName).setReplicationConfig(RatisReplicationConfig.getInstance(THREE)).setKeyName(keyName).build();
    OmKeyInfo info = cluster.getOzoneManager().lookupKey(keyArgs);
    BlockID blockID = info.getKeyLocationVersions().get(0).getLocationList().get(0).getBlockID();
    OzoneContainer ozoneContainer;
    final DatanodeStateMachine dnStateMachine = leader.getDatanodeStateMachine();
    ozoneContainer = dnStateMachine.getContainer();
    KeyValueHandler keyValueHandler = (KeyValueHandler) ozoneContainer.getDispatcher().getHandler(ContainerProtos.ContainerType.KeyValueContainer);
    Container container = ozoneContainer.getContainerSet().getContainer(blockID.getContainerID());
    BlockData blockData = keyValueHandler.getBlockManager().getBlock(container, blockID);
    //cluster.getOzoneManager().deleteKey(keyArgs);
    client.getObjectStore().getVolume(volumeName).getBucket(bucketName).deleteKey("ratis");
    // make sure the chunk was never deleted on the leader even though
    // deleteBlock handler is invoked
    for (ContainerProtos.ChunkInfo chunkInfo : blockData.getChunks()) {
        keyValueHandler.getChunkManager().readChunk(container, blockID, ChunkInfo.getFromProtoBuf(chunkInfo), null);
    }
    long numReadStateMachineOps = stateMachine.getMetrics().getNumReadStateMachineOps();
    assertEquals(0, stateMachine.getMetrics().getNumReadStateMachineFails());
    stateMachine.evictStateMachineCache();
    cluster.restartHddsDatanode(follower.getDatanodeDetails(), false);
    // wait for the raft server to come up and join the ratis ring
    Thread.sleep(10000);
    // Make sure the readStateMachine call got triggered after the follower
    // caught up
    assertThat(stateMachine.getMetrics().getNumReadStateMachineOps()).isGreaterThan(numReadStateMachineOps);
    assertEquals(0, stateMachine.getMetrics().getNumReadStateMachineFails());
    // wait for the chunk to get deleted now
    Thread.sleep(10000);
    for (HddsDatanodeService dn : cluster.getHddsDatanodes()) {
        keyValueHandler = (KeyValueHandler) dn.getDatanodeStateMachine().getContainer().getDispatcher().getHandler(ContainerProtos.ContainerType.KeyValueContainer);
        // make sure the chunk is now deleted on the all dns
        KeyValueHandler finalKeyValueHandler = keyValueHandler;
        StorageContainerException e = assertThrows(StorageContainerException.class, () -> {
            for (ContainerProtos.ChunkInfo chunkInfo : blockData.getChunks()) {
                finalKeyValueHandler.getChunkManager().readChunk(container, blockID, ChunkInfo.getFromProtoBuf(chunkInfo), null);
            }
        });
        assertSame(ContainerProtos.Result.UNABLE_TO_FIND_CHUNK, e.getResult());
    }
}

@Test
public void testDiscardPreallocatedBlocks() throws Exception {
    String keyName = getKeyName();
    OzoneOutputStream key = createKey(keyName, ReplicationType.RATIS, 2 * blockSize);
    KeyOutputStream keyOutputStream = assertInstanceOf(KeyOutputStream.class, key.getOutputStream());
    // With the initial size provided, it should have pre allocated 2 blocks
    assertEquals(2, keyOutputStream.getStreamEntries().size());
    long containerID1 = keyOutputStream.getStreamEntries().get(0).getBlockID().getContainerID();
    long containerID2 = keyOutputStream.getStreamEntries().get(1).getBlockID().getContainerID();
    assertEquals(containerID1, containerID2);
    String dataString = ContainerTestHelper.getFixedLengthString(keyString, (1 * blockSize));
    byte[] data = dataString.getBytes(UTF_8);
    key.write(data);
    List<OmKeyLocationInfo> locationInfos = new ArrayList<>(keyOutputStream.getLocationInfoList());
    List<BlockOutputStreamEntry> locationStreamInfos = new ArrayList<>(keyOutputStream.getStreamEntries());
    long containerID = locationInfos.get(0).getContainerID();
    ContainerInfo container = cluster.getStorageContainerManager().getContainerManager().getContainer(ContainerID.valueOf(containerID));
    Pipeline pipeline = cluster.getStorageContainerManager().getPipelineManager().getPipeline(container.getPipelineID());
    List<DatanodeDetails> datanodes = pipeline.getNodes();
    assertEquals(3, datanodes.size());
    waitForContainerClose(key);
    dataString = ContainerTestHelper.getFixedLengthString(keyString, (1 * blockSize));
    data = dataString.getBytes(UTF_8);
    key.write(data);
    assertEquals(3, keyOutputStream.getStreamEntries().size());
    // the 1st block got written. Now all the containers are closed, so the 2nd
    // pre allocated block will be removed from the list and new block should
    // have been allocated
    assertEquals(keyOutputStream.getLocationInfoList().get(0).getBlockID(), locationInfos.get(0).getBlockID());
    assertNotEquals(locationStreamInfos.get(1).getBlockID(), keyOutputStream.getLocationInfoList().get(1).getBlockID());
    key.close();
}

