public void testUploadTwiceWithEC() throws IOException, NoSuchAlgorithmException {
    bucketName = UUID.randomUUID().toString();
    bucket = getOzoneECBucket(bucketName);
    byte[] data = generateData(81920, (byte) 97);
    // perform upload and complete
    OmMultipartInfo multipartInfo = bucket.initiateMultipartUpload(keyName);
    String uploadID = multipartInfo.getUploadID();
    int partNumber = 1;
    Pair<String, String> partNameAndETag = uploadPart(bucket, keyName, uploadID, partNumber, data);
    Map<Integer, String> eTagsMap = new HashMap<>();
    eTagsMap.put(partNumber, partNameAndETag.getValue());
    bucket.completeMultipartUpload(keyName, uploadID, eTagsMap);
    long replicatedSize = QuotaUtil.getReplicatedSize(data.length, bucket.getReplicationConfig());
    assertEquals(volume.getBucket(bucketName).getUsedBytes(), replicatedSize);
    //upload same key again
    multipartInfo = bucket.initiateMultipartUpload(keyName);
    uploadID = multipartInfo.getUploadID();
    partNameAndETag = uploadPart(bucket, keyName, uploadID, partNumber, data);
    eTagsMap = new HashMap<>();
    eTagsMap.put(partNumber, partNameAndETag.getValue());
    bucket.completeMultipartUpload(keyName, uploadID, eTagsMap);
    // used sized should remain same, overwrite previous upload
    assertEquals(volume.getBucket(bucketName).getUsedBytes(), replicatedSize);
}

