@Test
public void testS3Auth() throws Exception {
    String volumeName = UUID.randomUUID().toString();
    String strToSign = "AWS4-HMAC-SHA256\n" + "20150830T123600Z\n" + "20150830/us-east-1/iam/aws4_request\n" + "f536975d06c0309214f805bb90ccff089219ecd68b2" + "577efef23edd43b7e1a59";
    String signature = "5d672d79c15b13162d9279b0855cfba" + "6789a8edb4c82c400e06b5924a6f2b5d7";
    String secret = "wJalrXUtnFEMI/K7MDENG+bPxRfiCYEXAMPLEKEY";
    String accessKey = UserGroupInformation.getCurrentUser().getUserName();
    S3SecretManager s3SecretManager = getCluster().getOzoneManager().getS3SecretManager();
    // Add secret to S3Secret table.
    s3SecretManager.storeSecret(accessKey, S3SecretValue.of(accessKey, secret));
    OMRequest writeRequest = OMRequest.newBuilder().setCmdType(OzoneManagerProtocolProtos.Type.CreateVolume).setVersion(ClientVersion.CURRENT_VERSION).setClientId(UUID.randomUUID().toString()).setCreateVolumeRequest(CreateVolumeRequest.newBuilder().setVolumeInfo(VolumeInfo.newBuilder().setVolume(volumeName).setAdminName(accessKey).setOwnerName(accessKey).build()).build()).setS3Authentication(S3Authentication.newBuilder().setAccessId(accessKey).setSignature(signature).setStringToSign(strToSign)).build();
    GenericTestUtils.waitFor(() -> getCluster().getOzoneManager().isLeaderReady(), 100, 120000);
    OMResponse omResponse = getCluster().getOzoneManager().getOmServerProtocol().submitRequest(null, writeRequest);
    // Verify response.
    assertEquals(Status.OK, omResponse.getStatus());
    // Read Request
    OMRequest readRequest = OMRequest.newBuilder().setCmdType(OzoneManagerProtocolProtos.Type.InfoVolume).setVersion(ClientVersion.CURRENT_VERSION).setClientId(UUID.randomUUID().toString()).setInfoVolumeRequest(InfoVolumeRequest.newBuilder().setVolumeName(volumeName).build()).setS3Authentication(S3Authentication.newBuilder().setAccessId(accessKey).setSignature(signature).setStringToSign(strToSign)).build();
    omResponse = getCluster().getOzoneManager().getOmServerProtocol().submitRequest(null, readRequest);
    // Verify response.
    assertEquals(Status.OK, omResponse.getStatus());
    VolumeInfo volumeInfo = omResponse.getInfoVolumeResponse().getVolumeInfo();
    assertNotNull(volumeInfo);
    assertEquals(volumeName, volumeInfo.getVolume());
    assertEquals(accessKey, volumeInfo.getAdminName());
    assertEquals(accessKey, volumeInfo.getOwnerName());
    // Override secret to S3Secret store with some dummy value
    s3SecretManager.storeSecret(accessKey, S3SecretValue.of(accessKey, "dummy"));
    // Write request with invalid credentials.
    omResponse = getCluster().getOzoneManager().getOmServerProtocol().submitRequest(null, writeRequest);
    assertEquals(Status.INVALID_TOKEN, omResponse.getStatus());
    // Read request with invalid credentials.
    omResponse = getCluster().getOzoneManager().getOmServerProtocol().submitRequest(null, readRequest);
    assertEquals(Status.INVALID_TOKEN, omResponse.getStatus());
}

