    OzoneTestUtils.closeAllContainers(scm.getEventQueue(), scm);
    Thread.sleep(2000);
    for (int j = 0; j < keyCount; j++) {
        OmKeyArgs keyArgs = new OmKeyArgs.Builder().setVolumeName(volumeName).setBucketName(bucketName).setKeyName(keys.get(j)).setDataSize(0).setReplicationConfig(RatisReplicationConfig.getInstance(HddsProtos.ReplicationFactor.THREE)).build();
        writeClient.deleteKey(keyArgs);
    }
    // Wait for block delete command sent from OM
    GenericTestUtils.waitFor(() -> {
        try {
            if (scm.getScmBlockManager().getDeletedBlockLog().getNumOfValidTransactions() > 0) {
