@Test
public void test() throws Exception {
    cluster.waitForClusterToBeReady();
    DatanodeDetails datanodeDetails = cluster.getHddsDatanodes().get(0).getDatanodeDetails();
    Long currentScmUsed = cluster.getStorageContainerManager().getScmNodeManager().getUsageInfo(datanodeDetails).getScmNodeStat().getScmUsed().get();
    //creating a key to take some storage space
    try (OzoneClient client = OzoneClientFactory.getRpcClient(conf)) {
        ObjectStore objectStore = client.getObjectStore();
        objectStore.createVolume("test");
        objectStore.getVolume("test").createBucket("test");
        OzoneOutputStream key = objectStore.getVolume("test").getBucket("test").createKey("test", 4096, ReplicationType.RATIS, ReplicationFactor.ONE, new HashMap<>());
        key.write("test".getBytes(UTF_8));
        key.close();
        //a new key is created, but the datanode default REFRESH_PERIOD is 1 hour,
        //still the cache is updated, so the scm will eventually get the new
        //used space from the datanode through node report.
        assertTrue(cluster.getStorageContainerManager().getScmNodeManager().getUsageInfo(datanodeDetails).getScmNodeStat().getScmUsed().isEqual(currentScmUsed));
        try {
            GenericTestUtils.waitFor(() -> isUsageInfoRefreshed(cluster, datanodeDetails, currentScmUsed), 500, 5 * 1000);
        } catch (TimeoutException te) {
            //no op
        } catch (InterruptedException ie) {
            //no op
        }
        //after waiting for several node report , this usage info
        //in SCM should be updated as we have updated the DN's cached usage info.
        assertTrue(cluster.getStorageContainerManager().getScmNodeManager().getUsageInfo(datanodeDetails).getScmNodeStat().getScmUsed().isGreater(currentScmUsed));
        //send refresh volume usage command to datanode
        cluster.getStorageContainerManager().getScmNodeManager().refreshAllHealthyDnUsageInfo();
        //waiting for the new usage info is refreshed
        GenericTestUtils.waitFor(() -> isUsageInfoRefreshed(cluster, datanodeDetails, currentScmUsed), 500, 5 * 1000);
    }
}

