@Test
@Flaky("HDDS-11087")
public void testECContainerReplication() throws Exception {
    OzoneConfiguration conf = createConfiguration(false);
    final Map<Integer, Integer> failedReadChunkCountMap = new ConcurrentHashMap<>();
    // Overiding Config to support 1k Chunk size
    conf.set("ozone.replication.allowed-configs", "(^((STANDALONE|RATIS)/(ONE|THREE))|(EC/(3-2|6-3|10-4)-" + "(512|1024|2048|4096|1)k)$)");
    conf.set(OZONE_SCM_CONTAINER_PLACEMENT_EC_IMPL_KEY, SCMContainerPlacementRackScatter.class.getCanonicalName());
    try (MockedStatic<ContainerProtocolCalls> mockedContainerProtocolCalls = Mockito.mockStatic(ContainerProtocolCalls.class, Mockito.CALLS_REAL_METHODS)) {
        mockContainerProtocolCalls(mockedContainerProtocolCalls, failedReadChunkCountMap);
        // Creating Cluster with 5 Nodes
        try (MiniOzoneCluster cluster = MiniOzoneCluster.newBuilder(conf).setNumDatanodes(5).build()) {
            cluster.waitForClusterToBeReady();
            try (OzoneClient client = OzoneClientFactory.getRpcClient(conf)) {
                Set<DatanodeDetails> allNodes = cluster.getHddsDatanodes().stream().map(HddsDatanodeService::getDatanodeDetails).collect(Collectors.toSet());
                List<DatanodeDetails> initialNodesWithData = new ArrayList<>();
                // Keeping 5 DNs and stopping the 6th Node here it is kept in the var extraNodes
                for (DatanodeDetails dn : allNodes) {
                    if (initialNodesWithData.size() < 5) {
                        initialNodesWithData.add(dn);
                    } else {
                        cluster.shutdownHddsDatanode(dn);
                    }
                }
                // Creating 2 stripes with Chunk Size 1k
                int size = 6 * 1024;
                byte[] originalData = createTestData(client, size);
                // Getting latest location of the key
                final OmKeyLocationInfo keyLocation = lookupKeyFirstLocation(cluster);
                long containerID = keyLocation.getContainerID();
                waitForContainerClose(cluster, containerID);
                // Forming Replica Index Map
                Map<Integer, DatanodeDetails> replicaIndexMap = initialNodesWithData.stream().map(dn -> new Object[] { dn, keyLocation.getPipeline().getReplicaIndex(dn) }).collect(Collectors.toMap(x -> (Integer) x[1], x -> (DatanodeDetails) x[0]));
                //Reading through file and comparing with input data.
                byte[] readData = new byte[size];
                try (OzoneInputStream inputStream = createInputStream(client)) {
                    inputStream.read(readData);
                    Assertions.assertArrayEquals(readData, originalData);
                }
                Assertions.assertEquals(0, failedReadChunkCountMap.size());
                //Opening a new stream before we make changes to the blocks.
                try (OzoneInputStream inputStream = createInputStream(client)) {
                    int firstReadLen = 1024 * 3;
                    Arrays.fill(readData, (byte) 0);
                    //Reading first stripe.
                    inputStream.read(readData, 0, firstReadLen);
                    Assertions.assertEquals(0, failedReadChunkCountMap.size());
                    //Checking the initial state as per the latest location.
                    assertState(cluster, ImmutableMap.of(1, replicaIndexMap.get(1), 2, replicaIndexMap.get(2), 3, replicaIndexMap.get(3), 4, replicaIndexMap.get(4), 5, replicaIndexMap.get(5)));
                    // Stopping replication manager
                    cluster.getStorageContainerManager().getReplicationManager().stop();
                    // Deleting the container from DN1 & DN3
                    deleteContainer(cluster, replicaIndexMap.get(1), containerID);
                    deleteContainer(cluster, replicaIndexMap.get(3), containerID);
                    // Waiting for replica count of container to come down to 3.
                    waitForReplicaCount(containerID, 3, cluster);
                    // Shutting down DN1
                    cluster.shutdownHddsDatanode(replicaIndexMap.get(1));
                    // Starting replication manager which should process under replication & write replica 1 to DN3.
                    cluster.getStorageContainerManager().getReplicationManager().start();
                    waitForReplicaCount(containerID, 4, cluster);
                    // Asserting Replica 1 has been written to DN3.
                    assertState(cluster, ImmutableMap.of(1, replicaIndexMap.get(3), 2, replicaIndexMap.get(2), 4, replicaIndexMap.get(4), 5, replicaIndexMap.get(5)));
                    // Starting DN1.
                    cluster.restartHddsDatanode(replicaIndexMap.get(1), false);
                    // Waiting for underreplication to get resolved.
                    waitForReplicaCount(containerID, 5, cluster);
                    // Asserting Replica 1 & Replica 3 has been swapped b/w DN1 & DN3.
                    assertState(cluster, ImmutableMap.of(1, replicaIndexMap.get(3), 2, replicaIndexMap.get(2), 3, replicaIndexMap.get(1), 4, replicaIndexMap.get(4), 5, replicaIndexMap.get(5)));
                    // Reading the Stripe 2 from the pre initialized inputStream
                    inputStream.read(readData, firstReadLen, size - firstReadLen);
                    // Asserting there was a failure in the first read chunk.
                    Assertions.assertEquals(ImmutableMap.of(1, 1, 3, 1), failedReadChunkCountMap);
                    Assertions.assertArrayEquals(readData, originalData);
                }
            }
        }
    }
}

@Test
public void testContainerRecoveryOverReplicationProcessing() throws Exception {
    byte[] inputData = getInputBytes(3);
    final OzoneBucket bucket = getOzoneBucket();
    String keyName = UUID.randomUUID().toString();
    final Pipeline pipeline;
    ECReplicationConfig repConfig = new ECReplicationConfig(3, 2, ECReplicationConfig.EcCodec.RS, chunkSize);
    try (OzoneOutputStream out = bucket.createKey(keyName, 1024, repConfig, new HashMap<>())) {
        out.write(inputData);
        pipeline = ((ECKeyOutputStream) out.getOutputStream()).getStreamEntries().get(0).getPipeline();
    }
    List<ContainerInfo> containers = cluster.getStorageContainerManager().getContainerManager().getContainers();
    ContainerInfo container = null;
    for (ContainerInfo info : containers) {
        if (info.getPipelineID().getId().equals(pipeline.getId().getId())) {
            container = info;
        }
    }
    StorageContainerManager scm = cluster.getStorageContainerManager();
    // Shutting down DN triggers close pipeline and close container.
    cluster.shutdownHddsDatanode(pipeline.getFirstNode());
    // Make sure container closed.
    waitForSCMContainerState(StorageContainerDatanodeProtocolProtos.ContainerReplicaProto.State.CLOSED, container.containerID());
    //Temporarily stop the RM process.
    scm.getReplicationManager().stop();
    waitForReplicationManagerStopped(scm.getReplicationManager());
    // Wait for the lower replication.
    waitForContainerCount(4, container.containerID(), scm);
    // Start the RM to resume the replication process and wait for the
    // reconstruction.
    scm.getReplicationManager().start();
    waitForContainerCount(5, container.containerID(), scm);
    // Let's verify for Over replications now.
    //Temporarily stop the RM process.
    scm.getReplicationManager().stop();
    waitForReplicationManagerStopped(scm.getReplicationManager());
    // Restart the DN to make the over replication and expect replication to be
    // increased.
    cluster.restartHddsDatanode(pipeline.getFirstNode(), true);
    // Check container is over replicated.
    waitForContainerCount(6, container.containerID(), scm);
    // Resume RM and wait the over replicated replica deleted.
    // ReplicationManager fix container replica state if different
    scm.getReplicationManager().start();
    // Wait for all the replicas to be closed.
    container = scm.getContainerInfo(container.getContainerID());
    waitForDNContainerState(container, scm);
    waitForContainerCount(5, container.containerID(), scm);
}

