        ReconstructECContainersCommandHandler handler = GenericTestUtils.getFieldReflection(dn.getDatanodeStateMachine(), "reconstructECContainersCommandHandler");
        ECReconstructionCoordinator coordinator = GenericTestUtils.mockFieldReflection(handler, "coordinator");
        doAnswer(invocation -> {
