    deleteKeys(volBbucketA);
    int volBBucketAKeyCount = keyCount(volBbucketA, snapshotKeyPrefix + "key-");
    assertEquals(20, volBBucketAKeyCount);
    snapshotKeyPrefix = createSnapshot(volumeB, bucketB);
    deleteKeys(volBbucketB);
    int volBBucketBKeyCount = keyCount(volBbucketB, snapshotKeyPrefix + "key-");
