@Test
public void testSnapDiff() throws Exception {
    String volume = "vol-" + counter.incrementAndGet();
    String bucket = "buck-" + counter.incrementAndGet();
    store.createVolume(volume);
    OzoneVolume volume1 = store.getVolume(volume);
    volume1.createBucket(bucket);
    OzoneBucket bucket1 = volume1.getBucket(bucket);
    // Create Key1 and take snapshot
    String key1 = "key-1-";
    key1 = createFileKeyWithPrefix(bucket1, key1);
    String snap1 = "snap" + counter.incrementAndGet();
    createSnapshot(volume, bucket, snap1);
    // When from and to snapshots are same, it returns empty response.
    SnapshotDiffReportOzone diff0 = getSnapDiffReport(volume, bucket, snap1, snap1);
    assertTrue(diff0.getDiffList().isEmpty());
    // Do nothing, take another snapshot
    String snap2 = "snap" + counter.incrementAndGet();
    createSnapshot(volume, bucket, snap2);
    SnapshotDiffReportOzone diff1 = getSnapDiffReport(volume, bucket, snap1, snap2);
    assertTrue(diff1.getDiffList().isEmpty());
    // Create Key2 and delete Key1, take snapshot
    String key2 = "key-2-";
    key2 = createFileKeyWithPrefix(bucket1, key2);
    bucket1.deleteKey(key1);
    String snap3 = "snap" + counter.incrementAndGet();
    createSnapshot(volume, bucket, snap3);
    // Diff should have 2 entries
    SnapshotDiffReportOzone diff2 = getSnapDiffReport(volume, bucket, snap2, snap3);
    assertEquals(2, diff2.getDiffList().size());
    assertEquals(Arrays.asList(SnapshotDiffReportOzone.getDiffReportEntry(SnapshotDiffReport.DiffType.DELETE, key1), SnapshotDiffReportOzone.getDiffReportEntry(SnapshotDiffReport.DiffType.CREATE, key2)), diff2.getDiffList());
    // Rename Key2
    String key2Renamed = key2 + "_renamed";
    bucket1.renameKey(key2, key2Renamed);
    String snap4 = "snap" + counter.incrementAndGet();
    createSnapshot(volume, bucket, snap4);
    SnapshotDiffReportOzone diff3 = getSnapDiffReport(volume, bucket, snap3, snap4);
    assertEquals(1, diff3.getDiffList().size());
    assertThat(diff3.getDiffList()).contains(SnapshotDiffReportOzone.getDiffReportEntry(SnapshotDiffReportOzone.DiffType.RENAME, key2, key2Renamed));
    // Create a directory
    String dir1 = "dir-1" + counter.incrementAndGet();
    bucket1.createDirectory(dir1);
    String snap5 = "snap" + counter.incrementAndGet();
    createSnapshot(volume, bucket, snap5);
    SnapshotDiffReportOzone diff4 = getSnapDiffReport(volume, bucket, snap4, snap5);
    assertEquals(1, diff4.getDiffList().size());
    assertThat(diff4.getDiffList()).contains(SnapshotDiffReportOzone.getDiffReportEntry(SnapshotDiffReportOzone.DiffType.CREATE, dir1));
    String key3 = createFileKeyWithPrefix(bucket1, "key-3-");
    String snap6 = "snap" + counter.incrementAndGet();
    createSnapshot(volume, bucket, snap6);
    createFileKey(bucket1, key3);
    String renamedKey3 = key3 + "_renamed";
    bucket1.renameKey(key3, renamedKey3);
    String snap7 = "snap" + counter.incrementAndGet();
    createSnapshot(volume, bucket, snap7);
    SnapshotDiffReportOzone diff5 = getSnapDiffReport(volume, bucket, snap6, snap7);
    List<SnapshotDiffReport.DiffReportEntry> expectedDiffList = Arrays.asList(SnapshotDiffReportOzone.getDiffReportEntry(SnapshotDiffReport.DiffType.RENAME, key3, renamedKey3), SnapshotDiffReportOzone.getDiffReportEntry(SnapshotDiffReport.DiffType.MODIFY, key3));
    assertEquals(expectedDiffList, diff5.getDiffList());
    IOException ioException = assertThrows(IOException.class, () -> store.snapshotDiff(volume, bucket, snap6, snap7, "3", 0, forceFullSnapshotDiff, disableNativeDiff));
    assertThat(ioException.getMessage()).contains("Index (given: 3) " + "should be a number >= 0 and < totalDiffEntries: 2. Page size " + "(given: 1000) should be a positive number > 0.");
}

@Test
public void testSnapDiffCancel() throws Exception {
    // Create key1 and take snapshot.
    String key1 = "key-1-" + counter.incrementAndGet();
    createFileKey(ozoneBucket, key1);
    String fromSnapName = "snap-1-" + counter.incrementAndGet();
    createSnapshot(volumeName, bucketName, fromSnapName);
    // Create key2 and take snapshot.
    String key2 = "key-2-" + counter.incrementAndGet();
    createFileKey(ozoneBucket, key2);
    String toSnapName = "snap-2-" + counter.incrementAndGet();
    createSnapshot(volumeName, bucketName, toSnapName);
    SnapshotDiffResponse response = store.snapshotDiff(volumeName, bucketName, fromSnapName, toSnapName, null, 0, false, disableNativeDiff);
    assertEquals(IN_PROGRESS, response.getJobStatus());
    CancelSnapshotDiffResponse cancelResponse = store.cancelSnapshotDiff(volumeName, bucketName, fromSnapName, toSnapName);
    assertEquals(CANCEL_SUCCEEDED.getMessage(), cancelResponse.getMessage());
    response = store.snapshotDiff(volumeName, bucketName, fromSnapName, toSnapName, null, 0, false, disableNativeDiff);
    // Job status should be updated to CANCELLED.
    assertEquals(CANCELLED, response.getJobStatus());
    // Executing the command again should return the
    // CANCEL_ALREADY_CANCELLED_JOB message.
    cancelResponse = store.cancelSnapshotDiff(volumeName, bucketName, fromSnapName, toSnapName);
    assertEquals(CANCEL_ALREADY_CANCELLED_JOB.getMessage(), cancelResponse.getMessage());
    response = store.snapshotDiff(volumeName, bucketName, fromSnapName, toSnapName, null, 0, false, disableNativeDiff);
    assertEquals(CANCELLED, response.getJobStatus());
    String fromSnapshotTableKey = SnapshotInfo.getTableKey(volumeName, bucketName, fromSnapName);
    String toSnapshotTableKey = SnapshotInfo.getTableKey(volumeName, bucketName, toSnapName);
    UUID fromSnapshotID = ozoneManager.getOmSnapshotManager().getSnapshotInfo(fromSnapshotTableKey).getSnapshotId();
    UUID toSnapshotID = ozoneManager.getOmSnapshotManager().getSnapshotInfo(toSnapshotTableKey).getSnapshotId();
    // Construct SnapshotDiffJob table key.
    String snapDiffJobKey = fromSnapshotID + DELIMITER + toSnapshotID;
    // Get the job from the SnapDiffJobTable, in order to get its ID.
    String jobID = ozoneManager.getOmSnapshotManager().getSnapshotDiffManager().getSnapDiffJobTable().get(snapDiffJobKey).getJobId();
    SnapshotDiffCleanupService snapshotDiffCleanupService = ozoneManager.getOmSnapshotManager().getSnapshotDiffCleanupService();
    // Run SnapshotDiffCleanupService.
    snapshotDiffCleanupService.run();
    // Verify that after running the cleanup service,
    // job exists in the purged job table.
    assertNotNull(snapshotDiffCleanupService.getEntryFromPurgedJobTable(jobID));
}

@Test
public void testSnapDiffCancelFailureResponses() throws Exception {
    // Create key1 and take snapshot.
    String key1 = "key-1-" + counter.incrementAndGet();
    createFileKey(ozoneBucket, key1);
    String fromSnapName = "snap-1-" + counter.incrementAndGet();
