    assertEquals(3, (getKeyTableSstFiles().size() - keyTableSize));
    // add a file to bucket1 and take second snapshot
    createFileKeyWithPrefix(bucket1, keyPrefix);
    String snap2 = "snap" + counter.incrementAndGet();
