    createSnapshot(volume1, bucket3, "bucket3-snap3");
    List<CompactionNode> filteredNodes = ozoneManager.getMetadataManager().getStore().getRocksDBCheckpointDiffer().getCompactionNodeMap().values().stream().filter(node -> !COLUMN_FAMILIES_TO_TRACK_IN_DAG.contains(node.getColumnFamily())).collect(Collectors.toList());
    assertEquals(0, filteredNodes.size());
    assertEquals(100, fetchReportPage(volume1, bucket1, "bucket1-snap1", "bucket1-snap2", null, 0).getDiffList().size());
    assertEquals(100, fetchReportPage(volume1, bucket1, "bucket1-snap2", "bucket1-snap3", null, 0).getDiffList().size());
    assertEquals(200, fetchReportPage(volume1, bucket1, "bucket1-snap1", "bucket1-snap3", null, 0).getDiffList().size());
    assertEquals(100, fetchReportPage(volume1, bucket2, "bucket2-snap1", "bucket2-snap2", null, 0).getDiffList().size());
    assertEquals(100, fetchReportPage(volume1, bucket2, "bucket2-snap2", "bucket2-snap3", null, 0).getDiffList().size());
    assertEquals(200, fetchReportPage(volume1, bucket2, "bucket2-snap1", "bucket2-snap3", null, 0).getDiffList().size());
    assertEquals(100, fetchReportPage(volume1, bucket3, "bucket3-snap1", "bucket3-snap2", null, 0).getDiffList().size());
    assertEquals(100, fetchReportPage(volume1, bucket3, "bucket3-snap2", "bucket3-snap3", null, 0).getDiffList().size());
    assertEquals(200, fetchReportPage(volume1, bucket3, "bucket3-snap1", "bucket3-snap3", null, 0).getDiffList().size());
}

