@Test
public // based on TestObjectStoreWithFSO:testListKeysAtDifferentLevels
void testListKeysAtDifferentLevels() throws Exception {
    OzoneVolume ozoneVolume = objectStore.getVolume(VOLUME_NAME);
    assertEquals(ozoneVolume.getName(), VOLUME_NAME);
    OzoneBucket ozoneBucket = ozoneVolume.getBucket(bucketName);
    assertEquals(ozoneBucket.getName(), bucketName);
    List<String> keys = Arrays.asList("/a/b1/c1/c1.tx", "/a/b1/c2/c2.tx", "/a/b2/d1/d11.tx", "/a/b2/d2/d21.tx", "/a/b2/d2/d22.tx", "/a/b2/d3/d31.tx", "/a/b3/e1/e11.tx", "/a/b3/e2/e21.tx", "/a/b3/e3/e31.tx");
    createKeys(ozoneBucket, keys);
    String snapshotName = UUID.randomUUID().toString();
    setKeyPrefix(createSnapshot(snapshotName).substring(1));
    // Delete the active fs so that we don't inadvertently read it
    deleteRootDir();
    // Root level listing keys
    Iterator<? extends OzoneKey> ozoneKeyIterator = ozoneBucket.listKeys(keyPrefix, null);
    verifyFullTreeStructure(ozoneKeyIterator);
    ozoneKeyIterator = ozoneBucket.listKeys(keyPrefix + "a/", null);
    verifyFullTreeStructure(ozoneKeyIterator);
    LinkedList<String> expectedKeys;
    // Intermediate level keyPrefix - 2nd level
    ozoneKeyIterator = ozoneBucket.listKeys(keyPrefix + "a/b2/", null);
    expectedKeys = new LinkedList<>();
    expectedKeys.add("a/b2/");
    expectedKeys.add("a/b2/d1/");
    expectedKeys.add("a/b2/d1/d11.tx");
    expectedKeys.add("a/b2/d2/");
    expectedKeys.add("a/b2/d2/d21.tx");
    expectedKeys.add("a/b2/d2/d22.tx");
    expectedKeys.add("a/b2/d3/");
    expectedKeys.add("a/b2/d3/d31.tx");
    checkKeyList(ozoneKeyIterator, expectedKeys);
    // Intermediate level keyPrefix - 3rd level
    ozoneKeyIterator = ozoneBucket.listKeys(keyPrefix + "a/b2/d1", null);
    expectedKeys = new LinkedList<>();
    expectedKeys.add("a/b2/d1/");
    expectedKeys.add("a/b2/d1/d11.tx");
    checkKeyList(ozoneKeyIterator, expectedKeys);
    // Boundary of a level
    ozoneKeyIterator = ozoneBucket.listKeys(keyPrefix + "a/b2/d2", keyPrefix + "a/b2/d2/d21.tx");
    expectedKeys = new LinkedList<>();
    expectedKeys.add("a/b2/d2/d22.tx");
    checkKeyList(ozoneKeyIterator, expectedKeys);
    // Boundary case - last node in the depth-first-traversal
    ozoneKeyIterator = ozoneBucket.listKeys(keyPrefix + "a/b3/e3", keyPrefix + "a/b3/e3/e31.tx");
    expectedKeys = new LinkedList<>();
    checkKeyList(ozoneKeyIterator, expectedKeys);
    deleteSnapshot(snapshotName);
    String expectedMessage = String.format("Unable to load snapshot. " + "Snapshot with table key '/%s/%s/%s' is no longer active", VOLUME_NAME, bucketName, snapshotName);
    OMException exception = assertThrows(OMException.class, () -> ozoneBucket.listKeys(keyPrefix + "a/", null));
    assertEquals(expectedMessage, exception.getMessage());
    exception = assertThrows(OMException.class, () -> ozoneBucket.listKeys(keyPrefix + "a/b2/", null));
    assertEquals(expectedMessage, exception.getMessage());
    exception = assertThrows(OMException.class, () -> ozoneBucket.listKeys(keyPrefix + "a/b2/d1", null));
    assertEquals(expectedMessage, exception.getMessage());
    exception = assertThrows(OMException.class, () -> ozoneBucket.listKeys(keyPrefix + "a/b2/d2", keyPrefix + "a/b2/d2/d21.tx"));
    assertEquals(expectedMessage, exception.getMessage());
    exception = assertThrows(OMException.class, () -> ozoneBucket.listKeys(keyPrefix + "a/b3/e3", keyPrefix + "a/b3/e3/e31.tx"));
    assertEquals(expectedMessage, exception.getMessage());
}

