    Path snapshotRoot2 = new Path(snapshotKeyPrefix2 + root);
    Path snapshotParent2 = new Path(snapshotKeyPrefix2 + parent);
    fileStatuses = o3fs.listStatus(snapshotRoot2);
    assertEquals(1, fileStatuses.length, "Should have created parent");
    assertEquals(fileStatuses[0].getPath().toUri().getPath(), snapshotParent2.toString(), "Parent path doesn't match");
    // ListStatus on a directory should return all subdirs along with
    // files, even if there exists a file and sub-dir with the same name.
    fileStatuses = o3fs.listStatus(snapshotParent2);
    assertEquals(2, fileStatuses.length, "FileStatus did not return all children of the directory");
    // ListStatus should return only the immediate children of a directory.
