    String snapshotKeyPrefix3 = createSnapshot(snapshotName3);
    Path snapshotParent3 = new Path(snapshotKeyPrefix3 + parent);
    deleteRootDir();
    fileStatuses = o3fs.listStatus(snapshotParent3);
    assertEquals(3, fileStatuses.length, "FileStatus did not return all children of the directory");
    deleteSnapshot(snapshotName1);
    FileNotFoundException exception1 = assertThrows(FileNotFoundException.class, () -> fs.listStatus(snapshotRoot1));
    assertEquals(String.format("Unable to load snapshot. " + "Snapshot with table key '/%s/%s/%s' is no longer active", VOLUME_NAME, bucketName, snapshotName1), exception1.getMessage());
    deleteSnapshot(snapshotName2);
    FileNotFoundException exception2 = assertThrows(FileNotFoundException.class, () -> fs.listStatus(snapshotRoot2));
    assertEquals(String.format("Unable to load snapshot. " + "Snapshot with table key '/%s/%s/%s' is no longer active", VOLUME_NAME, bucketName, snapshotName2), exception2.getMessage());
    deleteSnapshot(snapshotName3);
    FileNotFoundException exception3 = assertThrows(FileNotFoundException.class, () -> fs.listStatus(snapshotParent3));
    assertEquals(String.format("Unable to load snapshot. " + "Snapshot with table key '/%s/%s/%s' is no longer active", VOLUME_NAME, bucketName, snapshotName3), exception3.getMessage());
}

