@Test
public // based on TestOzoneFileSystem:testListStatusOnLargeDirectory
void testListStatusOnLargeDirectory() throws Exception {
    Path root = new Path("/");
    Set<String> paths = new TreeSet<>();
    int numDirs = LISTING_PAGE_SIZE + LISTING_PAGE_SIZE / 2;
    for (int i = 0; i < numDirs; i++) {
        Path p = new Path(root, String.valueOf(i));
        fs.mkdirs(p);
        paths.add(p.getName());
    }
    String snapshotName = UUID.randomUUID().toString();
    String snapshotKeyPrefix = createSnapshot(snapshotName);
    deleteRootDir();
    Path snapshotRoot = new Path(snapshotKeyPrefix + root);
    FileStatus[] fileStatuses = o3fs.listStatus(snapshotRoot);
    // Added logs for debugging failures, to check any sub-path mismatches.
    Set<String> actualPaths = new TreeSet<>();
    ArrayList<String> actualPathList = new ArrayList<>();
    if (numDirs != fileStatuses.length) {
        for (int i = 0; i < fileStatuses.length; i++) {
            boolean duplicate = actualPaths.add(fileStatuses[i].getPath().getName());
            if (!duplicate) {
                LOG.info("Duplicate path:{} in FileStatusList", fileStatuses[i].getPath().getName());
            }
            actualPathList.add(fileStatuses[i].getPath().getName());
        }
        if (numDirs != actualPathList.size()) {
            LOG.info("actualPathsSize: {}", actualPaths.size());
            LOG.info("actualPathListSize: {}", actualPathList.size());
            actualPaths.removeAll(paths);
            actualPathList.removeAll(paths);
            LOG.info("actualPaths: {}", actualPaths);
            LOG.info("actualPathList: {}", actualPathList);
        }
    }
    assertEquals(numDirs, fileStatuses.length, "Total directories listed do not match the existing directories");
    for (int i = 0; i < numDirs; i++) {
        assertThat(paths).contains(fileStatuses[i].getPath().getName());
    }
    deleteSnapshot(snapshotName);
    FileNotFoundException exception = assertThrows(FileNotFoundException.class, () -> fs.listStatus(snapshotRoot));
    assertEquals(String.format("Unable to load snapshot. " + "Snapshot with table key '/%s/%s/%s' is no longer active", VOLUME_NAME, bucketName, snapshotName), exception.getMessage());
}

// Test snapshot diff when OM restarts in HA OM env.
@Test
public void testSnapshotDiffWhenOmLeaderRestart() throws Exception {
    String snapshot1 = "snap-" + RandomStringUtils.randomNumeric(10);
    String snapshot2 = "snap-" + RandomStringUtils.randomNumeric(10);
    createFileKey(ozoneBucket, "key-" + RandomStringUtils.randomNumeric(10));
    store.createSnapshot(volumeName, bucketName, snapshot1);
    for (int i = 0; i < 100; i++) {
        createFileKey(ozoneBucket, "key-" + RandomStringUtils.randomNumeric(10));
    }
    store.createSnapshot(volumeName, bucketName, snapshot2);
    SnapshotDiffResponse response = store.snapshotDiff(volumeName, bucketName, snapshot1, snapshot2, null, 0, false, false);
    assertEquals(IN_PROGRESS, response.getJobStatus());
    String oldLeader = cluster.getOMLeader().getOMNodeId();
    OzoneManager omLeader = cluster.getOMLeader();
    cluster.shutdownOzoneManager(omLeader);
    cluster.restartOzoneManager(omLeader, true);
    cluster.waitForLeaderOM();
    String newLeader = cluster.getOMLeader().getOMNodeId();
    if (Objects.equals(oldLeader, newLeader)) {
        // If old leader becomes leader again. Job should be done by this time.
        response = store.snapshotDiff(volumeName, bucketName, snapshot1, snapshot2, null, 0, false, false);
        assertEquals(DONE, response.getJobStatus());
        assertEquals(100, response.getSnapshotDiffReport().getDiffList().size());
    } else {
        // If new leader is different from old leader. SnapDiff request will be
        // new to OM, and job status should be IN_PROGRESS.
        response = store.snapshotDiff(volumeName, bucketName, snapshot1, snapshot2, null, 0, false, false);
        assertEquals(IN_PROGRESS, response.getJobStatus());
        while (true) {
            response = store.snapshotDiff(volumeName, bucketName, snapshot1, snapshot2, null, 0, false, false);
            if (DONE == response.getJobStatus()) {
                assertEquals(100, response.getSnapshotDiffReport().getDiffList().size());
                break;
            }
            Thread.sleep(response.getWaitTimeInMs());
        }
    }
}

