@Test
@Order(3)
@Flaky("HDDS-11131")
public void testSnapshotWithFSO() throws Exception {
    Table<String, OmDirectoryInfo> dirTable = om.getMetadataManager().getDirectoryTable();
    Table<String, SnapshotInfo> snapshotInfoTable = om.getMetadataManager().getSnapshotInfoTable();
    Table<String, OmKeyInfo> keyTable = om.getMetadataManager().getFileTable();
    Table<String, RepeatedOmKeyInfo> deletedTable = om.getMetadataManager().getDeletedTable();
    Table<String, OmKeyInfo> deletedDirTable = om.getMetadataManager().getDeletedDirTable();
    Table<String, String> renamedTable = om.getMetadataManager().getSnapshotRenamedTable();
    BucketArgs bucketArgs = new BucketArgs.Builder().setBucketLayout(BucketLayout.FILE_SYSTEM_OPTIMIZED).build();
    OzoneBucket bucket2 = TestDataUtil.createBucket(client, VOLUME_NAME, bucketArgs, BUCKET_NAME_FSO);
    // Create 10 keys
    for (int i = 1; i <= 10; i++) {
        TestDataUtil.createKey(bucket2, "key" + i, ReplicationFactor.THREE, ReplicationType.RATIS, CONTENT);
    }
    // Create 5 keys to overwrite
    for (int i = 11; i <= 15; i++) {
        TestDataUtil.createKey(bucket2, "key" + i, ReplicationFactor.THREE, ReplicationType.RATIS, CONTENT);
    }
    // Create Directory and Sub
    for (int i = 1; i <= 3; i++) {
        String parent = "parent" + i;
        client.getProxy().createDirectory(VOLUME_NAME, BUCKET_NAME_FSO, parent);
        for (int j = 1; j <= 3; j++) {
            String childFile = "/childFile" + j;
            String childDir = "/childDir" + j;
            client.getProxy().createDirectory(VOLUME_NAME, BUCKET_NAME_FSO, parent + childDir);
            TestDataUtil.createKey(bucket2, parent + childFile, ReplicationFactor.THREE, ReplicationType.RATIS, CONTENT);
        }
    }
    // Total 12 dirs, 19 keys.
    assertTableRowCount(dirTable, 12);
    assertTableRowCount(keyTable, 24);
    assertTableRowCount(deletedDirTable, 0);
    // Create Snapshot1
    client.getObjectStore().createSnapshot(VOLUME_NAME, BUCKET_NAME_FSO, "snap1");
    assertTableRowCount(snapshotInfoTable, 1);
    // Overwrite 3 keys -> Moves previous version to deletedTable
    for (int i = 11; i <= 13; i++) {
        TestDataUtil.createKey(bucket2, "key" + i, ReplicationFactor.THREE, ReplicationType.RATIS, CONTENT);
    }
    assertTableRowCount(keyTable, 24);
    // Delete 5 Keys
    for (int i = 1; i <= 5; i++) {
        client.getProxy().deleteKey(VOLUME_NAME, BUCKET_NAME_FSO, "key" + i, false);
    }
    // Rename Keys 3 keys
    for (int i = 6; i <= 8; i++) {
        client.getProxy().renameKey(VOLUME_NAME, BUCKET_NAME_FSO, "key" + i, "renamedKey" + i);
    }
    // Rename 1 Dir
    for (int i = 1; i <= 1; i++) {
        client.getProxy().renameKey(VOLUME_NAME, BUCKET_NAME_FSO, "/parent" + i, "/renamedParent" + i);
    }
    // Delete 2 Dirs
    for (int i = 2; i <= 3; i++) {
        client.getProxy().deleteKey(VOLUME_NAME, BUCKET_NAME_FSO, "/parent" + i, true);
    }
    assertTableRowCount(renamedTable, 4);
    // Delete Renamed Keys
    for (int i = 6; i <= 8; i++) {
        client.getProxy().deleteKey(VOLUME_NAME, BUCKET_NAME_FSO, "renamedKey" + i, false);
    }
    // Delete Renamed Dir
    for (int i = 1; i <= 1; i++) {
        client.getProxy().deleteKey(VOLUME_NAME, BUCKET_NAME_FSO, "/renamedParent" + i, true);
    }
    assertTableRowCount(deletedTable, 11);
    assertTableRowCount(deletedDirTable, 3);
    assertTableRowCount(dirTable, 9);
    assertTableRowCount(renamedTable, 4);
    // Create Snapshot2
    client.getObjectStore().createSnapshot(VOLUME_NAME, BUCKET_NAME_FSO, "snap2");
    assertTableRowCount(snapshotInfoTable, 2);
    // Once snapshot is taken renamedTable, deletedTable, deletedDirTable
    // should be cleaned
    assertTableRowCount(renamedTable, 0);
    assertTableRowCount(deletedTable, 0);
    assertTableRowCount(deletedDirTable, 0);
    // Delete 3 overwritten keys
    for (int i = 11; i <= 13; i++) {
        client.getProxy().deleteKey(VOLUME_NAME, BUCKET_NAME_FSO, "key" + i, false);
    }
    // Overwrite 2 keys
    for (int i = 14; i <= 15; i++) {
        TestDataUtil.createKey(bucket2, "key" + i, ReplicationFactor.THREE, ReplicationType.RATIS, CONTENT);
    }
    // Delete 2 more keys
    for (int i = 9; i <= 10; i++) {
        client.getProxy().deleteKey(VOLUME_NAME, BUCKET_NAME_FSO, "key" + i, false);
    }
    assertTableRowCount(deletedTable, 7);
    // Create Snapshot3
    client.getObjectStore().createSnapshot(VOLUME_NAME, BUCKET_NAME_FSO, "snap3");
    assertTableRowCount(snapshotInfoTable, 3);
    assertTableRowCount(renamedTable, 0);
    assertTableRowCount(deletedDirTable, 0);
    assertTableRowCount(deletedTable, 0);
    assertTableRowCount(keyTable, 11);
    SnapshotInfo deletedSnap = om.getMetadataManager().getSnapshotInfoTable().get("/vol1/bucketfso/snap2");
    client.getObjectStore().deleteSnapshot(VOLUME_NAME, BUCKET_NAME_FSO, "snap2");
    assertTableRowCount(snapshotInfoTable, 2);
    // Delete 2 overwritten keys
    for (int i = 14; i <= 15; i++) {
        client.getProxy().deleteKey(VOLUME_NAME, BUCKET_NAME_FSO, "key" + i, false);
    }
    assertTableRowCount(deletedTable, 2);
    // Once all the tables are moved, the snapshot is deleted
    assertTableRowCount(om.getMetadataManager().getSnapshotInfoTable(), 2);
    verifySnapshotChain(deletedSnap, "/vol1/bucketfso/snap3");
    OmSnapshot snap3 = om.getOmSnapshotManager().getSnapshot(VOLUME_NAME, BUCKET_NAME_FSO, "snap3").get();
    Table<String, OmKeyInfo> snapDeletedDirTable = snap3.getMetadataManager().getDeletedDirTable();
    Table<String, String> snapRenamedTable = snap3.getMetadataManager().getSnapshotRenamedTable();
    Table<String, RepeatedOmKeyInfo> snapDeletedTable = snap3.getMetadataManager().getDeletedTable();
    assertTableRowCount(snapRenamedTable, 4);
    assertTableRowCount(snapDeletedDirTable, 3);
    // All the keys deleted before snapshot2 is moved to snap3
    assertTableRowCount(snapDeletedTable, 15);
    // Before deleting the last snapshot
    assertTableRowCount(renamedTable, 0);
    assertTableRowCount(deletedDirTable, 0);
    assertTableRowCount(deletedTable, 2);
    // Delete Snapshot3 and check entries moved to active DB
    client.getObjectStore().deleteSnapshot(VOLUME_NAME, BUCKET_NAME_FSO, "snap3");
    // Check entries moved to active DB
    assertTableRowCount(snapshotInfoTable, 1);
