    GenericTestUtils.LogCapturer miniOzoneClusterLog = GenericTestUtils.LogCapturer.captureLogs(MiniOzoneHAClusterImpl.LOG);
    /**
     * ************************************************************************
     *  1. Force bootstrap (with 1 node down and updated configs on rest) -> pass
     * ************************************************************************
     */
    // Update configs on all active OMs and Bootstrap a new node
    final String newNodeId = "omNode-bootstrap-1";
    IOException e = assertThrows(IOException.class, () -> cluster.bootstrapOzoneManager(newNodeId, true, false), "Bootstrap should have failed as configs are not updated on all OMs.");
    assertEquals(OmUtils.getOMAddressListPrintString(Lists.newArrayList(downOM.getNodeDetails())) + " do not have or " + "have incorrect information of the bootstrapping OM. Update their " + "ozone-site.xml before proceeding.", e.getMessage());
    assertThat(omLog.getOutput()).contains("Remote OM " + downOMNodeId + " configuration returned null");
    assertThat(omLog.getOutput()).contains("Remote OM config check " + "failed on OM " + downOMNodeId);
    assertThat(miniOzoneClusterLog.getOutput()).contains(newNodeId + " - System Exit");
    /**
     * ************************************************************************
     *  2. Force bootstrap (with 1 node down and updated configs on rest) -> pass
     * ************************************************************************
     */
