    OmKeyArgs finalKeyArgs1 = keyArgs;
    ex = assertThrows(OMException.class, () -> writeClient.createFile(finalKeyArgs1, false, false), "Open file should fail for non recursive write");
    if (ex.getResult() != OMException.ResultCodes.DIRECTORY_NOT_FOUND) {
        throw ex;
    }
    // file create should pass when recursive flag is set to true
    keySession = writeClient.createFile(keyArgs, false, true);
    keyArgs.setLocationInfoList(keySession.getKeyInfo().getLatestVersionLocations().getLocationList());
    writeClient.commitKey(keyArgs, keySession.getId());
    assertTrue(keyManager.getFileStatus(keyArgs).isFile());
    // try creating a file over a directory
    keyArgs = createBuilder().setKeyName("").build();
    OmKeyArgs finalKeyArgs2 = keyArgs;
    ex = assertThrows(OMException.class, () -> writeClient.createFile(finalKeyArgs2, true, true), "Open file should fail for non recursive write");
    if (ex.getResult() != OMException.ResultCodes.NOT_A_FILE) {
        throw ex;
    }
}

