@Test
public void testPrefixAclOps() throws IOException {
    String volumeName = "vol1";
    String bucketName = "bucket1";
    String prefix1 = "pf1/";
    OzoneObj ozPrefix1 = new OzoneObjInfo.Builder().setVolumeName(volumeName).setBucketName(bucketName).setPrefixName(prefix1).setResType(OzoneObj.ResourceType.PREFIX).setStoreType(OzoneObj.StoreType.OZONE).build();
    OzoneAcl ozAcl1 = new OzoneAcl(ACLIdentityType.USER, "user1", ACCESS, ACLType.READ);
    writeClient.addAcl(ozPrefix1, ozAcl1);
    List<OzoneAcl> ozAclGet = writeClient.getAcl(ozPrefix1);
    assertEquals(1, ozAclGet.size());
    assertEquals(ozAcl1, ozAclGet.get(0));
    List<OzoneAcl> acls = new ArrayList<>();
    OzoneAcl ozAcl2 = new OzoneAcl(ACLIdentityType.USER, "admin", ACCESS, ACLType.ALL);
    OzoneAcl ozAcl3 = new OzoneAcl(ACLIdentityType.GROUP, "dev", ACCESS, READ, WRITE);
    OzoneAcl ozAcl4 = new OzoneAcl(ACLIdentityType.GROUP, "dev", ACCESS, WRITE);
    OzoneAcl ozAcl5 = new OzoneAcl(ACLIdentityType.GROUP, "dev", ACCESS, READ);
    acls.add(ozAcl2);
    acls.add(ozAcl3);
    writeClient.setAcl(ozPrefix1, acls);
    ozAclGet = writeClient.getAcl(ozPrefix1);
    assertEquals(2, ozAclGet.size());
    int matchEntries = 0;
    for (OzoneAcl acl : ozAclGet) {
        if (acl.getType() == ACLIdentityType.GROUP) {
            assertEquals(ozAcl3, acl);
            matchEntries++;
        }
        if (acl.getType() == ACLIdentityType.USER) {
            assertEquals(ozAcl2, acl);
            matchEntries++;
        }
    }
    assertEquals(2, matchEntries);
    boolean result = writeClient.removeAcl(ozPrefix1, ozAcl4);
    assertTrue(result);
    ozAclGet = writeClient.getAcl(ozPrefix1);
    assertEquals(2, ozAclGet.size());
    result = writeClient.removeAcl(ozPrefix1, ozAcl3);
    assertTrue(result);
    ozAclGet = writeClient.getAcl(ozPrefix1);
    assertEquals(1, ozAclGet.size());
    assertEquals(ozAcl2, ozAclGet.get(0));
    // add dev:w
    writeClient.addAcl(ozPrefix1, ozAcl4);
    ozAclGet = writeClient.getAcl(ozPrefix1);
    assertEquals(2, ozAclGet.size());
    // add dev:r and validate the acl bitset combined
    writeClient.addAcl(ozPrefix1, ozAcl5);
    ozAclGet = writeClient.getAcl(ozPrefix1);
    assertEquals(2, ozAclGet.size());
    matchEntries = 0;
    for (OzoneAcl acl : ozAclGet) {
        if (acl.getType() == ACLIdentityType.GROUP) {
            assertEquals(ozAcl3, acl);
            matchEntries++;
        }
        if (acl.getType() == ACLIdentityType.USER) {
            assertEquals(ozAcl2, acl);
            matchEntries++;
        }
    }
    assertEquals(2, matchEntries);
    // cleanup
    writeClient.removeAcl(ozPrefix1, ozAcl1);
    writeClient.removeAcl(ozPrefix1, ozAcl2);
    writeClient.removeAcl(ozPrefix1, ozAcl3);
}

@Test
public void testInvalidPrefixAcl() throws IOException {
    String volumeName = "vol1";
    String bucketName = "bucket1";
    String prefix1 = "pf1/";
    // Invalid prefix not ending with "/"
    String invalidPrefix = "invalid/pf";
    OzoneAcl ozAcl1 = new OzoneAcl(ACLIdentityType.USER, "user1", ACCESS, ACLType.READ);
    OzoneObj ozInvalidPrefix = new OzoneObjInfo.Builder().setVolumeName(volumeName).setBucketName(bucketName).setPrefixName(invalidPrefix).setResType(OzoneObj.ResourceType.PREFIX).setStoreType(OzoneObj.StoreType.OZONE).build();
    // add acl with invalid prefix name
    Exception ex = assertThrows(OMException.class, () -> writeClient.addAcl(ozInvalidPrefix, ozAcl1));
    assertTrue(ex.getMessage().startsWith("Missing trailing slash"));
    OzoneObj ozPrefix1 = new OzoneObjInfo.Builder().setVolumeName(volumeName).setBucketName(bucketName).setPrefixName(prefix1).setResType(OzoneObj.ResourceType.PREFIX).setStoreType(OzoneObj.StoreType.OZONE).build();
    writeClient.addAcl(ozPrefix1, ozAcl1);
    List<OzoneAcl> ozAclGet = writeClient.getAcl(ozPrefix1);
    assertEquals(1, ozAclGet.size());
    assertEquals(ozAcl1, ozAclGet.get(0));
    // get acl with invalid prefix name
    ex = assertThrows(OMException.class, () -> writeClient.getAcl(ozInvalidPrefix));
    assertTrue(ex.getMessage().startsWith("Missing trailing slash"));
    // set acl with invalid prefix name
    List<OzoneAcl> ozoneAcls = new ArrayList<OzoneAcl>();
    ozoneAcls.add(ozAcl1);
    ex = assertThrows(OMException.class, () -> writeClient.setAcl(ozInvalidPrefix, ozoneAcls));
    assertTrue(ex.getMessage().startsWith("Missing trailing slash"));
    // remove acl with invalid prefix name
    ex = assertThrows(OMException.class, () -> writeClient.removeAcl(ozInvalidPrefix, ozAcl1));
    assertTrue(ex.getMessage().startsWith("Missing trailing slash"));
}

@Test
public void testLongestPrefixPath() throws IOException {
    String volumeName = "vol1";
    String bucketName = "bucket1";
    String prefix1 = "pf1/pf11/pf111/pf1111/";
    String file1 = "pf1/pf11/file1";
    String file2 = "pf1/pf11/pf111/pf1111/file2";
    OzoneObj ozPrefix1 = new OzoneObjInfo.Builder().setVolumeName(volumeName).setBucketName(bucketName).setPrefixName(prefix1).setResType(OzoneObj.ResourceType.PREFIX).setStoreType(OzoneObj.StoreType.OZONE).build();
    OzoneAcl ozAcl1 = new OzoneAcl(ACLIdentityType.USER, "user1", ACCESS, ACLType.READ);
    writeClient.addAcl(ozPrefix1, ozAcl1);
    OzoneObj ozFile1 = new OzoneObjInfo.Builder().setVolumeName(volumeName).setBucketName(bucketName).setKeyName(file1).setResType(OzoneObj.ResourceType.KEY).setStoreType(OzoneObj.StoreType.OZONE).build();
    List<OmPrefixInfo> prefixInfos = prefixManager.getLongestPrefixPath(ozFile1.getPath());
    assertEquals(5, prefixInfos.size());
    OzoneObj ozFile2 = new OzoneObjInfo.Builder().setVolumeName(volumeName).setBucketName(bucketName).setPrefixName(file2).setResType(OzoneObj.ResourceType.KEY).setStoreType(OzoneObj.StoreType.OZONE).build();
    prefixInfos = prefixManager.getLongestPrefixPath(ozFile2.getPath());
    assertEquals(7, prefixInfos.size());
    // Only the last node has acl on it
    assertEquals(ozAcl1, prefixInfos.get(6).getAcls().get(0));
    // All other nodes don't have acl value associate with it
    for (int i = 0; i < 6; i++) {
        assertNull(prefixInfos.get(i));
    }
    // cleanup
    writeClient.removeAcl(ozPrefix1, ozAcl1);
}

@Test
public void testLookupFile() throws IOException {
    String keyName = RandomStringUtils.randomAlphabetic(5);
    OmKeyArgs keyArgs = createBuilder().setKeyName(keyName).build();
    // lookup for a non-existent file
    OmKeyArgs finalKeyArgs = keyArgs;
    OMException ex = assertThrows(OMException.class, () -> keyManager.lookupFile(finalKeyArgs, null), "Lookup file should fail for non existent file");
    if (ex.getResult() != OMException.ResultCodes.FILE_NOT_FOUND) {
        throw ex;
    }
    // create a file
    OpenKeySession keySession = writeClient.createFile(keyArgs, false, false);
    keyArgs.setLocationInfoList(keySession.getKeyInfo().getLatestVersionLocations().getLocationList());
    writeClient.commitKey(keyArgs, keySession.getId());
    assertEquals(keyManager.lookupFile(keyArgs, null).getKeyName(), keyName);
    // lookup for created file
    keyArgs = createBuilder().setKeyName("").build();
    OmKeyArgs finalKeyArgs1 = keyArgs;
    ex = assertThrows(OMException.class, () -> keyManager.lookupFile(finalKeyArgs1, null), "Lookup file should fail for a directory");
    if (ex.getResult() != OMException.ResultCodes.NOT_A_FILE) {
        throw ex;
    }
}

@Test
public void testLookupKeyWithLocation() throws IOException {
    String keyName = RandomStringUtils.randomAlphabetic(5);
    OmKeyArgs keyArgs = createBuilder().setKeyName(keyName).setSortDatanodesInPipeline(true).build();
    // lookup for a non-existent key
    OMException ex = assertThrows(OMException.class, () -> keyManager.lookupKey(keyArgs, resolvedBucket(), null), "Lookup key should fail for non existent key");
    if (ex.getResult() != OMException.ResultCodes.KEY_NOT_FOUND) {
        throw ex;
    }
    // create a key
    OpenKeySession keySession = writeClient.createFile(keyArgs, false, false);
    // randomly select 3 datanodes
    List<DatanodeDetails> nodeList = new ArrayList<>();
    nodeList.add((DatanodeDetails) scm.getClusterMap().getNode(0, null, null, null, null, 0));
    nodeList.add((DatanodeDetails) scm.getClusterMap().getNode(1, null, null, null, null, 0));
    nodeList.add((DatanodeDetails) scm.getClusterMap().getNode(2, null, null, null, null, 0));
    assumeFalse(nodeList.get(0).equals(nodeList.get(1)));
    assumeFalse(nodeList.get(0).equals(nodeList.get(2)));
    // create a pipeline using 3 datanodes
    Pipeline pipeline = scm.getPipelineManager().createPipeline(RatisReplicationConfig.getInstance(ReplicationFactor.THREE), nodeList);
    List<OmKeyLocationInfo> locationInfoList = new ArrayList<>();
    List<OmKeyLocationInfo> locationList = keySession.getKeyInfo().getLatestVersionLocations().getLocationList();
    assertEquals(1, locationList.size());
    long containerID = locationList.get(0).getContainerID();
    locationInfoList.add(new OmKeyLocationInfo.Builder().setPipeline(pipeline).setBlockID(new BlockID(containerID, locationList.get(0).getLocalID())).build());
    keyArgs.setLocationInfoList(locationInfoList);
    writeClient.commitKey(keyArgs, keySession.getId());
    ContainerInfo containerInfo = new ContainerInfo.Builder().setContainerID(containerID).setPipelineID(pipeline.getId()).build();
    List<ContainerWithPipeline> containerWithPipelines = Arrays.asList(new ContainerWithPipeline(containerInfo, pipeline));
    when(mockScmContainerClient.getContainerWithPipelineBatch(Arrays.asList(containerID))).thenReturn(containerWithPipelines);
    OmKeyInfo key = keyManager.lookupKey(keyArgs, resolvedBucket(), null);
    assertEquals(key.getKeyName(), keyName);
    Pipeline keyPipeline = key.getLatestVersionLocations().getLocationList().get(0).getPipeline();
    DatanodeDetails leader = keyPipeline.getFirstNode();
    DatanodeDetails follower1 = keyPipeline.getNodes().get(1);
    DatanodeDetails follower2 = keyPipeline.getNodes().get(2);
    assertNotEquals(leader, follower1);
    assertNotEquals(follower1, follower2);
    // lookup key, leader as client
    OmKeyInfo key1 = keyManager.lookupKey(keyArgs, resolvedBucket(), leader.getIpAddress());
    assertEquals(leader, key1.getLatestVersionLocations().getLocationList().get(0).getPipeline().getClosestNode());
    // lookup key, follower1 as client
    OmKeyInfo key2 = keyManager.lookupKey(keyArgs, resolvedBucket(), follower1.getIpAddress());
    assertEquals(follower1, key2.getLatestVersionLocations().getLocationList().get(0).getPipeline().getClosestNode());
    // lookup key, follower2 as client
    OmKeyInfo key3 = keyManager.lookupKey(keyArgs, resolvedBucket(), follower2.getIpAddress());
    assertEquals(follower2, key3.getLatestVersionLocations().getLocationList().get(0).getPipeline().getClosestNode());
    // lookup key, random node as client
    OmKeyInfo key4 = keyManager.lookupKey(keyArgs, resolvedBucket(), "/d=default-drack/127.0.0.1");
    assertThat(keyPipeline.getNodes()).containsAll(key4.getLatestVersionLocations().getLocationList().get(0).getPipeline().getNodesInOrder());
}

@Test
public void testLatestLocationVersion() throws IOException {
    String keyName = RandomStringUtils.randomAlphabetic(5);
    OmKeyArgs keyArgs = createBuilder(VERSIONED_BUCKET_NAME).setKeyName(keyName).setLatestVersionLocation(true).build();
    // lookup for a non-existent key
    OmKeyArgs finalKeyArgs = keyArgs;
    OMException ex = assertThrows(OMException.class, () -> keyManager.lookupKey(finalKeyArgs, resolvedBucket(), null), "Lookup key should fail for non existent key");
    if (ex.getResult() != OMException.ResultCodes.KEY_NOT_FOUND) {
        throw ex;
    }
    // create a key
    OpenKeySession keySession = writeClient.createFile(keyArgs, false, false);
    // randomly select 3 datanodes
    List<DatanodeDetails> nodeList = new ArrayList<>();
    nodeList.add((DatanodeDetails) scm.getClusterMap().getNode(0, null, null, null, null, 0));
    nodeList.add((DatanodeDetails) scm.getClusterMap().getNode(1, null, null, null, null, 0));
    nodeList.add((DatanodeDetails) scm.getClusterMap().getNode(2, null, null, null, null, 0));
    assumeFalse(nodeList.get(0).equals(nodeList.get(1)));
    assumeFalse(nodeList.get(0).equals(nodeList.get(2)));
    // create a pipeline using 3 datanodes
    Pipeline pipeline = scm.getPipelineManager().createPipeline(RatisReplicationConfig.getInstance(ReplicationFactor.THREE), nodeList);
    List<OmKeyLocationInfo> locationInfoList = new ArrayList<>();
    List<OmKeyLocationInfo> locationList = keySession.getKeyInfo().getLatestVersionLocations().getLocationList();
    assertEquals(1, locationList.size());
    locationInfoList.add(new OmKeyLocationInfo.Builder().setPipeline(pipeline).setBlockID(new BlockID(locationList.get(0).getContainerID(), locationList.get(0).getLocalID())).build());
    keyArgs.setLocationInfoList(locationInfoList);
    writeClient.commitKey(keyArgs, keySession.getId());
    // Mock out the pipelines from the SCM
    ContainerInfo containerInfo = new ContainerInfo.Builder().setContainerID(1L).setPipelineID(pipeline.getId()).build();
    List<ContainerWithPipeline> containerWithPipelines = Arrays.asList(new ContainerWithPipeline(containerInfo, pipeline));
    when(mockScmContainerClient.getContainerWithPipelineBatch(Arrays.asList(1L))).thenReturn(containerWithPipelines);
    OmKeyInfo key = keyManager.lookupKey(keyArgs, resolvedBucket(), null);
    assertEquals(key.getKeyLocationVersions().size(), 1);
    keySession = writeClient.createFile(keyArgs, true, true);
    writeClient.commitKey(keyArgs, keySession.getId());
    // Test lookupKey (latestLocationVersion == true)
    key = keyManager.lookupKey(keyArgs, resolvedBucket(), null);
    assertEquals(key.getKeyLocationVersions().size(), 1);
    // Test ListStatus (latestLocationVersion == true)
    List<OzoneFileStatus> fileStatuses = keyManager.listStatus(keyArgs, false, "", 1);
    assertEquals(fileStatuses.size(), 1);
    assertEquals(fileStatuses.get(0).getKeyInfo().getKeyLocationVersions().size(), 1);
    // Test GetFileStatus (latestLocationVersion == true)
    OzoneFileStatus ozoneFileStatus = keyManager.getFileStatus(keyArgs, null);
    assertEquals(ozoneFileStatus.getKeyInfo().getKeyLocationVersions().size(), 1);
    // Test LookupFile (latestLocationVersion == true)
    key = keyManager.lookupFile(keyArgs, null);
    assertEquals(key.getKeyLocationVersions().size(), 1);
    keyArgs = createBuilder(VERSIONED_BUCKET_NAME).setKeyName(keyName).setLatestVersionLocation(false).build();
    // Test lookupKey (latestLocationVersion == false)
    key = keyManager.lookupKey(keyArgs, resolvedBucket(), null);
    assertEquals(key.getKeyLocationVersions().size(), 2);
    // Test ListStatus (latestLocationVersion == false)
    fileStatuses = keyManager.listStatus(keyArgs, false, "", 100);
    assertEquals(fileStatuses.size(), 1);
    assertEquals(fileStatuses.get(0).getKeyInfo().getKeyLocationVersions().size(), 2);
    // Test GetFileStatus (latestLocationVersion == false)
    ozoneFileStatus = keyManager.getFileStatus(keyArgs, null);
    assertEquals(ozoneFileStatus.getKeyInfo().getKeyLocationVersions().size(), 2);
    // Test LookupFile (latestLocationVersion == false)
    key = keyManager.lookupFile(keyArgs, null);
    assertEquals(key.getKeyLocationVersions().size(), 2);
    // Test ListKeys (latestLocationVersion is always true for ListKeys)
    List<OmKeyInfo> keyInfos = keyManager.listKeys(keyArgs.getVolumeName(), keyArgs.getBucketName(), "", keyArgs.getKeyName(), 100).getKeys();
    assertEquals(keyInfos.size(), 1);
    assertEquals(keyInfos.get(0).getKeyLocationVersions().size(), 1);
}

@Test
public void testListStatusWithTableCache() throws Exception {
    // Inspired by TestOmMetadataManager#testListKeys
    String prefixKeyInDB = "key-d";
    String prefixKeyInCache = "key-c";
    // Add a total of 100 key entries to DB and TableCache (50 entries each)
    for (int i = 1; i <= 100; i++) {
        if (i % 2 == 0) {
            // Add to DB
            OMRequestTestUtils.addKeyToTable(false, VOLUME_NAME, BUCKET_NAME, prefixKeyInDB + i, 1000L, RatisReplicationConfig.getInstance(ONE), metadataManager);
        } else {
            // Add to TableCache
            OMRequestTestUtils.addKeyToTableCache(VOLUME_NAME, BUCKET_NAME, prefixKeyInCache + i, RatisReplicationConfig.getInstance(ONE), metadataManager);
        }
    }
    OmKeyArgs rootDirArgs = createKeyArgs("");
    // Get entries in both TableCache and DB
    List<OzoneFileStatus> fileStatuses = keyManager.listStatus(rootDirArgs, true, "", 1000);
    assertEquals(100, fileStatuses.size());
    // Get entries with startKey=prefixKeyInDB
    fileStatuses = keyManager.listStatus(rootDirArgs, true, prefixKeyInDB, 1000);
    assertEquals(50, fileStatuses.size());
    // Get entries with startKey=prefixKeyInCache
    fileStatuses = keyManager.listStatus(rootDirArgs, true, prefixKeyInCache, 1000);
    assertEquals(100, fileStatuses.size());
    // Clean up cache by marking those keys in cache as deleted
    for (int i = 1; i <= 100; i += 2) {
        String key = metadataManager.getOzoneKey(VOLUME_NAME, BUCKET_NAME, prefixKeyInCache + i);
        metadataManager.getKeyTable(getDefaultBucketLayout()).addCacheEntry(new CacheKey<>(key), CacheValue.get(2L));
    }
}

@ParameterizedTest
@ValueSource(booleans = { true, false })
public void testListStatusWithTableCacheRecursive(boolean enablePath) throws Exception {
    conf.setBoolean(OMConfigKeys.OZONE_OM_ENABLE_FILESYSTEM_PATHS, enablePath);
    String keyNameDir1 = "dir1";
    OmKeyArgs keyArgsDir1 = createBuilder().setKeyName(keyNameDir1).build();
    addDirectory(keyArgsDir1);
    String keyNameDir1Subdir1 = "dir1" + OZONE_URI_DELIMITER + "subdir1";
    OmKeyArgs keyArgsDir1Subdir1 = createBuilder().setKeyName(keyNameDir1Subdir1).build();
    addDirectory(keyArgsDir1Subdir1);
    String keyNameDir2 = "dir2";
    OmKeyArgs keyArgsDir2 = createBuilder().setKeyName(keyNameDir2).build();
    addDirectory(keyArgsDir2);
    OmKeyArgs rootDirArgs = createKeyArgs("");
    // Test listStatus with recursive=false, should only have dirs under root
    List<OzoneFileStatus> fileStatuses = keyManager.listStatus(rootDirArgs, false, "", 1000);
    assertEquals(2, fileStatuses.size());
    // Test listStatus with recursive=true, should have dirs under root and
    fileStatuses = keyManager.listStatus(rootDirArgs, true, "", 1000);
    assertEquals(3, fileStatuses.size());
    // Add a total of 10 key entries to DB and TableCache under dir1
    String prefixKeyInDB = "key-d";
    String prefixKeyInCache = "key-c";
    for (int i = 1; i <= 10; i++) {
        if (i % 2 == 0) {
            // Add to DB
            OMRequestTestUtils.addKeyToTable(false, VOLUME_NAME, BUCKET_NAME, keyNameDir1Subdir1 + OZONE_URI_DELIMITER + prefixKeyInDB + i, 1000L, RatisReplicationConfig.getInstance(ONE), metadataManager);
        } else {
            // Add to TableCache
            OMRequestTestUtils.addKeyToTableCache(VOLUME_NAME, BUCKET_NAME, keyNameDir1Subdir1 + OZONE_URI_DELIMITER + prefixKeyInCache + i, RatisReplicationConfig.getInstance(ONE), metadataManager);
        }
    }
    // Test non-recursive, should return the dir under root
    fileStatuses = keyManager.listStatus(rootDirArgs, false, "", 1000);
    assertEquals(2, fileStatuses.size());
    // Test recursive, should return the dir and the keys in it
    fileStatuses = keyManager.listStatus(rootDirArgs, true, "", 1000);
    assertEquals(10 + 3, fileStatuses.size());
    // Clean up
    for (int i = 1; i <= 10; i += 2) {
        // Mark TableCache entries as deleted
        // Note that DB entry clean up is handled by cleanupTest()
        String key = metadataManager.getOzoneKey(VOLUME_NAME, BUCKET_NAME, keyNameDir1Subdir1 + OZONE_URI_DELIMITER + prefixKeyInCache + i);
        metadataManager.getKeyTable(getDefaultBucketLayout()).addCacheEntry(new CacheKey<>(key), CacheValue.get(2L));
    }
}

@Test
public void testListStatusWithDeletedEntriesInCache() throws Exception {
    String prefixKey = "key-";
    TreeSet<String> existKeySet = new TreeSet<>();
    TreeSet<String> deletedKeySet = new TreeSet<>();
    for (int i = 1; i <= 100; i++) {
        if (i % 2 == 0) {
            OMRequestTestUtils.addKeyToTable(false, VOLUME_NAME, BUCKET_NAME, prefixKey + i, 1000L, RatisReplicationConfig.getInstance(ONE), metadataManager);
            existKeySet.add(prefixKey + i);
        } else {
            OMRequestTestUtils.addKeyToTableCache(VOLUME_NAME, BUCKET_NAME, prefixKey + i, RatisReplicationConfig.getInstance(ONE), metadataManager);
            String key = metadataManager.getOzoneKey(VOLUME_NAME, BUCKET_NAME, prefixKey + i);
            // Mark as deleted in cache.
            metadataManager.getKeyTable(getDefaultBucketLayout()).addCacheEntry(new CacheKey<>(key), CacheValue.get(2L));
            deletedKeySet.add(key);
        }
    }
    OmKeyArgs rootDirArgs = createKeyArgs("");
    List<OzoneFileStatus> fileStatuses = keyManager.listStatus(rootDirArgs, true, "", 1000);
    // Should only get entries that are not marked as deleted.
    assertEquals(50, fileStatuses.size());
    // Test startKey
    fileStatuses = keyManager.listStatus(rootDirArgs, true, prefixKey, 1000);
    // Should only get entries that are not marked as deleted.
    assertEquals(50, fileStatuses.size());
    // Verify result
    TreeSet<String> expectedKeys = new TreeSet<>();
    for (OzoneFileStatus fileStatus : fileStatuses) {
        String keyName = fileStatus.getKeyInfo().getKeyName();
        expectedKeys.add(keyName);
        assertTrue(keyName.startsWith(prefixKey));
    }
    assertEquals(expectedKeys, existKeySet);
    // Sanity check, existKeySet should not intersect with deletedKeySet.
    assertEquals(0, Sets.intersection(existKeySet, deletedKeySet).size());
    // Next, mark half of the entries left as deleted
    boolean doDelete = false;
    for (String key : existKeySet) {
        if (doDelete) {
            String ozoneKey = metadataManager.getOzoneKey(VOLUME_NAME, BUCKET_NAME, key);
            metadataManager.getKeyTable(getDefaultBucketLayout()).addCacheEntry(new CacheKey<>(ozoneKey), CacheValue.get(2L));
            deletedKeySet.add(key);
        }
        doDelete = !doDelete;
    }
    // Update existKeySet
    existKeySet.removeAll(deletedKeySet);
    fileStatuses = keyManager.listStatus(rootDirArgs, true, "", 1000);
    // Should only get entries that are not marked as deleted.
    assertEquals(50 / 2, fileStatuses.size());
    // Verify result
    expectedKeys.clear();
    for (OzoneFileStatus fileStatus : fileStatuses) {
        String keyName = fileStatus.getKeyInfo().getKeyName();
        expectedKeys.add(keyName);
        assertTrue(keyName.startsWith(prefixKey));
    }
    assertEquals(expectedKeys, existKeySet);
    // Test pagination
    final int batchSize = 5;
    String startKey = "";
    expectedKeys.clear();
    do {
        fileStatuses = keyManager.listStatus(rootDirArgs, true, startKey, batchSize);
        // Note fileStatuses will never be empty since we are using the last
        // keyName as the startKey of next batch,
        // the startKey itself will show up in the next batch of results.
        // This is fine as we are using a set to store results.
        for (OzoneFileStatus fileStatus : fileStatuses) {
            startKey = fileStatus.getKeyInfo().getKeyName();
            expectedKeys.add(startKey);
            assertTrue(startKey.startsWith(prefixKey));
        }
        // fileStatuses.size() == batchSize indicates there might be another batch
        // fileStatuses.size() < batchSize indicates it is the last batch
    } while (fileStatuses.size() == batchSize);
    assertEquals(expectedKeys, existKeySet);
    // Clean up by marking remaining entries as deleted
    for (String key : existKeySet) {
        String ozoneKey = metadataManager.getOzoneKey(VOLUME_NAME, BUCKET_NAME, key);
        metadataManager.getKeyTable(getDefaultBucketLayout()).addCacheEntry(new CacheKey<>(ozoneKey), CacheValue.get(2L));
        deletedKeySet.add(key);
    }
    // Update existKeySet
    existKeySet.removeAll(deletedKeySet);
    assertTrue(existKeySet.isEmpty());
}

@ParameterizedTest
@ValueSource(booleans = { true, false })
public void testListStatus(boolean enablePath) throws IOException {
    conf.setBoolean(OMConfigKeys.OZONE_OM_ENABLE_FILESYSTEM_PATHS, enablePath);
    String superDir = RandomStringUtils.randomAlphabetic(5);
    int numDirectories = 5;
    int numFiles = 5;
    // set of directory descendants of root
    Set<String> directorySet = new TreeSet<>();
    // set of file descendants of root
    Set<String> fileSet = new TreeSet<>();
    createDepthTwoDirectory(superDir, numDirectories, numFiles, directorySet, fileSet);
    // set of all descendants of root
    Set<String> children = new TreeSet<>(directorySet);
    children.addAll(fileSet);
    // number of entries in the filesystem
    int numEntries = directorySet.size() + fileSet.size();
    OmKeyArgs rootDirArgs = createKeyArgs("");
    List<OzoneFileStatus> fileStatuses = keyManager.listStatus(rootDirArgs, true, "", 100);
    // verify the number of status returned is same as number of entries
    assertEquals(numEntries, fileStatuses.size());
    fileStatuses = keyManager.listStatus(rootDirArgs, false, "", 100);
    // the number of immediate children of root is 1
    assertEquals(1, fileStatuses.size());
    // if startKey is the first descendant of the root then listStatus should
    // return all the entries.
    String startKey = children.iterator().next();
    fileStatuses = keyManager.listStatus(rootDirArgs, true, startKey.substring(0, startKey.length() - 1), 100);
    assertEquals(numEntries, fileStatuses.size());
    for (String directory : directorySet) {
        // verify status list received for each directory with recursive flag set
        // to false
        OmKeyArgs dirArgs = createKeyArgs(directory);
        fileStatuses = keyManager.listStatus(dirArgs, false, "", 100);
        verifyFileStatus(directory, fileStatuses, directorySet, fileSet, false);
        // verify status list received for each directory with recursive flag set
        // to true
        fileStatuses = keyManager.listStatus(dirArgs, true, "", 100);
        verifyFileStatus(directory, fileStatuses, directorySet, fileSet, true);
        // verify list status call with using the startKey parameter and
        // recursive flag set to false. After every call to listStatus use the
        // latest received file status as the startKey until no more entries are
        // left to list.
        List<OzoneFileStatus> tempFileStatus = null;
        Set<OzoneFileStatus> tmpStatusSet = new HashSet<>();
        do {
            tempFileStatus = keyManager.listStatus(dirArgs, false, tempFileStatus != null ? tempFileStatus.get(tempFileStatus.size() - 1).getKeyInfo().getKeyName() : null, 2);
            tmpStatusSet.addAll(tempFileStatus);
        } while (tempFileStatus.size() == 2);
        verifyFileStatus(directory, new ArrayList<>(tmpStatusSet), directorySet, fileSet, false);
        // verify list status call with using the startKey parameter and
        // recursive flag set to true. After every call to listStatus use the
        // latest received file status as the startKey until no more entries are
        // left to list.
        tempFileStatus = null;
        tmpStatusSet = new HashSet<>();
        do {
            tempFileStatus = keyManager.listStatus(dirArgs, true, tempFileStatus != null ? tempFileStatus.get(tempFileStatus.size() - 1).getKeyInfo().getKeyName() : null, 2);
            tmpStatusSet.addAll(tempFileStatus);
        } while (tempFileStatus.size() == 2);
        verifyFileStatus(directory, new ArrayList<>(tmpStatusSet), directorySet, fileSet, true);
    }
}

