@Test
public void testKeysPurgingByKeyDeletingService() throws Exception {
    // Create Volume and Bucket
    String volumeName = UUID.randomUUID().toString();
    String bucketName = UUID.randomUUID().toString();
    store.createVolume(volumeName);
    OzoneVolume volume = store.getVolume(volumeName);
    volume.createBucket(bucketName);
    OzoneBucket bucket = volume.getBucket(bucketName);
    // Create some keys and write data into them
    String keyBase = UUID.randomUUID().toString();
    String keyString = UUID.randomUUID().toString();
    byte[] data = ContainerTestHelper.getFixedLengthString(keyString, KEY_SIZE).getBytes(UTF_8);
    List<String> keys = new ArrayList<>(NUM_KEYS);
    for (int i = 1; i <= NUM_KEYS; i++) {
        String keyName = keyBase + "-" + i;
        keys.add(keyName);
        OzoneOutputStream keyStream = TestHelper.createKey(keyName, ReplicationType.RATIS, ReplicationFactor.ONE, KEY_SIZE, store, volumeName, bucketName);
        keyStream.write(data);
        keyStream.close();
    }
    // Delete created keys
    for (String key : keys) {
        bucket.deleteKey(key);
    }
    // Verify that KeyDeletingService picks up deleted keys and purges them
    // from DB.
    KeyManager keyManager = om.getKeyManager();
    KeyDeletingService keyDeletingService = (KeyDeletingService) keyManager.getDeletingService();
    GenericTestUtils.waitFor(() -> keyDeletingService.getDeletedKeyCount().get() >= NUM_KEYS, 1000, 10000);
    assertThat(keyDeletingService.getRunCount().get()).isGreaterThan(1);
    GenericTestUtils.waitFor(() -> {
        try {
            return keyManager.getPendingDeletionKeys(Integer.MAX_VALUE).getKeyBlocksList().size() == 0;
        } catch (IOException e) {
            return false;
        }
    }, 1000, 10000);
}

