@Test
public void testBootstrapLocking() throws Exception {
    cluster = MiniOzoneCluster.newBuilder(conf).setNumDatanodes(1).build();
    cluster.waitForClusterToBeReady();
    // Get the bootstrap state handlers
    KeyManager keyManager = cluster.getOzoneManager().getKeyManager();
    BootstrapStateHandler keyDeletingService = keyManager.getDeletingService();
    BootstrapStateHandler snapshotDeletingService = keyManager.getSnapshotDeletingService();
    BootstrapStateHandler sstFilteringService = keyManager.getSnapshotSstFilteringService();
    BootstrapStateHandler differ = cluster.getOzoneManager().getMetadataManager().getStore().getRocksDBCheckpointDiffer();
    ExecutorService executorService = Executors.newCachedThreadPool();
    OMDBCheckpointServlet omDbCheckpointServlet = new OMDBCheckpointServlet();
    OMDBCheckpointServlet spyServlet = spy(omDbCheckpointServlet);
    ServletContext servletContext = mock(ServletContext.class);
    when(servletContext.getAttribute(OzoneConsts.OM_CONTEXT_ATTRIBUTE)).thenReturn(cluster.getOzoneManager());
    doReturn(servletContext).when(spyServlet).getServletContext();
    spyServlet.init();
    // Confirm the other handlers are locked out when the bootstrap
    //  servlet takes the lock.
    try (BootstrapStateHandler.Lock ignoredLock = spyServlet.getBootstrapStateLock().lock()) {
        confirmServletLocksOutOtherHandler(keyDeletingService, executorService);
        confirmServletLocksOutOtherHandler(snapshotDeletingService, executorService);
        confirmServletLocksOutOtherHandler(sstFilteringService, executorService);
        confirmServletLocksOutOtherHandler(differ, executorService);
    }
    // Confirm the servlet is locked out when any of the other
    //  handlers takes the lock.
    confirmOtherHandlerLocksOutServlet(keyDeletingService, spyServlet, executorService);
    confirmOtherHandlerLocksOutServlet(snapshotDeletingService, spyServlet, executorService);
    confirmOtherHandlerLocksOutServlet(sstFilteringService, spyServlet, executorService);
    confirmOtherHandlerLocksOutServlet(differ, spyServlet, executorService);
    // Confirm that servlet takes the lock when none of the other
    //  handlers have it.
    Future<Boolean> servletTest = checkLock(spyServlet, executorService);
    assertTrue(servletTest.get(10000, TimeUnit.MILLISECONDS));
    executorService.shutdownNow();
}

@Test
public void testUniqueTrxnIndexOnOMRestart() throws Exception {
    // When OM is restarted, the transaction index for requests should not
    // start from 0. It should incrementally increase from the last
    // transaction index which was stored in DB before restart.
    String volumeName = "volume" + RandomStringUtils.randomNumeric(5);
    String bucketName = "bucket" + RandomStringUtils.randomNumeric(5);
    String keyName = "key" + RandomStringUtils.randomNumeric(5);
    OzoneManager om = cluster.getOzoneManager();
    ObjectStore objectStore = client.getObjectStore();
    UserGroupInformation ugi = UserGroupInformation.getCurrentUser();
    OzoneManagerProtocolClientSideTranslatorPB omClient = new OzoneManagerProtocolClientSideTranslatorPB(OmTransportFactory.create(conf, ugi, null), RandomStringUtils.randomAscii(5));
    objectStore.createVolume(volumeName);
    // Verify that the last transactionIndex stored in DB after volume
    // creation equals the transaction index corresponding to volume's
    // objectID. Also, the volume transaction index should be 1 as this is
    // the first transaction in this cluster.
    OmVolumeArgs volumeInfo = omClient.getVolumeInfo(volumeName);
    long volumeTrxnIndex = OmUtils.getTxIdFromObjectId(volumeInfo.getObjectID());
    assertEquals(1, volumeTrxnIndex);
    assertEquals(volumeTrxnIndex, om.getLastTrxnIndexForNonRatis());
    OzoneVolume ozoneVolume = objectStore.getVolume(volumeName);
    ozoneVolume.createBucket(bucketName);
    // Verify last transactionIndex is updated after bucket creation
    OmBucketInfo bucketInfo = omClient.getBucketInfo(volumeName, bucketName);
    long bucketTrxnIndex = OmUtils.getTxIdFromObjectId(bucketInfo.getObjectID());
    assertEquals(2, bucketTrxnIndex);
    assertEquals(bucketTrxnIndex, om.getLastTrxnIndexForNonRatis());
    // Restart the OM and create new object
    cluster.restartOzoneManager();
    String data = "random data";
    OzoneOutputStream ozoneOutputStream = ozoneVolume.getBucket(bucketName).createKey(keyName, data.length(), ReplicationType.RATIS, ReplicationFactor.ONE, new HashMap<>());
    ozoneOutputStream.write(data.getBytes(UTF_8), 0, data.length());
    ozoneOutputStream.close();
    // Verify last transactionIndex is updated after key creation and the
    // transaction index after restart is incremented from the last
    // transaction index before restart.
    OmKeyInfo omKeyInfo = omClient.lookupKey(new OmKeyArgs.Builder().setVolumeName(volumeName).setBucketName(bucketName).setKeyName(keyName).build());
    long keyTrxnIndex = OmUtils.getTxIdFromObjectId(omKeyInfo.getObjectID());
    assertEquals(3, keyTrxnIndex);
    // Key commit is a separate transaction. Hence, the last trxn index in DB
    // should be 1 more than KeyTrxnIndex
    assertEquals(4, om.getLastTrxnIndexForNonRatis());
}

@Test
public void testIncreaseTrxnIndexBasedOnExistingDB() throws Exception {
    // Set transactionInfo.getTerm() not -1 to mock the DB migrated from ratis cluster.
    // When OM is first started from the existing ratis DB, the transaction index for
    // requests should not start from 0. It should incrementally increase from the last
    // transaction index which was stored in DB transactionInfoTable before started.
    String volumeName = "volume" + RandomStringUtils.randomNumeric(5);
    String bucketName = "bucket" + RandomStringUtils.randomNumeric(5);
    String keyName = "key" + RandomStringUtils.randomNumeric(5);
    OzoneManager om = cluster.getOzoneManager();
    ObjectStore objectStore = client.getObjectStore();
    objectStore.createVolume(volumeName);
    OzoneVolume ozoneVolume = objectStore.getVolume(volumeName);
    ozoneVolume.createBucket(bucketName);
    Table<String, TransactionInfo> transactionInfoTable = om.getMetadataManager().getTransactionInfoTable();
    long initIndex = transactionInfoTable.get(TRANSACTION_INFO_KEY).getTransactionIndex();
    // Set transactionInfo.getTerm() = 1 to mock the DB migrated from ratis cluster
    transactionInfoTable.put(TRANSACTION_INFO_KEY, TransactionInfo.valueOf(1, initIndex));
    TransactionInfo transactionInfo = transactionInfoTable.get(TRANSACTION_INFO_KEY);
    // Verify transaction term != -1 and index > 1
    assertEquals(1, transactionInfo.getTerm());
    assertTrue(initIndex > 1);
    // Restart the OM and create new object
    cluster.restartOzoneManager();
    String data = "random data";
    OzoneOutputStream ozoneOutputStream = ozoneVolume.getBucket(bucketName).createKey(keyName, data.length());
    ozoneOutputStream.write(data.getBytes(UTF_8), 0, data.length());
    ozoneOutputStream.close();
    // Transaction index after OM restart is incremented by 2 (create and commit op) from the last
    // transaction index before OM restart rather than from 0.
    // So, the transactionIndex should be (initIndex + 2) rather than (0 + 2)
    assertEquals(initIndex + 2, om.getMetadataManager().getTransactionInfoTable().get(TRANSACTION_INFO_KEY).getTransactionIndex());
}

