@Test
public void testStartupSlvLessThanMlv() throws Exception {
    // Add subdirectories under the temporary folder where the version file
    // will be placed.
    String subDir = folder.toAbsolutePath() + "/om/current";
    File omSubdir = Files.createDirectories(Paths.get(subDir)).toFile();
    OzoneConfiguration conf = new OzoneConfiguration();
    conf.set(OMConfigKeys.OZONE_OM_DB_DIRS, folder.toAbsolutePath().toString());
    // Set metadata layout version larger than software layout version.
    int largestSlv = 0;
    for (LayoutFeature f : OMLayoutFeature.values()) {
        largestSlv = Math.max(largestSlv, f.layoutVersion());
    }
    int mlv = largestSlv + 1;
    // Create version file with MLV > SLV, which should fail the cluster build.
    UpgradeTestUtils.createVersionFile(omSubdir, HddsProtos.NodeType.OM, mlv);
    MiniOzoneCluster.Builder clusterBuilder = MiniOzoneCluster.newBuilder(conf);
    OMException omException = assertThrows(OMException.class, clusterBuilder::build);
    String expectedMessage = String.format("Cannot initialize " + "VersionManager. Metadata layout version (%s) > software layout" + " version (%s)", mlv, largestSlv);
    assertEquals(expectedMessage, omException.getMessage());
}

@Test
public void testRestartWithFSOLayout() throws Exception {
    try {
        // 1. build cluster with default bucket layout FSO
        OzoneConfiguration conf = new OzoneConfiguration();
        conf.set(OMConfigKeys.OZONE_DEFAULT_BUCKET_LAYOUT, BucketLayout.FILE_SYSTEM_OPTIMIZED.name());
        startCluster(conf);
        // 2. create bucket with FSO bucket layout and verify
        OzoneBucket bucket1 = TestDataUtil.createVolumeAndBucket(client, BucketLayout.FILE_SYSTEM_OPTIMIZED);
        verifyBucketLayout(bucket1, BucketLayout.FILE_SYSTEM_OPTIMIZED);
        // 3. verify OM default behavior with empty
        restartCluster();
        OzoneBucket bucket2 = TestDataUtil.createVolumeAndBucket(client, null);
        verifyBucketLayout(bucket2, BucketLayout.FILE_SYSTEM_OPTIMIZED);
        // 4. create bucket with OBS bucket layout and verify
        restartCluster();
        OzoneBucket bucket3 = TestDataUtil.createVolumeAndBucket(client, BucketLayout.OBJECT_STORE);
        verifyBucketLayout(bucket3, BucketLayout.OBJECT_STORE);
        // 5. verify all bucket
        restartCluster();
        verifyBucketLayout(bucket1, BucketLayout.FILE_SYSTEM_OPTIMIZED);
        verifyBucketLayout(bucket2, BucketLayout.FILE_SYSTEM_OPTIMIZED);
        verifyBucketLayout(bucket3, BucketLayout.OBJECT_STORE);
        // 6. verify after update default bucket layout
        conf.set(OMConfigKeys.OZONE_DEFAULT_BUCKET_LAYOUT, BucketLayout.OBJECT_STORE.name());
        restartCluster();
        verifyBucketLayout(bucket1, BucketLayout.FILE_SYSTEM_OPTIMIZED);
        verifyBucketLayout(bucket2, BucketLayout.FILE_SYSTEM_OPTIMIZED);
        verifyBucketLayout(bucket3, BucketLayout.OBJECT_STORE);
    } finally {
        teardown();
    }
}

