    assertSame(followerOM.getOmRatisServer().checkLeaderStatus(), OzoneManagerRatisServer.RaftServerStatus.NOT_LEADER);
    OzoneManagerProtocolProtos.OMRequest writeRequest = OzoneManagerProtocolProtos.OMRequest.newBuilder().setCmdType(OzoneManagerProtocolProtos.Type.ListVolume).setVersion(ClientVersion.CURRENT_VERSION).setClientId(randomUUID().toString()).build();
    OzoneManagerProtocolServerSideTranslatorPB omServerProtocol = followerOM.getOmServerProtocol();
    ServiceException ex = assertThrows(ServiceException.class, () -> omServerProtocol.submitRequest(null, writeRequest));
    assertThat(ex).hasCauseInstanceOf(OMNotLeaderException.class).hasMessageEndingWith("Suggested leader is OM:" + leaderOMNodeId + "[" + leaderOMAddress + "].");
}

