@ParameterizedTest
@MethodSource("outOfServiceNodeStateArgs")
@Flaky("HDDS-11128")
void testNodesInDecommissionOrMaintenance(NodeOperationalState initialState, NodeOperationalState finalState, boolean isMaintenance) throws Exception {
    Pipeline pipeline = scmClient.getContainerWithPipeline(containerIdR3).getPipeline();
    List<DatanodeDetails> details = pipeline.getNodes().stream().filter(d -> d.getPersistedOpState().equals(IN_SERVICE)).collect(Collectors.toList());
    final DatanodeDetails nodeToGoOffline1 = details.get(0);
    final DatanodeDetails nodeToGoOffline2 = details.get(1);
    UnHealthyContainerStates underReplicatedState = UnHealthyContainerStates.UNDER_REPLICATED;
    UnHealthyContainerStates overReplicatedState = UnHealthyContainerStates.OVER_REPLICATED;
    // First node goes offline.
    if (isMaintenance) {
        scmClient.startMaintenanceNodes(Collections.singletonList(TestNodeUtil.getDNHostAndPort(nodeToGoOffline1)), 0, true);
    } else {
        scmClient.decommissionNodes(Collections.singletonList(TestNodeUtil.getDNHostAndPort(nodeToGoOffline1)), false);
    }
    TestNodeUtil.waitForDnToReachOpState(scmNodeManager, nodeToGoOffline1, initialState);
    compareRMReportToReconResponse(underReplicatedState);
    compareRMReportToReconResponse(overReplicatedState);
    TestNodeUtil.waitForDnToReachOpState(scmNodeManager, nodeToGoOffline1, finalState);
    // Every time a node goes into decommission,
    // a new replica-copy is made to another node.
    // For maintenance, there is no replica-copy in this case.
    if (!isMaintenance) {
        TestHelper.waitForReplicaCount(containerIdR3, 4, cluster);
    }
    compareRMReportToReconResponse(underReplicatedState);
    compareRMReportToReconResponse(overReplicatedState);
    // Second node goes offline.
    if (isMaintenance) {
        scmClient.startMaintenanceNodes(Collections.singletonList(TestNodeUtil.getDNHostAndPort(nodeToGoOffline2)), 0, true);
    } else {
        scmClient.decommissionNodes(Collections.singletonList(TestNodeUtil.getDNHostAndPort(nodeToGoOffline2)), false);
    }
    TestNodeUtil.waitForDnToReachOpState(scmNodeManager, nodeToGoOffline2, initialState);
    compareRMReportToReconResponse(underReplicatedState);
    compareRMReportToReconResponse(overReplicatedState);
    TestNodeUtil.waitForDnToReachOpState(scmNodeManager, nodeToGoOffline2, finalState);
    // There will be a replica copy for both maintenance and decommission.
    // maintenance 3 -> 4, decommission 4 -> 5.
    int expectedReplicaNum = isMaintenance ? 4 : 5;
    TestHelper.waitForReplicaCount(containerIdR3, expectedReplicaNum, cluster);
    compareRMReportToReconResponse(underReplicatedState);
    compareRMReportToReconResponse(overReplicatedState);
    scmClient.recommissionNodes(Arrays.asList(TestNodeUtil.getDNHostAndPort(nodeToGoOffline1), TestNodeUtil.getDNHostAndPort(nodeToGoOffline2)));
    TestNodeUtil.waitForDnToReachOpState(scmNodeManager, nodeToGoOffline1, IN_SERVICE);
    TestNodeUtil.waitForDnToReachOpState(scmNodeManager, nodeToGoOffline2, IN_SERVICE);
    TestNodeUtil.waitForDnToReachPersistedOpState(nodeToGoOffline1, IN_SERVICE);
    TestNodeUtil.waitForDnToReachPersistedOpState(nodeToGoOffline2, IN_SERVICE);
    compareRMReportToReconResponse(underReplicatedState);
    compareRMReportToReconResponse(overReplicatedState);
}

