@Test
public void testKeyDeleteOrSkipTrashWhenTrashEnableFSO() throws IOException {
    // Create 100 keys
    generateKeys("/volumefso1", "/bucket1", BucketLayout.FILE_SYSTEM_OPTIMIZED.toString());
    // Enable trash
    String trashConfKey = generateSetConfString(OMConfigKeys.OZONE_FS_TRASH_INTERVAL_KEY, "1");
    String[] args = new String[] { trashConfKey, "key", "delete", "/volumefso1/bucket1/key4" };
    // Delete one key from FSO bucket
    execute(ozoneShell, args);
    // Get key list in .Trash path
    String prefixKey = "--prefix=.Trash";
    args = new String[] { "key", "list", prefixKey, "o3://" + omServiceId + "/volumefso1/bucket1/" };
    out.reset();
    execute(ozoneShell, args);
    // One key should be present in .Trash
    assertEquals(1, getNumOfKeys());
    args = new String[] { trashConfKey, "key", "delete", "/volumefso1/bucket1/key5" };
    execute(ozoneShell, args);
    args = new String[] { "key", "list", "o3://" + omServiceId + "/volumefso1/bucket1/", "-l ", "110" };
    out.reset();
    execute(ozoneShell, args);
    // Total number of keys still 100.
    assertEquals(100, getNumOfKeys());
    // .Trash should contain 2 keys
    prefixKey = "--prefix=.Trash";
    args = new String[] { "key", "list", prefixKey, "o3://" + omServiceId + "/volumefso1/bucket1/" };
    out.reset();
    execute(ozoneShell, args);
    assertEquals(2, getNumOfKeys());
    final String username = UserGroupInformation.getCurrentUser().getShortUserName();
    Path trashRoot = new Path(OZONE_URI_DELIMITER, TRASH_PREFIX);
    Path userTrash = new Path(trashRoot, username);
    Path current = new Path("Current");
    Path userTrashCurrent = new Path(userTrash, current);
    // Try to delete from trash path
    args = new String[] { trashConfKey, "key", "delete", "/volumefso1/bucket1/" + userTrashCurrent.toUri().getPath() + "/key4" };
    out.reset();
    execute(ozoneShell, args);
    args = new String[] { "key", "list", "o3://" + omServiceId + "/volumefso1/bucket1/", "-l ", "110" };
    out.reset();
    execute(ozoneShell, args);
    // Total number of keys still remain 100 as
    // delete from trash not allowed using sh command
    assertEquals(100, getNumOfKeys());
}

