    // Check volume creation
    OmVolumeArgs volArgs = cluster.getOzoneManager().getVolumeInfo("finance");
    assertEquals("finance", volArgs.getVolume());
    // Creating the tenant with the same name again should fail
    executeHA(tenantShell, new String[] { "create", "finance" });
    checkOutput(out, "", true);
    checkOutput(err, "Tenant 'finance' already exists\n", true);
    executeHA(tenantShell, new String[] { "create", "research" });
    checkOutput(out, "", true);
    checkOutput(err, "", true);
    executeHA(tenantShell, new String[] { "create", "dev" });
    checkOutput(out, "", true);
    checkOutput(err, "", true);
    executeHA(tenantShell, new String[] { "ls" });
    checkOutput(out, "dev\nfinance\nresearch\n", true);
    checkOutput(err, "", true);
    executeHA(tenantShell, new String[] { "list", "--json" });
    // Not checking the full output here
    checkOutput(out, "\"tenantId\" : \"dev\",", false);
    checkOutput(err, "", true);
    // Attempt user getsecret before assignment, should fail
    executeHA(tenantShell, new String[] { "user", "getsecret", "finance$bob" });
    checkOutput(out, "", false);
    checkOutput(err, "accessId 'finance$bob' doesn't exist\n", true);
    // Assign user accessId
    // Equivalent to `ozone tenant user assign bob --tenant=finance`
    executeHA(tenantShell, new String[] { "--verbose", "user", "assign", "bob", "--tenant=finance" });
    checkOutput(out, "export AWS_ACCESS_KEY_ID='finance$bob'\n" + "export AWS_SECRET_ACCESS_KEY='", false);
    checkOutput(err, "Assigned 'bob' to 'finance' with accessId" + " 'finance$bob'.\n", true);
    // Try user getsecret again after assignment, should succeed
    executeHA(tenantShell, new String[] { "user", "getsecret", "finance$bob" });
    checkOutput(out, "export AWS_ACCESS_KEY_ID='finance$bob'\n", false);
    checkOutput(err, "", true);
    executeHA(tenantShell, new String[] { "--verbose", "user", "assign", "bob", "--tenant=research" });
    checkOutput(out, "export AWS_ACCESS_KEY_ID='research$bob'\n" + "export AWS_SECRET_ACCESS_KEY='", false);
    checkOutput(err, "Assigned 'bob' to 'research' with accessId" + " 'research$bob'.\n", true);
    executeHA(tenantShell, new String[] { "user", "assign", "bob", "--tenant=dev" });
    checkOutput(out, "export AWS_ACCESS_KEY_ID='dev$bob'\n" + "export AWS_SECRET_ACCESS_KEY='", false);
    checkOutput(err, "", true);
    // accessId length exceeding limit, should fail
    executeHA(tenantShell, new String[] { "user", "assign", StringUtils.repeat('a', 100), "--tenant=dev" });
    checkOutput(out, "", true);
    checkOutput(err, "accessId length (104) exceeds the maximum length " + "allowed (100)\n", true);
    // Get user info
    // Equivalent to `ozone tenant user info bob`
    executeHA(tenantShell, new String[] { "user", "info", "bob" });
    checkOutput(out, "User 'bob' is assigned to:\n" + "- Tenant 'research' with accessId 'research$bob'\n" + "- Tenant 'finance' with accessId 'finance$bob'\n" + "- Tenant 'dev' with accessId 'dev$bob'\n", true);
    checkOutput(err, "", true);
    // Assign admin
    executeHA(tenantShell, new String[] { "user", "assign-admin", "dev$bob", "--tenant=dev", "--delegated" });
    checkOutput(out, "", true);
    checkOutput(err, "", true);
    executeHA(tenantShell, new String[] { "user", "info", "bob" });
    checkOutput(out, "Tenant 'dev' delegated admin with accessId", false);
    checkOutput(err, "", true);
    executeHA(tenantShell, new String[] { "user", "info", "--json", "bob" });
    checkOutput(out, "{\n" + "  \"user\" : \"bob\",\n" + "  \"tenants\" : [ {\n" + "    \"accessId\" : \"research$bob\",\n" + "    \"tenantId\" : \"research\",\n" + "    \"isAdmin\" : false,\n" + "    \"isDelegatedAdmin\" : false\n" + "  }, {\n" + "    \"accessId\" : \"finance$bob\",\n" + "    \"tenantId\" : \"finance\",\n" + "    \"isAdmin\" : false,\n" + "    \"isDelegatedAdmin\" : false\n" + "  }, {\n" + "    \"accessId\" : \"dev$bob\",\n" + "    \"tenantId\" : \"dev\",\n" + "    \"isAdmin\" : true,\n" + "    \"isDelegatedAdmin\" : true\n" + "  } ]\n" + "}\n", true, true);
    checkOutput(err, "", true);
    // Revoke admin
    executeHA(tenantShell, new String[] { "user", "revoke-admin", "dev$bob", "--tenant=dev" });
    checkOutput(out, "", true);
    checkOutput(err, "", true);
    executeHA(tenantShell, new String[] { "user", "info", "bob" });
    checkOutput(out, "User 'bob' is assigned to:\n" + "- Tenant 'research' with accessId 'research$bob'\n" + "- Tenant 'finance' with accessId 'finance$bob'\n" + "- Tenant 'dev' with accessId 'dev$bob'\n", true);
    checkOutput(err, "", true);
    // Revoke user accessId
    executeHA(tenantShell, new String[] { "user", "revoke", "research$bob" });
    checkOutput(out, "", true);
    checkOutput(err, "", true);
    executeHA(tenantShell, new String[] { "user", "info", "bob" });
    checkOutput(out, "User 'bob' is assigned to:\n" + "- Tenant 'finance' with accessId 'finance$bob'\n" + "- Tenant 'dev' with accessId 'dev$bob'\n", true);
    checkOutput(err, "", true);
    // Assign user again
    executeHA(tenantShell, new String[] { "user", "assign", "bob", "--tenant=research" });
    checkOutput(out, "export AWS_ACCESS_KEY_ID='research$bob'\n" + "export AWS_SECRET_ACCESS_KEY='", false);
    checkOutput(err, "", true);
    // Attempt to assign the user to the tenant again
    executeHA(tenantShell, new String[] { "user", "assign", "bob", "--tenant=research", "--accessId=research$bob" });
    checkOutput(out, "", false);
    checkOutput(err, "accessId 'research$bob' already exists!\n", true);
    // Attempt to assign the user to the tenant with a custom accessId
    executeHA(tenantShell, new String[] { "user", "assign", "bob", "--tenant=research", "--accessId=research$bob42" });
    checkOutput(out, "", false);
    // HDDS-6366: Disallow specifying custom accessId.
    checkOutput(err, "Invalid accessId 'research$bob42'. " + "Specifying a custom access ID disallowed. " + "Expected accessId to be assigned is 'research$bob'\n", true);
    executeHA(tenantShell, new String[] { "list" });
    checkOutput(out, "dev\nfinance\nresearch\n", true);
    checkOutput(err, "", true);
    // Clean up
    executeHA(tenantShell, new String[] { "user", "revoke", "research$bob" });
    checkOutput(out, "", true);
    checkOutput(err, "", true);
    executeHA(tenantShell, new String[] { "delete", "research" });
    checkOutput(out, "", true);
    checkOutput(err, "Deleted tenant 'research'.\n", false);
    deleteVolume("research");
    executeHA(tenantShell, new String[] { "user", "revoke", "finance$bob" });
    checkOutput(out, "", true);
    checkOutput(err, "", true);
    executeHA(tenantShell, new String[] { "list" });
    checkOutput(out, "dev\nfinance\n", true);
    checkOutput(err, "", true);
    executeHA(tenantShell, new String[] { "delete", "finance" });
    checkOutput(out, "", true);
    checkOutput(err, "Deleted tenant 'finance'.\n", false);
    deleteVolume("finance");
    executeHA(tenantShell, new String[] { "list" });
    checkOutput(out, "dev\n", true);
    checkOutput(err, "", true);
    // Attempt to delete tenant with accessIds still assigned to it, should fail
    int exitCode = executeHA(tenantShell, new String[] { "delete", "dev" });
    assertNotEquals(0, exitCode, "Tenant delete should fail!");
    checkOutput(out, "", true);
    checkOutput(err, "Tenant 'dev' is not empty. All accessIds associated " + "to this tenant must be revoked before the tenant can be deleted. " + "See `ozone tenant user revoke`\n", true);
    // Trigger BG sync on OMs to recover roles and policies deleted
    // by previous tenant delete attempt.
    // Note: Potential source of flakiness if triggered only on leader OM
    // in this case.
    // Because InMemoryMultiTenantAccessController is used in OMs for this
    // integration test, we need to trigger BG sync on all OMs just
    // in case a leader changed right after the last operation.
    cluster.getOzoneManagersList().forEach(om -> om.getMultiTenantManager().getOMRangerBGSyncService().triggerRangerSyncOnce());
    // Delete dev volume should fail because the volume reference count > 0L
    exitCode = execute(ozoneSh, new String[] { "volume", "delete", "dev" });
    assertNotEquals(0, exitCode, "Volume delete should fail!");
    checkOutput(out, "", true);
    checkOutput(err, "Volume reference count is not zero (1). " + "Ozone features are enabled on this volume. " + "Try `ozone tenant delete <tenantId>` first.\n", true);
    executeHA(tenantShell, new String[] { "list" });
    checkOutput(out, "dev\n", true);
    checkOutput(err, "", true);
    // Revoke accessId first
    executeHA(tenantShell, new String[] { "user", "revoke", "dev$bob" });
    checkOutput(out, "", true);
    checkOutput(err, "", true);
    // Then delete tenant, should succeed
    executeHA(tenantShell, new String[] { "--verbose", "delete", "dev" });
    checkOutput(out, "{\n" + "  \"tenantId\" : \"dev\",\n" + "  \"volumeName\" : \"dev\",\n" + "  \"volumeRefCount\" : 0\n" + "}\n", true, true);
    checkOutput(err, "Deleted tenant 'dev'.\n", false);
    deleteVolume("dev");
    // Sanity check: tenant list should be empty
    executeHA(tenantShell, new String[] { "list" });
    checkOutput(out, "", true);
    checkOutput(err, "", true);
}

