    ugiBob.doAs((PrivilegedExceptionAction<Void>) () -> {
        int exitC = executeHA(tenantShell, new String[] { "user", "setsecret", tenantName + "$alice", "--secret=somesecret2" });
        assertNotEquals(0, exitC, "Should return non-zero exit code!");
