@Test
void testSCMSecurityProtocol() throws Exception {
    initSCM();
    scm = HddsTestUtils.getScmSimple(conf);
    //Reads the SCM Info from SCM instance
    try {
        scm.start();
        // Case 1: User with Kerberos credentials should succeed.
        UserGroupInformation ugi = UserGroupInformation.loginUserFromKeytabAndReturnUGI(testUserPrincipal, testUserKeytab.getCanonicalPath());
        ugi.setAuthenticationMethod(KERBEROS);
        try (SCMSecurityProtocolClientSideTranslatorPB securityClient = getScmSecurityClient(conf, ugi)) {
            assertNotNull(securityClient);
            String caCert = securityClient.getCACertificate();
            assertNotNull(caCert);
            // Get some random certificate, used serial id 100 which will be
            // unavailable as our serial id is time stamp. Serial id 1 is root CA,
            // and it is persisted in DB.
            SCMSecurityException securityException = assertThrows(SCMSecurityException.class, () -> securityClient.getCertificate("100"));
            assertThat(securityException).hasMessageContaining("Certificate not found");
        }
        // Case 2: User without Kerberos credentials should fail.
        ugi = UserGroupInformation.createRemoteUser("test");
        ugi.setAuthenticationMethod(AuthMethod.TOKEN);
        try (SCMSecurityProtocolClientSideTranslatorPB securityClient = getScmSecurityClient(conf, ugi)) {
            String cannotAuthMessage = "Client cannot authenticate via:[KERBEROS]";
            IOException ioException = assertThrows(IOException.class, securityClient::getCACertificate);
            assertThat(ioException).hasMessageContaining(cannotAuthMessage);
            ioException = assertThrows(IOException.class, () -> securityClient.getCertificate("1"));
            assertThat(ioException).hasMessageContaining(cannotAuthMessage);
        }
    } finally {
        if (scm != null) {
            scm.stop();
        }
    }
}

