/**
 * Tests delegation token renewal after a certificate renew.
 */
@Test
void testDelegationTokenRenewCrossCertificateRenew() throws Exception {
    initSCM();
    try {
        scm = HddsTestUtils.getScmSimple(conf);
        scm.start();
        // Setup secure OM for start.
        // 40s
        final int certLifetime = 40 * 1000;
        OzoneConfiguration newConf = new OzoneConfiguration(conf);
        newConf.set(HDDS_X509_DEFAULT_DURATION, Duration.ofMillis(certLifetime).toString());
        newConf.set(HDDS_X509_RENEW_GRACE_DURATION, Duration.ofMillis(certLifetime - 15 * 1000).toString());
        newConf.setLong(OMConfigKeys.DELEGATION_TOKEN_MAX_LIFETIME_KEY, certLifetime - 20 * 1000);
        setupOm(newConf);
        OzoneManager.setTestSecureOmFlag(true);
        CertificateClientTestImpl certClient = new CertificateClientTestImpl(newConf, true);
        X509Certificate omCert = certClient.getCertificate();
        String omCertId1 = omCert.getSerialNumber().toString();
        // Start OM
        om.setCertClient(certClient);
        om.setScmTopologyClient(new ScmTopologyClient(scmBlockClient));
        om.start();
        GenericTestUtils.waitFor(() -> om.isLeaderReady(), 100, 10000);
        UserGroupInformation ugi = UserGroupInformation.getCurrentUser();
        // Get first OM client which will authenticate via Kerberos
        omClient = new OzoneManagerProtocolClientSideTranslatorPB(OmTransportFactory.create(newConf, ugi, null), RandomStringUtils.randomAscii(5));
        // Since client is already connected get a delegation token
        Token<OzoneTokenIdentifier> token1 = omClient.getDelegationToken(new Text("om"));
        // Check if token is of right kind and renewer is running om instance
        assertNotNull(token1);
        assertEquals("OzoneToken", token1.getKind().toString());
        assertEquals(SecurityUtil.buildTokenService(om.getNodeDetails().getRpcAddress()).toString(), token1.getService().toString());
        assertEquals(omCertId1, token1.decodeIdentifier().getOmCertSerialId());
        // Renew delegation token
        long expiryTime = omClient.renewDelegationToken(token1);
        assertThat(expiryTime).isGreaterThan(0);
        // Wait for OM certificate to renew
        LambdaTestUtils.await(certLifetime, 100, () -> !StringUtils.equals(token1.decodeIdentifier().getOmCertSerialId(), omClient.getDelegationToken(new Text("om")).decodeIdentifier().getOmCertSerialId()));
        String omCertId2 = certClient.getCertificate().getSerialNumber().toString();
        assertNotEquals(omCertId1, omCertId2);
        // Get a new delegation token
        Token<OzoneTokenIdentifier> token2 = omClient.getDelegationToken(new Text("om"));
        assertEquals(omCertId2, token2.decodeIdentifier().getOmCertSerialId());
        // Because old certificate is still valid, so renew old token will succeed
        expiryTime = omClient.renewDelegationToken(token1);
        assertThat(expiryTime).isGreaterThan(0).isLessThan(omCert.getNotAfter().getTime());
    } finally {
        if (scm != null) {
            scm.stop();
        }
        IOUtils.closeQuietly(om);
    }
}

