@Test
public void testBucketContainsIncompleteMPUs() throws Exception {
    String volumeName = UUID.randomUUID().toString();
    String bucketName = UUID.randomUUID().toString();
    OMRequest omRequest = createDeleteBucketRequest(volumeName, bucketName);
    OMRequestTestUtils.addVolumeAndBucketToDB(volumeName, bucketName, omMetadataManager);
    OMBucketDeleteRequest omBucketDeleteRequest = new OMBucketDeleteRequest(omRequest);
    // Create a MPU key in the MPU table to simulate incomplete MPU
    String uploadId = OMMultipartUploadUtils.getMultipartUploadId();
    final OmKeyInfo keyInfo = OMRequestTestUtils.createOmKeyInfo(volumeName, bucketName, UUID.randomUUID().toString(), RatisReplicationConfig.getInstance(ONE), new OmKeyLocationInfoGroup(0L, new ArrayList<>(), true)).build();
    final OmMultipartKeyInfo multipartKeyInfo = OMRequestTestUtils.createOmMultipartKeyInfo(uploadId, Time.now(), HddsProtos.ReplicationType.RATIS, HddsProtos.ReplicationFactor.ONE, 0L);
    OMRequestTestUtils.addMultipartInfoToTable(false, keyInfo, multipartKeyInfo, 0L, omMetadataManager);
    // Bucket delete request should fail since there are still incomplete MPUs
    OMClientResponse omClientResponse = omBucketDeleteRequest.validateAndUpdateCache(ozoneManager, 1L);
    assertEquals(OzoneManagerProtocolProtos.Status.BUCKET_NOT_EMPTY, omClientResponse.getOMResponse().getStatus());
    assertNotNull(omMetadataManager.getBucketTable().get(omMetadataManager.getBucketKey(volumeName, bucketName)));
    // Remove the MPU keys to simulate MPU aborts / completes
    String multipartKey = omMetadataManager.getMultipartKey(volumeName, bucketName, keyInfo.getKeyName(), uploadId);
    omMetadataManager.getMultipartInfoTable().addCacheEntry(new CacheKey<>(multipartKey), CacheValue.get(2L));
    omMetadataManager.getMultipartInfoTable().delete(multipartKey);
