    // Check modification time
    assertEquals(modifiedOmRequest.getCreateFileRequest().getKeyArgs().getModificationTime(), omKeyInfo.getModificationTime());
    assertEquals(omKeyInfo.getModificationTime(), omKeyInfo.getCreationTime());
    // Check data of the block
    OzoneManagerProtocolProtos.KeyLocation keyLocation = modifiedOmRequest.getCreateFileRequest().getKeyArgs().getKeyLocations(0);
    assertEquals(keyLocation.getBlockID().getContainerBlockID().getContainerID(), omKeyLocationInfo.getContainerID());
