@Test
public void testValidateAndUpdateCache() throws Exception {
    // Add volume, bucket, key entries to DB.
    OMRequestTestUtils.addVolumeAndBucketToDB(volumeName, bucketName, omMetadataManager, getBucketLayout());
    addKeyToOpenKeyTable(volumeName, bucketName);
    OMRequest modifiedOmRequest = doPreExecute(createAllocateBlockRequest());
    OMAllocateBlockRequest omAllocateBlockRequest = getOmAllocateBlockRequest(modifiedOmRequest);
    // Check before calling validateAndUpdateCache. As adding DB entry has
    // not added any blocks, so size should be zero.
    OmKeyInfo omKeyInfo = verifyPathInOpenKeyTable(keyName, clientID, true);
    List<OmKeyLocationInfo> omKeyLocationInfo = omKeyInfo.getLatestVersionLocations().getLocationList();
    assertEquals(0, omKeyLocationInfo.size());
    OMClientResponse omAllocateBlockResponse = omAllocateBlockRequest.validateAndUpdateCache(ozoneManager, 100L);
    assertEquals(OzoneManagerProtocolProtos.Status.OK, omAllocateBlockResponse.getOMResponse().getStatus());
    // Check open table whether new block is added or not.
    omKeyInfo = verifyPathInOpenKeyTable(keyName, clientID, true);
    // Check modification time
    assertEquals(modifiedOmRequest.getAllocateBlockRequest().getKeyArgs().getModificationTime(), omKeyInfo.getModificationTime());
    // creationTime was assigned at OMRequestTestUtils.addKeyToTable
    // modificationTime was assigned at
    // doPreExecute(createAllocateBlockRequest())
    assertThat(omKeyInfo.getCreationTime()).isLessThanOrEqualTo(omKeyInfo.getModificationTime());
    // Check data of the block
    OzoneManagerProtocolProtos.KeyLocation keyLocation = modifiedOmRequest.getAllocateBlockRequest().getKeyLocation();
    omKeyLocationInfo = omKeyInfo.getLatestVersionLocations().getLocationList();
    assertEquals(1, omKeyLocationInfo.size());
    assertEquals(keyLocation.getBlockID().getContainerBlockID().getContainerID(), omKeyLocationInfo.get(0).getContainerID());
    assertEquals(keyLocation.getBlockID().getContainerBlockID().getLocalID(), omKeyLocationInfo.get(0).getLocalID());
}

