@ParameterizedTest
@MethodSource("data")
public void testValidateAndUpdateCache(boolean setKeyPathLock, boolean setFileSystemPaths) throws Exception {
    when(ozoneManager.getOzoneLockProvider()).thenReturn(new OzoneLockProvider(setKeyPathLock, setFileSystemPaths));
    Map<String, String> tags = new HashMap<>();
    tags.put("tag-key1", "tag-value1");
    tags.put("tag-key2", "tag-value2");
    OMRequest modifiedOmRequest = doPreExecute(createKeyRequest(false, 0, emptyMap(), tags));
    OMKeyCreateRequest omKeyCreateRequest = getOMKeyCreateRequest(modifiedOmRequest);
    // Add volume and bucket entries to DB.
    addVolumeAndBucketToDB(volumeName, bucketName, omMetadataManager, getBucketLayout());
    long id = modifiedOmRequest.getCreateKeyRequest().getClientID();
    String openKey = getOpenKey(id);
    // Before calling
    OmKeyInfo omKeyInfo = omMetadataManager.getOpenKeyTable(omKeyCreateRequest.getBucketLayout()).get(openKey);
    assertNull(omKeyInfo);
    OMClientResponse omKeyCreateResponse = omKeyCreateRequest.validateAndUpdateCache(ozoneManager, 100L);
    checkResponse(modifiedOmRequest, omKeyCreateResponse, id, false, omKeyCreateRequest.getBucketLayout());
    // Network returns only latest version.
    assertEquals(1, omKeyCreateResponse.getOMResponse().getCreateKeyResponse().getKeyInfo().getKeyLocationListCount());
    // Disk should have 1 version, as it is fresh key create.
    OmKeyInfo openKeyInfo = omMetadataManager.getOpenKeyTable(omKeyCreateRequest.getBucketLayout()).get(openKey);
    assertEquals(1, openKeyInfo.getKeyLocationVersions().size());
    assertThat(openKeyInfo.getTags()).containsAllEntriesOf(tags);
    // Write to DB like key commit.
    omMetadataManager.getKeyTable(omKeyCreateRequest.getBucketLayout()).put(getOzoneKey(), omMetadataManager.getOpenKeyTable(omKeyCreateRequest.getBucketLayout()).get(openKey));
    tags.remove("tag-key1");
    tags.remove("tag-key2");
    tags.put("tag-key3", "tag-value3");
    // Override same key again
    modifiedOmRequest = doPreExecute(createKeyRequest(false, 0, emptyMap(), tags));
    id = modifiedOmRequest.getCreateKeyRequest().getClientID();
    openKey = getOpenKey(id);
    // Before calling
    omKeyInfo = omMetadataManager.getOpenKeyTable(omKeyCreateRequest.getBucketLayout()).get(openKey);
    assertNull(omKeyInfo);
    omKeyCreateRequest = getOMKeyCreateRequest(modifiedOmRequest);
    omKeyCreateResponse = omKeyCreateRequest.validateAndUpdateCache(ozoneManager, 101L);
    checkResponse(modifiedOmRequest, omKeyCreateResponse, id, true, omKeyCreateRequest.getBucketLayout());
    // Network returns only latest version
    assertEquals(1, omKeyCreateResponse.getOMResponse().getCreateKeyResponse().getKeyInfo().getKeyLocationListCount());
    // Disk should have 1 versions when bucket versioning is off.
    assertEquals(1, omMetadataManager.getOpenKeyTable(omKeyCreateRequest.getBucketLayout()).get(openKey).getKeyLocationVersions().size());
    openKeyInfo = omMetadataManager.getOpenKeyTable(omKeyCreateRequest.getBucketLayout()).get(openKey);
    assertEquals(1, openKeyInfo.getKeyLocationVersions().size());
    assertThat(openKeyInfo.getTags()).containsAllEntriesOf(tags);
    assertThat(openKeyInfo.getTags()).doesNotContainKeys("tag-key1", "tag-key2");
}

