    SnapshotInfo fromSnapshotInfo = new SnapshotInfo.Builder().setVolumeName(volumeName).setBucketName(bucketName).setName("snap1").build();
    ReferenceCounted<OmSnapshot> rcOmSnapshot = ozoneManager.getOmSnapshotManager().getSnapshot(fromSnapshotInfo.getVolumeName(), fromSnapshotInfo.getBucketName(), fromSnapshotInfo.getName());
    OmSnapshot omSnapshot = rcOmSnapshot.get();
    // The keys should be present in the snapshot's deletedTable
    for (String deletedKey : deletedKeyNames) {
        assertTrue(omSnapshot.getMetadataManager().getDeletedTable().isExist(deletedKey));
    }
    // Create PurgeKeysRequest to purge the deleted keys
    OMRequest omRequest = createPurgeKeysRequest(deletedKeyNames, snapInfo.getTableKey());
    OMRequest preExecutedRequest = preExecute(omRequest);
    OMKeyPurgeRequest omKeyPurgeRequest = new OMKeyPurgeRequest(preExecutedRequest);
    omKeyPurgeRequest.validateAndUpdateCache(ozoneManager, 100L);
    OMResponse omResponse = OMResponse.newBuilder().setPurgeKeysResponse(PurgeKeysResponse.getDefaultInstance()).setCmdType(Type.PurgeKeys).setStatus(Status.OK).build();
    try (BatchOperation batchOperation = omMetadataManager.getStore().initBatchOperation()) {
        OMKeyPurgeResponse omKeyPurgeResponse = new OMKeyPurgeResponse(omResponse, deletedKeyNames, fromSnapshotInfo, null);
        omKeyPurgeResponse.addToDBBatch(omMetadataManager, batchOperation);
        // Do manual commit and see whether addToBatch is successful or not.
        omMetadataManager.getStore().commitBatchOperation(batchOperation);
    }
    // The keys should not exist in the DeletedKeys table
    for (String deletedKey : deletedKeyNames) {
        assertFalse(omSnapshot.getMetadataManager().getDeletedTable().isExist(deletedKey));
    }
    omSnapshot = null;
    rcOmSnapshot.close();
}

