/**
 * Tests removing keys from the open key table cache that have higher
 * updateID than the transactionID. Those keys should be ignored.
 * It is OK if updateID equals to or less than transactionID.
 * See {@link WithObjectID#setUpdateID(long, boolean)}.
 *
 * @throws Exception
 */
@ParameterizedTest
@MethodSource("bucketLayouts")
public void testDeleteKeyWithHigherUpdateID(BucketLayout buckLayout) throws Exception {
    this.bucketLayout = buckLayout;
    final String volume = UUID.randomUUID().toString();
    final String bucket = UUID.randomUUID().toString();
    OMRequestTestUtils.addVolumeAndBucketToDB(volume, bucket, omMetadataManager, getBucketLayout());
    final long updateId = 200L;
    final long transactionId = 100L;
    OmKeyInfo.Builder builder = new OmKeyInfo.Builder().setVolumeName(volume).setBucketName(bucket).setUpdateID(updateId).setReplicationConfig(ReplicationConfig.fromTypeAndFactor(ReplicationType.RATIS, ReplicationFactor.THREE));
    if (getBucketLayout().isFileSystemOptimized()) {
        builder.setParentObjectID(random.nextLong());
    }
    List<Pair<Long, OmKeyInfo>> keysWithHigherUpdateID = new ArrayList<>(1);
    keysWithHigherUpdateID.add(Pair.of(clientID, builder.setKeyName("key").setFileName("key").setUpdateID(updateId).build()));
    List<Pair<Long, OmKeyInfo>> keysWithSameUpdateID = new ArrayList<>(1);
    keysWithSameUpdateID.add(Pair.of(clientID, builder.setKeyName("key2").setFileName("key2").setUpdateID(transactionId).build()));
    List<Pair<Long, OmKeyInfo>> allKeys = new ArrayList<>(2);
    allKeys.addAll(keysWithHigherUpdateID);
    allKeys.addAll(keysWithSameUpdateID);
    addToOpenKeyTableDB(allKeys);
    OMRequest omRequest = doPreExecute(createDeleteOpenKeyRequest(allKeys));
    OMOpenKeysDeleteRequest openKeyDeleteRequest = new OMOpenKeysDeleteRequest(omRequest, getBucketLayout());
    OMClientResponse omClientResponse = openKeyDeleteRequest.validateAndUpdateCache(ozoneManager, transactionId);
    assertEquals(Status.OK, omClientResponse.getOMResponse().getStatus());
    assertInOpenKeyTable(keysWithHigherUpdateID);
    assertNotInOpenKeyTable(keysWithSameUpdateID);
}

/**
 * Tests metrics set by {@link OMOpenKeysDeleteRequest}.
 * Submits a set of keys for deletion where only some of the keys actually
 * exist in the open key table, and asserts that the metrics count keys
 * that were submitted for deletion versus those that were actually deleted.
 * @throws Exception
 */
@ParameterizedTest
@MethodSource("bucketLayouts")
public void testMetrics(BucketLayout buckLayout) throws Exception {
    this.bucketLayout = buckLayout;
    final String volume = UUID.randomUUID().toString();
    final String bucket = UUID.randomUUID().toString();
    final String key = UUID.randomUUID().toString();
    final int numExistentKeys = 3;
    final int numNonExistentKeys = 5;
    OMRequestTestUtils.addVolumeAndBucketToDB(volume, bucket, omMetadataManager, getBucketLayout());
    OMMetrics metrics = ozoneManager.getMetrics();
    assertEquals(metrics.getNumOpenKeyDeleteRequests(), 0);
    assertEquals(metrics.getNumOpenKeyDeleteRequestFails(), 0);
    assertEquals(metrics.getNumOpenKeysSubmittedForDeletion(), 0);
    assertEquals(metrics.getNumOpenKeysDeleted(), 0);
    List<Pair<Long, OmKeyInfo>> existentKeys = makeOpenKeys(volume, bucket, key, numExistentKeys);
    List<Pair<Long, OmKeyInfo>> nonExistentKeys = makeOpenKeys(volume, bucket, key, numNonExistentKeys);
    addToOpenKeyTableDB(existentKeys);
    deleteOpenKeysFromCache(existentKeys, nonExistentKeys);
    assertNotInOpenKeyTable(existentKeys);
    assertNotInOpenKeyTable(nonExistentKeys);
    assertEquals(1, metrics.getNumOpenKeyDeleteRequests());
    assertEquals(0, metrics.getNumOpenKeyDeleteRequestFails());
    assertEquals(numExistentKeys + numNonExistentKeys, metrics.getNumOpenKeysSubmittedForDeletion());
    assertEquals(numExistentKeys, metrics.getNumOpenKeysDeleted());
}

@Test
public void testAddAclRequest() throws Exception {
    PrefixManagerImpl prefixManager = new PrefixManagerImpl(ozoneManager, ozoneManager.getMetadataManager(), true);
    when(ozoneManager.getPrefixManager()).thenReturn(prefixManager);
    String prefixName = UUID.randomUUID() + OZONE_URI_DELIMITER;
    OzoneObj prefixObj = createPrefixObj(prefixName);
    // Manually add volume, bucket and key to DB
    OMRequestTestUtils.addVolumeAndBucketToDB(volumeName, bucketName, omMetadataManager);
    OMRequestTestUtils.addPrefixToTable(volumeName, bucketName, prefixName, 1L, omMetadataManager);
    OzoneAcl acl = OzoneAcl.parseAcl("user:bilbo:rwdlncxy[ACCESS]");
    // Create KeyAddAcl request
    OMRequest originalRequest = createAddAclPrefixRequest(prefixName, acl);
    OMPrefixAddAclRequest omPrefixAddAclRequest = new OMPrefixAddAclRequest(originalRequest);
    omPrefixAddAclRequest.preExecute(ozoneManager);
    // Execute original request
    OMClientResponse omClientResponse = omPrefixAddAclRequest.validateAndUpdateCache(ozoneManager, 2);
    assertEquals(OzoneManagerProtocolProtos.Status.OK, omClientResponse.getOMResponse().getStatus());
    // Check that it exists in Prefix tree (PrefixManagerImpl)
    OmPrefixInfo prefixInfo = prefixManager.getPrefixInfo(prefixObj);
    assertEquals(prefixObj.getPath(), prefixInfo.getName());
    assertEquals(2L, prefixInfo.getUpdateID());
    List<OzoneAcl> ozoneAcls = prefixManager.getAcl(prefixObj);
    assertEquals(1, ozoneAcls.size());
    assertEquals(acl, ozoneAcls.get(0));
    // Check that it exists in Prefix table (cache)
    OmPrefixInfo prefixInfoFromTable = omMetadataManager.getPrefixTable().get(prefixObj.getPath());
    assertEquals(prefixObj.getPath(), prefixInfoFromTable.getName());
    assertEquals(2L, prefixInfoFromTable.getUpdateID());
    // Adding ACL that already exists
    OMClientResponse omClientResponse1 = omPrefixAddAclRequest.validateAndUpdateCache(ozoneManager, 3);
    // Check that it exists in Prefix tree (PrefixManagerImpl)
    prefixInfo = prefixManager.getPrefixInfo(prefixObj);
    assertEquals(prefixObj.getPath(), prefixInfo.getName());
    assertEquals(3L, prefixInfo.getUpdateID());
    ozoneAcls = prefixManager.getAcl(prefixObj);
    assertEquals(1, ozoneAcls.size());
    assertEquals(acl, ozoneAcls.get(0));
    // Check that it exists in Prefix table (cache)
    prefixInfoFromTable = omMetadataManager.getPrefixTable().get(prefixObj.getPath());
    assertEquals(prefixObj.getPath(), prefixInfoFromTable.getName());
    assertEquals(3L, prefixInfoFromTable.getUpdateID());
    assertEquals(OzoneManagerProtocolProtos.Status.OK, omClientResponse1.getOMResponse().getStatus());
}

