@Test
public void testValidateAndUpdateCacheSuccess() throws Exception {
    String volumeName = UUID.randomUUID().toString();
    String bucketName = UUID.randomUUID().toString();
    String keyName = getKeyName();
    OMRequestTestUtils.addVolumeAndBucketToDB(volumeName, bucketName, omMetadataManager, getBucketLayout());
    Map<String, String> customMetadata = new HashMap<>();
    customMetadata.put("custom-key1", "custom-value1");
    customMetadata.put("custom-key2", "custom-value2");
    Map<String, String> tags = new HashMap<>();
    tags.put("tag-key1", "tag-value1");
    tags.put("tag-key2", "tag-value2");
    String uploadId = checkValidateAndUpdateCacheSuccess(volumeName, bucketName, keyName, customMetadata, tags);
    checkDeleteTableCount(volumeName, bucketName, keyName, 0, uploadId);
    customMetadata.remove("custom-key1");
    customMetadata.remove("custom-key2");
    customMetadata.put("custom-key3", "custom-value3");
    tags.remove("tag-key1");
    tags.remove("tag-key2");
    tags.put("tag-key3", "tag-value3");
    // Do it twice to test overwrite
    uploadId = checkValidateAndUpdateCacheSuccess(volumeName, bucketName, keyName, customMetadata, tags);
    // After overwrite, one entry must be in delete table
    checkDeleteTableCount(volumeName, bucketName, keyName, 1, uploadId);
}

@Test
public void testInvalidPartOrderError() throws Exception {
    String volumeName = UUID.randomUUID().toString();
    String bucketName = UUID.randomUUID().toString();
    String keyName = getKeyName();
    OMRequestTestUtils.addVolumeAndBucketToDB(volumeName, bucketName, omMetadataManager, getBucketLayout());
    OMRequest initiateMPURequest = doPreExecuteInitiateMPU(volumeName, bucketName, keyName);
    S3InitiateMultipartUploadRequest s3InitiateMultipartUploadRequest = getS3InitiateMultipartUploadReq(initiateMPURequest);
    OMClientResponse omClientResponse = s3InitiateMultipartUploadRequest.validateAndUpdateCache(ozoneManager, 1L);
    long clientID = Time.now();
    String multipartUploadID = omClientResponse.getOMResponse().getInitiateMultiPartUploadResponse().getMultipartUploadID();
    OMRequest commitMultipartRequest = doPreExecuteCommitMPU(volumeName, bucketName, keyName, clientID, multipartUploadID, 1);
    S3MultipartUploadCommitPartRequest s3MultipartUploadCommitPartRequest = getS3MultipartUploadCommitReq(commitMultipartRequest);
    // Add key to open key table.
    addKeyToTable(volumeName, bucketName, keyName, clientID);
    s3MultipartUploadCommitPartRequest.validateAndUpdateCache(ozoneManager, 2L);
    List<Part> partList = new ArrayList<>();
    String partName = getPartName(volumeName, bucketName, keyName, multipartUploadID, 23);
    partList.add(Part.newBuilder().setETag(partName).setPartName(partName).setPartNumber(23).build());
    partName = getPartName(volumeName, bucketName, keyName, multipartUploadID, 1);
    partList.add(Part.newBuilder().setETag(partName).setPartName(partName).setPartNumber(1).build());
    OMRequest completeMultipartRequest = doPreExecuteCompleteMPU(volumeName, bucketName, keyName, multipartUploadID, partList);
    S3MultipartUploadCompleteRequest s3MultipartUploadCompleteRequest = getS3MultipartUploadCompleteReq(completeMultipartRequest);
    omClientResponse = s3MultipartUploadCompleteRequest.validateAndUpdateCache(ozoneManager, 3L);
    assertEquals(OzoneManagerProtocolProtos.Status.INVALID_PART_ORDER, omClientResponse.getOMResponse().getStatus());
}

