@Test
public void testGetOwnSecretTwice() throws IOException {
    // This effectively makes alice an S3 Admin.
    when(ozoneManager.isS3Admin(ugiAlice)).thenReturn(true);
    String userPrincipalId = USER_ALICE;
    S3GetSecretRequest s3GetSecretRequest = new S3GetSecretRequest(new S3GetSecretRequest(s3GetSecretRequest(userPrincipalId)).preExecute(ozoneManager));
    // Run validateAndUpdateCache for the first time
    OMClientResponse omClientResponse1 = s3GetSecretRequest.validateAndUpdateCache(ozoneManager, 1);
    // Check response type and cast
    assertInstanceOf(S3GetSecretResponse.class, omClientResponse1);
    final S3GetSecretResponse s3GetSecretResponse1 = (S3GetSecretResponse) omClientResponse1;
    // Secret is returned the first time
    final S3SecretValue s3SecretValue1 = s3GetSecretResponse1.getS3SecretValue();
    assertEquals(userPrincipalId, s3SecretValue1.getKerberosID());
    final String awsSecret1 = s3SecretValue1.getAwsSecret();
    assertNotNull(awsSecret1);
    final GetS3SecretResponse getS3SecretResponse1 = s3GetSecretResponse1.getOMResponse().getGetS3SecretResponse();
    // The secret inside should be the same.
    final S3Secret s3Secret2 = getS3SecretResponse1.getS3Secret();
    assertEquals(userPrincipalId, s3Secret2.getKerberosID());
    // Run validateAndUpdateCache for the second time
    OMClientResponse omClientResponse2 = s3GetSecretRequest.validateAndUpdateCache(ozoneManager, 2);
    // Check response type and cast
    assertInstanceOf(S3GetSecretResponse.class, omClientResponse2);
    final S3GetSecretResponse s3GetSecretResponse2 = (S3GetSecretResponse) omClientResponse2;
    // no secret is returned as it is the second time
    assertNull(s3GetSecretResponse2.getS3SecretValue());
}

@Test
public void testGetSecretWithTenant() throws IOException {
    // This effectively makes alice an S3 admin.
    when(ozoneManager.isS3Admin(ugiAlice)).thenReturn(true);
    // Make alice a non-delegated admin
    when(omMultiTenantManager.isTenantAdmin(ugiAlice, TENANT_ID, false)).thenReturn(true);
    // Init LayoutVersionManager to prevent NPE in checkLayoutFeature
    final OMLayoutVersionManager lvm = new OMLayoutVersionManager(OMLayoutVersionManager.maxLayoutVersion());
    when(ozoneManager.getVersionManager()).thenReturn(lvm);
    // 1. CreateTenantRequest: Create tenant "finance".
    long txLogIndex = 1;
    // Run preExecute
    OMTenantCreateRequest omTenantCreateRequest = new OMTenantCreateRequest(new OMTenantCreateRequest(createTenantRequest(TENANT_ID)).preExecute(ozoneManager));
    // Run validateAndUpdateCache
    OMClientResponse omClientResponse = omTenantCreateRequest.validateAndUpdateCache(ozoneManager, txLogIndex);
    // Check response type and cast
    assertInstanceOf(OMTenantCreateResponse.class, omClientResponse);
    final OMTenantCreateResponse omTenantCreateResponse = (OMTenantCreateResponse) omClientResponse;
    // Check response
    assertTrue(omTenantCreateResponse.getOMResponse().getSuccess());
    assertEquals(TENANT_ID, omTenantCreateResponse.getOmDBTenantState().getTenantId());
    // 2. AssignUserToTenantRequest: Assign "bob@EXAMPLE.COM" to "finance".
    ++txLogIndex;
    // Additional mock setup needed to pass accessId check
    when(ozoneManager.getMultiTenantManager()).thenReturn(omMultiTenantManager);
    // Run preExecute
    OMTenantAssignUserAccessIdRequest omTenantAssignUserAccessIdRequest = new OMTenantAssignUserAccessIdRequest(new OMTenantAssignUserAccessIdRequest(assignUserToTenantRequest(TENANT_ID, USER_BOB_SHORT, ACCESS_ID_BOB)).preExecute(ozoneManager));
    when(omMultiTenantManager.getTenantVolumeName(TENANT_ID)).thenReturn(TENANT_ID);
    // Run validateAndUpdateCache
    omClientResponse = omTenantAssignUserAccessIdRequest.validateAndUpdateCache(ozoneManager, txLogIndex);
    // Check response type and cast
    assertInstanceOf(OMTenantAssignUserAccessIdResponse.class, omClientResponse);
    final OMTenantAssignUserAccessIdResponse omTenantAssignUserAccessIdResponse = (OMTenantAssignUserAccessIdResponse) omClientResponse;
    // Check response - successful as secret is created for the first time
    assertTrue(omTenantAssignUserAccessIdResponse.getOMResponse().getSuccess());
    assertTrue(omTenantAssignUserAccessIdResponse.getOMResponse().hasTenantAssignUserAccessIdResponse());
    final OmDBAccessIdInfo omDBAccessIdInfo = omTenantAssignUserAccessIdResponse.getOmDBAccessIdInfo();
    assertNotNull(omDBAccessIdInfo);
    final S3SecretValue originalS3Secret = omTenantAssignUserAccessIdResponse.getS3Secret();
    assertNotNull(originalS3Secret);
    // 3. S3GetSecretRequest: Get secret of "bob@EXAMPLE.COM" (as an admin).
    ++txLogIndex;
    // Run preExecute
    S3GetSecretRequest s3GetSecretRequest = new S3GetSecretRequest(new S3GetSecretRequest(s3GetSecretRequest(ACCESS_ID_BOB)).preExecute(ozoneManager));
    // Run validateAndUpdateCache
    omClientResponse = s3GetSecretRequest.validateAndUpdateCache(ozoneManager, txLogIndex);
    // Check response type and cast
    assertInstanceOf(S3GetSecretResponse.class, omClientResponse);
    final S3GetSecretResponse s3GetSecretResponse = (S3GetSecretResponse) omClientResponse;
    // Check response
    assertTrue(s3GetSecretResponse.getOMResponse().getSuccess());
    /*
       getS3SecretValue() should be null in this case because
       the entry is already inserted to DB in the previous request.
       The entry will get overwritten if it isn't null.
