@ParameterizedTest
@ValueSource(ints = { 0, 1, 2, 3, 4 })
public void testSnapshotChainCleanup(int index) throws Exception {
    List<String> snapshots = createSnapshots(5);
    String snapShotToPurge = snapshots.get(index);
    // Before purge, check snapshot chain
    OmMetadataManagerImpl metadataManager = (OmMetadataManagerImpl) omMetadataManager;
    SnapshotChainManager chainManager = metadataManager.getSnapshotChainManager();
    SnapshotInfo snapInfo = metadataManager.getSnapshotInfoTable().get(snapShotToPurge);
    // Get previous and next snapshotInfos to verify if the SnapInfo
    // is changed.
    // Get previous and next snapshotInfos to verify if the SnapInfo
    // is changed.
    UUID prevPathSnapId = null;
    UUID prevGlobalSnapId = null;
    UUID nextPathSnapId = null;
    UUID nextGlobalSnapId = null;
    if (chainManager.hasPreviousPathSnapshot(snapInfo.getSnapshotPath(), snapInfo.getSnapshotId())) {
        prevPathSnapId = chainManager.previousPathSnapshot(snapInfo.getSnapshotPath(), snapInfo.getSnapshotId());
    }
    if (chainManager.hasPreviousGlobalSnapshot(snapInfo.getSnapshotId())) {
        prevGlobalSnapId = chainManager.previousGlobalSnapshot(snapInfo.getSnapshotId());
    }
    if (chainManager.hasNextPathSnapshot(snapInfo.getSnapshotPath(), snapInfo.getSnapshotId())) {
        nextPathSnapId = chainManager.nextPathSnapshot(snapInfo.getSnapshotPath(), snapInfo.getSnapshotId());
    }
    if (chainManager.hasNextGlobalSnapshot(snapInfo.getSnapshotId())) {
        nextGlobalSnapId = chainManager.nextGlobalSnapshot(snapInfo.getSnapshotId());
    }
    long rowsInTableBeforePurge = omMetadataManager.countRowsInTable(omMetadataManager.getSnapshotInfoTable());
    // Purge Snapshot of the given index.
    List<String> toPurgeList = Collections.singletonList(snapShotToPurge);
    OMRequest snapshotPurgeRequest = createPurgeKeysRequest(toPurgeList);
    purgeSnapshots(snapshotPurgeRequest);
    // After purge, check snapshot chain.
    if (nextPathSnapId != null) {
        SnapshotInfo nextPathSnapshotInfoAfterPurge = metadataManager.getSnapshotInfoTable().get(chainManager.getTableKey(nextPathSnapId));
        assertEquals(nextPathSnapshotInfoAfterPurge.getGlobalPreviousSnapshotId(), prevPathSnapId);
    }
    if (nextGlobalSnapId != null) {
        SnapshotInfo nextGlobalSnapshotInfoAfterPurge = metadataManager.getSnapshotInfoTable().get(chainManager.getTableKey(nextGlobalSnapId));
        assertEquals(nextGlobalSnapshotInfoAfterPurge.getGlobalPreviousSnapshotId(), prevGlobalSnapId);
    }
    assertNotEquals(rowsInTableBeforePurge, omMetadataManager.countRowsInTable(omMetadataManager.getSnapshotInfoTable()));
}

@ParameterizedTest(name = "{0}")
@MethodSource("snapshotPurgeCases")
public void testSnapshotChainInSnapshotInfoTableAfterSnapshotPurge(String description, int numberOfBuckets, int numberOfKeysPerBucket, int fromIndex, int toIndex, boolean createInBucketOrder) throws Exception {
    SnapshotChainManager chainManager = ((OmMetadataManagerImpl) omMetadataManager).getSnapshotChainManager();
    int totalKeys = numberOfBuckets * numberOfKeysPerBucket;
    List<String> buckets = new ArrayList<>();
    for (int i = 0; i < numberOfBuckets; i++) {
        String bucketNameLocal = "bucket-" + UUID.randomUUID();
        OMRequestTestUtils.addVolumeAndBucketToDB(volumeName, bucketNameLocal, omMetadataManager);
        buckets.add(bucketNameLocal);
    }
    List<SnapshotInfo> snapshotInfoList = new ArrayList<>();
    for (int i = 0; i < numberOfBuckets; i++) {
        for (int j = 0; j < numberOfKeysPerBucket; j++) {
            int bucketIndex = createInBucketOrder ? i : j;
            String bucket = buckets.get(bucketIndex % numberOfBuckets);
            String snapshotName = UUID.randomUUID().toString();
            createSnapshotCheckpoint(volumeName, bucket, snapshotName);
            String snapshotTableKey = SnapshotInfo.getTableKey(volumeName, bucket, snapshotName);
            SnapshotInfo snapshotInfo = omMetadataManager.getSnapshotInfoTable().get(snapshotTableKey);
            snapshotInfoList.add(snapshotInfo);
        }
    }
    long numberOfSnapshotBeforePurge = omMetadataManager.countRowsInTable(omMetadataManager.getSnapshotInfoTable());
    assertEquals(totalKeys, numberOfSnapshotBeforePurge);
    assertEquals(totalKeys, chainManager.getGlobalSnapshotChain().size());
    validateSnapshotOrderInSnapshotInfoTableAndSnapshotChain(snapshotInfoList);
    List<String> purgeSnapshotKeys = new ArrayList<>();
    for (int i = fromIndex; i <= toIndex; i++) {
        SnapshotInfo purgeSnapshotInfo = snapshotInfoList.get(i);
        String purgeSnapshotKey = SnapshotInfo.getTableKey(volumeName, purgeSnapshotInfo.getBucketName(), purgeSnapshotInfo.getName());
        purgeSnapshotKeys.add(purgeSnapshotKey);
    }
    OMRequest snapshotPurgeRequest = createPurgeKeysRequest(purgeSnapshotKeys);
    purgeSnapshots(snapshotPurgeRequest);
    List<SnapshotInfo> snapshotInfoListAfterPurge = new ArrayList<>();
    for (int i = 0; i < totalKeys; i++) {
        if (i < fromIndex || i > toIndex) {
            SnapshotInfo info = snapshotInfoList.get(i);
            String snapshotKey = SnapshotInfo.getTableKey(volumeName, info.getBucketName(), info.getName());
            snapshotInfoListAfterPurge.add(omMetadataManager.getSnapshotInfoTable().get(snapshotKey));
        }
    }
    long expectNumberOfSnapshotAfterPurge = totalKeys - (toIndex - fromIndex + 1);
    long actualNumberOfSnapshotAfterPurge = omMetadataManager.countRowsInTable(omMetadataManager.getSnapshotInfoTable());
    assertEquals(expectNumberOfSnapshotAfterPurge, actualNumberOfSnapshotAfterPurge);
    assertEquals(expectNumberOfSnapshotAfterPurge, chainManager.getGlobalSnapshotChain().size());
    validateSnapshotOrderInSnapshotInfoTableAndSnapshotChain(snapshotInfoListAfterPurge);
}

