@Test
public void testValidateAndUpdateCache() throws IOException {
    long initialSnapshotSetPropertyCount = omMetrics.getNumSnapshotSetProperties();
    long initialSnapshotSetPropertyFailCount = omMetrics.getNumSnapshotSetPropertyFails();
    createSnapshotDataForTest();
    assertFalse(omMetadataManager.getSnapshotInfoTable().isEmpty());
    List<OMRequest> snapshotUpdateSizeRequests = createSnapshotUpdateSizeRequest();
    // Pre-Execute
    for (OMRequest request : snapshotUpdateSizeRequests) {
        OMSnapshotSetPropertyRequest omSnapshotSetPropertyRequest = new OMSnapshotSetPropertyRequest(request);
        OMRequest modifiedOmRequest = omSnapshotSetPropertyRequest.preExecute(ozoneManager);
        omSnapshotSetPropertyRequest = new OMSnapshotSetPropertyRequest(modifiedOmRequest);
        // Validate and Update Cache
        OMSnapshotSetPropertyResponse omSnapshotSetPropertyResponse = (OMSnapshotSetPropertyResponse) omSnapshotSetPropertyRequest.validateAndUpdateCache(ozoneManager, 200L);
        // Commit to DB.
        batchOperation = omMetadataManager.getStore().initBatchOperation();
        omSnapshotSetPropertyResponse.checkAndUpdateDB(omMetadataManager, batchOperation);
        omMetadataManager.getStore().commitBatchOperation(batchOperation);
    }
    assertEquals(initialSnapshotSetPropertyCount + snapshotUpdateSizeRequests.size(), omMetrics.getNumSnapshotSetProperties());
    assertEquals(initialSnapshotSetPropertyFailCount, omMetrics.getNumSnapshotSetPropertyFails());
    // Check if the exclusive size is set.
    try (TableIterator<String, ? extends Table.KeyValue<String, SnapshotInfo>> iterator = omMetadataManager.getSnapshotInfoTable().iterator()) {
        while (iterator.hasNext()) {
            Table.KeyValue<String, SnapshotInfo> snapshotEntry = iterator.next();
            assertCacheValues(snapshotEntry.getKey());
            assertEquals(exclusiveSize, snapshotEntry.getValue().getExclusiveSize());
            assertEquals(exclusiveSizeAfterRepl, snapshotEntry.getValue().getExclusiveReplicatedSize());
        }
    }
}

