    OmKeyInfo fromKeyInfo = getOmKeyInfo(toKeyInfo, keyName);
    String dbFromKey = addKeyToTable(fromKeyInfo);
    String dbToKey = getDBKeyName(toKeyInfo);
    OMKeyRenameResponse omKeyRenameResponse = getOMKeyRenameResponse(omResponse, fromKeyInfo, toKeyInfo);
    assertTrue(omMetadataManager.getKeyTable(getBucketLayout()).isExist(dbFromKey));
    assertFalse(omMetadataManager.getKeyTable(getBucketLayout()).isExist(dbToKey));
    assertTrue(omMetadataManager.getSnapshotRenamedTable().isEmpty());
    if (getBucketLayout() == BucketLayout.FILE_SYSTEM_OPTIMIZED) {
        assertFalse(omMetadataManager.getDirectoryTable().isExist(getDBKeyName(fromKeyParent)));
        assertFalse(omMetadataManager.getDirectoryTable().isExist(getDBKeyName(toKeyParent)));
        assertFalse(omMetadataManager.getBucketTable().iterator().hasNext());
    }
    omKeyRenameResponse.addToDBBatch(omMetadataManager, batchOperation);
    // Do manual commit and see whether addToBatch is successful or not.
    omMetadataManager.getStore().commitBatchOperation(batchOperation);
    assertFalse(omMetadataManager.getKeyTable(getBucketLayout()).isExist(dbFromKey));
    assertTrue(omMetadataManager.getKeyTable(getBucketLayout()).isExist(dbToKey));
    String renameDbKey = omMetadataManager.getRenameKey(fromKeyInfo.getVolumeName(), fromKeyInfo.getBucketName(), fromKeyInfo.getObjectID());
    // snapshotRenamedTable shouldn't contain those keys which
    // is not part of snapshot bucket.
    assertFalse(omMetadataManager.getSnapshotRenamedTable().isExist(renameDbKey));
    if (getBucketLayout() == BucketLayout.FILE_SYSTEM_OPTIMIZED) {
        assertTrue(omMetadataManager.getDirectoryTable().isExist(getDBKeyName(fromKeyParent)));
        assertTrue(omMetadataManager.getDirectoryTable().isExist(getDBKeyName(toKeyParent)));
        Table.KeyValue<String, OmBucketInfo> keyValue = omMetadataManager.getBucketTable().iterator().next();
        assertEquals(omMetadataManager.getBucketKey(bucketInfo.getVolumeName(), bucketInfo.getBucketName()), keyValue.getKey());
    }
}

