        for (OmMultipartAbortInfo abortInfo : abortInfos) {
            // All the associated parts of the MPU should have been moved from
            // the multipartInfoTable to the deleted table.
            assertFalse(omMetadataManager.getMultipartInfoTable().isExist(abortInfo.getMultipartKey()));
            assertFalse(omMetadataManager.getOpenKeyTable(getBucketLayout()).isExist(abortInfo.getMultipartOpenKey()));
            for (PartKeyInfo partKeyInfo : abortInfo.getOmMultipartKeyInfo().getPartKeyInfoMap()) {
                OmKeyInfo currentPartKeyInfo = OmKeyInfo.getFromProtobuf(partKeyInfo.getPartKeyInfo());
                String deleteKey = omMetadataManager.getOzoneDeletePathKey(currentPartKeyInfo.getObjectID(), abortInfo.getMultipartKey());
                assertTrue(omMetadataManager.getDeletedTable().isExist(deleteKey));
            }
        }
    }
    for (List<OmMultipartAbortInfo> abortInfos : mpusToKeep.values()) {
        for (OmMultipartAbortInfo abortInfo : abortInfos) {
            // These MPUs should not have been removed from the multipartInfoTable
            // and its parts should not be in the deletedTable.
            assertTrue(omMetadataManager.getMultipartInfoTable().isExist(abortInfo.getMultipartKey()));
            assertTrue(omMetadataManager.getOpenKeyTable(getBucketLayout()).isExist(abortInfo.getMultipartOpenKey()));
            for (PartKeyInfo partKeyInfo : abortInfo.getOmMultipartKeyInfo().getPartKeyInfoMap()) {
                OmKeyInfo currentPartKeyInfo = OmKeyInfo.getFromProtobuf(partKeyInfo.getPartKeyInfo());
                String deleteKey = omMetadataManager.getOzoneDeletePathKey(currentPartKeyInfo.getObjectID(), abortInfo.getMultipartKey());
                assertFalse(omMetadataManager.getDeletedTable().isExist(deleteKey));
            }
        }
    }
}

