@Test
public void testDeleteDirectoryCrossingSizeLimit() throws Exception {
    OzoneConfiguration conf = createConfAndInitValues();
    OmTestManagers omTestManagers = new OmTestManagers(conf);
    KeyManager keyManager = omTestManagers.getKeyManager();
    writeClient = omTestManagers.getWriteClient();
    om = omTestManagers.getOzoneManager();
    OMRequestTestUtils.addVolumeAndBucketToDB(volumeName, bucketName, om.getMetadataManager(), BucketLayout.FILE_SYSTEM_OPTIMIZED);
    String bucketKey = om.getMetadataManager().getBucketKey(volumeName, bucketName);
    OmBucketInfo bucketInfo = om.getMetadataManager().getBucketTable().get(bucketKey);
    // create parent directory and 2000 files in it crossing
    // size of 4MB as defined for the testcase
    StringBuilder sb = new StringBuilder("test");
    for (int i = 0; i < 100; ++i) {
        sb.append("0123456789");
    }
    String longName = sb.toString();
    OmDirectoryInfo dir1 = new OmDirectoryInfo.Builder().setName("dir" + longName).setCreationTime(Time.now()).setModificationTime(Time.now()).setObjectID(1).setParentObjectID(bucketInfo.getObjectID()).setUpdateID(0).build();
    OMRequestTestUtils.addDirKeyToDirTable(true, dir1, volumeName, bucketName, 1L, om.getMetadataManager());
    for (int i = 0; i < 2000; ++i) {
        String keyName = "key" + longName + i;
        OmKeyInfo omKeyInfo = OMRequestTestUtils.createOmKeyInfo(volumeName, bucketName, keyName, RatisReplicationConfig.getInstance(ONE)).setObjectID(dir1.getObjectID() + 1 + i).setParentObjectID(dir1.getObjectID()).setUpdateID(100L).build();
        OMRequestTestUtils.addFileToKeyTable(false, true, keyName, omKeyInfo, 1234L, i + 1, om.getMetadataManager());
    }
    // delete directory recursively
    OmKeyArgs delArgs = new OmKeyArgs.Builder().setVolumeName(volumeName).setBucketName(bucketName).setKeyName("dir" + longName).setReplicationConfig(StandaloneReplicationConfig.getInstance(ONE)).setDataSize(0).setRecursive(true).build();
    writeClient.deleteKey(delArgs);
    // wait for file count of only 100 but not all 2000 files
    // as logic, will take 1000 files
    DirectoryDeletingService dirDeletingService = (DirectoryDeletingService) keyManager.getDirDeletingService();
    GenericTestUtils.waitFor(() -> dirDeletingService.getMovedFilesCount() >= 1000 && dirDeletingService.getMovedFilesCount() < 2000, 500, 60000);
    assertThat(dirDeletingService.getRunCount().get()).isGreaterThanOrEqualTo(1);
}

/**
 * In this test, we create a bunch of keys and delete them. Then we start the
 * KeyDeletingService and pass a SCMClient which does not fail. We make sure
 * that all the keys that we deleted is picked up and deleted by
 * OzoneManager.
 */
@Test
void checkIfDeleteServiceIsDeletingKeys() throws IOException, TimeoutException, InterruptedException {
    final long initialDeletedCount = getDeletedKeyCount();
    final long initialRunCount = getRunCount();
    final int keyCount = 100;
    createAndDeleteKeys(keyCount, 1);
    GenericTestUtils.waitFor(() -> getDeletedKeyCount() >= initialDeletedCount + keyCount, 100, 10000);
    assertThat(getRunCount()).isGreaterThan(initialRunCount);
    assertThat(keyManager.getPendingDeletionKeys(Integer.MAX_VALUE).getKeyBlocksList()).isEmpty();
}

