/**
 * In this test, we create a bunch of MPU keys with uncommitted parts, then
 * we will start the OpenKeyCleanupService. The OpenKeyCleanupService
 * should only delete the open MPU part keys (not the open MPU key).
 *
 * @throws IOException - on Failure.
 */
@ParameterizedTest
@CsvSource({ "9, 0", "0, 8", "6, 7" })
public void testCleanupExpiredOpenMPUPartKeys(int numDEFKeys, int numFSOKeys) throws Exception {
    LOG.info("numDEFMpuKeys={}, numFSOMpuKeys={}", numDEFKeys, numFSOKeys);
    OpenKeyCleanupService openKeyCleanupService = (OpenKeyCleanupService) keyManager.getOpenKeyCleanupService();
    openKeyCleanupService.suspend();
    // wait for submitted tasks to complete
    Thread.sleep(SERVICE_INTERVAL);
    final long oldkeyCount = openKeyCleanupService.getSubmittedOpenKeyCount();
    final long oldrunCount = openKeyCleanupService.getRunCount();
    LOG.info("oldMpuKeyCount={}, oldMpuRunCount={}", oldkeyCount, oldrunCount);
    final OMMetrics metrics = om.getMetrics();
    long numOpenKeysCleaned = metrics.getNumOpenKeysCleaned();
    final int keyCount = numDEFKeys + numFSOKeys;
    final int partCount = NUM_MPU_PARTS * keyCount;
    createIncompleteMPUKeys(numDEFKeys, BucketLayout.DEFAULT, NUM_MPU_PARTS, false);
    createIncompleteMPUKeys(numFSOKeys, BucketLayout.FILE_SYSTEM_OPTIMIZED, NUM_MPU_PARTS, false);
