@Test
@DisplayName("Cache eviction with try-with-resources")
void testEviction3WithClose() throws IOException, InterruptedException, TimeoutException {
    final UUID dbKey1 = UUID.randomUUID();
    try (ReferenceCounted<OmSnapshot> rcOmSnapshot = snapshotCache.get(dbKey1)) {
        assertEquals(1L, rcOmSnapshot.getTotalRefCount());
        assertEquals(1, snapshotCache.size());
        assertEquals(1, omMetrics.getNumSnapshotCacheSize());
    }
    // ref count should have been decreased because it would be close()d
    // upon exiting try-with-resources.
    assertEquals(0L, snapshotCache.getDbMap().get(dbKey1).getTotalRefCount());
    assertEquals(1, snapshotCache.size());
    assertEquals(1, omMetrics.getNumSnapshotCacheSize());
    final UUID dbKey2 = UUID.randomUUID();
    try (ReferenceCounted<OmSnapshot> rcOmSnapshot = snapshotCache.get(dbKey2)) {
        assertEquals(1L, rcOmSnapshot.getTotalRefCount());
        assertEquals(2, snapshotCache.size());
        assertEquals(2, omMetrics.getNumSnapshotCacheSize());
        // Get dbKey2 entry a second time
        try (ReferenceCounted<OmSnapshot> rcOmSnapshot2 = snapshotCache.get(dbKey2)) {
            assertEquals(2L, rcOmSnapshot.getTotalRefCount());
            assertEquals(2L, rcOmSnapshot2.getTotalRefCount());
            assertEquals(2, snapshotCache.size());
            assertEquals(2, omMetrics.getNumSnapshotCacheSize());
        }
        assertEquals(1L, rcOmSnapshot.getTotalRefCount());
    }
    assertEquals(0L, snapshotCache.getDbMap().get(dbKey2).getTotalRefCount());
    assertEquals(2, snapshotCache.size());
    assertEquals(2, omMetrics.getNumSnapshotCacheSize());
    final UUID dbKey3 = UUID.randomUUID();
    try (ReferenceCounted<OmSnapshot> rcOmSnapshot = snapshotCache.get(dbKey3)) {
        assertEquals(1L, rcOmSnapshot.getTotalRefCount());
        assertEquals(3, snapshotCache.size());
        assertEquals(3, omMetrics.getNumSnapshotCacheSize());
    }
    assertEquals(0L, snapshotCache.getDbMap().get(dbKey3).getTotalRefCount());
    assertEquals(3, snapshotCache.size());
    assertEquals(3, omMetrics.getNumSnapshotCacheSize());
    final UUID dbKey4 = UUID.randomUUID();
    try (ReferenceCounted<OmSnapshot> rcOmSnapshot = snapshotCache.get(dbKey4)) {
        GenericTestUtils.waitFor(() -> snapshotCache.size() == 1, 50, 3000);
        assertEquals(1L, rcOmSnapshot.getTotalRefCount());
        assertEquals(1, snapshotCache.size());
        assertEquals(1, omMetrics.getNumSnapshotCacheSize());
    }
    assertEquals(0L, snapshotCache.getDbMap().get(dbKey4).getTotalRefCount());
    assertEquals(1, snapshotCache.size());
    assertEquals(1, omMetrics.getNumSnapshotCacheSize());
}

@Test
public void testAddSnapshot() throws Exception {
    final String snapshotPath = "vol1/bucket1";
    // add three snapshots
    UUID snapshotID1 = UUID.randomUUID();
    UUID snapshotID2 = UUID.randomUUID();
    UUID snapshotID3 = UUID.randomUUID();
    ArrayList<UUID> snapshotIDs = new ArrayList<>();
    snapshotIDs.add(snapshotID1);
    snapshotIDs.add(snapshotID2);
    snapshotIDs.add(snapshotID3);
    UUID prevSnapshotID = null;
    List<Integer> times = Arrays.asList(1, 2, 0);
    int timeIdx = 0;
    // add 3 snapshots
    for (UUID snapshotID : snapshotIDs) {
        chainManager.addSnapshot(createSnapshotInfo(snapshotID, prevSnapshotID, prevSnapshotID, times.get(timeIdx++)));
        prevSnapshotID = snapshotID;
    }
    assertEquals(snapshotID3, chainManager.getLatestGlobalSnapshotId());
    assertEquals(snapshotID3, chainManager.getLatestPathSnapshotId(String.join("/", "vol1", "bucket1")));
    int i = 0;
    UUID curID = snapshotIDs.get(i);
    while (chainManager.hasNextGlobalSnapshot(curID)) {
        i++;
        assertEquals(snapshotIDs.get(i), chainManager.nextGlobalSnapshot(curID));
        curID = snapshotIDs.get(i);
    }
    curID = snapshotIDs.get(i);
    while (chainManager.hasPreviousGlobalSnapshot(curID)) {
        i--;
        assertEquals(snapshotIDs.get(i), chainManager.previousGlobalSnapshot(curID));
        curID = snapshotIDs.get(i);
    }
    i = 0;
    curID = snapshotIDs.get(i);
    while (chainManager.hasNextPathSnapshot(snapshotPath, curID)) {
        i++;
        assertEquals(snapshotIDs.get(i), chainManager.nextPathSnapshot(snapshotPath, curID));
        curID = snapshotIDs.get(i);
    }
    curID = snapshotIDs.get(i);
    while (chainManager.hasPreviousPathSnapshot(snapshotPath, curID)) {
        i--;
        assertEquals(snapshotIDs.get(i), chainManager.previousPathSnapshot(snapshotPath, curID));
        curID = snapshotIDs.get(i);
    }
}

@Test
public void testDeleteSnapshot() throws Exception {
    // add three snapshots
    UUID snapshotID1 = UUID.randomUUID();
    UUID snapshotID2 = UUID.randomUUID();
    UUID snapshotID3 = UUID.randomUUID();
    ArrayList<UUID> snapshotIDs = new ArrayList<>();
    snapshotIDs.add(snapshotID1);
    snapshotIDs.add(snapshotID2);
    snapshotIDs.add(snapshotID3);
    UUID prevSnapshotID = null;
    List<Integer> times = Arrays.asList(1, 2, 0);
    int timeIdx = 0;
    // add 3 snapshots
    for (UUID snapshotID : snapshotIDs) {
        snapshotIdToSnapshotInfoMap.put(snapshotID, createSnapshotInfo(snapshotID, prevSnapshotID, prevSnapshotID, times.get(timeIdx++)));
        chainManager.addSnapshot(snapshotIdToSnapshotInfoMap.get(snapshotID));
        prevSnapshotID = snapshotID;
    }
    // delete snapshotID2
    // should have snapshots ID1 and ID3 in chain
    deleteSnapshot(snapshotID2);
    // start with first snapshot in snapshot chain
    assertFalse(chainManager.hasPreviousGlobalSnapshot(snapshotID1));
    assertTrue(chainManager.hasNextGlobalSnapshot(snapshotID1));
    assertFalse(chainManager.hasNextGlobalSnapshot(snapshotID3));
    assertEquals(snapshotID3, chainManager.nextGlobalSnapshot(snapshotID1));
    // add snapshotID2 and delete snapshotID1
    // should have snapshotID3 and snapshotID2
    deleteSnapshot(snapshotID1);
    chainManager.addSnapshot(snapshotIdToSnapshotInfoMap.get(snapshotID2));
    assertFalse(chainManager.hasPreviousGlobalSnapshot(snapshotID3));
    assertTrue(chainManager.hasNextGlobalSnapshot(snapshotID3));
    assertEquals(snapshotID2, chainManager.nextGlobalSnapshot(snapshotID3));
    assertFalse(chainManager.hasNextGlobalSnapshot(snapshotID2));
    assertEquals(snapshotID3, chainManager.previousGlobalSnapshot(snapshotID2));
}

