@ParameterizedTest
@CsvSource({ "0,10,1000", "1,10,8", "10,1000,10", "-1,1000,10000", "1,0,1000", "1,-1,1000" })
public void testCreatePageResponse(int startIdx, int pageSize, int totalNumberOfRecords) throws IOException, RocksDBException {
    String testJobId = "jobId";
    String testJobId2 = "jobId2";
    IntStream.range(0, totalNumberOfRecords).boxed().forEach(idx -> {
        try {
            db.get().put(snapDiffReportTable, codecRegistry.asRawData(SnapshotDiffManager.getReportKeyForIndex(testJobId, idx)), codecRegistry.asRawData(getTestDiffEntry(testJobId, idx)));
            db.get().put(snapDiffReportTable, codecRegistry.asRawData(testJobId2 + DELIMITER + idx), codecRegistry.asRawData(getTestDiffEntry(testJobId2, idx)));
        } catch (IOException | RocksDBException e) {
            throw new RuntimeException(e);
        }
    });
    SnapshotDiffJob snapshotDiffJob = new SnapshotDiffJob(0, testJobId, JobStatus.DONE, "vol", "buck", "fs", "ts", false, true, totalNumberOfRecords);
    SnapshotDiffJob snapshotDiffJob2 = new SnapshotDiffJob(0, testJobId2, JobStatus.DONE, "vol", "buck", "fs", "ts", false, true, totalNumberOfRecords);
    db.get().put(snapDiffJobTable, codecRegistry.asRawData(testJobId), codecRegistry.asRawData(snapshotDiffJob));
    db.get().put(snapDiffJobTable, codecRegistry.asRawData(testJobId2), codecRegistry.asRawData(snapshotDiffJob2));
    if (pageSize <= 0 || startIdx < 0) {
        assertThrows(IOException.class, () -> snapshotDiffManager.createPageResponse(snapshotDiffJob, "vol", "buck", "fs", "ts", startIdx, pageSize));
        return;
    }
    SnapshotDiffReportOzone snapshotDiffReportOzone = snapshotDiffManager.createPageResponse(snapshotDiffJob, "vol", "buck", "fs", "ts", startIdx, pageSize);
    int expectedTotalNumberOfRecords = Math.max(Math.min(pageSize, totalNumberOfRecords - startIdx), 0);
    assertEquals(snapshotDiffReportOzone.getDiffList().size(), expectedTotalNumberOfRecords);
    int idx = startIdx;
    for (DiffReportEntry entry : snapshotDiffReportOzone.getDiffList()) {
        assertEquals(getTestDiffEntry(testJobId, idx), entry);
        idx++;
    }
}

/**
 * Once a job is cancelled, it stays in the table until
 * SnapshotDiffCleanupService removes it.
 * Job response until that happens, is CANCELLED.
 */
@Test
public void testGetSnapshotDiffReportForCancelledJob() throws IOException {
    String volumeName = "vol-" + RandomStringUtils.randomNumeric(5);
    String bucketName = "bucket-" + RandomStringUtils.randomNumeric(5);
    String fromSnapshotName = "snap-" + RandomStringUtils.randomNumeric(5);
    String toSnapshotName = "snap-" + RandomStringUtils.randomNumeric(5);
    UUID fromSnapshotUUID = UUID.randomUUID();
    UUID toSnapshotUUID = UUID.randomUUID();
    setupMocksForRunningASnapDiff(volumeName, bucketName);
    setUpSnapshots(volumeName, bucketName, fromSnapshotName, toSnapshotName, fromSnapshotUUID, toSnapshotUUID);
    PersistentMap<String, SnapshotDiffJob> snapDiffJobMap = snapshotDiffManager.getSnapDiffJobTable();
    String diffJobKey = fromSnapshotUUID + DELIMITER + toSnapshotUUID;
    SnapshotDiffJob diffJob = snapDiffJobMap.get(diffJobKey);
    assertNull(diffJob);
    SnapshotDiffManager spy = spy(snapshotDiffManager);
    doNothing().when(spy).generateSnapshotDiffReport(eq(diffJobKey), anyString(), eq(volumeName), eq(bucketName), eq(fromSnapshotName), eq(toSnapshotName), eq(false), eq(false));
    // Submit a new job.
    SnapshotDiffResponse snapshotDiffResponse = spy.getSnapshotDiffReport(volumeName, bucketName, fromSnapshotName, toSnapshotName, 0, 0, false, false);
    assertEquals(JobStatus.IN_PROGRESS, snapshotDiffResponse.getJobStatus());
    // Cancel the job.
    spy.cancelSnapshotDiff(volumeName, bucketName, fromSnapshotName, toSnapshotName);
    // Job status should be cancelled until the cleanup
    // service removes the job from the table.
    snapshotDiffResponse = spy.getSnapshotDiffReport(volumeName, bucketName, fromSnapshotName, toSnapshotName, 0, 0, false, false);
    assertEquals(JobStatus.CANCELLED, snapshotDiffResponse.getJobStatus());
    // Check snapDiffJobTable.
    diffJob = snapDiffJobMap.get(diffJobKey);
    assertNotNull(diffJob);
    assertEquals(JobStatus.CANCELLED, diffJob.getStatus());
    // Response should still be cancelled.
    snapshotDiffResponse = spy.getSnapshotDiffReport(volumeName, bucketName, fromSnapshotName, toSnapshotName, 0, 0, false, false);
    assertEquals(JobStatus.CANCELLED, snapshotDiffResponse.getJobStatus());
    // Check snapDiffJobTable.
    diffJob = snapDiffJobMap.get(diffJobKey);
    assertNotNull(diffJob);
    assertEquals(JobStatus.CANCELLED, diffJob.getStatus());
}

