@Test
public void testVolumeOps() throws Exception {
    OzoneObj vol0 = getTestVolumeobj(0);
    // admin = true, owner = false, ownerName = testvolumeOwner
    RequestContext nonOwnerContext = getUserRequestContext("om", IAccessAuthorizer.ACLType.CREATE, false, getTestVolOwnerName(0));
    assertTrue(nativeAuthorizer.checkAccess(vol0, nonOwnerContext), "matching admins are allowed to perform admin " + "operations");
    // admin = true, owner = false, ownerName = null
    assertTrue(nativeAuthorizer.checkAccess(vol0, nonOwnerContext), "matching admins are allowed to perform admin " + "operations");
    // admin = false, owner = false, ownerName = testvolumeOwner
    RequestContext nonAdminNonOwnerContext = getUserRequestContext("testuser", IAccessAuthorizer.ACLType.CREATE, false, getTestVolOwnerName(0));
    assertFalse(nativeAuthorizer.checkAccess(vol0, nonAdminNonOwnerContext), "mismatching admins are not allowed to " + "perform admin operations");
    // admin = false, owner = true
    RequestContext nonAdminOwnerContext = getUserRequestContext(getTestVolOwnerName(0), IAccessAuthorizer.ACLType.CREATE, true, getTestVolOwnerName(0));
    assertFalse(nativeAuthorizer.checkAccess(vol0, nonAdminOwnerContext), "mismatching admins are not allowed to " + "perform admin operations even for owner");
    List<IAccessAuthorizer.ACLType> aclsToTest = Arrays.stream(IAccessAuthorizer.ACLType.values()).filter((type) -> type != NONE && type != CREATE).collect(Collectors.toList());
    for (IAccessAuthorizer.ACLType type : aclsToTest) {
        nonAdminOwnerContext = getUserRequestContext(getTestVolOwnerName(0), type, true, getTestVolOwnerName(0));
        assertTrue(nativeAuthorizer.checkAccess(vol0, nonAdminOwnerContext), "Owner is allowed to perform all non-admin " + "operations");
    }
}

