/**
 * Tests that only designated endpoints are not marked with the @AdminOnly
 * annotation, meaning they are accessible to all users.
 */
@Test
public void testAdminOnlyEndpoints() {
    // Get all classes with @Path annotation anywhere in recon.
    Reflections reflections = new Reflections("org.apache.hadoop.ozone.recon", new TypeAnnotationsScanner(), new SubTypesScanner());
    Set<Class<?>> allEndpoints = reflections.getTypesAnnotatedWith(Path.class);
    assertThat(allEndpoints).isNotEmpty();
    // If an endpoint is added, it must be explicitly added to this set or be
    // marked with @AdminOnly for this test to pass.
    Set<Class<?>> nonAdminEndpoints = new HashSet<>();
    nonAdminEndpoints.add(UtilizationEndpoint.class);
    nonAdminEndpoints.add(ClusterStateEndpoint.class);
    nonAdminEndpoints.add(MetricsProxyEndpoint.class);
    nonAdminEndpoints.add(NodeEndpoint.class);
    nonAdminEndpoints.add(PipelineEndpoint.class);
    nonAdminEndpoints.add(TaskStatusService.class);
    nonAdminEndpoints.add(TriggerDBSyncEndpoint.class);
    assertThat(allEndpoints).containsAll(nonAdminEndpoints);
    Set<Class<?>> adminEndpoints = Sets.difference(allEndpoints, nonAdminEndpoints);
    for (Class<?> endpoint : nonAdminEndpoints) {
        assertFalse(endpoint.isAnnotationPresent(AdminOnly.class), String.format("Endpoint class %s has been declared as non admin " + "in this test, but is marked as @AdminOnly.", endpoint));
    }
    for (Class<?> endpoint : adminEndpoints) {
        assertTrue(endpoint.isAnnotationPresent(AdminOnly.class), String.format("Endpoint class %s must be marked as @AdminOnly " + "or explicitly declared as non admin in this test.", endpoint));
    }
}

