    assertEquals(3, containerDiscrepancyInfoListOM.size());
    // Set the filter to "SCM" to get missing containers in SCM
    Response responseSCM = containerEndpoint.getContainerMisMatchInsights(10, 0, "SCM");
    Map<String, Object> responseMapSCM = (Map<String, Object>) responseSCM.getEntity();
    List<ContainerDiscrepancyInfo> containerDiscrepancyInfoListSCM = (List<ContainerDiscrepancyInfo>) responseMapSCM.get("containerDiscrepancyInfo");
