    BucketsResponse bucketResponseLimitWithVolume = (BucketsResponse) responseLimitWithVolume.getEntity();
    assertEquals(1, bucketResponseLimitWithVolume.getTotalCount());
    assertEquals(1, bucketResponseLimitWithVolume.getBuckets().size());
    // Case 3: Test prevKey (it should not be ignored)
