    BucketsResponse bucketVolumeNotExistResponse = (BucketsResponse) responseVolumeNotExist.getEntity();
    assertEquals(0, bucketVolumeNotExistResponse.getTotalCount());
    assertEquals(0, bucketVolumeNotExistResponse.getBuckets().size());
