@Test
public void testConstructFullPath() throws IOException {
    OmKeyInfo keyInfo = new OmKeyInfo.Builder().setKeyName("file2").setVolumeName(VOL).setBucketName(BUCKET_ONE).setObjectID(KEY_TWO_OBJECT_ID).setParentObjectID(DIR_TWO_OBJECT_ID).build();
    // Call constructFullPath and verify the result
    String fullPath = ReconUtils.constructFullPath(keyInfo, reconNamespaceSummaryManager, reconOMMetadataManager);
    String expectedPath = "vol/bucket1/dir1/dir2/file2";
    Assertions.assertEquals(expectedPath, fullPath);
    // Create key info for file 3
    keyInfo = new OmKeyInfo.Builder().setKeyName("file3").setVolumeName(VOL).setBucketName(BUCKET_ONE).setObjectID(KEY_THREE_OBJECT_ID).setParentObjectID(DIR_THREE_OBJECT_ID).build();
    fullPath = ReconUtils.constructFullPath(keyInfo, reconNamespaceSummaryManager, reconOMMetadataManager);
    expectedPath = "vol/bucket1/dir1/dir3/file3";
    Assertions.assertEquals(expectedPath, fullPath);
    // Create key info for file 6
    keyInfo = new OmKeyInfo.Builder().setKeyName("file6").setVolumeName(VOL).setBucketName(BUCKET_ONE).setObjectID(KEY_SIX_OBJECT_ID).setParentObjectID(DIR_FOUR_OBJECT_ID).build();
    fullPath = ReconUtils.constructFullPath(keyInfo, reconNamespaceSummaryManager, reconOMMetadataManager);
    expectedPath = "vol/bucket1/dir1/dir4/file6";
    Assertions.assertEquals(expectedPath, fullPath);
    // Create key info for file 1
    keyInfo = new OmKeyInfo.Builder().setKeyName("file1").setVolumeName(VOL).setBucketName(BUCKET_ONE).setObjectID(KEY_ONE_OBJECT_ID).setParentObjectID(BUCKET_ONE_OBJECT_ID).build();
    fullPath = ReconUtils.constructFullPath(keyInfo, reconNamespaceSummaryManager, reconOMMetadataManager);
    expectedPath = "vol/bucket1/file1";
    Assertions.assertEquals(expectedPath, fullPath);
    // Create key info for file 9
    keyInfo = new OmKeyInfo.Builder().setKeyName("file9").setVolumeName(VOL_TWO).setBucketName(BUCKET_THREE).setObjectID(KEY_NINE_OBJECT_ID).setParentObjectID(DIR_FIVE_OBJECT_ID).build();
    fullPath = ReconUtils.constructFullPath(keyInfo, reconNamespaceSummaryManager, reconOMMetadataManager);
    expectedPath = "vol2/bucket3/dir5/file9";
    Assertions.assertEquals(expectedPath, fullPath);
    // Check for when we encounter a NSSUmamry with parentId -1
    // Fetch NSSummary for dir1 and immediately update its parentId.
    NSSummary dir1Summary = reconNamespaceSummaryManager.getNSSummary(DIR_ONE_OBJECT_ID);
    // Update parentId to -1
    dir1Summary.setParentId(-1);
    reconNamespaceSummaryManager.deleteNSSummary(DIR_ONE_OBJECT_ID);
    reconNamespaceSummaryManager.storeNSSummary(DIR_ONE_OBJECT_ID, dir1Summary);
    NSSummary changedDir1Summary = reconNamespaceSummaryManager.getNSSummary(DIR_ONE_OBJECT_ID);
    Assertions.assertEquals(-1, changedDir1Summary.getParentId(), "The parentId should be updated to -1");
    keyInfo = new OmKeyInfo.Builder().setKeyName("file2").setVolumeName(VOL).setBucketName(BUCKET_ONE).setObjectID(KEY_TWO_OBJECT_ID).setParentObjectID(DIR_TWO_OBJECT_ID).build();
    // Call constructFullPath and verify the result
    fullPath = ReconUtils.constructFullPath(keyInfo, reconNamespaceSummaryManager, reconOMMetadataManager);
}

