    insertGlobalStatsRecords(statsDao, now, "openFileTableReplicatedDataSize", 30L);
    insertGlobalStatsRecords(statsDao, now, "openKeyTableReplicatedDataSize", 30L);
    insertGlobalStatsRecords(statsDao, now, "deletedTableReplicatedDataSize", 30L);
