    }
    ReplicatedReplicationConfig replicationConfig = RatisReplicationConfig.getInstance(THREE);
    // Under replicated
    ContainerInfo containerInfo1 = TestContainerInfo.newBuilderForTest().setContainerID(1).setReplicationConfig(replicationConfig).build();
    when(containerManagerMock.getContainer(ContainerID.valueOf(1L))).thenReturn(containerInfo1);
    when(containerManagerMock.getContainerReplicas(containerInfo1.containerID())).thenReturn(getMockReplicas(1L, State.CLOSED, State.UNHEALTHY));
    // return all UNHEALTHY replicas for container ID 2 -> UNDER_REPLICATED
    ContainerInfo containerInfo2 = TestContainerInfo.newBuilderForTest().setContainerID(2).setReplicationConfig(replicationConfig).build();
    when(containerManagerMock.getContainer(ContainerID.valueOf(2L))).thenReturn(containerInfo2);
    when(containerManagerMock.getContainerReplicas(containerInfo2.containerID())).thenReturn(getMockReplicas(2L, State.UNHEALTHY));
    // return 0 replicas for container ID 3 -> Empty Missing
    ContainerInfo containerInfo3 = TestContainerInfo.newBuilderForTest().setContainerID(3).setReplicationConfig(replicationConfig).build();
    when(containerManagerMock.getContainer(ContainerID.valueOf(3L))).thenReturn(containerInfo3);
    when(containerManagerMock.getContainerReplicas(containerInfo3.containerID())).thenReturn(Collections.emptySet());
    // Return 5 Healthy -> Over replicated
