@Test
public void concurrentParse() {
    CompleteMultipartUploadRequestUnmarshaller unmarshaller = new CompleteMultipartUploadRequestUnmarshaller();
    byte[] bytes = ("<CompleteMultipartUpload>" + "<Part><ETag>" + part1 + "</ETag><PartNumber>1</PartNumber" + "></Part><Part><ETag>" + part2 + "</ETag><PartNumber>2" + "</PartNumber></Part></CompleteMultipartUpload>").getBytes(UTF_8);
    List<CompletableFuture<CompleteMultipartUploadRequest>> futures = new ArrayList<>();
    for (int i = 0; i < 40; i++) {
        futures.add(CompletableFuture.supplyAsync(() -> {
            try {
                //GIVEN
                ByteArrayInputStream inputBody = new ByteArrayInputStream(bytes);
                //WHEN
                return unmarshall(unmarshaller, inputBody);
            } catch (IOException e) {
                return null;
            }
        }));
    }
    for (CompletableFuture<CompleteMultipartUploadRequest> future : futures) {
        CompleteMultipartUploadRequest request = future.join();
        //THEN
        checkContent(request);
    }
}

