@Test
public void testUploadWithCopy() throws Exception {
    OzoneBucket bucket = client.getObjectStore().getS3Bucket(S3BUCKET);
    byte[] keyContent = S3_COPY_EXISTING_KEY_CONTENT.getBytes(UTF_8);
    try (OutputStream stream = bucket.createStreamKey(S3_COPY_EXISTING_KEY, keyContent.length, ReplicationConfig.fromTypeAndFactor(ReplicationType.RATIS, ReplicationFactor.THREE), new HashMap<>())) {
        stream.write(keyContent);
    }
    final long dataSize = bucket.getKey(S3_COPY_EXISTING_KEY).getDataSize();
    assertEquals(dataSize, keyContent.length);
    Map<String, String> additionalHeaders = new HashMap<>();
    additionalHeaders.put(COPY_SOURCE_HEADER, S3BUCKET + "/" + S3_COPY_EXISTING_KEY);
    HttpHeaders headers = mock(HttpHeaders.class);
    when(headers.getHeaderString(STORAGE_CLASS_HEADER)).thenReturn("STANDARD");
    additionalHeaders.forEach((k, v) -> when(headers.getHeaderString(k)).thenReturn(v));
    REST.setHeaders(headers);
    Response response = REST.put(S3BUCKET, S3KEY, 0, 0, null, null);
    assertEquals(200, response.getStatus());
    final long newDataSize = bucket.getKey(S3KEY).getDataSize();
    assertEquals(dataSize, newDataSize);
}

@Test
public void testOS3Exceptions() {
    OS3Exception ex = new OS3Exception("AccessDenied", "Access Denied", 403);
    String requestId = OzoneUtils.getRequestID();
    ex = S3ErrorTable.newError(ex, "bucket");
    ex.setRequestId(requestId);
    String val = ex.toXml();
    String formatString = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>%n" + "<Error>%n" + "  <Code>%s</Code>%n" + "  <Message>%s</Message>%n" + "  <Resource>%s</Resource>%n" + "  <RequestId>%s</RequestId>%n" + "</Error>%n";
    String expected = String.format(formatString, ex.getCode(), ex.getErrorMessage(), ex.getResource(), ex.getRequestId());
    assertEquals(expected, val);
}

